/* ÇEVİRİ de · olay — arac/ceviri.py ile YAZILDI, elle düzenleme: py arac/ceviri.py uygula.
   Kayıt: id → [metin, kaynak_ozet] (olayda alan başına). Tasarım: denetim/CEVIRI-1103/TASARIM.md */
Ceviri.ekle("de","olay",{
"OLAYLAR:1299-01:0":{"b": ["Gründung des osmanischen Beylik", "9f0b7c0a"], "d": ["Der Beginn selbstständigen Handelns Osman Gazis aus dem Stamm der Kayı im Raum Söğüt–Domaniç gilt traditionell als Ausgangspunkt der Gründung des Osmanischen Staates; manche Historiker sehen im Sieg von Bapheus (1302) den eigentlichen Wendepunkt. Dank seiner Lage im byzantinischen Grenzgebiet gewann das Beylik durch Gaza-Raubzüge rasch an Macht. In diesem Umfeld des Zerfalls des seldschukischen Erbes sammelte Osman Gazi Ahis, Gazis und nomadische Turkmenen um sich; seine Verbindung zu Scheich Edebali gilt als Grundlage der geistlichen Legitimität des Beylik. Zum selben Datum angeschlossene weitere Orte: İnegöl, Yarhisar.", "9d689d45"]},
"OLAYLAR:1326-04-06:0":{"b": ["Eroberung von Bursa", "98c727fa"], "d": ["Das jahrelang blockierte Bursa ergab sich Orhan Gazi, der die Schlussphase der Belagerung leitete; die Stadt wurde zur ersten großen Hauptstadt des Beylik. Der Überlieferung nach wurde die Nachricht von der Eroberung dem sterbenden Osman Gazi überbracht; auf sein Vermächtnis hin wurde Osman Gazi in Bursa bestattet. Die Stadt wurde in kurzer Zeit mit Moscheen, Imarets und Medresen ausgestattet und wurde zum Modell des frühosmanischen Städtebaus.", "9ede6ee9"]},
"OLAYLAR:1331-03-02:0":{"b": ["Eroberung von İznik", "a846a811"], "d": ["İznik (Nikaia), eines der wichtigsten Zentren der Byzantiner in Anatolien, ergab sich Orhan Gazi, nachdem es nach dem Sieg von Pelekanon (1329) die Hoffnung auf Widerstand verloren hatte. Hier wurde die erste osmanische Medrese gegründet, und Gelehrte wie Dâvûd-i Kayserî begannen zu lehren; die Stadt wurde zum Wissenschaftszentrum der Frühzeit. Die Hagia-Sophia-Kirche wurde in eine Moschee umgewandelt, was ein frühes Beispiel der Eroberungstradition darstellt.", "8fd3bfb5"]},
"OLAYLAR:1337-01-01:0":{"b": ["Eroberung von İzmit", "06a35035"], "d": ["Mit dem Fall von İzmit (Nikomedia) kam auch die letzte bedeutende byzantinische Festung auf der anatolischen Seite unter osmanische Herrschaft; die gesamte Halbinsel Kocaeli bis zur Küste gegenüber von Konstantinopel wurde osmanisches Gebiet. Damit beherrschte das Beylik die gesamte Süd- und Ostküste des Marmarameeres und schuf die Voraussetzungen für den Übergang nach Rumelien.", "f677745c"]},
"OLAYLAR:1352-03-01:0":{"b": ["Festung Çimpe – Übergang nach Rumelien", "c2f0a07d"], "d": ["Süleyman Pascha, ein Sohn Orhan Gazis, hatte die ihm im byzantinischen Bürgerkrieg überlassene Festung Çimpe 1352 zum Stützpunkt gemacht; nach dem großen Erdbeben, das im März 1354 Gelibolu zerstörte, wurden die verlassenen Festungen rasch befestigt und die Halbinsel zu einem dauerhaften osmanischen Brückenkopf ausgebaut. Dieser durch die Ansiedlung der aus Anatolien herangeführten turkmenischen Bevölkerung gestützte Schritt ist der Beginn der über 550 Jahre währenden Präsenz der Osmanen auf dem europäischen Kontinent.", "4857333a"]},
"OLAYLAR:1361-05-05:0":{"b": ["Eroberung von Adrianopel (Edirne)", "2f54ebb0"], "d": ["Die Einnahme der thrakischen Schlüsselstadt Adrianopel (Edirne) bestimmte den Hauptstützpunkt und die Richtung der Eroberungen auf dem Balkan; das Eroberungsdatum ist in den Quellen zwischen 1361 und 1369 umstritten. Die Stadt wurde bald darauf zur Hauptstadt gemacht und verkündete damit die Verlagerung des Schwerpunkts des Staates nach Rumelien; sie blieb bis zur Eroberung Konstantinopels etwa 90 Jahre Residenzstadt.", "25bd644f"]},
"OLAYLAR:1362-03:0":{"b": ["Murad I. besteigt den Thron", "f8d48a26"], "d": ["Murad I. (Hüdavendigâr), der mit dem Tod Orhan Gazis auf den Thron kam, führte den Staat in seiner 27-jährigen Herrschaft von einem Grenz-Beylik zum Gerüst eines Imperiums. Mit dem Pençik-System wurde der Grundstein des Janitscharenkorps gelegt, die Timar-Ordnung wurde verbreitet, das Beylerbeylik von Rumelien wurde gegründet und das Wesirat gestärkt. Die Eroberungen auf dem Balkan wurden unter ihm zu einer systematischen Staatspolitik.", "d463078a"]},
"OLAYLAR:1389-06-15:0":{"b": ["Erste Schlacht auf dem Amselfeld – Märtyrertod Murads I.", "10b8ddc9"], "d": ["Das unter Knez Lazar stehende Balkanbündnis wurde auf dem Amselfeld (Kosovo-Ebene) entscheidend geschlagen; Serbien geriet unter osmanische Oberhoheit. Murad I., der das Schlachtfeld abschritt, wurde vom serbischen Edelmann Miloš Obilić erdolcht und fiel als Märtyrer — er ist der einzige osmanische Sultan, der auf dem Schlachtfeld starb. An seiner Stelle wurde Bayezid Yıldırım im Heerlager auf den Thron gehoben; sein Bruder Yakub Çelebi wurde erdrosselt, was eines der ersten bekannten Beispiele des Brudermords darstellt.", "153449fe"]},
"OLAYLAR:1396-09-25:0":{"b": ["Sieg bei Nikopolis", "75716e96"], "d": ["Das große Kreuzfahrerheer, das auf den Aufruf des ungarischen Königs Sigismund zusammengekommen war und an dem auch französisch-burgundische Ritter teilnahmen, wurde vor Nikopolis an der Donau von Bayezid Yıldırım vernichtend geschlagen. Der Sieg festigte die osmanische Herrschaft über Bulgarien; in Europa konnte eine Generation lang kein großer Kreuzzug mehr organisiert werden.", "0d06e36c"]},
"OLAYLAR:1402-07-28:0":{"b": ["Schlacht von Ankara – Beginn des Interregnums (Fetret Devri)", "b4a99d96"], "d": ["In der schweren Niederlage gegen das Heer Timurs auf der Çubuk-Ebene geriet Bayezid Yıldırım in Gefangenschaft und starb einige Monate später in der Gefangenschaft. Timur ließ die anatolischen Beyliks wieder aufleben; das osmanische Gebiet wurde unter den Söhnen Bayezids aufgeteilt, und ein elf Jahre währender Thronkampf (Interregnum, Fetret Devri) begann. Diese schwerste Krise seit der Staatsgründung prägte dem osmanischen Gedächtnis die Bedeutung der zentralistischen Struktur ein. Zum selben Datum verlorene weitere Siedlungen: Datça, Marmaris, Fethiye (Makri), Söke, Kütahya, Afyon, Isparta, Manisa, Aydın, Denizli, Muğla, Antalya, Konya, Karaman, Kayseri, Kastamonu, Bartın, Safranbolu, Samsun, Sivas, Malatya, Beyşehir, Sivrihisar, Kırşehir, Çorum, Çankırı, Yenişehir (Bursa), İnegöl, Burg Aydos, Geyve, Köprühisar (Yenişehir), Marmaracık, Akhisar (Pamukova), Mekece, Kestel, Ulubat, Harmankaya, Akyazı, Insel İmralı, Kandıra, Mudanya, Yalova, Karamürsel, Armutlu, Gemlik (Kios), Söğüt, Bilecik, Eskişehir, Bursa, İznik, İzmit, Balıkesir, Çanakkale, Bergama, Amasya, Tokat, Çorlu, Lüleburgaz, Malkara, Keşan, İpsala, Kilitbahir, Çirmen, Stara Zagora (Eski Zağra), Tatarpazarcığı, İhtiman, Köstendil, Petriç, Nevrokop (Gotse Delčev), Drama, Gelibolu, Çimpe, Edirne, Dimetoka, Kırklareli, Tekirdağ, Plowdiw, Sofia, Niš, Vidin, Tarnowo, Warna, Schumen, Silistra, Nikopolis, Russe, Thessaloniki, Serres, Kavala, Skopje, Bitola, Ohrid, Yenişehir (Larissa), Tırhala, İzdin (Lamia), Plewen, Gümülcine, Biga, Domaniç, Kulacahisar, Karacahisar, Yarhisar, Dimbos, Kite (Kete), Lefke (Osmaneli), Leblebicihisar, Karaçepüş, Karatigin, Absu (Hypsu), Adranos (Orhaneli), Pelekanon (Eskihisar), Gebze, Hereke, Samandıra, Kirmasti (M.Kemalpaşa), Mihaliç (Karacabey), Konstanza, Gölyazı (Apollonia).", "d34e55d5"]},
"OLAYLAR:1413-07:0":{"b": ["Çelebi Mehmed stellt die Einheit wieder her", "03413dfd"], "d": ["Im letzten Abrechnungskampf unter den Brüdern besiegte Mehmed I. Musa Çelebi bei Çamurlu und vereinte das Land unter einer einzigen Herrschaft; deshalb gilt er als „zweiter Gründer des Staates“. Während seiner Herrschaft wurde die angeschlagene Staatsstruktur repariert, die Beziehungen zu den anatolischen Beyliks ausbalanciert und in Rumelien eine vorsichtige Friedenspolitik verfolgt.", "d8f535c2"]},
"OLAYLAR:1416-05-01:0":{"b": ["Aufstand des Scheich Bedreddin", "e0a072ca"], "d": ["Die religiös-soziale Bewegung um Scheich Bedreddin, einen bedeutenden Rechtsgelehrten und Mystiker, der im Interregnum (Fetret Devri) das Amt des Heeresrichters (Kazasker) bekleidet hatte, brach gleichzeitig mit den Aufständen des Börklüce Mustafa in Karaburun und des Torlak Kemal in Manisa aus. Die Aufstände wurden blutig niedergeschlagen; Bedreddin wurde im Deliorman gefangen genommen und in Serres hingerichtet. Als frühester großer sozial-mahdistischer Aufstand der osmanischen Geschichte hinterließ das Ereignis tiefe Spuren in Literatur und Geschichtsschreibung.", "1cf72ec4"]},
"OLAYLAR:1444-11-10:0":{"b": ["Sieg bei Warna", "f739eedc"], "d": ["Das ungarisch-polnische Kreuzfahrerheer, das den Vertrag von Szeged gebrochen hatte und nach Süden vorgestoßen war, wurde bei Warna von Murad II., der trotz seines Thronverzichts an die Spitze des Heeres zurückgekehrt war, vernichtet; der junge König Władysław III. fiel auf dem Schlachtfeld. Der Sieg beseitigte die letzte Chance einer großen äußeren Intervention zur Liquidierung der osmanischen Präsenz auf dem Balkan und sicherte den Weg zur Eroberung Konstantinopels.", "43adf0fb"]},
"OLAYLAR:1448-10-17:0":{"b": ["Zweite Schlacht auf dem Amselfeld", "ebe0b662"], "d": ["Das Heer des János Hunyadi, der Rache für Warna nehmen wollte, wurde in einer dreitägigen harten Schlacht von Murad II. endgültig geschlagen. Dies ist die letzte große Feldschlacht, die die Kreuzfahrer auf dem Balkan gegen die Osmanen wagten; mit dem Sieg festigte sich die osmanische Herrschaft südlich der Donau unumkehrbar.", "ea3ae23b"]},
"OLAYLAR:1453-05-29:0":{"b": ["Eroberung Konstantinopels", "583d5e3e"], "d": ["Nach einer 54 Tage währenden Belagerung (6. April–29. Mai 1453) überwand das osmanische Heer am Morgen des 29. Mai die Mauern und drang in die Stadt ein; der letzte Kaiser Konstantin XI. fiel in den Kämpfen, und das 1100 Jahre alte Oströmische Reich verschwand aus der Geschichte. Der junge Sultan nahm den Titel „Fâtih“ (Eroberer) an, machte die Stadt zur Hauptstadt und wandelte die Hagia Sophia in eine Moschee um; die Stadt wurde durch Besiedlung und Aufbau in kurzer Zeit wiederbelebt. Das Gießen riesiger Kanonen, das Überland-Ziehen von Schiffen und die Belagerungsanlagen vor den Mauern gelten als Höhepunkt der Militärtechnik der Zeit. Die Eroberung wird in der europäischen Geschichtsschreibung zu den Symboldaten für das Ende des Mittelalters gezählt.", "3664c5fe"]},
"OLAYLAR:1461-08-15:0":{"b": ["Eroberung von Trapezunt (Trabzon)", "15f52403"], "d": ["Am Ende des schwierigen Schwarzmeerfeldzugs, den Mehmed der Eroberer zu Land und zu Wasser gleichzeitig führte, ergab sich das Kaiserreich von Trapezunt; mit der Beseitigung dieses letzten Überrests der byzantinischen Welt in Anatolien kam die gesamte Südküste des Schwarzen Meeres unter osmanische Herrschaft. Das Ende der Dynastie der Komnenen bekräftigte den Anspruch Mehmeds, „Herrscher zweier Meere und zweier Länder“ zu sein. Zum selben Datum angeschlossene weitere Orte: Giresun, Rize.", "ca6ead13"]},
"OLAYLAR:1473-01-01:0":{"b": ["Endgültige Eroberung von Silifke – Brechung des letzten Widerstands der Karamaniden", "d988bee4"], "d": ["Die Burg Silifke hatte sich 1472 einmal Gedik Ahmed Pascha ergeben, war aber im selben Jahr von dem Karamaniden Kasım Bey mit Hilfe der Kreuzfahrerflotte im Mittelmeer zurückerobert worden. Nach dem Sieg von Otlukbeli beauftragte Mehmed der Eroberer seinen Sohn und Gedik Ahmed Pascha, die Region endgültig einzunehmen; mit Hilfe der erfahrenen osmanischen Artilleristen wurde das Pulverlager in Brand gesetzt und die Burg rasch zu Fall gebracht. Damit wurde der letzte Widerstand der Karamaniden in den Gebirgen von Taşeli und İçel gebrochen; die Liquidierung des Beylik sollte 1474 abgeschlossen werden.", "e9814184"]},
"OLAYLAR:1473-08-11:0":{"b": ["Schlacht von Otlukbeli", "42c7194e"], "d": ["Uzun Hasan, der Herrscher der Ak Koyunlu, der im Osten zu einer großen Macht geworden war und ein Bündnis mit Venedig geschlossen hatte, erlitt bei Otlukbeli gegen das mit Feuerwaffen ausgerüstete Heer Mehmeds des Eroberers eine schwere Niederlage. Der Sieg festigte die osmanische Überlegenheit in Anatolien; zugleich war er ein früher Beweis für die Überlegenheit eines zentralen Heeres, das Kanonen und Gewehre einsetzte, gegenüber dem klassischen Heer.", "9c59ac50"]},
"OLAYLAR:1475-06-06:0":{"b": ["Die Krim unter osmanischem Schutz", "44e3f7c8"], "d": ["Die Flotte unter dem Kommando Gedik Ahmed Paschas eroberte die südlichen Küstenstädte der Krim, allen voran das genuesische Kefe; diese Küsten wurden unmittelbar zum osmanischen Sandschak gemacht. Das Krim-Khanat unter Mengli Giray wurde dagegen zu einem privilegierten Vasallenstaat, der die osmanische Oberhoheit anerkannte, und blieb drei Jahrhunderte lang ein Grundpfeiler der Nordpolitik; das Schwarze Meer wurde faktisch zu einem osmanischen Binnenmeer. Zum selben Datum angeschlossene weitere Orte: Bahçesaray, Kertsch, Asow.", "a3448d71"]},
"OLAYLAR:1481-05-03:0":{"b": ["Tod Mehmeds des Eroberers – die Cem-Sultan-Affäre", "190ecf01"], "d": ["Nach dem plötzlichen Tod Mehmeds des Eroberers auf dem Feldzug bestieg Bayezid II. den Thron; sein Bruder Cem Sultan erhob Anspruch auf die Herrschaft und ließ in Bursa die Freitagspredigt (Hutbe) auf seinen Namen halten und Münzen prägen. Nach seiner Niederlage suchte er zunächst bei den Mamluken, dann bei den Johannitern (Rhodosrittern) Zuflucht; in den Händen der Ritter und des Papsttums zum Faustpfand der europäischen Diplomatie geworden, starb Cem 1495 in Neapel. Diese Affäre zwang die osmanische Außenpolitik fünfzehn Jahre lang zur Vorsicht.", "7e488d7b"]},
"OLAYLAR:1514-08:0":{"b": ["Sieg von Çaldıran", "fea64ebb"], "d": ["Selim I. (Yavuz), der die durch die safawidische Propaganda in Anatolien entstandene Bedrohung an der Wurzel lösen wollte, brachte dem Heer Schah İsmails auf der Ebene von Çaldıran dank der Überlegenheit seiner Kanonen und Gewehre eine schwere Niederlage bei. Täbris wurde betreten; Ost- und Südostanatolien sowie die Linie Mossul–Diyarbakır wurden der osmanischen Verwaltung angeschlossen. Die Anbindung der kurdischen Beys an die Osmanen durch das Bemühen von İdrîs-i Bitlisî legte den Rahmen der Ostgrenze fest, der Jahrhunderte währen sollte.", "67b03a64"]},
"OLAYLAR:1516-08-24:0":{"b": ["Sieg von Mercidabık", "07d254d3"], "d": ["Das mamlukische Heer wurde bei Mercidabık nördlich von Aleppo innerhalb weniger Stunden zerschlagen; der greise Sultan Kansu Gavri starb während der Schlacht. Mit dem Sieg, der die Tore Aleppos und Damaskus' weit öffnete, gingen Syrien, der Libanon und Palästina in osmanische Herrschaft über; der Weg für den Ägyptenfeldzug, der das Ende des Mamlukenstaates herbeiführen sollte, war frei.", "c4b15f39"]},
"OLAYLAR:1517-01-22:0":{"b": ["Ridaniye – Eroberung Ägyptens und Kalifat", "caf378d6"], "d": ["Das osmanische Heer, das die Sinai-Wüste rasch durchquert hatte, durchbrach bei Ridaniye die Verteidigungslinie Tomanbays und zog in Kairo ein; der weiterhin Widerstand leistende Tomanbay wurde gefangen genommen und hingerichtet, und der Mamlukenstaat verschwand aus der Geschichte. Ägypten, der Hedschas und die heiligen Städte kamen unter osmanische Herrschaft; der abbasidische Kalif und die heiligen Reliquien wurden nach Istanbul gebracht. Mit dem Übergang des Kalifats an die osmanische Dynastie übernahmen die Sultane den Anspruch auf die Führung der islamischen Welt; auch die Kontrolle über die Gewürzstraße brachte dem Reich große Einnahmen. Zum selben Datum angeschlossene weitere Orte: Akkon, Maan, Sidon, Kerak.", "a0cc8fdc"]},
"OLAYLAR:1520-09-30:0":{"b": ["Süleyman I., der Gesetzgeber, besteigt den Thron", "f6512269"], "d": ["Die 46-jährige Herrschaft Süleymans I., der nach dem Tod Selims als einziger männlicher Nachkomme auf den Thron kam, gilt als politischer, militärischer, rechtlicher und kultureller Höhepunkt des Reiches. Die Kanunnames, die das Gewohnheitsrecht (Örf) systematisierten, trugen ihm den Beinamen „Kanunî“ (der Gesetzgeber) ein; im Westen wurde er als „der Prächtige“ (Magnificent) bekannt. Die Werke des Baumeisters Sinan, das goldene Zeitalter der Diwan-Dichtung und die Überlegenheit der Flotte im Mittelmeer sind Symbole dieser Epoche.", "cda7a2fb"]},
"OLAYLAR:1521-08-29:0":{"b": ["Eroberung von Belgrad", "59ef5cec"], "d": ["Belgrad, das Mehmed der Eroberer 1456 nicht hatte einnehmen können und das als „Schlüssel Mitteleuropas“ galt, fiel auf Süleymans erstem Feldzug nach einer Belagerung am Zusammenfluss von Donau und Save. Damit war die südliche Verteidigungslinie Ungarns zusammengebrochen; mit dieser Eroberung öffnete sich das Tor zu den mitteleuropäischen Feldzügen, die fünf Jahre später nach Mohács und zwanzig Jahre später zur Annexion Budas führen sollten.", "69dbb7cc"]},
"OLAYLAR:1522-12-21:0":{"b": ["Eroberung von Rhodos", "807bbb1e"], "d": ["Rhodos, der Stützpunkt der Johanniter (Ritter von Saint-Jean), die die Seewege des östlichen Mittelmeers und die Pilgerroute bedrohten, ergab sich nach einer monatelangen blutigen Belagerung durch Kapitulationsvertrag; den Rittern wurde der freie Abzug von der Insel gestattet (später ließen sie sich in Malta nieder). Die Sicherheit der anatolischen Küsten war gewährleistet, und die Seeverbindung Istanbul–Ägypten kam unter ununterbrochene osmanische Kontrolle.", "aeedfb16"]},
"OLAYLAR:1526-08-29:0":{"b": ["Schlacht von Mohács", "f3418b0d"], "d": ["Das ungarische Heer wurde auf der Ebene von Mohács in etwa zwei Stunden durch Kanonenfeuer und überlegene Manöver vernichtet; König Ludwig II. (Lajos II.) kam auf der Flucht im Sumpf um. Mohács, eine der am schnellsten gewonnenen großen Feldschlachten der osmanischen Geschichte, beendete faktisch das unabhängige ungarische Königreich und eröffnete in Mitteleuropa das Zeitalter der osmanisch-habsburgischen Rivalität.", "48967894"]},
"OLAYLAR:1529-09:0":{"b": ["Erste Belagerung Wiens", "dc49ea4f"], "d": ["Bei dem Feldzug gegen den Griff der Habsburger nach dem ungarischen Thron belagerte das osmanische Heer Wien; wegen der auf dem Weg zurückgelassenen schweren Kanonen, des früh einsetzenden Winters und der Versorgungsschwierigkeiten wurde die Belagerung nach drei Wochen aufgehoben. Obwohl die Stadt nicht eingenommen werden konnte, blieb der osmanische Einfluss auf Ungarn erhalten; das Vorfeld Wiens markierte die logistische Reichweitengrenze des Reiches in Mitteleuropa.", "a49fc760"]},
"OLAYLAR:1534-12-04:0":{"b": ["Eroberung Bagdads – Irakeyn-Feldzug", "897092c3"], "d": ["Auf dem Feldzug gegen die „beiden Irak“ (Irak-ı Arap und Irak-ı Acem) wurde zunächst Täbris, dann kampflos Bagdad betreten; die Einnahme der alten Hauptstadt der Abbasiden verschaffte dem osmanischen Herrscher in der islamischen Welt hohes Ansehen. Das Mausoleum des Imam-ı Âzam Ebû Hanîfe wurde wiederhergestellt; mit dem Anschluss Bagdads und Basras reichte das osmanische Gebiet bis zum Persischen Golf. Zum selben Datum angeschlossene weitere Orte: Kirkuk, Kerbela.", "f3f80434"]},
"OLAYLAR:1538-09:0":{"b": ["Seesieg von Preveza", "30dc0f97"], "d": ["Die auf Initiative des Papstes gebildete Kreuzfahrerflotte wurde trotz zahlenmäßiger Überlegenheit durch Barbarossas Taktik, die Wind und Küste geschickt nutzte, vor Preveza zerstreut; Andrea Doria verließ das Schlachtfeld. Der Sieg begründete die unbestrittene osmanische Seeüberlegenheit im Mittelmeer, die etwa 33 Jahre währen sollte; in der türkischen Seefahrtstradition ist er das Symboldatum des Tages der Marine. Zum selben Datum angeschlossene weitere Orte: Aden, Bender.", "0411d92f"]},
"OLAYLAR:1541-08-29:0":{"b": ["Annexion Budas – Ungarn wird osmanische Provinz", "db53b244"], "d": ["Süleyman, der auf die Belagerung Budas durch die Habsburger hin zum Feldzug aufgebrochen war, befreite die Stadt, nahm Mittelungarn anschließend unmittelbar unter osmanische Verwaltung und gründete das Beylerbeylik Buda; Siebenbürgen wurde zu einem autonomen, den Osmanen untergeordneten Fürstentum gemacht. Diese dreigeteilte Ordnung Ungarns währte etwa 150 Jahre und bildete das dauerhafte Verwaltungsgerüst der Osmanen in Mitteleuropa.", "1eb63e33"]},
"OLAYLAR:1555-05-29:0":{"b": ["Frieden von Amasya", "a5afe0d1"], "d": ["Er ist der erste förmliche Friedensvertrag, der die jahrelangen osmanisch-safawidischen Kriege beendete. Bagdad und der Irak blieben bei den Osmanen, die Grenze in Ostanatolien wurde erstmals gegenseitig anerkannt; die Safawiden verpflichteten sich, die schiitische Propaganda im osmanischen Land einzustellen, die Osmanen, die Sicherheit der Durchreise persischer Pilger zu gewährleisten. Der Vertrag wurde zum ersten Beispiel für den rechtlichen Rahmen der Beziehungen zwischen den beiden Staaten.", "220b198f"]},
"OLAYLAR:1566-09-07:0":{"b": ["Szigetvár – Tod Süleymans I.", "e2917ed2"], "d": ["Der 72-jährige Süleyman starb auf seinem dreizehnten Feldzug in seinem Zelt (Otağ) wenige Stunden vor dem Fall der belagerten Festung Szigetvár; Sokollu Mehmed Pascha hielt den Tod wochenlang geheim, damit das Heer nicht auseinanderfiel. Die Festung wurde eingenommen, doch der Staat hatte seinen am längsten regierenden und glanzvollsten Sultan verloren; sein Sohn Selim II. bestieg den Thron, und das Gewicht der Großwesire in der Staatsführung begann zuzunehmen.", "62c468a1"]},
"OLAYLAR:1571-08:0":{"b": ["Eroberung Zyperns", "e364a2b3"], "d": ["Auf dem von Venedig beherrschten Zypern wurde 1570 gelandet; Nikosia fiel rasch, Famagusta ergab sich erst nach elfmonatiger Belagerung im August 1571. Die für die Sicherheit der Handels- und Pilgerwege des östlichen Mittelmeers entscheidende Insel wurde als Beylerbeylik organisiert, und Bevölkerung aus Anatolien wurde angesiedelt; die Eroberung wurde auch zum Anlass des großen Kreuzfahrerbündnisses, das bis zur Schlacht von Lepanto (İnebahtı) führen sollte.", "6dcfdc0f"]},
"OLAYLAR:1571-10-07:0":{"b": ["Niederlage von Lepanto (İnebahtı)", "6a1d44a9"], "d": ["Die wegen der Eroberung Zyperns vereinte Kreuzfahrerflotte stellte die osmanische Flotte im Golf von İnebahtı und vernichtete den größten Teil; der Kapudan Pascha Müezzinzâde Ali Pascha fiel, nur die Flotte Uluç Alis konnte entkommen. Nach der Katastrophe betraute Großwesir Sokollu Mehmed Pascha Uluç Ali Pascha mit dem Amt des Kapudan Pascha und damit, die zerstreute Flotte zu sammeln, und ließ in allen Werften von Istanbul bis Alanya den Bau einer neuen Flotte beginnen; doch die absolute Überlegenheit im Mittelmeer war psychologisch erschüttert.", "4cb5c93e"]},
"OLAYLAR:1596-10-26:0":{"b": ["Schlacht von Haçova", "da308ec5"], "d": ["In der größten Feldschlacht des Langen Krieges (1593–1606) sammelte sich das Heer unter dem persönlich anwesenden Mehmed III. in dem Augenblick, als es sich aufzulösen drohte, auf Zureden von Hoca Sâdeddin Efendi und schlug das Habsburger Heer in die Flucht. Sie gilt als die letzte große klassische Feldschlacht, die die Osmanen gewannen; doch dass sie den Gesamtverlauf des Krieges nicht änderte, wurde auch als Zeichen der Abnutzung des Militärsystems gewertet.", "77f2a384"]},
"OLAYLAR:1606-11-11:0":{"b": ["Frieden von Zsitvatorok", "39c01142"], "d": ["Mit dem Vertrag, der den dreizehnjährigen zermürbenden Krieg beendete, wurde der Habsburger Herrscher erstmals mit dem Titel „Römischer Kaiser“ als dem Sultan ebenbürtig anerkannt, und der jährliche Tribut wurde aufgehoben. Der Gebietsverlust war nahezu unbedeutend; doch dieser Wandel der diplomatischen Sprache wird als Symbol dafür gelesen, dass der Anspruch der Osmanen auf absolute Überlegenheit gegenüber Europa zu Ende ging.", "99a455e7"]},
"OLAYLAR:1639-05-17:0":{"b": ["Vertrag von Kasr-ı Şirin", "c1acf3af"], "d": ["Der nach der Rückeroberung Bagdads durch Murad IV. (1638) unterzeichnete Vertrag beendete die mehr als hundertjährigen osmanisch-safawidischen Kriege. Bagdad und der Irak blieben endgültig bei den Osmanen, Eriwan (Revan) wurde den Safawiden überlassen; die gezogene Linie wurde mit geringen Änderungen zur Grundlage der heutigen türkisch-iranischen Grenze und gilt als eine der langlebigsten Grenzen der Welt. Der Vertrag überließ den Osmanen Bedre, Cessân, Mendelî, Derteng und Derne; die Festung Zencir an der Grenze sollte zerstört werden, die Dörfer westlich davon sollten den Osmanen, die östlich davon Iran zufallen. Das Gebiet um die Festung Zalim bei Şehrizor und Kızılca Kale blieben bei den Osmanen, Avroman und Mihriban bei Iran; die Festungen Kotur, Mâkû und Mağazberd sollten von beiden Seiten zerstört werden.", "c2d59f3f"]},
"OLAYLAR:1669-09-06:0":{"b": ["Eroberung Kretas abgeschlossen", "e0d85604"], "d": ["Die Belagerung von Candia (Kandiye), der letzte Akt des 1645 begonnenen Kretakrieges, endete mit der dreijährigen entschlossenen Operation Fâzıl Ahmed Paschas; der venezianische Befehlshaber Morosini übergab die Stadt durch Vertrag. Der etwa ein Vierteljahrhundert währende Kampf ging als längste Belagerung der osmanischen Geschichte in die Annalen ein; auch die letzte große lateinische Festung des östlichen Mittelmeers kam unter osmanische Herrschaft. Die drei kleinen Felsenfestungen an der Nordküste der Insel — Suda, Spinalonga und Granbosa — blieben noch in venezianischem Besitz; da sie auf getrennten Inselchen liegen, können sie auf der Karte nicht vom Rest Kretas getrennt dargestellt werden.", "314efa97"]},
"OLAYLAR:1672-10-18:0":{"b": ["Vertrag von Bucaş – größte Ausdehnung", "b17b6e5a"], "d": ["Mit dem nach der Eroberung von Kamaniçe auf dem Polenfeldzug unterzeichneten Vertrag von Bucaş kam Podolien an die Osmanen, und ein Teil der Ukraine wurde unter Schutz gestellt. Das Reich erreichte damit seine größte Ausdehnung in Europa; dieser Punkt gilt als Höhepunkt und zugleich letztes Glied des Zeitalters der Expansion.", "6d489670"]},
"OLAYLAR:1683-09-12:0":{"b": ["Scheitern der Zweiten Belagerung Wiens", "7d889252"], "d": ["Die zwei Monate währende Belagerung Wiens durch Kara Mustafa Pascha von Merzifon endete mit dem plötzlichen Schlag, den der polnische König Jan Sobieski von den Höhen des Kahlenbergs herab führte, in einer Niederlage; das Heer zog unter Zurücklassung seines Trosses ab, Merzifonlu wurde in Belgrad hingerichtet. Der Krieg mit der nach dem Sieg gegründeten Heiligen Liga dauerte 16 Jahre; dieses Scheitern wird als Beginn des großen Niedergangs in der osmanischen Geschichte angeführt.", "88ceb19f"]},
"OLAYLAR:1692-01-01:0":{"b": ["Eroberung der Festung Granbosa – eine der in venezianischem Besitz verbliebenen Felsenfestungen Kretas", "3ddf9eeb"], "d": ["Obwohl die Eroberung Kretas mit der Übergabe Candias 1669 weitgehend als abgeschlossen galt, blieb die Felseninselfestung Granbosa an der Nordwestspitze der Insel noch dreiundzwanzig Jahre in venezianischer Hand. Mit ihrer Einnahme 1692 wurde eine der drei venezianischen Überreste auf Kreta beseitigt; Suda und Spinalonga sollten den Morea-Feldzug von 1715 abwarten.", "05e94fe9"]},
"OLAYLAR:1699-01-26:0":{"b": ["Frieden von Karlowitz – erster großer Gebietsverlust", "8f7e2546"], "d": ["Mit Karlowitz, das die sechzehnjährigen Kriege der Heiligen Liga beendete, wurden Ungarn und Siebenbürgen an Österreich, Podolien an Polen, Morea und die dalmatinischen Küsten an Venedig abgetreten. Zum ersten Mal in der osmanischen Geschichte ging Land in diesem Ausmaß am Verhandlungstisch und dauerhaft verloren; der Vertrag gilt als Urkunde des Beginns einer neuen Ära, in der das Reich gegenüber Europa in die Defensive ging, und ist zugleich ein Wendepunkt der osmanischen Diplomatiegeschichte.", "54bb2eee"]},
"OLAYLAR:1711-07-19:0":{"b": ["Sieg am Pruth", "2583572f"], "d": ["In dem Krieg, der wegen der Frage des nach der Niederlage von Poltawa zu den Osmanen geflohenen schwedischen Königs ausbrach, wurde das Heer Zar Peters I. am Pruth eingekesselt und musste sich ergeben. Durch den unterzeichneten Vertrag wurde Azak (Asow) zurückgewonnen; dass das Heer nicht vernichtet und der Zar freigelassen wurde, ging als bis heute umstrittene Entscheidung in die Geschichte ein.", "ce9c2996"]},
"OLAYLAR:1715-01-01:0":{"b": ["Eroberung der Festungen Suda und Spinalonga – Tilgung der letzten venezianischen Spur auf Kreta", "7261f7ba"], "d": ["Dreiundzwanzig Jahre nach dem Fall Granbosas 1692 wurden im Zuge eines Nebenarms des Morea-Feldzugs auch die letzten beiden Stützpunkte Venedigs auf Kreta, die Festungen Suda und Spinalonga, erobert. Damit war die 1645 begonnene Eroberung Kretas nach sechsundvierzig Jahren bis zum letzten Zentimeter der Insel abgeschlossen.", "d2044cae"]},
"OLAYLAR:1730-09-25:0":{"b": ["Aufstand des Patrona Halil", "100941a4"], "d": ["Die Misserfolge an der iranischen Front, die Steuern und der Zorn über den Luxus am Hof entluden sich unter Führung des Badehaus-Masseurs Patrona Halil in einem großen Aufstand. Großwesir İbrahim Pascha wurde getötet, Ahmed III. abgesetzt, und die Tulpenzeit (Lâle Devri) ging zu Ende; dass die Aufständischen monatelang über die Stadt geboten, zeigte auf eindrucksvolle Weise die Zerbrechlichkeit der Zentralgewalt.", "d87eea77"]},
"OLAYLAR:1739-09-18:0":{"b": ["Vertrag von Belgrad – Rückgewinnung von Belgrad, Semendria und Nordserbien", "ba7f8e46"], "d": ["Am Ende des an zwei Fronten gegen Österreich und Russland geführten Krieges (1736–1739) wurden Belgrad und Nordserbien zurückgewonnen; Russland willigte ein, Azak (Asow) zu entwaffnen und keine Flotte im Schwarzen Meer zu unterhalten. Der Vertrag, der als der letzte große Erfolg der osmanischen Diplomatie und Armee im 18. Jahrhundert gilt, verschaffte dem Reich eine Friedenszeit von einem Vierteljahrhundert.", "5b399dd2"]},
"OLAYLAR:1770-07-06:0":{"b": ["Überfall von Çeşme", "840b30bd"], "d": ["Die mit englischer Unterstützung ins Mittelmeer vorgestoßene russische Flotte überfiel die im Hafen von Çeşme Zuflucht suchende osmanische Flotte mit Brandschiffen und verbrannte sie nahezu vollständig. Russland trat erstmals als große Seemacht im Mittelmeer auf; die Katastrophe war einer der Schläge, die das Schicksal des Krieges bis zum Frieden von Küçük Kaynarca 1774 bestimmten, und machte die Notwendigkeit einer grundlegenden Reform der Flotte offenkundig.", "5b133a56"]},
"OLAYLAR:1774-07-21:0":{"b": ["Vertrag von Küçük Kaynarca", "2776dcdb"], "d": ["Mit Küçük Kaynarca, das den Krieg von 1768–1774 beendete und zu den schwersten Verträgen der osmanischen Geschichte zählt, wurde dem Krim-Khanat die „Unabhängigkeit“ gewährt — faktisch wurde damit eine russische Einflusssphäre geschaffen. Russland setzte sich an der Schwarzmeerküste fest, erhielt für Handelsschiffe das Recht zur Durchfahrt durch die Meerengen und eine ständige Botschaft in Istanbul; die vage Schutzklausel über die orthodoxen Untertanen öffnete die Tür zu den Interventionsvorwänden des folgenden Jahrhunderts. Zum ersten Mal wurde ein Land mit muslimischer Bevölkerung aus der osmanischen Herrschaft gelöst.", "b677ebfc"]},
"OLAYLAR:1783-04-19:0":{"b": ["Annexion der Krim durch Russland", "bdf6faa8"], "d": ["Die durch Küçük Kaynarca geschaffene „unabhängige“ Krim wurde unter dem Vorwand der Wirren in der Zeit des letzten Khans Şahin Giray durch ein Manifest Katharinas II. von Russland annektiert. Die dreihundertjährige osmanisch-krimische Verbindung endete; der Verlust der nördlichen Steppen beseitigte die Verteidigungstiefe Istanbuls und löste die erste große Welle der Auswanderung von Zehntausenden Krimtataren auf osmanisches Gebiet aus.", "8d4fcb03"]},
"OLAYLAR:1789-04:0":{"b": ["Selim III. und das Nizâm-ı Cedîd", "d53aec21"], "d": ["Der mitten im Krieg auf den Thron gelangte Selim III. erkannte, dass die Niederlagen struktureller Natur waren, und leitete unter dem Namen „Nizâm-ı Cedîd“ (Neue Ordnung) ein umfassendes Reformprogramm ein: ein neues, nach europäischem Muster gedrilltes Heer, eine eigene Schatzkammer zu dessen Finanzierung (Îrâd-ı Cedîd), die Stärkung der Ingenieurschulen und die ersten ständigen Botschaften in den europäischen Hauptstädten. Das Programm gilt als Beginn der modernen türkischen Reformtradition; doch es sollte 1807 am Widerstand der Korps und der Notabeln (Âyân) scheitern.", "87394990"]},
"OLAYLAR:1798-06-12:0":{"b": ["Auflösung der Malteserritter – Zwischenstation der französischen Flotte", "d62f901d"], "d": ["Die nach Ägypten fahrende französische Flotte lief Malta an; die Ritter von St. Johann (Malta) übergaben die Insel ohne großen Widerstand. Die Festung des Ritterordens, der 1522 aus Rhodos vertrieben worden war und sich hier niedergelassen hatte, ging damit unter. Malta sollte zwei Jahre später in englische Hand fallen, Napoleon wandte sich von der Insel unmittelbar nach Alexandria.", "aac1fe49"]},
"OLAYLAR:1798-07-01:0":{"b": ["Napoleons Besetzung Ägyptens", "93fede5f"], "d": ["Das Heer General Bonapartes landete in Alexandria und besetzte Ägypten; dieser auf den Weg Englands nach Indien zielende Feldzug war der erste unmittelbare Angriff einer europäischen Macht auf das Kernland der Osmanen. Nelsons Überfall bei Abukir und Cezzâr Ahmed Paschas Verteidigung von Akkon brachen den französischen Vormarsch; die Besetzung endete 1801, doch in der von ihr hinterlassenen Leere begann der Aufstieg des Mehmed Ali Pascha aus Kavala und das Zeitalter der „Orientalischen Frage“.", "b1ca7226"]},
"OLAYLAR:1808-10-07:0":{"b": ["Sened-i İttifak", "cce49ef5"], "d": ["Die Urkunde, die unter Führung des Ajans von Rusçuk Alemdar Mustafa Pascha, der Mahmud II. auf den Thron gebracht hatte, zwischen dem Hof und den mächtigen Notabelnfamilien der Provinz unterzeichnet wurde; die Notabeln verpflichteten sich zu Treue gegenüber dem Sultan und zur Truppenhilfe, während der Staat ihre Existenz und Rechte anerkannte. Da es das erste Beispiel in der osmanischen Geschichte war, dass die Autorität des Sultans durch ein Dokument beschränkt wurde, gilt sie manchen Historikern als ferner Anfang der konstitutionellen Tradition; faktisch wurde sie binnen weniger Monate wirkungslos.", "2d97fdfe"]},
"OLAYLAR:1821-03-25:0":{"b": ["Beginn des griechischen Aufstands", "a7293715"], "d": ["Der von der Organisation Filiki Eteria vorbereitete Aufstand brach zuerst in der Walachei, dann mit seiner eigentlichen Stärke auf der Morea aus; der mit der Affäre des Ali Pascha von Tepedelen beschäftigte Staat reagierte zunächst verspätet. Dank der starken griechenfreundlichen Stimmung in der europäischen Öffentlichkeit (Philhellenismus) wurde der Aufstand rasch zu einer internationalen Sache; so wurde die Lunte der ersten erfolgreichen Unabhängigkeitsbewegung des Zeitalters des Nationalismus auf osmanischem Boden gezündet. Zum selben Datum verlorene weitere Siedlungen: Athen, Balyabadra (Patras), İstefe (Theben), Livadya.", "316e2ac7"]},
"OLAYLAR:1826-06-15:0":{"b": ["Vaka-i Hayriyye – Auflösung des Janitscharenkorps", "08c9372a"], "d": ["Die Janitscharen, die gegen die Übungen des neu gegründeten Eşkinci-Korps rebellierten (die Kessel umstießen), wurden vom im Voraus vorbereiteten Kanonenfeuer der loyalen Truppen Mahmuds II. in ihren Kasernen am Etmeydanı vernichtet; das Korps wurde mit allen Zweigen und den angeschlossenen Bektaschi-Tekken aufgelöst. Diese unter dem Namen „glückliches Ereignis“ (Vaka-i Hayriyye) in die Geschichte eingegangene Operation beseitigte die vierhundertjährige Institution und ebnete den Weg für das Heer der Asâkir-i Mansûre-i Muhammediyye und alle späteren Zentralisierungsreformen.", "9ee152dd"]},
"OLAYLAR:1827-10-20:0":{"b": ["Überfall von Navarino", "ee579e7f"], "d": ["Die osmanisch-ägyptische Flotte, die den griechischen Aufstand niederzuschlagen im Begriff war, wurde in Navarino von der ohne Kriegserklärung in den Hafen eingelaufenen vereinten englisch-französisch-russischen Flotte verbrannt; fast sechzig Schiffe und Tausende Seeleute gingen verloren. Der in der europäischen Diplomatie als „unglücklicher Zwischenfall“ abgetane Überfall sicherte faktisch die griechische Unabhängigkeit und ebnete den Weg zum osmanisch-russischen Krieg von 1828–29.", "0d4b2c6f"]},
"OLAYLAR:1839-11-03:0":{"b": ["Erlass von Gülhane (Tanzimat-Ferman)", "5042ce7b"], "d": ["Mit dem in Gülhane verlesenen Hatt-ı Hümayun wurde die Sicherheit von Leben, Eigentum und Ehre aller Untertanen ohne Ansehen der Religion unter staatliche Garantie gestellt; die Grundsätze der Steuergerechtigkeit, der Ordnung im Militärdienst und des Verbots von Strafen ohne Gerichtsverfahren wurden verkündet. Der Ferman, ein Werk Mustafa Reşid Paschas, gilt als das erste große Dokument der osmanischen Modernisierung mit verfassungsähnlichem Charakter und gab dem Reformzeitalter „Tanzimat-Zeit“ (1839–1876) seinen Namen; in diesem Rahmen wurden Verwaltung, Recht, Bildung und Finanzwesen grundlegend umgestaltet.", "6ace4b82"]},
"OLAYLAR:1853-10-04:0":{"b": ["Beginn des Krimkrieges", "3b9ca3c8"], "d": ["Die mit der Frage der Heiligen Stätten und Russlands Schutzanspruch über die orthodoxen Untertanen begonnene Krise mündete in offenen Konflikt, als die Osmanen den Krieg erklärten; nach dem Überfall von Sinop traten England und Frankreich (später Piemont) auf osmanischer Seite in den Krieg ein. Der Krieg wurde, nachdem die alliierten Heere auf der Krim gelandet waren und Sewastopol genommen hatten, mit dem Pariser Frieden 1856 als Sieg beendet; doch die in den Kriegsjahren aufgenommene erste Auslandsschuld (1854) führte das Reich in eine ein halbes Jahrhundert währende Spirale finanzieller Abhängigkeit.", "bae16135"]},
"OLAYLAR:1856-02-18:0":{"b": ["Reformedikt (Islahat Fermanı)", "78ff234d"], "d": ["Der vor den Pariser Friedensverhandlungen verkündete Ferman erweiterte die Grundsätze der Tanzimat und gewährte den nichtmuslimischen Untertanen umfassende Gleichheitsrechte, darunter das Recht auf Staatsämter, Militärdienst und Schulgründungen; die Gemeindeorganisationen wurden neu geordnet. Mit dem anschließend unterzeichneten Pariser Frieden wurde das Osmanische Reich offiziell in die Familie des europäischen Völkerrechts aufgenommen und seine territoriale Integrität unter die gemeinsame Garantie der Großmächte gestellt — diese Garantie sollte in der Praxis zu einer neuen Tür für Interventionen werden.", "cfe6d847"]},
"OLAYLAR:1876-12-23:0":{"b": ["Kanûn-ı Esâsî – Erste Konstitutionelle Ära", "0fe052c1"], "d": ["Am Eröffnungstag der in Istanbul zur Erörterung der Balkankrise zusammengetretenen internationalen Konferenz wurde mit Kanonenschüssen die erste osmanische Verfassung verkündet; mit dem Kanûn-ı Esâsî, einem Werk der Bewegung der „Jungosmanen“ unter Führung Midhat Paschas, wurde ein Zweikammerparlament geschaffen. Das Meclis-i Meb'ûsan (Abgeordnetenhaus) wurde im März 1877 eröffnet; doch Abdülhamid II. vertagte das Parlament im Februar 1878 mit Verweis auf den „Krieg von 93“ auf unbestimmte Zeit, und die Verfassung blieb dreißig Jahre ausgesetzt.", "c0f01a41"]},
"OLAYLAR:1877-04:0":{"b": ["Krieg von 93 (Osmanisch-Russischer Krieg 1877–78)", "5bd96af7"], "d": ["In dem Krieg, der „Krieg von 93“ genannt wird, weil er in das Jahr 1293 der Rumi-Zeitrechnung fiel, griffen die russischen Heere an zwei Fronten an; obwohl Gazi Osman Paschas Verteidigung von Plewen und Ahmed Muhtar Paschas Gefechte im Kaukasus legendär wurden, brach die Front zusammen, und die Russen rückten bis Yeşilköy (Ayastefanos) vor. Der Krieg löste die großen, von den Balkanländern und dem Kaukasus nach Istanbul gerichteten muslimischen Migrationswellen aus, deren Folgen bis heute reichen; die demografische und finanzielle Struktur des Reiches konnte sich nie wieder erholen.", "3a2b2296"]},
"OLAYLAR:1878-07-13:0":{"b": ["Berliner Vertrag", "47f76a49"], "d": ["Der Berliner Kongress, der das durch Ayastefanos geschaffene „Großbulgarien“ im Namen des Gleichgewichts der Großmächte revidierte, hinterließ dennoch ein schweres Bild: Serbien, Montenegro und Rumänien wurden unabhängig; das autonome Fürstentum Bulgarien wurde gegründet; Bosnien-Herzegowina wurde der österreichischen Besetzung, Zypern der britischen Verwaltung, Kars–Ardahan–Batum Russland überlassen. Die fünfhundertjährige osmanische Ordnung in Rumelien löste sich weitgehend auf; die „Orientalische Frage“ wurde zum ständigen Thema der europäischen Diplomatie. Zum selben Datum verlorene weitere Siedlungen: Plowdiw, Vidin, Tarnowo, Warna, Schumen, Silistra, Russe, Bukarest, Iași, Konstanza.", "076697b6"]},
"OLAYLAR:1881-05-12:0":{"b": ["Besetzung von Tunis und die Düyûn-ı Umûmiyye", "c7e25598"], "d": ["Frankreich besetzte Tunis unter dem Vorwand der Vorfälle an der algerischen Grenze und stellte es mit dem Vertrag von Bardo unter sein Protektorat; die osmanische Präsenz in Nordafrika schrumpfte auf Tripolitanien. Mit dem im selben Jahr erlassenen Muharrem-Dekret wurde zur Verwaltung der bankrotten Auslandsschulden die Düyûn-ı Umûmiyye (Verwaltung der Öffentlichen Schuld) geschaffen, in der die Gläubiger vertreten waren: grundlegende Einnahmen wie Salz, Tabak und Seide wurden unmittelbar dieser ausländischen Verwaltung unterstellt, und die finanzielle Souveränität wurde schwer eingeschränkt. Zum selben Datum verlorene weitere Siedlungen: Kairouan, Gabès, Sfax, Djerba.", "64f23b86"]},
"OLAYLAR:1882-09:0":{"b": ["Britische Besetzung Ägyptens", "f1269768"], "d": ["Die gegen den Staatsbankrott und die ausländische Kontrolle in Ägypten erstarkte Bewegung Urâbî Paschas wurde nach der Bombardierung Alexandrias durch den Sieg der gelandeten britischen Armee bei Tel el-Kebir zerschlagen, und Kairo wurde besetzt. Obwohl Ägypten rechtlich weiter an die Osmanen gebunden blieb, kam es faktisch unter britische Verwaltung; die Kontrolle über den Sueskanal rückte ins Zentrum der britischen Imperialstrategie.", "b7bcf2d2"]},
"OLAYLAR:1908-07-23:0":{"b": ["Ausrufung der Zweiten Konstitutionellen Ära", "95ee2fd2"], "d": ["Angesichts der Bewegung, die durch den Gang der dem Komitee für Einheit und Fortschritt (İttihat ve Terakki Cemiyeti) angehörenden Offiziere in die Berge Makedoniens gewachsen war, setzte Abdülhamid II. den Kanûn-ı Esâsî wieder in Kraft; die „Ausrufung der Freiheit“ wurde mit Begeisterung aufgenommen, und es kam zu Wahlen. Doch Stabilität stellte sich nicht ein: Nach der Niederschlagung des Vorfalls vom 31. März (April 1909) wurde Abdülhamid abgesetzt; auch die Unabhängigkeit Bulgariens, die Annexion Bosniens und die Hinwendung Kretas zu Griechenland fielen in diese bewegten Monate.", "370f359f"]},
"OLAYLAR:1911-09-29:0":{"b": ["Tripolitanienkrieg", "ed441994"], "d": ["Das nach Kolonien strebende Italien erklärte Tripolitanien, dem letzten Besitz der Osmanen in Nordafrika, den Krieg und besetzte die Küsten; da der Staat ohne Flotte kein reguläres Heer entsenden konnte, gelangten junge Offiziere wie Mustafa Kemal und Enver Bey heimlich in die Region und organisierten mit den Senussi-Stämmen einen wirksamen Widerstand. Mit dem wegen des Ausbruchs des Balkankrieges unterzeichneten Vertrag von Uşi (Ouchy) (18. Oktober 1912) wurde Libyen an Italien abgetreten; Italien besetzte zudem Rhodos und die Zwölf Inseln (Dodekanes).", "9820482a"]},
"OLAYLAR:1913-05-30:0":{"b": ["Londoner Vertrag – Verlust Rumeliens", "f3f976df"], "d": ["Mit dem Londoner Vertrag, der den Ersten Balkankrieg beendete, gingen alle Gebiete westlich der Linie Midye–Enez und die Ägäisinseln verloren; Albanien wurde unabhängig. Von Rumelien, über mehr als fünfhundert Jahre demografisches, wirtschaftliches und kulturelles Schwerpunktzentrum des Reiches, sollte nur Ostthrakien bleiben (Edirne wurde im Zweiten Balkankrieg zurückgewonnen); der Verlust verschärfte die Kriegs- und Ansiedlungspolitik der unionistischen Führung (İttihat ve Terakki) grundlegend.", "077da59d"]},
"OLAYLAR:1914-11-01:0":{"b": ["Eintritt in den Ersten Weltkrieg", "05a0252e"], "d": ["Dass die vor England geflohenen Schlachtschiffe Goeben und Breslau als angekauft dargestellt und in die Meerenge hereingelassen wurden, zog den Staat Schritt für Schritt an die Seite Deutschlands; mit der Beschießung russischer Häfen durch die Flotte unter Admiral Souchon (29. Oktober) begann der Krieg faktisch, die gegenseitigen Erklärungen folgten Anfang November. Trotz der Ausrufung des Cihâd-ı Ekber (Großer Dschihad) blieb die erwartete Wirkung aus; das Reich geriet für vier Jahre an fünf verschiedenen Fronten vom Kaukasus bis Palästina in einen Existenzkampf.", "a9f179e7"]},
"OLAYLAR:1915-03-18:0":{"b": ["Sieg bei Çanakkale (Dardanellen)", "95d888e8"], "d": ["Die alliierte Armada, die Istanbul zu Fall bringen und Russland erreichen wollte, wurde am 18. März durch das Feuer der Minensperren und Küstenbatterien aus der Meerenge zurückgeschlagen; die vom Minenleger Nusret gelegte Sperre bestimmte das Schicksal der Schlacht. Auch die im April begonnene Landoperation auf Gelibolu wurde bei Anafartalar und Conkbayırı gestoppt; die Alliierten räumten die Halbinsel im Januar 1916 vollständig. Der Name von Oberstleutnant Mustafa Kemal wurde an dieser Front bekannt; der mit etwa einer Viertelmillion Gefallenen und Vermissten errungene Sieg gilt als Geburtsort der Kader und des Geistes des Nationalen Befreiungskampfes (Millî Mücadele).", "005303c3"]},
"OLAYLAR:1916-06-10:0":{"b": ["Aufstand des Scherifen Hussein", "75f7c58c"], "d": ["Der Emir von Mekka, Scherif Hussein, erhob sich nach einem geheimen Briefwechsel mit den Briten mit dem Versprechen eines unabhängigen arabischen Königreichs; die Hedschas-Bahn wurde zum Ziel von Überfällen. Fahreddin Paschas legendäre, bis nach dem Waffenstillstand andauernde Verteidigung Medinas blieb zwar ein Symbol des Widerstands, doch der Aufstand beschleunigte im Verbund mit dem britischen Vormarsch an der Palästinafront den Zerfall der osmanischen Herrschaft in den arabischen Provinzen. Zum selben Datum verlorene weitere Siedlungen: Tâif.", "a0e859bd"]},
"OLAYLAR:1918-10-30:0":{"b": ["Waffenstillstand von Mudros", "9e87c767"], "d": ["Das durch den Zusammenbruch Bulgariens an den Fronten voneinander abgeschnittene Osmanische Reich schied durch den an Bord des Schlachtschiffs Agamemnon unterzeichneten Waffenstillstand aus dem Krieg aus. Die Öffnung der Meerengen und insbesondere Artikel 7, der die Besetzung bei Gefährdung der Sicherheit zulassen sollte, wurde rasch zum rechtlichen Deckmantel der faktischen Aufteilung: Mossul, İskenderun, danach İzmir und Istanbul wurden besetzt. Der Waffenstillstand gilt als Dokument des faktischen Endes des Reiches. Zum selben Datum verlorene weitere Siedlungen: Hama, Damaskus, Homs.", "261b57f2"]},
"OLAYLAR:1919-05-19:0":{"b": ["Mustafa Kemal in Samsun – Nationaler Befreiungskampf", "09a8f784"], "d": ["Mustafa Kemal Pascha, der im Klima der Empörung über die Besetzung İzmirs in seiner Eigenschaft als Inspekteur der 9. Armee nach Samsun übersetzte, wandte seinen offiziellen Auftrag der Organisation des Widerstands in Anatolien zu. Das Rundschreiben von Amasya sowie die Kongresse von Erzurum und Sivas sind die Fortsetzung dieses Aufbruchs; der Grundsatz, „die Unabhängigkeit der Nation wird wiederum durch den Willen und die Entschlossenheit der Nation gerettet werden“, wurde zum Kern des politischen Programms des Nationalen Befreiungskampfes.", "330e4c51"]},
"OLAYLAR:1920-04:0":{"b": ["Eröffnung der TBMM und Sèvres", "2008feec"], "d": ["Nach der förmlichen Besetzung Istanbuls und der Auflösung des Meclis-i Meb'ûsan wurde am 23. April 1920 in Ankara die Große Nationalversammlung (Büyük Millet Meclisi) eröffnet; die Versammlung, die außerordentliche Befugnisse in sich vereinte, wurde zum Kern des neuen, auf dem Nationalwillen beruhenden Staates. Der im August von der Istanbuler Regierung unterzeichnete Vertrag von Sèvres teilte Anatolien auf; die TBMM erklärte die Unterzeichner zu Vaterlandsverrätern, und Sèvres konnte nie angewandt werden.", "9b4f7c0b"]},
"OLAYLAR:1921-09-13:0":{"b": ["Schlacht am Sakarya", "f2f970a6"], "d": ["Der griechische Angriff, der bis auf 50 Kilometer an Ankara herangekommen war, wurde in der 22 Tage und 22 Nächte währenden Schlacht gebrochen, die Mustafa Kemal Pascha, der die Befugnisse des Oberbefehlshabers übernommen hatte, mit dem Befehl führte: „Es gibt keine Verteidigungslinie, es gibt eine Verteidigungsfläche.“ Das griechische Heer ging erstmals zur strategischen Verteidigung über; der Sieg brachte Mustafa Kemal den Titel Gazi und den Rang eines Müşir (Marschall) und öffnete die Tür zum Abkommen von Ankara mit Frankreich und zur äußeren Anerkennung.", "f3372310"]},
"OLAYLAR:1922-09-09:0":{"b": ["Großer Angriff und Befreiung İzmirs", "172a50c4"], "d": ["Der am Morgen des 26. August vom Kocatepe aus begonnene Angriff gipfelte am 30. August bei Dumlupınar in der Schlacht des Oberbefehlshabers (Başkomutan Meydan Muharebesi) in der Vernichtung der griechischen Hauptkräfte; mit der Verfolgung unter dem Befehl „Armeen, euer erstes Ziel ist das Mittelmeer, vorwärts!“ wurde İzmir am 9. September befreit. Mit dem Waffenstillstand von Mudanya (11. Oktober) wurde Ostthrakien kampflos zurückgewonnen; der militärische Sieg bestimmte die Verhandlungsstärke des in Lausanne zu schaffenden neuen Staates.", "02bd94a5"]},
"OLAYLAR:1922-11-01:0":{"b": ["Abschaffung des Sultanats", "9f36a9f6"], "d": ["Nachdem auch die Istanbuler Regierung zu den Lausanner Verhandlungen eingeladen worden war, trennte die TBMM am 1. November 1922 Sultanat und Kalifat und schaffte das Sultanat ab; die 623-jährige osmanische Dynastieherrschaft endete rechtlich. Mehmed VI. Vahideddin verließ das Land am 17. November auf einem britischen Kriegsschiff; auf das Kalifatsamt wurde durch Beschluss der TBMM Abdülmecid Efendi gesetzt, und auch dieses Amt sollte am 3. März 1924 abgeschafft werden.", "910b763d"]},
"OLAYLAR:1923-07-24:0":{"b": ["Vertrag von Lausanne", "38c27f7d"], "d": ["Mit dem nach achtmonatigen zähen Verhandlungen unterzeichneten Friedensvertrag von Lausanne wurden die Grenzen, die volle Unabhängigkeit und die Souveränität des neuen türkischen Staates international anerkannt; die Kapitulationen wurden aufgehoben, die Düyûn-ı Umûmiyye einem Liquidationsprozess unterworfen, der Bevölkerungsaustausch geregelt. Lausanne, das Sèvres faktisch ungültig machte, gilt als diplomatischer Sieg des Nationalen Befreiungskampfes und als das Gründungsdokument der Republik nach außen.", "6d498c3f"]},
"OLAYLAR:1923-10:0":{"b": ["Ausrufung der Republik", "d5bfcdfb"], "d": ["Mit der Annahme der Bestimmung „Die Regierungsform des Staates der Türkei ist die Republik“ durch die TBMM im Wege einer Verfassungsänderung wurde die Republik ausgerufen; Mustafa Kemal Pascha wurde zum ersten Präsidenten gewählt. Das 624-jährige osmanische Abenteuer, das 1299 als Grenz-Beylik begonnen hatte, war damit beendet, und der neue Staat, in dem die Souveränität bedingungslos der Nation gehört, wurde auf dem Erbe des Reiches gegründet.", "f5cabb8c"]},
"OLAYLAR_7A4170:1856-01-01:0":{"b": ["Die Einbindung von Dschaghbub, dem Wüstenzentrum der Senussiya, in die osmanische Ordnung – das Befreiungsfirman von Abdülmecid", "039fce6d"], "d": ["Nachdem Muhammed b. Ali es-Senûsî, der viele Jahre in Mekka geblieben war, nach Tripolitanien zurückgekehrt war, ließ er sich in der Oase Dschaghbub an der ägyptischen Grenze nieder und ließ auf einem beherrschenden Felsen eine große Zawiya erbauen; der Ort, der aus einigen Baracken bestand, verwandelte sich rasch in eine Stadt. 1856 wurde durch den Ferman von Sultan Abdülmecid der Besitz der Ordensangehörigen von der Steuer befreit, und den Murids wurde die Befugnis erteilt, die Zakat zu erheben. Dieser Ferman machte die Oase an der Karawanenstraße, die Westafrika und den Sudan mit Kairo verband, zu einem Teil der osmanischen Finanz- und Verwaltungsordnung und stärkte Dschaghbub als Handelszentrum. Die Treue der Bevölkerung der Region zum Kalifen wird auch durch das Reisebuch von Oberst Sâdık el-Müeyyed bestätigt, der den Ort 1884 und 1893 besuchte.", "dbe926fd"]},
"OLAYLAR_7A4170:1859-04-25:0":{"b": ["Der Beginn der Aushebung des Sueskanals und die Gründung von Port Said", "cef0be8d"], "d": ["Die Aushebungsarbeiten für das Projekt von Lesseps, dem die Hohe Pforte (Bâbıâli) am 5. Januar 1856 zugestimmt hatte, begannen am 25. April 1859; der Kanal sollte zehn Jahre später, am 16. November 1869, fertiggestellt werden. Am Mittelmeerende des Aushubs bildete das für die Arbeiter errichtete Barackendorf aus fünf Häusern auf der Landzunge zwischen dem Menzaleh-See und dem Meer den Kern von Port Said. Der Stadt wurde 1860 von den Verantwortlichen der Kanalgesellschaft zu Ehren des damaligen ägyptischen Statthalters Said Pascha dieser Name im Sinne von „Hafen des Said“ gegeben. So entstand auf der osmanischen Karte an einem Küstenstreifen, an dem es zuvor keinerlei Siedlung gegeben hatte, ein neuer Hafen.", "3e95556e"]},
"OLAYLAR_7A4170:1863-04-03:0":{"b": ["Der Ägyptenbesuch von Sultan Abdülaziz und die Gründung von Ismailia auf der Landenge von Suez", "bcfacf38"], "d": ["Sultan Abdülaziz reiste auf Anregung von Großwesir Yûsuf Kâmil Pascha am 3. April 1863 nach Ägypten und wurde mit großen Kundgebungen empfangen; das Ziel war, die Verbundenheit der Provinz mit dem Zentrum zu festigen, die seit dem Aufstand von Kavalalı Mehmed Ali Pascha faktisch begonnen hatte, ein eigener Staat zu werden. Im selben Jahr wurde auf der Landenge, auf den Hügeln von Tilâlülcisr am Ufer des Timsah-Sees, die Verwaltungszentrale der Kanalgesellschaft gegründet: zuerst Karyetüttimsah für die Ingenieure, dann Karyetülarab für die Arbeiter. Als Khedive İsmâil Pascha sich sehr für den Süßwasserkanal interessierte und sich auf diesem Hügel einen Kiosk bauen ließ, wurde die Siedlung nach ihm Ismailia genannt. Die Gründung der Stadt wird auf das Jahr 1863 datiert; der genaue Tag ist unbekannt.", "bab96585"]},
"OLAYLAR_7A4170:1869-01-01:0":{"b": ["Midhat Paschas Statthalterschaft in Bagdad und die Stammesansiedlung – die Gründung von Ramadi und Nasiriyya", "0fa98f06"], "d": ["Midhat Pascha, der von der Präsidentschaft des Staatsrats entfernt und aus Istanbul fortgeschickt wurde, verwaltete das auch Mosul und Basra umfassende Vilâyet Bagdad von 1869 bis 1872 mit weitreichenden Befugnissen, wobei ihm auch das Kommando der Sechsten Armee oblag. Hier setzte er das Landgesetzbuch (Arazi Kanunnâmesi) und das neue Vilâyet-Gesetz um, verteilte das Land mit Grundbucheintragung und band die nomadischen Stämme an die sesshafte Ordnung und die Staatsautorität. Als Ergebnis dieser Ansiedlungspolitik wurde 1869 am Euphratufer für den Stamm Dulaim Ramadi gegründet, im Süden durch den Mutasarrıf von Müntefik, Nâsır Pascha es-Sa'dûn, Nasiriyya; beide entstanden an Orten, an denen es bis dahin keine Siedlung gegeben hatte, und gelangten zu diesem Zeitpunkt erstmals auf die Karte.", "7babb36f"]},
"OLAYLAR_EK10:1402-07-28:0":{"b": ["Nach der Niederlage von Ankara nahm der Woiwode der Walachei Mircea die Dobrudscha zurück – Silistra, Constanța (Köstence), Babadag, Isaccea (İshakçı)", "5eaefc68"], "d": ["Die Niederlage Bayezids des Blitzes (Yıldırım Bayezid) gegen Timur bei Ankara erschütterte die osmanische Herrschaft an der Donau. Der Woiwode der Walachei, Mircea, nutzte dieses Vakuum, um erneut in die Dobrudscha einzudringen; Silistra, Constanța, die Umgebung von Babadag und Isaccea am Donauufer blieben während der Jahre des Interregnums (Fetret) in seiner Hand. Mircea unterstützte Mûsâ Çelebi gegen Çelebi Mehmed. Silistra hielt er bis zu seinem Tod 1418.", "58dabbe8"]},
"OLAYLAR_EK10:1416-01-01:0":{"b": ["Der Übergang von Babadag und Umgebung an die Osmanen – Mircea und sein Sohn Mihail werden besiegt", "bfda2c60"], "d": ["Nachdem Çelebi Mehmed den Woiwoden der Walachei Mircea und seinen Sohn Mihail besiegt hatte, brachte er Babadag und Umgebung in der Nord-Dobrudscha unter osmanische Herrschaft. Babadag war eine Kleinstadt, die den Namen Saltuk Babas trägt und mit einer turkmenischen Siedlung des 13. Jahrhunderts gegründet worden war. Die umliegenden Festungen Silistra, Constanța und die übrigen Dobrudscha-Festungen blieben dagegen bis 1419 in der Walachei; Babadag erscheint also drei Jahre lang als vom osmanischen Gebiet abgetrennte Insel (Exklave).", "b1e2339a"]},
"OLAYLAR_EK10:1419-01-01:0":{"b": ["Die Rückeroberung von Silistra und der Dobrudscha – nach dem Tod Mirceas", "73eb6ae9"], "d": ["Die Wirren, die nach dem Tod des Woiwoden der Walachei Mircea 1418 in der Walachei ausbrachen, gaben Çelebi Sultan Mehmed die Gelegenheit, Silistra und die Dobrudscha zurückzuerobern. Im Frühjahr 1419 kamen Silistra, Constanța und der größte Teil der Dobrudscha wieder unter osmanische Verwaltung; die Festungen Enisala (Yenisale) und Isaccea wurden instand gesetzt und zu Grenzfestungen (Serhat) gemacht; die Dobrudscha blieb danach bis 1878 bei den Osmanen.", "a2a9ad4e"]},
"OLAYLAR_EK10:1420-01-01:0":{"b": ["Die Schließung der Unteren Donau – die Annexion von Yergöğü, Turnu und Orșova", "331a0b68"], "d": ["Der Vorstoß Çelebi Mehmeds, die Donaulinie nach dem Ende des Interregnums in Ordnung zu bringen, trug 1420 Früchte. Die Festung Yergöğü (Giurgiu), die der Woiwode der Walachei Koca Mircea auf seinem eigenen Boden errichten ließ und deren Kosten er durch den Salzverkauf deckte, gelangte in diesem Jahr in osmanische Hand (die Dobrudscha war ein Jahr zuvor, im Frühjahr 1419, zurückgewonnen worden – TDV silistre), und Turnu (Kule/Holovnik) am rechten Donauufer und Orșova – später Fethülislâm genannt – wurden annektiert. Damit waren beide Seiten des Flusses unter Kontrolle gebracht. Die Bedeutung von Yergöğü ergibt sich aus seiner Geographie: Es ist eine osmanische Festung, die am linken, also walachischen Ufer der Donau errichtet wurde und mit Rusçuk am gegenüberliegenden Ufer die beiden Enden desselben Übergangs hält. Die osmanischen Dokumente schreiben diese Zweiheit ausdrücklich – für Rusçuk heißt es „Yergöğü, diesseitiges Ufer“, für Giurgiu „Yergöğü, jenseitiges Ufer“. Die Festung sollte 1427 von den Walachen zurückerobert werden, 1449 wieder unter osmanische Kontrolle gelangen, und der Kreis Yergöğü sollte dem Sandschak Nikopol angegliedert werden und so zu einer innerhalb des Woiwodats unmittelbar verwalteten Insel werden. Auf der Karte beginnt hier die Antwort auf die Frage, warum der Donaurand der Walachei dunkel gefärbt ist.", "4c3c95d4"]},
"OLAYLAR_EK10:1433-01-01:0":{"b": ["Die Region Toplica (Kurşunlu, Ürküp) gelangte unter osmanische Herrschaft", "e22e690d"], "d": ["Es wird für wahrscheinlich gehalten, dass die Region Dubočica und Toplica (die Umgebung von Leskovac, Kurşunlu und Ürküp) während der Verlobung Murads II. mit Mara Branković unter osmanische Herrschaft kam; das Tahrir-Register von 1445–1447 zeigt, dass die Region den osmanischen Sipahis als Timar vergeben wurde. Auf der Karte stehen Kurşunlu und Ürküp seit diesem Jahr unter osmanischer Verwaltung.", "335352f1"]},
"OLAYLAR_EK10:1448-01-01:0":{"b": ["Die Annexion der Saray-Ebene – die Einrichtung der osmanischen Spitze innerhalb Bosniens", "be5c0f00"], "d": ["Nachdem die bosnischen Könige 1428–1429 tributpflichtig gemacht worden waren, begannen die Osmanen, sich dauerhaft ins Innere des Königreichs hinein anzusiedeln. Zwischen 1428 und 1435 wurde die Kleinstadt Hodidjed genommen; 852 (1448) kam das Vilâyet Hodidjed zusammen mit der Saray-Ebene vollständig unter osmanische Verwaltung. Dies ist ein Grenzgebiet, das fünfzehn Jahre vor der Eroberung Bosniens mitten im Königreich errichtet wurde und vom Bey von Üsküp Îsâ Bey, der den Titel Woiwode trug, verwaltet wurde – da sich in seiner Umgebung noch immer den Osmanen tributpflichtige bosnische Beys befanden, stand die Region unter doppelter Kontrolle. Auch die Stadt selbst entstand in dieser Zeit: Vor 1462 gründete İshak Bey oder sein Sohn Îsâ Bey das erste muslimische Viertel, 862 (1458) wurde im Namen des Eroberers (Fâtih) die Hünkâr-Moschee erbaut, und durch die Bebauung der Felder des Dorfes Brodec entstand die Kleinstadt Saray. Die Eroberung von 1463 beseitigte das Königreich Bosnien; die Saray-Ebene war zu diesem Zeitpunkt schon seit fünfzehn Jahren osmanisches Gebiet.", "df377352"]},
"OLAYLAR_EK10:1457-01-01:0":{"b": ["Die Angliederung Podgoricas an das osmanische Gebiet – die Kontrolle über die Zeta-Ebene", "46e401c5"], "d": ["Die in der Ebene, in der die Gewässer Morača und Ribnica zusammenfließen, zwanzig Kilometer nördlich des Shkodra-Sees gelegene Kleinstadt wird in den Quellen erstmals 1216 unter dem Namen Ribnica, 1326 unter dem Namen Podgorica erwähnt. 1457 wurde sie dem osmanischen Gebiet angegliedert, und die Kontrolle über die Zeta-Ebene ging damit aus den Händen der Dynastien Balšić und Crnojević. Der Eroberer Mehmed (Fâtih Sultan Mehmed) ließ in den Jahren 1474–1478 auf den steilen Felsen am Zusammenfluss der beiden Flüsse eine Festung und eine Moschee errichten; nach der Eroberung Shkodras 1479 wurde die Region dem neu gegründeten Sandschak Shkodra angegliedert. Podgorica, nach dem Tahrir von 1485 eine christliche Kleinstadt von vierzig Haushalten, erreichte 1529–30 800 Personen und eine Garnison von zweiunddreißig Mann unter einem Dizdar in der Festung, 1582 322 Haushalte. Evliya Çelebi zählte 1662 in der Fâtih-Festung dreihundert Häuser, Speicher, Zeughäuser und siebenhundert Wächter. Diese Aufzeichnungen zeigen auch den Unterschied zwischen Ebene und Berg in Zeta: Die Ebene ist ein gezählter, besteuerter und mit Garnison versehener osmanischer Kreis (Kaza) – dennoch sollte die Stadt im 18. Jahrhundert mit sechs Bastionen und dreitorigen Mauern befestigt werden müssen, um die Überfälle der Stämme in den Bergen Montenegros abzuwehren. Podgorica fiel gegen Ende des Krieges von 1876–1878 an Montenegro und blieb durch den Berliner Vertrag dort.", "d0b08ff8"]},
"OLAYLAR_EK10:1465-01-01:0":{"b": ["Die Einnahme von Foča – die Öffnung des ersten Zugangs zum Herzogtum Herzegowina", "f098a9e6"], "d": ["Nachdem das Königreich Bosnien 1463 beseitigt worden war, kam die Reihe an das Gebiet von Stjepan Vukčić Kosača, der sich vom Königreich gelöst und sein eigenes Herzogtum gegründet hatte. Foča, im Drina-Tal am Knotenpunkt des Handelswegs gelegen, der Istanbul mit Dubrovnik verband, kam 1465 unter osmanische Verwaltung. Die Bedeutung der Stadt wurde sofort erkannt: 1470 wurde sie zum Sitz des neu gebildeten Sandschaks Herzegowina gemacht – das heißt, der administrative Kern Herzegowinas wurde in Foča errichtet, noch bevor das Herzogtum selbst gestürzt war. Die Annexion des gesamten Herzogtums sollte noch bis 1483 dauern. Foča entwickelte sich danach dank seines günstigen Klimas und seiner Lage am Wegknotenpunkt zu einem Handels- und Verwaltungszentrum. Auf der Karte ist dieses Datum der Tag, an dem nach der Eroberung Bosniens die zweite Welle nach Süden begann.", "9acfcdda"]},
"OLAYLAR_EK10:1469-01-01:0":{"b": ["Die endgültige Annexion von Livno und Westbosnien – die Errichtung der venezianischen Grenze", "c14d4283"], "d": ["Die Festung auf dem Plateau, das die Ebene von Livno beherrscht, war 1448–1454 in der Hand von Stjepan Vukčić Kosača, dem Gründer des Herzogtums Herzegowina. Beim Bosnien-Feldzug von 1463 war sie kurze Zeit von osmanischen Truppen besetzt, im selben Jahr aber zurückerobert worden; 1466 ist der Herr der Stadt Ivaniš Vlatković. Laut der TDV fand die endgültige osmanische Herrschaft mit großer Wahrscheinlichkeit 1468–1469 statt, und der Tahrir von 1485 verzeichnet Livno bereits als osmanisches Gebiet. Dies ist der Abschluss des Westendes der Eroberung Bosniens: Livno wurde zu einer gefährlichen Grenzstadt, die entlang der flachen Ebene nur sechsunddreißig Kilometer entfernt an venezianisches Gebiet grenzte, und behielt diese Stellung bis zur Einnahme der venezianischen Festungen durch den Statthalter von Bosnien Gazi Hüsrev Bey in den Jahren 1521–1522.", "8e012cb5"]},
"OLAYLAR_EK10:1476-02-01:0":{"b": ["Der Verlust von Böğürdelen an die Ungarn – die erste Bresche in der Savelinie", "129fe8f2"], "d": ["An dem zur Zeit des Eroberers Mehmed (Fâtih Sultan Mehmed) in osmanische Hand gelangten und zuvor unter dem Namen Zaslon bekannten Ort war 1471 eine Holz-Erde-Burg errichtet worden. Weil sie an einem Punkt lag, der Belgrad bedrohte, und von hier aus leicht Streifzüge nach Ungarn und in die südlichen Gebiete Österreichs unternommen werden konnten, hatte die Festung ihren Namen auch von dieser Funktion – Böğürdelen bedeutet „Bastion, die von der Seite trifft“. Der ungarische König Matthias Corvinus belagerte die Festung Ende 1475 und nahm sie im Februar 1476 ein. Das die Belagerung schildernde ungarische Epos Szabács viadala gehört zu den längsten erhaltenen Texten der ungarischen Geschichtsdichtung des 15. Jahrhunderts. Die Ungarn richteten in der Region ein Banat ein und befestigten die Festung neu in Stein, wodurch sie zu einem Glied der Kette der Grenzburgen wurde. Die Osmanen versuchten 1492, sie zurückzugewinnen, und scheiterten; die Festung blieb fünfundvierzig Jahre in ungarischer Hand.", "87ae8b15"]},
"OLAYLAR_EK10:1479-08-01:0":{"b": ["Die Eroberung der Ionischen Inseln – das Ende des Herzogtums Tocco: Ayamavra (Leukas), Kephallonia, Zakynthos, Ithaka", "07b27251"], "d": ["Der im Januar desselben Jahres mit Venedig unterzeichnete Vertrag von Istanbul hatte Shkodra und die albanische Küste bei den Osmanen belassen; die Ionischen Inseln standen aber nicht unter venezianischer Verwaltung, sondern unter der der Familie Tocco, die die Grafschaft Kephallonia-Zakynthos innehatte, und wurden in einem gesonderten Feldzug genommen. Laut dem Artikel „Ayamavra“ der TDV hatte der letzte Herzog Leonardo Tocco zunächst durch seine Heirat mit Milica Branković, einer Verwandten des Eroberers (Fâtih), seine Treue gewahrt; als seine Frau 1464 starb, verärgerte er den Sultan, indem er 1477 Francesca Marzano aus dem neapolitanischen Haus heiratete. Zwei Jahre später nahm die Flotte unter dem Kommando von Gedik Ahmed Pascha, dem Bey von Vlora (Avlonya), Ayamavra zusammen mit dem südlich gelegenen Kephallonia ein; Leonardo und Francesca flohen nach Italien. Der Artikel „Gedik Ahmed Paşa“ vermerkt, dass bei demselben Feldzug auch Zakynthos (Zanta) genommen wurde; auch Ithaka, das zur Grafschaft Kephallonia gehörte, kam in dieser Zeit unter osmanische Verwaltung. Damit wurde der Seeweg von der Adriamündung bis zur Morea vollständig unter Kontrolle gebracht. Von den Inseln sollte Zakynthos drei Jahre später an Venedig abgetreten werden, Kephallonia und Ithaka sollten 1500 verloren gehen, und allein Ayamavra sollte zweihundert Jahre bei den Osmanen bleiben.", "725a61d9"]},
"OLAYLAR_EK10:1482-01-01:0":{"b": ["Die Vasallität von Zeta unter den Crnojević und Cetinje wird Zentrum", "59d20267"], "d": ["Dadurch, dass Shkodra 1479 bei den Osmanen blieb, geriet auch das Bergland von Zeta in seinem Hinterland in die Grenzen des Reiches. Die Familie Crnojević, die die Region in der Hand hielt, erkannte die Herrschaft Bayezids II. an, der nach dem Tod des Eroberers (Fâtih) den Thron bestieg, wurde tributpflichtig und blieb in ihren inneren Angelegenheiten frei; Ivan Crnojević verlegte sein Zentrum aus der Ebene nach Cetinje am Fuß des Lovćen und gründete die Stadt. Das zwei Jahre später dort errichtete Kloster wurde zum religiösen Zentrum der Region. Montenegro erscheint auf der Karte daher nicht als unmittelbar osmanisches Gebiet, sondern als vasallisches Gebiet in hellem Ton. Der Artikel „Karadağ“ der TDV erwähnt die Dynastie und das Bistum Cetinje und schreibt, dass die Herrschaft 1514 durch İskender Bey (aus dem Geschlecht der Crnojević, am osmanischen Hof aufgewachsen) in einen eigenen Sandschak umgewandelt wurde; das Jahr 1482 kommt in der TDV nicht vor, es ist das Datum der montenegrinischen Geschichtsschreibung. Wegen der Härte der Geographie funktionierte die Verwaltung dort nie so straff wie in den Ebenen.", "c61bf059"]},
"OLAYLAR_EK10:1484-07-15:0":{"b": ["Die Eroberung der Festung Kilia – der Schlüssel zur Donaumündung", "ef4eca73"], "d": ["Die Moldau war seit September 1455 ein tributpflichtiges, jährlich zweitausend Goldstücke zahlendes vasallisches Woiwodat, aber die beiden Häfen am Schwarzen Meer waren noch in der Hand des Woiwoden, und der Handel von der Donau lief über sie. Bayezid II. unternahm den ersten großen Feldzug seiner Herrschaft gegen diese beiden Häfen. Der Kommandant der zehn Tage lang Tag und Nacht beschossenen Festung Kilia musste sich ergeben. Die Festung wurde unmittelbar der osmanischen Verwaltung unterstellt und zu einem Sandschakbeylik gemacht; in der zweiten Hälfte des 16. Jahrhunderts wurde sie wegen der Kosakengefahr zum Kreis (Kaza) gemacht und dem zum Beylerbeyilik Rumelien gehörenden Sandschak Akkerman angegliedert. Von hier an erscheint die Moldau auf der Karte zweistufig: Im Inneren steht das Woiwodat als vasallisches Gebiet in hellem Ton, die beiden Häfen an der Küste sind dagegen unmittelbar osmanische Sandschaks in dunklem Ton. Der Artikel „Boğdan“ der TDV nennt diese beiden „die Schlüssel und Tore der Moldau“ und schreibt, dass die Region zur Zeit Bayezids II. endgültig an die Osmanen gebunden wurde.", "8b039ea4"]},
"OLAYLAR_EK10:1484-08-04:0":{"b": ["Die Eroberung von Akkerman – die Dnister-Mündung und die Schließung des Schwarzmeertors der Moldau", "7cb20feb"], "d": ["Zwanzig Tage nach der Übergabe von Kilia stand das Heer vor Akkerman an der Dnister-Mündung, und die Festung wurde am 4. August genommen. Die Stadt war der verkehrsreichste Hafen der Moldau; als Woiwode Petru III. 1455 zur Zeit des Eroberers (Fâtih) die osmanische Herrschaft anerkannte, war den Kaufleuten von Akkerman Handelsfreiheit gewährt worden, nun wurde der Hafen unmittelbar Eigentum des Staates. Akkerman, das nach der Eroberung zu einem zum Beylerbeyilik Rumelien gehörenden Sandschak gemacht wurde, wurde 1593 dem neu gegründeten Eyalet Özü angegliedert. Damit begann die äußere Schale der Moldau, im Norden von Chotyn (Hotin), im Süden von Kilia und Akkerman umgeben, unter die unmittelbare Kontrolle der Osmanen zu geraten; das Woiwodat blieb in den inneren Angelegenheiten frei, hatte aber keinen Zugang zum Meer mehr. Auf der Karte gibt es dazwischen keine leere Region – die dunkel getönten Hafen-Sandschaks und das hell getönte Woiwodatsgebiet berühren sich; die Budschak-Steppe zwischen beiden ist bis 1538 noch Teil des Woiwodats.", "23705829"]},
"OLAYLAR_EK10:1499-08-26:0":{"b": ["Die Übergabe von Lepanto (İnebahtı) – die Mündung des Golfs von Korinth wird Venedig abgenommen", "2cfe0777"], "d": ["Lepanto war seit 1407 in venezianischer Hand und hielt die Mündung des Golfs von Korinth; die gesamte Küste im Inneren des Golfs hing von der Reichweite dieser Festung ab. Beim Feldzug von 1499 wurde die Festung zu Lande belagert, und die osmanische Flotte, die vor Lepanto mit der venezianischen Flotte kämpfte, unterstützte die Belagerungstruppen von der See her. Die Venezianer in der Festung übergaben die Stadt am 26. August den Osmanen. Die Stadt blieb danach hundertachtundachtzig Jahre bei den Osmanen, ging 1687 mit dem Verlust der Morea wieder an Venedig über und wurde 1715 zurückerobert. Die Seeschlacht im selben Sommer und diese Übergabe sind zwei getrennte Ereignisse: Die Flottenschlacht fand am Westende der Morea in den Gewässern von Sapienza (Zonchio) statt; Lepanto fiel dagegen an der Mündung des Golfs von Korinth durch eine Landbelagerung.", "49c0fbd8"]},
"OLAYLAR_EK10:1512-01-01:0":{"b": ["Die Annexion des Banats Srebrenik – die erste Brechung der ungarischen Linie in Nordbosnien", "6d98c725"], "d": ["Nachdem das Königreich Bosnien 1463 gestürzt worden war, war Matthias Corvinus zum Gegenangriff übergegangen und hatte im Norden des Königreichs zwei Banate eingerichtet, die das osmanische Vordringen aufhielten: im Westen Jajce, im Nordosten Srebrenik. Sie waren die vorgeschobene Verteidigungslinie Ungarns in Bosnien und verschlossen den Korridor zwischen Save und Bosna. Das Banat Srebrenik wurde 1512 eingenommen; damit brach der Ostflügel der Linie zusammen, und der Sandschak İzvornik konnte sich nach Norden ausdehnen. Jajce im Westflügel sollte noch sechzehn Jahre standhalten und erst nach Mohács 1528 genommen werden können.", "0d4ad0e7"]},
"OLAYLAR_EK10:1521-07-07:0":{"b": ["Die Eroberung von Böğürdelen – die erste Festung, die Süleyman der Gesetzgeber (Kanûnî) nahm, und der Ort, an dem der Belgrad-Beschluss gefasst wurde", "85177a90"], "d": ["Die Truppen des Beylerbeys von Rumelien Ahmed Pascha, der beim ersten Ungarn-Feldzug von Sultan Süleyman dem Gesetzgeber (Kanûnî) in die Region entsandt worden war, nahmen die Festung nach einer heftigen Belagerung am 7. Juli 1521 ein. Böğürdelen ist die erste Festung, die in der Herrschaft Kanûnîs erobert wurde. Der Sultan betrat nach der Eroberung persönlich die Festung und ordnete den Ausbau der Stadt an; auch die Beschlüsse zur Eroberung Belgrads wurden hier gefasst – das heißt, der Plan für Belgrad, das am 29. August 1521 fallen sollte, wurde in Böğürdelen gemacht. Die Festung blieb danach fast zweihundert Jahre in osmanischer Hand; sie gehörte zunächst zu Rumelien, ab 1580 zum Eyalet Bosnien, dann kurze Zeit zu Smederevo (Semendire) und schließlich zum Sandschak İzvornik. Auf der Karte ist dieses Datum der Tag, an dem sich die Savelinie zugunsten der Osmanen schloss.", "8c0178ad"]},
"OLAYLAR_EK10:1594-08-28:0":{"b": ["Der Aufstand der drei Woiwodate beginnt – Siebenbürgen geht zur Heiligen Liga über, osmanfreundliche Beys werden verhaftet", "68a33800"], "d": ["Im zweiten Jahr des Langen Krieges löste sich der vasallische Gürtel der Osmanen in Mitteleuropa auf einen Schlag auf. Der unter der Schirmherrschaft von Papst Clemens VIII. gegründeten Heiligen Liga schlossen sich Ende des Sommers die Moldau und Siebenbürgen an: Der Woiwode der Moldau, Aron Vodă, machte seinen Anschluss an die christliche Seite am 16. August 1594 durch ein Dokument offiziell, und der Fürst von Siebenbürgen, Sigismund Báthory, brach am 28. August 1594 die innere Opposition, indem er die osmanfreundlichen Beys, die sich dem Krieg widersetzten, ausschaltete. Der Woiwode der Walachei, Michael der Tapfere, trat im Herbst desselben Jahres der Liga bei. Damit wechselten die drei vasallischen Fürstentümer der Osmanen nördlich der Donau – drei Woiwodate, die seit hundertfünfzig Jahren Tribut zahlten und deren Woiwoden von Istanbul bestätigt wurden – im selben Herbst auf einmal auf die Gegenseite. Der Beschluss wurde durch den am 28. Januar 1595 in Prag unterzeichneten Vertrag offiziell. Dies war die schwerste Erschütterung der indirekten Herrschaftsordnung der Osmanen im Norden des Balkans; der Aufstand sollte niedergeschlagen werden, aber die Loyalität der drei Fürstentümer sollte nie wieder so fest sein wie zwischen 1526 und 1593.", "32a29f3a"]},
"OLAYLAR_EK10:1594-11-01:0":{"b": ["Der Aufstand von Bukarest und der Angriff auf die Donaufestungen", "18971100"], "d": ["Der Beschluss der Heiligen Liga wurde einen Monat später blutig umgesetzt: Michael der Tapfere ließ in Bukarest die osmanische Wachtruppe und die levantinischen Gläubiger in der Stadt über die Klinge springen. Der Aufstand breitete sich im selben Winter auf die Donaulinie aus; walachische Truppen griffen Yergöğü (Giurgiu), Brăila, Hârșova und Silistra an, auf der Seite der Moldau überfiel Aron Vodă die osmanischen Wachen in Bender auf dieselbe Weise. Die Wahl der getroffenen Orte ist kein Zufall: Es waren allesamt nicht Woiwodatsgebiet, sondern Festungen und Kreise am Donaulauf, die unmittelbar der osmanischen Verwaltung unterstanden – der Kreis Yergöğü gehörte zum Sandschakbeylik Nikopol, Brăila seit 1538 unmittelbar zum Staat, Bender ebenfalls seit 1538 zum Sandschak Budschak. Das heißt, der Aufstand traf nicht das vasallische Binnenland, sondern die unmittelbar osmanische Schale, die dieses umgab. Ohne dass diese Schale durchlöchert wurde, konnte das Dreieck Siebenbürgen–Walachei–Moldau nicht an die Habsburger Front angeschlossen werden.", "95f2286f"]},
"OLAYLAR_EK10:1595-08-23:0":{"b": ["Die Schlacht von Călugăreni – der Walachei-Feldzug von Koca Sinan Pascha", "201210a1"], "d": ["Als die drei Woiwodate auf einmal verloren gegangen waren, überschritt Großwesir Koca Sinan Pascha mit einem großen Heer die Donau und zog los, um die Walachei wieder zum Gehorsam zu bringen. Michael der Tapfere, der wusste, dass er in offener Schlacht nicht standhalten konnte, erwartete das Heer in Călugăreni, an der sumpfigen Furt des Neajlov, und überfiel die in dem engen Gelände eingezwängten Truppen. Nach dem Überfall konnte er der zahlenmäßig überlegenen osmanischen Armee nicht standhalten und zog sich nach Norden in die Berge zurück; Sinan Pascha besetzte Bukarest und Târgoviște und versuchte, die Walachei unmittelbar der Verwaltung zu unterstellen. Călugăreni war für die Osmanen deshalb keine Niederlage, sondern ein Überfall, der den Abschluss des Feldzugs verzögerte; dass Michael sein Heer erhalten konnte, ermöglichte es ihm jedoch, einige Wochen später mit der Hilfe aus Siebenbürgen zum Gegenangriff überzugehen.", "a2263c60"]},
"OLAYLAR_EK10:1595-10-01:0":{"b": ["Der Rückzug aus der Walachei und der Überfall bei Yergöğü – das ergebnislose Ende des Unterdrückungsfeldzugs", "118806e1"], "d": ["Als Michael der Tapfere sich mit den Truppen des Fürsten von Siebenbürgen vereinigte und zum Gegenangriff überging, räumte Sinan Pascha Târgoviște und Bukarest und zog sich zur Donau zurück. Der teuerste Augenblick des Rückzugs ereignete sich am Übergang: Im Oktober 1595 wurden die Akıncıs, die dem aus der Walachei zurückkehrenden Heer folgten, bei Yergöğü von Michael überfallen. Der Feldzug endete damit, ohne das Ziel zu erreichen, die Walachei unmittelbarer Verwaltung zu unterstellen, und das Woiwodat blieb faktisch verloren. Die osmanische Autorität konnte in diesem Dreieck erst im Laufe der Jahre und stückweise wiederhergestellt werden; die Rückkehr Siebenbürgens zum Gehorsam sollte 1604 den Bocskai-Aufstand abwarten, der vollständige Abschluss der Front den Vertrag von Zsitvatorok von 1606.", "ab33575c"]},
"OLAYLAR_EK10:1713-06-24:0":{"b": ["Chotyn (Hotin) wird aus der Moldau herausgelöst – ein unmittelbar osmanischer Sandschak mitten im Woiwodat", "947517cb"], "d": ["Dass der Woiwode der Moldau, Dimitrie Cantemir, beim Pruth-Feldzug auf die russische Seite überging, zeigte, dass die Nordgrenze des Woiwodats nicht länger dem Woiwoden überlassen werden konnte. Daraufhin wurde Chotyn nach 1711 der Moldau entnommen und unmittelbar der osmanischen Verwaltung unterstellt; zunächst wurde ihm der Status einer Nahiye, dann eines Sandschaks verliehen. Nach der vorübergehenden russischen Besetzung von 1713 wurde die Festung unter der Aufsicht einer aus Istanbul entsandten osmanischen und französischen technischen Kommission neu instand gesetzt und erweitert und wurde zur stärksten osmanischen Befestigung nördlich der Donau. Dass Chotyn auf der Karte seit diesem Datum aus dem Ton des vasallischen Woiwodats heraustritt und zur unmittelbaren osmanischen Farbe zurückkehrt und mitten in der vasallischen Moldau wie eine Insel allein steht, ist die Entsprechung dieser administrativen Trennung – es ist kein Zeichenfehler. Dieselbe Struktur gab es im Budschak seit 1538 und in Kilia und Akkerman seit 1484 bereits: Das Woiwodat ist in den inneren Angelegenheiten frei, die Grenzfestungen gehören dem Staat.", "7c5d350f"]},
"OLAYLAR_EK10:1788-04-24:0":{"b": ["Die zweite österreichische Besetzung von Böğürdelen – die Eröffnung der Savefront", "063b3ad0"], "d": ["Nach dem Kriegseintritt Österreichs an der Seite Russlands am 9. Februar 1788 wurde die Savelinie erneut zur Front, und Böğürdelen ging am 24. April 1788 an die österreichische Herrschaft über. Die Festung war zuvor am 17. August 1717 kampflos an Österreich abgetreten und bis zum Frieden von Belgrad (1739) gehalten worden; ihre Bevölkerung war damals so zurückgegangen, dass in der Stadt vierunddreißig christliche Häuser und kein einziger Muslim übrig blieben. In der osmanischen Zeit von 1739 bis 1788 war die Bevölkerung wieder auf 1500–2000 gestiegen. Die zweite Besetzung sollte durch den Frieden von Svischtow (Ziştovi) (4. August 1791) enden, und die Festung sollte den Osmanen zurückgegeben werden.", "de07456b"]},
"OLAYLAR_EK10:1806-01-26:0":{"b": ["Die Übergabe von Böğürdelen an Karađorđe (Kara Yorgi) – die erste Festung im Ersten Serbischen Aufstand", "5c913eb4"], "d": ["Während der ersten serbischen Revolution, die 1804 als Reaktion auf den Druck der Deys und Yamaks in Belgrad begann und dann einen nationalistischen Charakter annahm, wurde die Festung Böğürdelen am 26. Januar 1806 an Kara Yorgi übergeben. Diese Festung an der Save ist die erste große osmanische Befestigung, die die Aufständischen einnahmen, und sie kündigt den Fall Belgrads an. Als der Aufstand 1813 niedergeschlagen und Belgrad zurückgewonnen wurde, kehrte auch die Festung unter osmanische Verwaltung zurück; mit der Garnisonsbedingung des Fermans von 1830 wurde Böğürdelen jedoch zusammen mit Belgrad, Smederevo (Semendire) und Fethülislâm als eine der vier Festungen innerhalb des autonomen Serbien bestimmt, in denen osmanische Soldaten verblieben, und behielt diesen Status, bis die Garnison 1867 abgezogen wurde.", "092a75b8"]},
"OLAYLAR_EK10:1832-01-01:0":{"b": ["İzdin (Lamia) blieb innerhalb der griechischen Grenzen – die Linie Arta–Volos", "930f63b8"], "d": ["Die Nordgrenze des unabhängigen griechischen Staates wurde 1832 auf der Linie vom Golf von Arta bis zum Golf von Volos gezogen. İzdin, in osmanischer Zeit (1424–1832) ein zum Sandschak Euböa (Eğriboz) gehörender Kreissitz, ging an Griechenland, da es südlich dieser Linie lag; der Rest Thessaliens (Yenişehir, Tırhala) blieb bis 1881 bei den Osmanen.", "577080e0"]},
"OLAYLAR_EK10:1877-04-24:0":{"b": ["Die Kriegserklärung Russlands – der Beginn des Krieges von 93", "ac548ab8"], "d": ["Die Niederschlagung des Bulgarischen Aufstands von 1876 hatte in der europäischen Öffentlichkeit große Empörung ausgelöst, und Russland hatte dies bis zum Äußersten genutzt, um die Hohe Pforte (Bâbıâli) zu isolieren. Nachdem das Osmanische Reich den Vorschlag der Istanbuler (Tersane-)Konferenz, Bulgarien in zwei autonome Provinzen zu teilen, und danach das Londoner Protokoll vom 31. März 1877 abgelehnt hatte, erklärte Russland am 24. April 1877 den Krieg, und sein Heer drang in das Gebiet des Fürstentums Rumänien ein, das es auf seine Seite gezogen hatte (die Karte zeigt die Walachei und die Moldau von diesem Augenblick bis zum Waffenstillstand von Edirne mit der Schraffur des russischen Vormarsches). Da er auf das Jahr 1293 des Rumi-Kalenders fiel, wird der Krieg als Krieg von 93 bezeichnet. Die Operationen liefen an zwei Fronten, an der Donau und in Ostanatolien: An der Donau hatte das osmanische Heer von 180.000 Mann das linke Flussufer als erste und das Balkangebirge als zweite Verteidigungslinie betrachtet; im Osten waren die 55.000 Soldaten Ahmed Muhtar Paschas zwischen Ardahan und Doğubayazıt stationiert. Dieser Krieg ist auf der Karte das Ereignis, das den Zusammenbruch des osmanischen Rumelien einleitete – die heutigen Grenzen Bulgariens, Serbiens, Montenegros und Rumäniens sind allesamt Produkt dieser fünfzehn Monate.", "a71008f1"]},
"OLAYLAR_EK10:1877-05-21:0":{"b": ["Die Unabhängigkeitserklärung Rumäniens – das Ende der Vasallität der Walachei und der Moldau", "bdd164b3"], "d": ["Zwei Wochen nach der Kriegserklärung des Krieges von 93 erklärte das Fürstentum Rumänien seine Unabhängigkeit und trat an der Seite Russlands in den Krieg ein; sein Anteil an der Belagerung von Plewen wurde für die osmanische Niederlage entscheidend. Die über vierhundert Jahre dauernde Vasallität der Walachei und der Moldau endete damit faktisch; die Unabhängigkeit erlangte auf dem Berliner Kongress (1878) internationale Anerkennung. Die Karte zeigt Rumänien von diesem Datum an nicht mehr als vasallisch, sondern als unabhängigen Staat in seiner eigenen Farbe.", "02d51dee"]},
"OLAYLAR_EK10:1877-06-27:0":{"b": ["Der Donauübergang des russischen Heeres – der Fall von Svischtow (Ziştovi) und Tarnowo", "811367b1"], "d": ["Die Russen, die mit Kriegsbeginn in das Gebiet Rumäniens einmarschiert waren und dieses Fürstentum auf ihre Seite gezogen hatten, rückten in zwei Kolonnen vor, die eine in Richtung Dobrudscha, die andere in Richtung Bukarest. Die Donau wurde zwischen Rusçuk und Nikopol überschritten, und am 27. Juni wurde Svischtow, am 1. Juli die alte bulgarische Hauptstadt Tarnowo genommen. Da der Befehl zur Räumung nicht sorgfältig beachtet wurde, ergab sich auch Nikopol nach einigem Widerstand. Der innerhalb einer Woche erfolgte Durchbruch der ersten Verteidigungslinie löste in Istanbul große Panik aus; es verbreiteten sich sogar Gerüchte, der Sitz des Sultanats werde nach Bursa verlegt, und die Führung des Krieges wurde einem in der Hauptstadt gebildeten Militärrat übertragen.", "f266b11c"]},
"OLAYLAR_EK10:1877-07-19:0":{"b": ["Die Räumung des Schipka-Passes – der Durchbruch der Balkanlinie", "1f45e50a"], "d": ["Die osmanischen Truppen am Schipka-Pass, dem strategisch wichtigsten der Pässe über das Balkangebirge, leisteten den russischen Angriffen heftigen Widerstand; als sie aber zu der Überzeugung gelangten, besiegt zu werden, räumten sie den Pass am 19. Juli heimlich. Damit war auch die zweite Verteidigungslinie geöffnet, und General Gurko nahm am 22. Juli Stara Sagora. Obwohl Süleyman Pascha, der aus Montenegro herbeigeeilt war, Gurko besiegte und die besetzten Orte südlich des Balkans zurückeroberte, konnte er den Schipka-Pass trotz monatelanger Angriffe seit dem 21. August nicht zurückgewinnen. Auf der Karte ist dies der Umstand, dass die Verteidigungsgeschlossenheit zwischen dem Norden und dem Süden des Balkangebirges nie wieder hergestellt werden konnte: Der Kampf an der Donaufront wird sich von da an in Plewen verknoten.", "3463a17b"]},
"OLAYLAR_EK10:1877-08-23:0":{"b": ["Lowetsch wird vom russischen Heer besetzt", "70e54611"], "d": ["Im Krieg von 93 war Lowetsch am 5. Juni 1877 von den Russen besetzt worden, und die osmanischen Truppen unter dem Kommando von Rifat Pascha hatten die Russen am 15. Juni zurückgeschlagen; die Stadt wurde am 23. August von den Osmanen geräumt und geriet erneut unter russische Besetzung. Die Karte zeigt Lowetsch von diesem Tag bis zum Berliner Vertrag unter russischer Besetzung (schraffiert); rechtlich bleibt sie weiterhin osmanisches Gebiet.", "45e61a80"]},
"OLAYLAR_EK10:1877-11-18:0":{"b": ["Der Fall von Kars – die Auflösung der Ostfront und die Aziziye-Bastionen", "53fc3bf5"], "d": ["Die Russen, die in Ostanatolien in drei Kolonnen auf Kars, Doğubayazıt und Ardahan vorrückten, hatten am 30. April Doğubayazıt genommen und waren in Ardahan eingezogen, waren aber am 15. Juli beim Marsch auf Erzurum besiegt und über die Grenze zurückgeworfen worden. Dieser Erfolg, der Ahmed Muhtar Pascha den Titel „Gazi“ einbrachte, kehrte sich im August um, als General Lazarof erneut zum Angriff überging, und am 18. November fiel Kars. Die osmanischen Truppen, die sich für eine günstigere Verteidigung nach Erzurum zurückgezogen hatten, leisteten in den Aziziye-Bastionen mit der Ermutigung der Bevölkerung durch Nene Hatun großen Widerstand. Kars, Ardahan und Batumi sollten acht Monate später in Berlin als Gegenleistung für einen Teil der Kriegsentschädigung Russland überlassen werden.", "07faf844"]},
"OLAYLAR_EK10:1912-10-08:0":{"b": ["Der Beginn des Ersten Balkankrieges – die Kriegserklärung Montenegros", "c0c2697e"], "d": ["Die Balkanstaaten hatten, nachdem das Komitee für Einheit und Fortschritt mit dem Gesetz vom 3. Juli 1911 die Kirchenfrage gelöst hatte, das größte Hindernis zwischen sich beseitigt und im Laufe des Jahres 1912 auf Anstiftung Russlands Bündnisverträge miteinander unterzeichnet (am 13. März Bulgarien–Griechenland, im August Montenegro–Bulgarien, am 6. Oktober Montenegro–Serbien). Die Hohe Pforte (Bâbıâli) bemerkte dies nicht; im Vertrauen auf die Garantie Russlands entließ sie sogar die 120 ausgebildeten Bataillone in Rumelien. Die vier Staaten forderten am 3. Oktober mit einer gemeinsamen Note Autonomie für Makedonien, Albanien und Kreta; da sie keine Antwort erhielten, begannen die Operationen am 8. Oktober 1912 mit der Kriegserklärung Montenegros. Am 13. Oktober wurden den Gesandten Serbiens und Bulgariens ihre Pässe ausgehändigt, am folgenden Tag erklärten diese beiden Staaten, danach Griechenland den Krieg. Die politischen Meinungsverschiedenheiten innerhalb des Heeres spielten während des Krieges bei der Niederlage eine große Rolle.", "f008aef9"]},
"OLAYLAR_EK10:1912-10-20:0":{"b": ["Die Abteilung von Kardschali wird in den Rhodopen zerschlagen, Kardschali fällt", "8cf59b7f"], "d": ["Nach der bulgarischen Kriegserklärung besiegten die aus den Rhodopen herabsteigenden bulgarischen Truppen die Abteilung von Kardschali (Kırcaali) unter Mehmed Yaver Pascha und zogen in Kardschali ein. Die geschlagene Abteilung zog sich in Richtung Gümülcine zurück; der Ostteil der Rhodopen ging in der ersten Woche des Krieges verloren.", "c675e240"]},
"OLAYLAR_EK10:1912-10-23:0":{"b": ["Die Niederlage der Ostarmee und der Rückzug auf die Linie von Çatalca – der Verlust von Kumanovo und Thessaloniki", "cf95591a"], "d": ["Die osmanische Ostarmee wurde am 23. Oktober 1912 vom dreimal so zahlreichen bulgarischen Heer besiegt und zog sich bis zur Linie von Çatalca dreißig Kilometer westlich von Istanbul zurück; die Hauptstadt geriet im ersten Monat des Krieges unmittelbar in Bedrängnis. In denselben Tagen wurde die Westarmee am 23.–24. Oktober bei Kumanovo von den Serben besiegt, und Tahsin Pascha ergab sich mit seiner 35.000 Mann starken Armee in Thessaloniki den Griechen. Aufgrund dieser Niederlagen trat am 29. Oktober das Kabinett von Gazi Ahmed Muhtar Pascha zurück; der in Thessaloniki im Exil lebende Abdülhamid II. wurde am 1. November nach Istanbul überführt. Die Linie von Çatalca wurde bis zum Ende des Krieges gehalten – die fünfhundertjährige osmanische Geographie Rumeliens schrumpfte binnen weniger Wochen auf diesen schmalen Streifen.", "376c6d31"]},
"OLAYLAR_EK10:1912-10-23:1":{"b": ["Prinz Alexander zieht in das Zentrum des Sandschaks Novi Pazar (Yenipazar) ein", "326d0616"], "d": ["Die serbischen Truppen nahmen in der ersten Woche des Krieges Yenipazar ein und vereinigten sich mit den aus dem Westen kommenden montenegrinischen Truppen. Der Sandschak Yenipazar, der Serbien und Montenegro seit hundert Jahren getrennt hatte, wurde damit zu einer Brücke zwischen den beiden Verbündeten.", "afe8a034"]},
"OLAYLAR_EK10:1912-10-24:0":{"b": ["Nach der Schlacht von Kırkkilise geht Kırklareli verloren", "eda4c759"], "d": ["Nachdem die Ostarmee in Ostthrakien in der Schlacht von Kırkkilise besiegt worden war, wurde die von Kölemen Abdullah Pascha verteidigte Stadt den bulgarischen Truppen überlassen. Die Stadt wurde von der neun Monate dauernden Besetzung erst im Zweiten Balkankrieg am 21. Juli 1913 befreit.", "ee5cf8d2"]},
"OLAYLAR_EK10:1912-10-26:0":{"b": ["Üsküp (Skopje), das Zentrum des Vilâyets Kosovo, wird kampflos überlassen", "455d9b71"], "d": ["Nach der Niederlage von Kumanovo (23.–24. Oktober) blieb Üsküp, das Zentrum des Vilâyets Kosovo, ohne Verteidigung. Da die Bevölkerung keine Gefechte um die Stadt wollte, zogen die über die Konsuln eingeladenen serbischen Truppen unter dem Kommando von Prinz Alexander am Abend des 26. Oktober ohne Widerstand in die Stadt ein.", "3992a650"]},
"OLAYLAR_EK10:1912-10-28:0":{"b": ["Köprülü (Veles) am Vardar geht verloren", "73d20b7d"], "d": ["Zwei Tage nach dem Fall von Üsküp nahm das serbische Heer, das den Vardar entlang nach Süden vorrückte, Köprülü ein. Das Tor des Vardar-Tals nach Thessaloniki fiel damit in die Hände der Serben.", "e762a0e1"]},
"OLAYLAR_EK10:1912-10-29:0":{"b": ["Das Bregalnica-Becken: General Stefanović zog in Štip (İştip) ein", "70a84256"], "d": ["Die serbischen Truppen unter dem Kommando von General Stefanović nahmen İştip ein, ohne auf Widerstand zu stoßen; zuerst zogen irreguläre Banden in die Stadt ein. Nach Kumanovo geriet das Bregalnica-Becken in Ostmakedonien unter serbische Kontrolle.", "3b2e609b"]},
"OLAYLAR_EK10:1912-10-29:1":{"b": ["Nach dem Sarantaporo-Pass geht Karaferye an die griechische Herrschaft über", "02a68e02"], "d": ["Nachdem das aus Thessalien nach Norden vorrückende griechische Heer den Pass von Sarantaporo (Kırkgeçit) überwunden hatte, beherrschte es Karaferye. Ein Teil der muslimischen Bevölkerung der Stadt verließ die Region in dieser Zeit.", "a76cea57"]},
"OLAYLAR_EK10:1912-10-31:0":{"b": ["Vodina an der Bahnlinie Thessaloniki–Monastir geht verloren", "fc15b917"], "d": ["Vodina an der Bahnlinie Thessaloniki–Monastir fiel in die Hände des griechischen Heeres. Durch die erzwungene Trennung der slawischen und türkischen Bevölkerung ging die Einwohnerzahl der Stadt rasch ernsthaft zurück.", "e28f0a57"]},
"OLAYLAR_EK10:1912-11-02:0":{"b": ["Die Schlacht von Yenice – Yenice-i Vardar fällt an die Griechen", "8f6cb76e"], "d": ["Das 8. Gemischte Korps von Hasan Tahsin Pascha wurde bei Yenice westlich von Thessaloniki vom griechischen Heer besiegt und zog sich in das Gebiet von Thessaloniki zurück. Während der Schlacht brannte der größte Teil der Kleinstadt nieder; der Weg nach Thessaloniki stand dem griechischen Heer offen.", "d0f12da4"]},
"OLAYLAR_EK10:1912-11-03:0":{"b": ["Prizren im Südwesten des Kosovo ergibt sich", "bae6b1b9"], "d": ["Prizren im Südwesten des Kosovo ergab sich den serbischen Truppen. Das Verhalten der in die Stadt einziehenden Einheiten gegenüber der muslimischen Bevölkerung wurde als eines der schwersten Kapitel des Krieges im Kosovo verzeichnet.", "8cf0b7ae"]},
"OLAYLAR_EK10:1912-11-05:0":{"b": ["Oberst Mitov verhängt in Ustrumca den Belagerungszustand", "bcad75cc"], "d": ["Der bulgarische Oberst Mitov zog in Ustrumca ein und verhängte den Belagerungszustand; als er am folgenden Tag abzog, überließ er die Kleinstadt einem bulgarischen Kaymakam und einem serbischen Kommandanten. Ustrumca wechselte während des Krieges unter den Verbündeten den Besitzer und wurde 1913 Bulgarien angegliedert.", "acfc04ac"]},
"OLAYLAR_EK10:1912-11-08:0":{"b": ["Hasan Tahsin Pascha überließ Thessaloniki den Griechen", "1738933c"], "d": ["Hasan Tahsin Pascha, der sich nach der Niederlage von Yenice nach Thessaloniki zurückgezogen hatte, überließ die Stadt den Griechen, als das bulgarische Heer sich von Norden näherte; das griechische Heer zog am Mittag des 8. November in die Stadt ein. Thessaloniki, die größte Hafenstadt des osmanischen Rumeliens und Geburtsort des Komitees für Einheit und Fortschritt, ging damit verloren.", "e65f92fc"]},
"OLAYLAR_EK10:1912-11-21:0":{"b": ["Gümülcine, das Zentrum Westthrakiens, wurde den Bulgaren geöffnet", "96eec25f"], "d": ["Als die aus Kardschali abgezogene Abteilung von Yaver Pascha sich in Richtung Fere zurückzog, ergab sich Gümülcine den bulgarischen Truppen. Das Zentrum Westthrakiens gehörte zu den ersten der Gebiete, die am Ende des Krieges Bulgarien überlassen werden sollten.", "dab74d84"]},
"OLAYLAR_EK10:1912-11-28:0":{"b": ["Die in Elbasan (İlbasan) eintreffenden Serben zogen am selben Tag in Debar (Debre) ein", "16720246"], "d": ["Die von Monastir nach Westen vorrückenden serbischen Truppen zogen am Tag ihres Eintreffens in Elbasan auch in Debar ein und stiegen zur Adria hinab. Am selben Tag wurde in Vlora (Avlonya) die Unabhängigkeit Albaniens erklärt.", "6e52cff7"]},
"OLAYLAR_EK11:1401-01-01:0":{"b": ["Timur besetzte Bagdad zum zweiten Mal – die abbasidischen Viertel der Stadt wurden zerstört", "04b68a24"], "d": ["Timur nahm Bagdad im Abstand von acht Jahren zweimal ein. Bei der ersten Besetzung von 1393 hatte die Stadt nicht viel Schaden genommen; die zweite von 1401 gilt dagegen als der zweite schwere Schlag, der dem kulturellen Leben Bagdads zugefügt wurde – die Bevölkerung wurde über die Klinge springen gelassen, die meisten Viertel und Gebäude aus abbasidischer Zeit wurden zerstört. Der dschalairidische Herrscher Ahmed kehrte 1405 in die Stadt zurück und versuchte, die zerstörten Mauern und Basare instand zu setzen, fand aber keine Zeit dazu; Bagdad geriet 1410 in die Hand der Kara-Koyunlu-Turkmenen. Diese beiden Besetzungen gehören zu den konkretesten Schritten, die zeigen, wie nahe Timur auf dem Weg zur Schlacht von Ankara den osmanischen und mamlukischen Grenzen kam.", "b24ba76b"]},
"OLAYLAR_EK11:1422-01-01:0":{"b": ["Cüneyd Bey kehrte an die Spitze von Aydın-ili zurück – die Aydınoğulları wieder unabhängig", "63281658"], "d": ["Çelebi Mehmed hatte 1414–15 Izmir genommen und Cüneyd Bey zum Sandschakbeylik Nikopol geschickt, wodurch er Aydın-ili der osmanischen Verwaltung angegliedert hatte. Cüneyd trat nach dem Tod Çelebi Mehmeds an der Seite von Mustafa Çelebi, den Byzanz als Thronprätendenten vorgeschoben hatte, wieder auf die Bühne und war sogar sein Wesir. Murad II. trennte ihn mit dem Versprechen, ihm sein früheres Beylik zurückzugeben, von diesem Bündnis; Cüneyd kehrte nach Izmir zurück, nahm Ayasuluk ein, tötete den Aydınoğlu Mustafa Bey und gelangte an die Spitze des Beyliks. So entstand Aydın-ili aus der Krise des Falschen Mustafa heraus als aus der osmanischen Verwaltung ausgeschieden.", "c5020860"]},
"OLAYLAR_EK11:1426-01-01:0":{"b": ["Die Hinrichtung von Cüneyd Bey und seiner Familie – das Ende des Beyliks der Aydınoğulları", "efa684ba"], "d": ["Als Cüneyd Bey, der Aydın-ili wieder beherrschte, die anatolischen Beys aufwiegelte und Kontakt zu Venedig suchte, schickte Murad II. den Beylerbey von Anatolien, Hamza Bey, gegen ihn. Nachdem sein Sohn Kurd Hasan bei Akhisar besiegt und gefangen genommen worden war, zog sich Cüneyd nach İpsili gegenüber der Insel Samos zurück; als die vom Karamanoğlu erwartete Hilfe ausblieb und die gemeinsam mit den Osmanen handelnden Genuesen ihn von der See her blockierten, musste er sich ergeben; er wurde mit seiner ganzen Sippe beseitigt. Das Gebiet der Aydınoğulları kam damit vollständig unter osmanische Verwaltung.", "662b578c"]},
"OLAYLAR_EK11:1502-01-01:0":{"b": ["Erzurum und das Van-Becken gehen an die Safawiden über – die Nordflanke der Ak Koyunlu bricht zusammen", "b418875f"], "d": ["Schah Ismail, der bei Şerûr Elvend Bey besiegt hatte und im Sommer 1501 in Täbris eingezogen war, rückte im folgenden Jahr nach Nordwesten vor und brachte die Linie von Erzurum bis zum Van-See-Becken unter seine Herrschaft. Der Ak-Koyunlu-Staat war nach dem Tod Uzun Hasans durch Thronstreitigkeiten ohnehin in zwei Teile gespalten: Elvend Bey hielt Aserbaidschan und Diyarbekir, sein Vetter Murad Irak-i Adschem und Fars. Diese Spaltung erleichterte das safawidische Vordringen; die Region wechselte innerhalb eines Jahres in zehn Einträgen den Besitzer. Erzurum blieb danach sechzehn Jahre in safawidischer Hand und kam erst nach Çaldıran, 1518–19, unter osmanische Herrschaft.", "9c2345ba"]},
"OLAYLAR_EK11:1503-01-01:0":{"b": ["Die Niederlage von Murad Bey bei Hamadan: Irak-i Adschem und Fars gehen an die Safawiden über", "8de07a31"], "d": ["Sultan Murad, der zweite Prätendent des Ak-Koyunlu-Throns, erlitt in der Schlacht bei Hamadan gegen Schah Ismail eine schwere Niederlage und floh nach Bagdad. Mit dieser einen Schlacht kamen die Regionen Irak-i Adschem, Fars und Kerman unter safawidische Verwaltung; auf der Karte wechseln diese Regionen gleichzeitig den Besitzer. Dies ist der größte einzelne Schritt in der Auflösung des Ak-Koyunlu-Staates – der Verlust von Täbris hatte die Dynastie ohne Hauptstadt gelassen, die Niederlage von Hamadan ließ sie ohne Land zurück.", "f9d2ba4d"]},
"OLAYLAR_EK11:1504-12-06:0":{"b": ["Schah Ismail zog in Yazd ein: die letzte Festung der Ak-Koyunlu-Reste in Zentraliran fiel", "6f9835df"], "d": ["Obwohl Irak-i Adschem und Fars nach der Niederlage von Hamadan 1503 an die Safawiden gegangen waren, war Yazd in der Hand von Bayındırlı Murad Bey aus der Ak-Koyunlu-Dynastie gesondert geblieben. Die Stadt fiel nach einmonatiger Belagerung, und die letzte Ak-Koyunlu-Insel in Zentraliran war geschlossen. Die Aufzeichnung der TDV: „Schah Ismail zog am 28. Cemâziyelâhir 910 (6. Dezember 1504) nach einer einmonatigen Belagerung in die Stadt ein.“", "577a0ec7"]},
"OLAYLAR_EK11:1507-01-01:0":{"b": ["Schah Ismails Diyarbekir-Feldzug: die letzten Zentren der Ak Koyunlu fielen", "b6d8504e"], "d": ["Schah Ismail, der Aserbaidschan und das iranische Plateau in der Hand hatte, wandte sich 1507 nach Westen, in die Region Diyarbekir, wo die Ak-Koyunlu-Dynastie entstanden war. Die Linie von Âmid bis Mardin, von Urfa bis Harput kam in zwei Zügen unter safawidische Verwaltung, und die Ak Koyunlu verschwanden faktisch. Dieser Feldzug brachte die safawidische Grenze zum ersten Mal an die osmanische und mamlukische Grenze; so wurde der geographische Boden für die zu Çaldıran führende Spannung gelegt.", "d0346bf4"]},
"OLAYLAR_EK11:1508-01-01:0":{"b": ["Bagdad geht an die Safawiden über – Irak-i Arab wechselt den Besitzer", "39730186"], "d": ["Schah Ismail drang 1508 dem nach der Niederlage von Hamadan nach Bagdad geflohenen Ak-Koyunlu-Sultan Murad nach in Irak-i Arab ein und nahm Bagdad. Dass die Mausoleen in Kerbela und Nadschaf unter safawidische Verwaltung kamen, war im Hinblick auf den konfessionellen Anspruch der Bewegung ebenso wichtig wie die Einnahme von Täbris. Auf der Karte wechselt Irak-i Arab am selben Tag den Besitzer; dies ist der letzte und breiteste geographische Schritt des Auflösungsprozesses. Bagdad blieb bis zum Irakeyn-Feldzug Kanûnîs 1534 in safawidischer Hand.", "10e3e563"]},
"OLAYLAR_EK11:1510-12-02:0":{"b": ["Die Schlacht von Merw: Die Usbeken wurden schwer geschlagen, Merw und Herat genommen", "f8e45aaf"], "d": ["Schah Ismail, der im Westen das Erbe der Ak Koyunlu vervollständigt hatte, zog nach Osten, nach Chorasan, und brachte vor Merw den Usbeken eine schwere Niederlage bei; Şeybânî Khan fiel auf dem Schlachtfeld. Merw und Herat kamen unter safawidische Herrschaft, und der Safawidenstaat erlangte seine Grenzen, die sich vom Euphrat bis zum Amudarja erstreckten. Damit war der mit dem Einzug in Täbris im Sommer 1501 begonnene Prozess in neun Jahren abgeschlossen: Das Erbe der Ak Koyunlu war vollständig an die Safawidenverwaltung übergegangen, und das Osmanische Reich war im Osten zu einem zweiten Staat seiner eigenen Größe benachbart.", "ae88b613"]},
"OLAYLAR_EK11:1539-02-24:0":{"b": ["Die endgültige Aufnahme von Zabid in die osmanische Herrschaft", "ddd971c7"], "d": ["Die Flotte, die die Belagerung von Diu am 5. November 1538 aufgehoben hatte, legte auf der Rückfahrt an der jemenitischen Küste an, und Zabid wurde endgültig an die osmanische Verwaltung gebunden; Hadım Süleyman Pascha verließ die Stadt am 10. März 1539 und erreichte am 1. April Dschidda. Die Stadt war seit 1517 im Namen der Osmanen von den früheren Mamlukenbeys verwaltet worden; mit diesem Datum ging sie in die unmittelbare Verwaltung über.", "5718f027"]},
"OLAYLAR_EK11:1581-04-16:0":{"b": ["Die Iberische Union: Die portugiesische Krone ging an den König von Spanien", "1cc6dfdc"], "d": ["Der mit dem erbenlosen Tod von Kardinal-König Heinrich eröffnete Erbfolgestreit wurde in der Schlacht von Alcântara (25. August 1580) zugunsten Spaniens entschieden, und die in Tomar versammelten portugiesischen Cortes erkannten Philipp II. am 16. April 1581 als König von Portugal an. Nach den Bedingungen von Tomar sollte Portugal seine eigenen Institutionen, sein Geld und seine Sprache behalten, in der Verwaltung sollten nur Portugiesen ernannt werden, und in Madrid sollte es einen eigenen portugiesischen Rat geben – das heißt, die Vereinigung war eine Personalunion, keine Annexion.", "40bd79df"]},
"OLAYLAR_EK11:1640-12-01:0":{"b": ["Restauração: Portugal gewann seine Unabhängigkeit zurück", "64ec0738"], "d": ["In den Tagen, in denen der katalanische Aufstand Spanien beschäftigte, überfiel in Lissabon eine Gruppe von Adligen den Palast, stürzte die spanische Verwaltung und rief den Herzog von Braganza als João IV. zum König aus. Die sechzig Jahre dauernde Iberische Union endete damit; Ceuta entschied sich jedoch, bei Spanien zu bleiben, und dies wurde durch den Vertrag von Lissabon von 1668 anerkannt. Dieses Zeitfenster, in dem Portugal in die Habsburger-Kriege eingebunden war, ist auch der Rahmen seiner Verluste in Asien: Hormuz ging 1622, Malakka 1641, Colombo 1656 verloren; Tanger und Bombay wurden als Preis der Unabhängigkeit an England abgetreten. Quelle: Britannica, History of Portugal — Restoration.", "bb04bea3"]},
"OLAYLAR_EK11:1662-01-30:0":{"b": ["Tanger wurde England übertragen", "1f7cad6d"], "d": ["Der zweite Artikel des Heiratsvertrags (23. Juni 1661), der geschlossen wurde, um die englische Unterstützung im portugiesischen Unabhängigkeitskrieg zu sichern, überließ Tanger als Mitgift von Katharina von Braganza England. Die Flotte des Earl of Sandwich ging am 29. Januar 1662 vor Anker, und am folgenden Tag erfolgte die offizielle Übergabe mit einer Zeremonie des Earl of Peterborough. Die Engländer sollten die Stadt 1684 verlassen.", "9328c723"]},
"OLAYLAR_EK11:1747-06-20:0":{"b": ["Die Ermordung Nâdir Schahs – die Auflösung der Afscharen-Herrschaft", "19c218c0"], "d": ["Nâdir Schah, der die Safawidenherrschaft beendet und 1736 in eigenem Namen die Herrschaft ausgerufen hatte, mit seinem Indien-Feldzug bis nach Delhi gelangt war und mit den Osmanen drei Kriege geführt und mit dem Vertrag von Kerden von 1746 Frieden geschlossen hatte, wurde von seinen eigenen Leibwächtern in seinem Zelt ermordet. Danach konnte Iran nicht mehr aus einer Hand regiert werden: Ein Rest der Afscharen in Chorasan, die Zand im Süden und die im Norden aufsteigenden Kadscharen teilten das Land neunundvierzig Jahre lang unter sich auf. Die osmanische Ostgrenze blieb dank dieser Zersplitterung lange Zeit ruhig.", "76a3f7ee"]},
"OLAYLAR_EK11:1796-01-01:0":{"b": ["Die Kadscharen-Dynastie wird zur Herrscherin Irans", "744b48c5"], "d": ["Der Anführer des Kadscharen-Stammes, Agha Mohammad Khan, stürzte die Zand-Herrschaft, brach den letzten afscharischen Widerstand in Chorasan, vereinte Iran wieder in einer Hand und machte Teheran zur Hauptstadt. Die neunundvierzigjährige Periode der Zersplitterung war damit beendet; von da an sollte der östliche Nachbar der Osmanen bis 1923 das Kadscharen-Iran sein.", "15d0cfa9"]},
"OLAYLAR_EK12:1527-09-23:0":{"b": ["Ferdinand nahm Buda ein – Szapolyai wurde aus der Hauptstadt vertrieben", "99f77c29"], "d": ["Nach Mohács waren auf dem ungarischen Thron zwei Könige aufgetreten: Ein Teil des Adels hatte János Szapolyai, ein Teil den Habsburger Ferdinand gewählt. Ferdinand nahm 1527 Buda ein und vertrieb Szapolyai aus der Hauptstadt; Szapolyai bat Sultan Süleyman um Hilfe. Dies ist der Grund, weshalb das erste Ziel des Wien-Feldzugs von 1529 Buda war.", "e45db1f0"]},
"OLAYLAR_EK12:1537-01-01:0":{"b": ["Barbarossas Feldzug zu den Ägäischen Inseln – das Herzogtum Naxos geriet unter osmanische Kontrolle", "722b2fea"], "d": ["Das Herzogtum Naxos, das seit 1207 unter venezianischer Schutzherrschaft von lateinischen Herzögen regiert worden war, geriet durch den Inselfeldzug von Barbaros Hayreddin Pascha unter osmanische Kontrolle. Am Status der Insel wurde nicht gerührt; das Herzogtum bestand als den Osmanen tributpflichtig fort, und mit dem osmanisch-venezianischen Abkommen von 1540 wurde das Herrschaftsrecht offiziell den Osmanen überlassen.", "e20e29f9"]},
"OLAYLAR_EK12:1560-03-12:0":{"b": ["Die Kreuzfahrerflotte besetzte Djerba – der Stützpunkt von Turgut Pascha ging verloren", "f41b3f2a"], "d": ["Die aus spanischen, päpstlichen, maltesischen, genuesischen und florentinischen Schiffen gebildete Kreuzfahrerflotte nahm Djerba ins Visier, das Turgut Reis seit 1551 als Stützpunkt für Streifzüge benutzt hatte. Wegen Stürmen und Seuchen konnte sie erst Anfang des Jahres 1560 vor der Insel eintreffen; am 12. März 1560 besetzte sie die Insel und errichtete eine Festung. Piyâle Pascha brach, als er davon erfuhr, am 28. März mit seiner Flotte von 120 Galeeren von Istanbul auf. Die Besetzung dauerte nicht lange: Die osmanische Flotte besiegte im Mai vor Djerba die Verbündeten, und die Festung wurde Ende Juli zurückerobert. Dieser Feldzug ist der Beginn der zweiten großen Seeoperation, die nach Preveza die osmanische Überlegenheit im Mittelmeer festigte.", "a420585e"]},
"OLAYLAR_EK12:1560-07-30:0":{"b": ["Der Fall der Festung von Djerba – der Übergang der Insel unter osmanische Verwaltung", "f1efc0df"], "d": ["Nach dem Seesieg Piyâle Paschas vom 14. Mai 1560 schlossen sich die Kreuzfahrertruppen in der auf der Insel erbauten Festung ein; die Truppen des Beylerbeys von Tripolis, Turgut Pascha, belagerten sie von Land aus. Die zwei Monate dauernde Belagerung endete am 30. Juli 1560 mit dem Fall der Festung, und die Insel wurde dem Beylerbeyilik Tripolis angegliedert. Zwischen dem Seesieg und der Eroberung der Festung liegen siebenundsiebzig Tage; die Insel hat nicht am 14. Mai, sondern am 30. Juli faktisch den Besitzer gewechselt.", "50b148da"]},
"OLAYLAR_EK12:1814-02-04:0":{"b": ["In Danzig endete die russisch-preußische Doppelherrschaft – Napoleons Freie Stadt kehrte an Preußen zurück", "1ccda4d2"], "d": ["Danzig, das durch den Frieden von Tilsit (9. Juli 1807) von Preußen getrennt und unter französischem Schutz zur Freien Stadt gemacht worden war, wurde von Napoleons Truppen nach der Belagerung von 1813 aufgegeben. Zwischen dem 2. Januar und dem 4. Februar 1814 hielt sich in der Stadt die russisch-preußische Doppelherrschaft; als Zar Alexander seinen Plan aufgab, Danzig und die Weichselmündung zu nehmen, ging die Stadt an die preußische Verwaltung über.", "8d215059"]},
"OLAYLAR_EK12:1913-08-31:0":{"b": ["Die Provisorische Regierung Westthrakiens mit Sitz in Gümülcine wird ausgerufen", "974b2e28"], "d": ["Als der Vertrag von Bukarest (10. August 1913) Westthrakien Bulgarien überließ, rief die türkische Bevölkerung der Region eine vorläufige Regierung mit Sitz in Gümülcine aus; nach der Einnahme von Dedeağaç verkündete die Regierung ihre Unabhängigkeit unter dem Namen „Garbî Trakya Hükûmet-i Müstakillesi“ (Unabhängige Regierung Westthrakiens). Durch das Eingreifen der Großmächte unterstützte die osmanische Regierung sie nicht; der Vertrag von Istanbul vom 29. September 1913 überließ Westthrakien den Bulgaren, und die Regierung lebte bis zum 25. Oktober 1913 nur siebenundfünfzig Tage.", "86d3bfee"]},
"OLAYLAR_EK12:1920-11-15:0":{"b": ["Die Freie Stadt Danzig wurde unter dem Schutz des Völkerbundes gegründet", "bd148fe8"], "d": ["Danzig, das durch den Vertrag von Versailles von Deutschland getrennt worden war, blieb ab dem 10. Januar 1920 unter der Übergangsverwaltung der alliierten Großmächte; am 15. November 1920 wurde es als Freie Stadt unter dem Schutz des Völkerbundes in einer Zollunion mit Polen gegründet.", "c74affc1"]},
"OLAYLAR_EK2:1327-01-01:0":{"b": ["Prägung der ersten osmanischen Akçe", "38d2d638"], "d": ["Die auf den Namen Orhan Gazis geprägte erste Silber-Akçe ist die monetäre Verkündung der unabhängigen Souveränität des Beylik; die Akçe blieb fünf Jahrhunderte lang die grundlegende Währungseinheit.", "8729ab5b"]},
"OLAYLAR_EK2:1362-09-01:0":{"b": ["Gründung des Beylerbeylik von Rumelien", "ffa16089"], "d": ["Die Eroberungen auf der europäischen Seite wurden unter einem einzigen militärisch-administrativen Dach zusammengefasst; die Beylerbeylik-Ordnung wurde zum Rückgrat der Provinzorganisation des Reiches.", "9c13c8c3"]},
"OLAYLAR_EK2:1390-01-15:0":{"b": ["Heirat Bayezid Yıldırıms mit Despina Hatun", "4b10dc6c"], "d": ["Das nach dem Amselfeld mit dem serbischen Despotat begründete Vasallenverhältnis wurde durch die Heirat Oliveras, der Tochter Lazars, mit Bayezid besiegelt — ein typisches Beispiel der frühen Heiratsdiplomatie.", "7d87810a"]},
"OLAYLAR_EK2:1393-01-01:0":{"b": ["Gründung des Beylerbeylik von Anatolien", "5ef8d3a7"], "d": ["Zur Verwaltung der annektierten Beylik-Gebiete wurde das Beylerbeylik von Anatolien organisiert; die zweiflügelige Verwaltungsordnung Rumelien–Anatolien war vollendet.", "55429c02"]},
"OLAYLAR_EK2:1399-06-01:0":{"b": ["Fertigstellung der Ulu Camii von Bursa", "27bcc4a5"], "d": ["Die mit der Beute von Nikopolis erbaute zwanzigkuppelige Große Moschee ist ein monumentales Beispiel der frühosmanischen Architektur und ein offenes Museum der Kalligrafie.", "b0e811e6"]},
"OLAYLAR_EK2:1453-06-01:0":{"b": ["Absetzung und Hinrichtung des Çandarlı Halil Pascha", "5e19438f"], "d": ["Nach der Eroberung wurde der Großwesir aus der alteingesessenen Familie Çandarlı, die der Belagerung distanziert gegenübergestanden hatte, hingerichtet; erstmals wurde ein Großwesir auf Befehl des Sultans getötet, und das Zeitalter der Wesire aus der Devschirme brach an.", "557b77f5"]},
"OLAYLAR_EK2:1456-06-01:0":{"b": ["Tributpflicht der Moldau", "25bd3693"], "d": ["Das Woiwodat Moldau willigte ein, Tribut zu zahlen; zusammen mit der Walachei und Siebenbürgen wurde der dreifache Vasallengürtel nördlich der Donau zur nördlichen Pufferzone des Reiches. Zum selben Datum angeschlossene weitere Orte: Iași.", "7cea09ea"]},
"OLAYLAR_EK2:1459-03-07:0":{"b": ["Tribut von Dubrovnik (Ragusa)", "d127c78a"], "d": ["Die Kaufmannsrepublik Ragusa sicherte sich gegen Tribut ihre Autonomie und ihre Handelsprivilegien; als Fenster der Osmanen zur Adria wurde sie wohlhabend. Auch die Insel Mljet, die zum Gebiet der Republik gehörte, teilte diesen Status.", "812b9f2b"]},
"OLAYLAR_EK2:1462-06-01:0":{"b": ["Walachei-Feldzug: der Pfähler-Woiwode", "fd4530bb"], "d": ["Mit dem Feldzug gegen Vlad Țepeș, der den Tribut verweigert und die Gesandten getötet hatte, wurde die Walachei in die Vasallität zurückgeführt; der nächtliche Überfall und die Schreckensszenen der Pfählung wurden in Europa zur Legende. Zum selben Datum angeschlossene weitere Orte: Bukarest.", "6ae089b4"]},
"OLAYLAR_EK2:1470-12-01:0":{"b": ["Eröffnung des Fatih-Komplexes", "a150ea55"], "d": ["Der Komplex mit seinen acht Medresen (Sahn-ı Semân) war der erste große Schritt des Programms, Istanbul zum Wissenschaftszentrum der islamischen Welt zu machen.", "cbec7a2f"]},
"OLAYLAR_EK2:1472-01-01:0":{"b": ["Ali Kuşçu in Istanbul", "8508229d"], "d": ["Ali Kuşçu, der letzte große Vertreter des Observatoriums von Samarkand, wurde auf Einladung Mehmeds des Eroberers Müderris an der Hagia-Sophia-Medrese; er begründete die mathematisch-astronomische Tradition in Istanbul.", "fd325f60"]},
"OLAYLAR_EK2:1477-01-01:0":{"b": ["Kanunname Mehmeds des Eroberers (Fâtih Kanunnâmesi)", "b08944c9"], "d": ["Die erste umfassende Gewohnheitsrechts-Kanunname, die Staatsorganisation, Protokoll und Strafen zusammenstellt; wegen ihres berühmten Artikels, der den Brudermord „für die Ordnung der Welt (nizâm-ı âlem)“ erlaubte, wird sie bis heute diskutiert.", "0e654de1"]},
"OLAYLAR_EK2:1478-06-01:0":{"b": ["Erste osmanische Goldmünze (Sultanî) geprägt", "2fd5c0dd"], "d": ["Die erste osmanische Goldmünze, dem venezianischen Dukaten gleichwertig, wurde geprägt; die Finanzen des Reiches traten in die internationale Währungsordnung ein.", "cac00614"]},
"OLAYLAR_EK2:1478-09-01:0":{"b": ["Umzug in den Topkapı-Palast", "b9cd6a5e"], "d": ["Mit der Fertigstellung des Neuen Palastes (Topkapı) wurde das Zentrum der Staatsverwaltung hierher verlegt; der Palast blieb vier Jahrhunderte lang das Gehirn des Reiches.", "748ada37"]},
"OLAYLAR_EK2:1532-04-27:0":{"b": ["Die Florentiner Republik wird Herzogtum – Alessandro de' Medici", "c08764e1"], "d": ["Auf Druck von Papst Klemens VII. nahm die Regierungskommission (Balìa) Florenz' eine neue Verfassung an; das fünfhundertjährige republikanische Regime wurde beseitigt, Alessandro de' Medici zum erblichen Herzog ausgerufen und bestieg am 1. Mai faktisch den Thron. Florenz wandelte sich so von einer unabhängigen Stadtrepublik in ein erbliches Herzogtum der Medici-Dynastie.", "92da65c9"]},
"OLAYLAR_EK2:1534-01-01:0":{"b": ["Eheschließung Süleymans des Gesetzgebers mit Hürrem Sultan", "abc05f26"], "d": ["Dass Süleyman Hürrem förmlich heiratete, veränderte die Hoftradition von Grund auf; die Institution der „Haseki Sultan“ entstand, und das Tor zum Zeitalter der Frauen in der Dynastiepolitik wurde geöffnet.", "db1f832b"]},
"OLAYLAR_EK2:1536-02-18:0":{"b": ["Erste umfassende Kapitulationen für Frankreich", "e2264e48"], "d": ["Im Rahmen des Bündnisses mit Frankreich gegen die Habsburger Umklammerung wurden zwischen Jean de la Forest und Makbul İbrâhim Pascha Handelsprivilegien unterzeichnet; die Kapitulationen, damals ein diplomatisches Instrument, sollten sich im Lauf der Jahrhunderte zur Tür der finanziellen Abhängigkeit entwickeln.", "e7c6fd84"]},
"OLAYLAR_EK2:1538-06-13:0":{"b": ["Indischer-Ozean-Feldzug: Belagerung von Diu", "fcd1217a"], "d": ["Die von Suez ausgelaufene Flotte durchquerte das Rote Meer und belagerte Diu in Gujarat; obwohl die Festung nicht genommen werden konnte, reichte die osmanische Macht erstmals bis in den Indischen Ozean, das portugiesische Monopol wurde erschüttert.", "ce118bf7"]},
"OLAYLAR_EK2:1553-12-07:0":{"b": ["Indienreise des Seydi Ali Reis", "e5da3b2c"], "d": ["Seydi Ali Reis, der beauftragt war, die Flotte aus Basra nach Ägypten zu bringen, wurde von Stürmen nach Indien verschlagen; sein Mir'âtü'l-memâlik, in dem er das Abenteuer der Rückkehr schildert, gehört zu den frühesten osmanischen Reisebeschreibungen.", "bb472cec"]},
"OLAYLAR_EK2:1554-01-01:0":{"b": ["Hinrichtung des Pîrî Reis", "63026444"], "d": ["Der große Seefahrer und Kartograf, der vom Hormuz-Feldzug zurückkehrte und die Flotte in Basra zurückgelassen hatte, wurde im Alter von 84 Jahren hingerichtet — eine der umstrittensten Entscheidungen unserer Wissenschaftsgeschichte.", "e3d1ac3f"]},
"OLAYLAR_EK2:1557-10-16:0":{"b": ["Eröffnung des Süleymaniye-Komplexes", "1c6458b2"], "d": ["Der Komplex, den der Baumeister Sinan sein „Gesellenwerk“ nannte, wurde mit seinen Medresen, seinem Dârüşşifâ (Krankenhaus) und seiner Bibliothek der größte Bildungs- und Wohltätigkeitskomplex der klassischen Zeit.", "0c203c6b"]},
"OLAYLAR_EK2:1565-05-18:0":{"b": ["Belagerung von Malta", "f57f6a85"], "d": ["Malta, der Schlüssel des Mittelmeers, wurde vier Monate belagert; Turgut Reis fiel, die Belagerung wurde aufgehoben. Sie war der erste große Rückschlag der Seefahrt der Zeit Süleymans des Gesetzgebers.", "860ee1bc"]},
"OLAYLAR_EK2:1575-03-01:0":{"b": ["Fertigstellung der Selimiye-Moschee", "3b0484e1"], "d": ["Die Selimiye, die Sinan sein „Meisterwerk“ nannte und in der eine einzige Kuppel den Raum beherrscht, gilt als Höhepunkt der klassischen osmanischen Architektur (UNESCO-Welterbe).", "9d7cd43c"]},
"OLAYLAR_EK2:1577-01-01:0":{"b": ["Gründung der Sternwarte von Istanbul", "169bdf5d"], "d": ["Die Sternwarte des Takiyyüddin, eine der bestausgestatteten Sternwarten ihrer Zeit, wurde 1580 nach den Auseinandersetzungen im Gefolge des Kometen von 1577 abgerissen; die institutionelle Astronomie verspätete sich um drei Jahrhunderte.", "7fb471aa"]},
"OLAYLAR_EK2:1578-08-09:0":{"b": ["Sieg von Çıldır – der Ostkrieg beginnt", "13125a54"], "d": ["Mit der Niederlage des safawidischen Heeres bei Çıldır öffneten sich die Tore des Kaukasus; Tiflis wurde genommen, und Georgien kam unter osmanische Herrschaft.", "0bf34d05"]},
"OLAYLAR_EK2:1583-05-09:0":{"b": ["Schlacht der Fackeln – Schirwan endgültig bei den Osmanen", "3bbc23bc"], "d": ["In der Schlacht, die ihren Namen daher hat, dass sie auch nachts im Fackellicht fortgesetzt wurde, wurden die Safawiden endgültig geschlagen; die osmanische Herrschaft in Schirwan und Baku wurde gefestigt.", "e2aa6d1e"]},
"OLAYLAR_EK2:1585-01-01:0":{"b": ["Große Münzverschlechterung (Tağşiş) – Akçe-Krise", "9205c3d4"], "d": ["Unter dem Druck der langen Kriege und des amerikanischen Silbers wurde der Silbergehalt der Akçe halbiert; die Preisrevolution nährte die Auflösung der Sipahi-Ordnung und die Celâlî-Wirren.", "bd2a508f"]},
"OLAYLAR_EK2:1585-09-25:0":{"b": ["Eroberung von Täbris", "6506bdb9"], "d": ["Serdar Özdemiroğlu Osman Pascha zog in Täbris ein; die alte Hauptstadt der Safawiden wurde unter osmanische Verwaltung genommen. Osman Pascha starb einige Wochen später im Heerlager.", "e54b35bd"]},
"OLAYLAR_EK2:1590-03-21:0":{"b": ["Vertrag des Ferhad Pascha – größte Ausdehnung im Osten", "c429972f"], "d": ["Nach der Ankunft des Gesandten Schah Abbas', Haydar Mirza, in Istanbul (18. Januar 1590) blieben mit dem unter der Bedingung, dass die eroberten Orte bei den Osmanen blieben, geschlossenen und den zwölfjährigen Krieg beendenden Vertrag Täbris, Karabach, Schirwan, Georgien und Luristan bei den Osmanen; das Reich erreichte im Osten die größte Ausdehnung seiner Geschichte.", "41d8b058"]},
"OLAYLAR_EK2:1603-10-21:0":{"b": ["Beginn des Osmanisch-Safawidischen Krieges (1603–1612) – Gegenangriff Schah Abbas', Verlust von Täbris", "abf27dd8"], "d": ["Schah Abbas, der sein Heer neu organisiert hatte, ging unter Ausnutzung der Celâlî-Wirren zum Angriff über; Täbris fiel, die Gewinne im Kaukasus gingen binnen weniger Jahre verloren. Auf demselben Feldzug und danach verlorene weitere Siedlungen: Nachitschewan, Hoy, Merend, Selmâs; auch die Beys von Karacadağ (Ahar) und Mukrî wandten sich der safawidischen Seite zu.", "b1757da9"]},
"OLAYLAR_EK2:1611-03-25:0":{"b": ["Geburt des Evliya Çelebi", "2b6051ff"], "d": ["Evliya Çelebi, der seine über fünfzig Jahre währenden Reisen im zehnbändigen Seyahatnâme zusammentrug, hinterließ ein einzigartiges Panorama der osmanischen Welt des 17. Jahrhunderts.", "bbd451a3"]},
"OLAYLAR_EK2:1612-11-20:0":{"b": ["Vertrag des Nasuh Pascha", "bb69e388"], "d": ["Mit dem Vertrag, der den seit 1603 währenden Krieg beendete, wurde auf die Gewinne von 1590 verzichtet und zur Grenze von Amasya von 1555 zurückgekehrt; an der Ostfront war das Gleichgewicht wiederhergestellt.", "f3ce47a7"]},
"OLAYLAR_EK2:1616-06-09:0":{"b": ["Eröffnung der Sultan-Ahmed-Moschee", "e39dfd43"], "d": ["Mit ihren sechs Minaretten und den blauen İznik-Fliesen ist die „Blaue Moschee“ der letzte große Sultanskomplex (Selâtin-Külliye) der klassischen Zeit.", "c3e55fc5"]},
"OLAYLAR_EK2:1648-08-18:0":{"b": ["Ermordung Sultan İbrahims", "bc4eb452"], "d": ["Mit der Begründung von Verschwendung und Regierungskrise setzte das Bündnis von Korps und Ulema İbrahim ab; zehn Tage später wurde er per Fetwa erdrosselt. Der siebenjährige Mehmed IV. bestieg den Thron; die Macht ging faktisch an die große Valide Kösem Sultan.", "b90693f4"]},
"OLAYLAR_EK2:1657-10-06:0":{"b": ["Tod des Kâtib Çelebi", "e167e89d"], "d": ["Mit seiner Bibliografie Keşfü'z-zunûn und seiner Geografie Cihannümâ ist er die Gipfelgestalt der osmanischen Wissenschaftsgeschichte; er ist bekannt für seinen bahnbrechenden Ansatz, europäische Quellen zu nutzen.", "786ec8d5"]},
"OLAYLAR_EK2:1703-08-22:0":{"b": ["Edirne-Vorfall (Edirne Vakası) – Absetzung Mustafas II.", "0291c1cd"], "d": ["Dass sich der Sultan in Edirne aufhielt, und der Zorn über den Einfluss Feyzullah Efendis mündeten in einen großen Aufstand von Heer und Handwerkern; der Scheich ül-Islam wurde gelyncht, der Sultan abgesetzt, der Hof kehrte nach Istanbul zurück.", "e8740499"]},
"OLAYLAR_EK2:1720-10-08:0":{"b": ["Botschafter nach Paris: Yirmisekiz Mehmed Çelebi", "26312a3f"], "d": ["Die nach Frankreich entsandte große Gesandtschaft war die erste systematische Beobachtung des Westens an Ort und Stelle; sein Sefâretnâme inspirierte die Erneuerung der Tulpenzeit.", "aa11c96a"]},
"OLAYLAR_EK2:1727-07-05:0":{"b": ["Gründung der ersten osmanischen Druckerei", "4943f7e5"], "d": ["Die Erlaubnis zum Druck türkischer Bücher wurde erteilt; das erste Werk, das Vankulu-Wörterbuch (Vankulu Lügati), wurde 1729 gedruckt. Die Druckerei ist das dauerhafteste Erbe der Erneuerung der Tulpenzeit.", "a33e45d0"]},
"OLAYLAR_EK2:1740-05-30:0":{"b": ["Kapitulationen werden dauerhaft", "d044a79e"], "d": ["Die Frankreich gewährten Privilegien wurden von der Bindung an den jeweiligen Sultan gelöst und an einen dauerhaften Vertrag gebunden; das Kapitulationsregime, das einseitig nicht mehr kündbar war, konnte erst in Lausanne beseitigt werden.", "d50899dc"]},
"OLAYLAR_EK2:1773-01-01:0":{"b": ["Gründung der Mühendishâne-i Bahrî-i Hümâyun", "9bf3f439"], "d": ["Die nach der Katastrophe von Çeşme zur Ausbildung moderner Marineoffiziere gegründete Ingenieurschule ist die erste dauerhafte Institution der technischen Bildung nach westlichem Muster; die Landingenieurschule folgte 1795.", "b73b2ce6"]},
"OLAYLAR_EK2:1793-06-01:0":{"b": ["Erste ständige Botschaft in London", "6b5630eb"], "d": ["Als Teil des Nizâm-ı Cedîd-Programms wurden in den europäischen Hauptstädten ständige Botschaften eröffnet; die osmanische Diplomatie ging zum Prinzip der Gegenseitigkeit über.", "0321b899"]},
"OLAYLAR_EK2:1808-11-16:0":{"b": ["Tod des Alemdar Mustafa Pascha", "4426534e"], "d": ["Der reformerische Großwesir, der in dem in der Nacht vom 15. November 1808 begonnenen Janitscharenaufstand an der Hohen Pforte (Bâbıâli) eingeschlossen wurde, sprengte, als die erwartete Hilfe nicht kam, am folgenden Tag das Munitionslager und starb mit Hunderten von Angreifern; die Ordnung des Sened-i İttifak und der erste Reformversuch wurden mit ihm begraben.", "04420a26"]},
"OLAYLAR_EK2:1831-11-01:0":{"b": ["Erste amtliche Zeitung: Takvîm-i Vekāyi", "c637f623"], "d": ["Die amtliche Zeitung des Staates begann zu erscheinen; sie ist der Beginn der Tradition der modernen Öffentlichkeit und amtlichen Bekanntmachung.", "b4f1f627"]},
"OLAYLAR_EK2:1838-08-16:0":{"b": ["Handelsvertrag von Balta Limanı", "e790b383"], "d": ["England wurde auch im Binnenhandel die meistbegünstigte Stellung eingeräumt, das Verfahren des Yed-i vahid (Monopol) wurde abgeschafft; während die einheimische Produktion schutzlos blieb, wurde der Vertrag zum Dokument der vollständigen Öffnung des osmanischen Marktes für den Freihandel.", "14089a77"]},
"OLAYLAR_EK2:1842-01-01:0":{"b": ["Ende des Emirats Libanon – Absetzung Beschirs III. Schihab", "f85ae454"], "d": ["Emir Beschir II. (III.), der den christlich-drusischen Streit und die inneren Gleichgewichte in der Region Schuf nicht kontrollieren konnte, wurde im Januar 1842 abgesetzt; die seit 1516 (durch die Ma'noğulları und anschließend die Şihâboğulları) bestehende lokale Emirats-Ordnung endete, und die Region ging zur unmittelbaren osmanischen Verwaltung, danach zum System der doppelten Kaymakamlık über.", "205abc18"]},
"OLAYLAR_EK2:1844-01-01:0":{"b": ["Tashîh-i sikke: Mecidiye-Ordnung", "c77be809"], "d": ["Durch die Münzreform wurden die im Feingehalt verdorbenen Münzen eingezogen; eine stabile Doppelwährungsordnung auf der Grundlage des Goldpfundes (Mecidiye) wurde eingerichtet.", "e0642ec8"]},
"OLAYLAR_EK2:1850-01-01:0":{"b": ["Ende der lokalen Herrschaft der Familie Harfûş in Baalbek", "8438f4ae"], "d": ["Der Einfluss der Familie Harfûş, die seit 1521 (nach dem Aufstand des Canbirdi Gazâlî) in Baalbek als kleine lokale Dynastie geherrscht hatte, endete mit der neuen Verwaltungsregelung der Hohen Pforte; die Stadt wurde zu einem gewöhnlichen, dem Vilayet Damaskus unterstellten Kaza-Zentrum gemacht.", "106eabb2"]},
"OLAYLAR_EK2:1851-01-01:0":{"b": ["Gründung der Şirket-i Hayriyye", "462830e7"], "d": ["Die zum Betrieb von Dampfschiffen auf dem Bosporus gegründete Gesellschaft gilt als die erste osmanische Aktiengesellschaft; die Dampfschiffanlegestellen prägten das Stadtleben.", "b4203b61"]},
"OLAYLAR_EK2:1854-08-24:0":{"b": ["Erste Auslandsschuldenvereinbarung", "9017c579"], "d": ["Zur Finanzierung des Krimkrieges wurde am Londoner Markt die erste Auslandsanleihe aufgenommen; der Punkt, den man nach 15 Anleihen in 21 Jahren erreichte, war das Moratorium von 1875 und die Düyûn-ı Umûmiyye.", "1c4f9949"]},
"OLAYLAR_EK2:1855-09-14:0":{"b": ["Telegrafenlinie in Istanbul", "d320f39f"], "d": ["Die durch die Bedürfnisse des Krimkrieges eingerichtete erste Telegrafenlinie wurde in Betrieb genommen; binnen weniger Jahrzehnte erhielt das Reich eines der größten Telegrafennetze der Welt.", "f59439a3"]},
"OLAYLAR_EK2:1858-06-06:0":{"b": ["Bodengesetz (Arazi Kanunnâmesi)", "6bae243a"], "d": ["Die Kanunname, die das Bodenrecht modernisierte, band die faktische Verfügung über Staatsland (mîrî) an das Grundbuch (Tapu); sie gehört zu den grundlegenden Dokumenten der Eigentumsordnung des heutigen Nahen Ostens.", "395494dc"]},
"OLAYLAR_EK2:1863-01-13:0":{"b": ["Erste Vorlesungen im Dârülfünun", "08f74066"], "d": ["Das Dârülfünun, das Bildung auf Universitätsniveau vermitteln sollte, nahm mit öffentlichen Vorlesungen die Arbeit auf; die mit Unterbrechungen bestehende Institution wurde 1900 dauerhaft eröffnet und wurde zum Kern der Universität Istanbul.", "6218d070"]},
"OLAYLAR_EK2:1864-11-08:0":{"b": ["Provinzverordnung (Vilâyet Nizamnâmesi)", "ad20853b"], "d": ["Anstelle der Eyalet-Ordnung wurde nach französischem Vorbild die Vilayet-Organisation geschaffen; nach dem Muster der Anwendung Midhat Paschas im Donau-Vilayet wurde sie auf das ganze Land ausgeweitet.", "665b97d3"]},
"OLAYLAR_EK2:1867-06-21:0":{"b": ["Europareise Abdülazizs", "9ff0fa1e"], "d": ["Die erste Europareise eines osmanischen Sultans zu friedlichen Zwecken; die Pariser Ausstellung und die Besuche in London dienten zugleich als Schaufenster der Diplomatie und der Modernisierung.", "bd58ae5d"]},
"OLAYLAR_EK2:1868-09-01:0":{"b": ["Eröffnung des Galatasaray Mekteb-i Sultânîsi", "f9688524"], "d": ["Das Gymnasium mit französischem Unterricht wurde mit seiner Schülerschaft ohne Unterschied von Religion und Millet zum Symbol des Ideals der Gleichheit in der Bildung in der Tanzimat.", "c9d5821d"]},
"OLAYLAR_EK2:1869-04-01:0":{"b": ["Erstes Buch der Mecelle in Kraft", "6475461c"], "d": ["Die Mecelle, die das Schuld- und Sachenrecht des islamischen Rechts mit moderner Gesetzgebungstechnik zusammenfasste, gilt als das erste islamische Zivilgesetzbuch; die Kommission unter dem Vorsitz von Cevdet Pascha vollendete die 16 Bücher 1876.", "9669c96e"]},
"OLAYLAR_EK2:1876-05-30:0":{"b": ["Absetzung Abdülazizs", "eb7397ea"], "d": ["Konstitutionell gesinnte Staatsmänner und die Militärführung setzten Abdülaziz in einem stillen Staatsstreich ab; sein verdächtiger Tod fünf Tage später und die anschließenden Ereignisse von Çırağan lösten jahrelange Abrechnungen aus.", "9523e81b"]},
"OLAYLAR_EK2:1878-05-20:0":{"b": ["Überfall auf den Çırağan-Palast (Ali-Suâvi-Affäre)", "d2a9ac87"], "d": ["Der Journalist Ali Suâvi überfiel Çırağan, um Murad V. wieder auf den Thron zu setzen; der Überfall wurde blutig niedergeschlagen, und das Regime Abdülhamids zog den Sicherheitsring dauerhaft enger.", "8bd8ba3f"]},
"OLAYLAR_EK2:1884-01-01:0":{"b": ["Gründung der Régie-Verwaltung (Tabakmonopol)", "bad9b030"], "d": ["Die Tabakeinnahmen wurden der der Düyûn-ı Umûmiyye angeschlossenen, ausländisch finanzierten Gesellschaft Régie übertragen; die Konflikte zwischen Bauern und Aufsehern (Kolcu) um den „Régie-Schmuggel“ dauerten Jahrzehnte. Zum selben Datum verlorene weitere Siedlungen: Zeyla.", "19e84e39"]},
"OLAYLAR_EK2:1898-10-18:0":{"b": ["Besuch Kaiser Wilhelms II. in Istanbul und Jerusalem", "2988cd06"], "d": ["Der zweite Besuch des deutschen Kaisers festigte die osmanisch-deutsche Annäherung; der Weg zur Bagdadbahn-Konzession wurde geöffnet, und in Damaskus wurde die Rede vom „Freund von dreihundert Millionen Muslimen“ gehalten.", "2e385229"]},
"OLAYLAR_EK2:1908-09-01:0":{"b": ["Hedschas-Bahn in Medina", "95009b9c"], "d": ["Die allein mit muslimischen Spenden und einheimischer Ingenieurskunst gebaute 1464 km lange Linie erreichte Medina; die Pilgerreise verkürzte sich von Wochen auf Tage. Sie ist das größte Infrastrukturwerk der Zeit Abdülhamids II.", "a1c98c4c"]},
"OLAYLAR_EK2:1909-04-13:0":{"b": ["Vorfall vom 31. März", "1d7c2bb2"], "d": ["Der große Aufstand gegen die Konstitution nahm Istanbul ein; die aus Thessaloniki herbeigeeilte Aktionsarmee (Hareket Ordusu) schlug den Aufstand nieder, und Abdülhamid II. wurde abgesetzt.", "4885dfd1"]},
"OLAYLAR_EK2:1912-10-26:0":{"b": ["Beginn der Belagerung von Edirne", "234d9b28"], "d": ["Die fünf Monate währende Verteidigung Şükrü Paschas wurde im Balkandesaster zu einem Epos des Widerstands; die Stadt fiel durch Hunger und wurde im Juli 1913 zurückgewonnen.", "3c3ca395"]},
"OLAYLAR_EK2:1913-01-23:0":{"b": ["Überfall auf die Hohe Pforte (Bâb-ı Âli Baskını)", "b304d02d"], "d": ["Die Regierung, die sich auf die Übergabe Edirnes vorbereitete, wurde durch einen bewaffneten Überfall der Unionisten gestürzt; Kriegsminister Nâzım Pascha wurde getötet. Die Zeit der vollen Herrschaft von İttihat ve Terakki begann.", "a8a7af44"]},
"OLAYLAR_EK2:1915-07-11:0":{"b": ["Aufhebung der Mutasarrıflık Dschebel Libanon", "b5639051"], "d": ["Die mit dem Règlement Organique von 1861 begründete und auf dem 1864 erneuerten internationalen Protokoll beruhende autonome Mutasarrıflık-Ordnung wurde im Ersten Weltkrieg vom Osmanischen Staat einseitig aufgekündigt; das Innenministerium (Dahiliye Nezâreti) begann, unmittelbar muslimische Mutasarrıfs für die Region zu ernennen. Die Autonomiezeit, in der von 1861 bis 1915 acht Mutasarrıfs amtierten, war damit beendet.", "83ff35bc"]},
"OLAYLAR_EK3:1402-08-01:0":{"b": ["Aufteilung des Landes unter den Prinzen", "82f26bfb"], "d": ["Nach dem Debakel von Ankara ging Süleyman Çelebi nach Rumelien und rief in Edirne das Sultanat aus; İsa Çelebi hielt Bursa, Çelebi Mehmed das Gebiet Amasya–Tokat–Sivas. Auf der Karte sind diese drei Anteile in verschiedenen Farben dargestellt.", "08baaa0b"]},
"OLAYLAR_EK3:1403-02-01:0":{"b": ["Vertrag von Gelibolu: Schwarzmeerküste bis Misivri an Byzanz abgetreten", "a4164eca"], "d": ["Emîr Süleyman, der sich nach dem Debakel von Ankara in Rumelien halten wollte, unterzeichnete in Gelibolu einen Vertrag mit dem byzantinischen Kaiser Manuel. Er überließ Byzanz Kartal, Pendik und Gebze sowie einige Inseln, in Rumelien Thessaloniki und Thessalien, am Schwarzen Meer den bis Misivri reichenden Küstenstreifen; auch der Tribut, den Byzanz den Osmanen zahlte, wurde aufgehoben. Ahtapolu, İğneada und Rezve an der Istranca-Küste blieben so einundzwanzig Jahre unter byzantinischer Verwaltung; Murad II. nahm die meisten dieser Orte mit dem Frieden von 1424 zurück.", "ad1af28a"]},
"OLAYLAR_EK3:1403-03-09:0":{"b": ["Tod Bayezid Yıldırıms in Gefangenschaft", "7e968d83"], "d": ["Der in der Hand Timurs gefangene Sultan starb in Akşehir; sein Leichnam wurde nach Bursa gebracht und bestattet. Sein Tod machte den Thronkampf unter den Prinzen unumkehrbar.", "af68bc4d"]},
"OLAYLAR_EK3:1403-06-15:0":{"b": ["Vertrag von Gelibolu – Zugeständnisse an Byzanz", "dfacbd00"], "d": ["Süleyman Çelebi, der seine Stellung in Rumelien sichern wollte, gab durch Vereinbarung mit Byzanz und den lateinischen Staaten Thessaloniki, die Marmaraküsten und einige Inseln zurück; er willigte sogar ein, Tribut zu zahlen.", "0d91820c"]},
"OLAYLAR_EK3:1403-09-01:0":{"b": ["Gefecht bei Ulubat – Niederlage İsa Çelebis", "500c5d24"], "d": ["İsa Çelebi, der Bursa hielt, wurde von seinem Bruder Mehmed bei Ulubat geschlagen; auch mehrere Versuche, sich wieder zu sammeln, blieben ohne Erfolg.", "624072ce"]},
"OLAYLAR_EK3:1406-06-01:0":{"b": ["Verschwinden İsa Çelebis", "0effa11e"], "d": ["İsa Çelebi, der mit Unterstützung Süleyman Çelebis mehrmals nach Anatolien zurückgekehrt war, verschwand nach seiner letzten Niederlage; sein Anteil ging an Çelebi Mehmed über, und auf der Karte dehnte sich das Gebiet Mehmeds nach Westen aus.", "d164b447"]},
"OLAYLAR_EK3:1406-06-18:0":{"b": ["Musa Çelebi geht in die Walachei", "8441267a"], "d": ["Çelebi Mehmed, der Bursa und Ankara an Süleyman Çelebi verloren hatte und sich nach Tokat–Amasya zurückgezogen hatte, ermunterte seinen Bruder Musa, nach Rumelien zu gehen. Musa nahm die Einladung des walachischen Woiwoden Mircea an und gelangte auf dem Seeweg in die Walachei; von hier aus sollte er den Kampf aufnehmen, der Süleyman zwischen zwei Fronten bringen würde.", "e7866931"]},
"OLAYLAR_EK3:1410-05-06:0":{"b": ["Çelebi Mehmed nimmt Bursa und Ankara zurück – der anatolische Anteil geht Süleyman Çelebi verloren", "bfb69f12"], "d": ["Auf die Erfolge Musa Çelebis in Rumelien (Yanbolu, 13. Februar 1410) hin ging der in Anatolien befindliche Emîr Süleyman Çelebi nach Rumelien. Nach Süleymans Abzug aus Anatolien nahm Mehmed Çelebi das Gebiet um Bursa einschließlich Ankaras wieder ein und ließ als Zeichen seiner Thronbesteigung Münzen mit dem Datum 813 prägen. Auf der Karte geht die anatolische Seite des Marmarameeres vom Anteil Emîr Süleymans in die Farbe Çelebi Mehmeds über.", "bc148b8e"]},
"OLAYLAR_EK3:1410-06-15:0":{"b": ["Schlacht von Kosmidion", "0efc2caa"], "d": ["In der Schlacht vor den Mauern Konstantinopels mit byzantinischer Unterstützung besiegte Süleyman Çelebi seinen Bruder Musa; doch seine Unterstützung in Rumelien begann rasch zu schwinden.", "ece5fe6b"]},
"OLAYLAR_EK3:1411-01-01:0":{"b": ["Belagerung Konstantinopels durch Musa Çelebi", "4932f586"], "d": ["Musa Çelebi, der Byzanz, das Süleyman unterstützt hatte, bestrafen wollte, belagerte Konstantinopel; diese Belagerung trieb Byzanz in ein Bündnis mit Çelebi Mehmed.", "b52f942c"]},
"OLAYLAR_EK3:1411-02-17:0":{"b": ["Tod Emîr Süleymans – Musa herrscht über Rumelien", "325c1549"], "d": ["Süleyman Çelebi, der auf der Flucht aus Edirne gefasst wurde, wurde getötet; ganz Rumelien fiel an Musa Çelebi. Auf der Karte wechselt Rumelien von Blau zu Violett.", "48aa849a"]},
"OLAYLAR_EK3:1413-07-05:0":{"b": ["Schlacht von Çamurlu – Wiederherstellung der Einheit", "0b23173e"], "d": ["Çelebi Mehmed, der die Unterstützung von Byzanz, des serbischen Despotats und der Beys von Rumelien erhielt, brachte seinem Bruder Musa bei Çamurlu eine entscheidende Niederlage bei; Musa wurde auf der Flucht getötet. Das in Musas Hand befindliche Rumelien ging zusammen mit Edirne an Mehmed über, und Mehmed Çelebi erklärte sich in Edirne zum alleinigen Herrscher des Osmanischen Staates. Das elf Jahre währende Interregnum (Fetret Devri) war beendet, die Prinzenanteile auf der Karte vereinten sich in einem einzigen Körper.", "649e53b7"]},
"OLAYLAR_EK3:1683-01-01:0":{"b": ["Beschluss des Wien-Feldzugs – der Friede von Vasvár wurde nicht erneuert, das Ziel von Yanıkkale auf Wien verlagert", "1bf278f2"], "d": ["Kaiser Leopold I. wünschte die Erneuerung des noch nicht abgelaufenen Vertrags von Vasvár, und auch Mehmed IV. erschien friedensgeneigt. Großwesir Kara Mustafa Pascha von Merzifon dagegen ließ den Frieden unter Berufung auf die Beschwerden des von ihm zum König von Mittelungarn ausgerufenen Imre Thököly nicht erneuern; er setzte die Prediger, allen voran Vânî Mehmed Efendi, in Bewegung und überzeugte den Sultan vom Krieg. In der abgehaltenen Beratung wurde beschlossen, dass der Sultan in Belgrad bleiben und der Serdâr-ı Ekrem vorrücken sollte, um Yanıkkale zu nehmen; doch in der Beratung in Stuhlweißenburg (İstolni Belgrad) wurde das Ziel trotz der Einwände des Krimkhans Murad Giray und des Statthalters von Buda, Uzun İbrâhim Pascha, auf die Belagerung Wiens geändert.", "7a572168"]},
"OLAYLAR_EK3:1683-07-14:0":{"b": ["Beginn der Zweiten Belagerung Wiens – das Heer vor Wien", "bb542e49"], "d": ["Das osmanische Heer unter dem Kommando von Großwesir Kara Mustafa Pascha kam am 14. Juli 1683 vor Wien an. Kaiser Leopold I. zog sich, nachdem er die Verteidigung der Stadt Starhemberg überlassen hatte, ins Innere Österreichs zurück. Diese zweite Belagerung, die im Unterschied zur ersten unmittelbar auf Wien als Ziel hin vorbereitet wurde, sollte bis zum 12. September dauern.", "ecea5576"]},
"OLAYLAR_EK3:1683-10-09:0":{"b": ["Niederlage bei Parkan und Verlust von Esztergom", "a7366740"], "d": ["Das aus Wien abziehende Heer wurde bei Parkan ein zweites Mal geschlagen; anschließend fiel Esztergom, eine der Schlüsselfestungen Ungarns. Der Rückzug begann sich in einen Zusammenbruch zu verwandeln.", "13a860f4"]},
"OLAYLAR_EK3:1683-12-25:0":{"b": ["Hinrichtung des Kara Mustafa Pascha von Merzifon", "ce8b10ac"], "d": ["Der für die Wiener Niederlage verantwortlich gemachte Großwesir wurde in Belgrad erdrosselt; doch seine Hinrichtung korrigierte weder die Front noch brachte sie das erschütterte Ansehen des Staates zurück.", "23449e61"]},
"OLAYLAR_EK3:1684-03-05:0":{"b": ["Gründung der Heiligen Liga", "060280d0"], "d": ["Unter der Führung des Papsttums wurde zwischen Österreich, Polen und Venedig gegen die Osmanen die Heilige Liga (Mukaddes İttifak) gegründet; 1686 trat auch Russland bei. Damit geriet das Reich in einen mehrfrontigen Krieg, der sechzehn Jahre dauern sollte.", "5f02a851"]},
"OLAYLAR_EK3:1684-07-14:0":{"b": ["Erste Verteidigung von Buda", "ccc43630"], "d": ["Die erste Belagerung Budas durch das Heer der Heiligen Liga wurde durch die vier Monate währende hartnäckige Verteidigung der Festung abgewehrt; die Festungen in Ungarn fielen jedoch weiter eine nach der anderen.", "fb62dd75"]},
"OLAYLAR_EK3:1685-08-19:0":{"b": ["Verlust von Uyvar", "689ab78c"], "d": ["Die Festung Uyvar, die zweiundzwanzig Jahre in osmanischer Hand gewesen und in Europa sprichwörtlich geworden war, fiel; die osmanische Präsenz in Oberungarn löste sich auf.", "559f5062"]},
"OLAYLAR_EK3:1685-10-15:0":{"b": ["Verhaftung Thökölys in Varad – das Königreich Mittelungarn löst sich auf, die Festungen Oberungarns ergeben sich", "1741aaaf"], "d": ["Nach der Wiener Niederlage hatten die Osmanen begonnen, auch Thököly unter denen zu sehen, die zum Krieg und zur Niederlage geführt hatten. Am 15. Oktober 1685 ließ Ahmed Pascha, der Beylerbey von Varad, auf Befehl des Serdar Melek İbrâhim Pascha den zur Hilfe gekommenen Thököly festnehmen; man hoffte, durch seine Auslieferung an die Habsburger bessere Friedensbedingungen zu erreichen. Als die Nachricht von der Festnahme sich verbreitete, ergaben sich mit Ausnahme von Munkács, das seine Frau Ilona Zrínyi verteidigte, sämtliche Festungen und Städte des Königreichs Mittelungarn den Habsburgern; die Kuruzen-Soldaten gingen größtenteils zum Habsburger Heer über. Als Thököly am 2. Januar 1686 in Belgrad freigelassen wurde, war das Königreich bereits verschwunden.", "1a00b9f3"]},
"OLAYLAR_EK3:1686-09-02:0":{"b": ["Verlust Budas – 145-jährige ungarische Hauptstadt", "70800e2b"], "d": ["Die Festung Buda fiel nach achtundsiebzigtägiger Belagerung; der letzte Beylerbey Abdurrahman Abdi Pascha fiel an den Mauern als Märtyrer. Der Verlust der seit 1541 unter osmanischer Herrschaft stehenden Stadt gilt als Symbol des Verlusts Ungarns. Zum selben Datum verlorene weitere Siedlungen: Pest (Peşte).", "e66f909f"]},
"OLAYLAR_EK3:1687-08-12:0":{"b": ["Zweite Schlacht von Mohács (Harsány) – Verlust Siebenbürgens und Mohács'", "a7922681"], "d": ["In der Ebene, in der 1526 der große Sieg errungen worden war, erlitt man diesmal eine schwere Niederlage; das Heer löste sich auf, die meuternden Soldaten ließen den Großwesir absetzen. Die Niederlage führte auch zum Verlust Siebenbürgens.", "6b95b7d0"]},
"OLAYLAR_EK3:1687-09-26:0":{"b": ["Verlust Athens und Explosion des Parthenon", "b6691730"], "d": ["Eine Bombe der venezianischen Artillerie sprengte den von den Osmanen als Munitionslager genutzten Parthenon in die Luft; der zweitausend Jahre alte Tempel wurde zur Ruine. Die Stadt fiel in venezianische Hand (sie sollte 1688 zurückgewonnen werden).", "e28ad137"]},
"OLAYLAR_EK3:1687-11-08:0":{"b": ["Absetzung Mehmeds IV. und Thronbesteigung Süleymans II.", "9f53037c"], "d": ["Aufgrund der Katastrophen an der Front und der Meuterei des Heeres wurde Mehmed IV. nach seiner 39-jährigen Herrschaft abgesetzt; an seine Stelle wurde sein vierzig Jahre im Käfig gehaltener Bruder Süleyman II. gesetzt.", "6a7bb845"]},
"OLAYLAR_EK3:1688-09-06:0":{"b": ["Erster Verlust Belgrads – Belagerung durch die Heilige Liga", "c6b9b19a"], "d": ["Belgrad, das seit 1521 in osmanischer Hand gewesen war, ergab sich dem Heer der Heiligen Liga; die Tore Serbiens wurden dem Feind geöffnet, und die Gefahr rückte an die Linie Niš–Sofia heran.", "33c7db1f"]},
"OLAYLAR_EK3:1689-08-01:0":{"b": ["Baden überschreitet bei Pasarofça (Passarowitz) die Morava – Pasarofça fällt an Österreich", "bcf3fc59"], "d": ["Markgraf Ludwig von Baden überschritt im August 1689 bei Pasarofça die Morava und rückte in Richtung Niš vor; die Stadt blieb bis zum Sommer 1690 in österreichischer Hand (TDV suleyman-ii sagt, dass Pasarofça 1690 zurückgewonnen wurde). Tag und Lesart von Röder wurden in dieser Sitzung nicht erneut verifiziert.", "28e54b6c"]},
"OLAYLAR_EK3:1689-09-24:0":{"b": ["Verlust von Niš – der Vormarsch der Habsburger (Krone des Königreichs Ungarn), das kritischste Jahr", "c5e27b3f"], "d": ["Der Vormarsch der Habsburger (Krone des Königreichs Ungarn) nahm den Osmanen auch Niš ab; die Streifzüge reichten bis Skopje und Priština. Vidin dagegen fiel erst danach, im Oktober 1689 (gesonderter Eintrag). Im dunkelsten Jahr des Krieges fühlte der Staat selbst die Hauptstadt bedroht.", "77de2b1f"]},
"OLAYLAR_EK3:1689-10-25:0":{"b": ["Orsova und Fethülislâm erhalten österreichische Garnison", "ee8dd875"], "d": ["Nach der kampflosen Einnahme Vidins (Oktober 1689, TDV vidin) ließ Baden am 25. Oktober 1689 Orsova und Fethülislâm instand setzen und mit einer Garnison belegen; Orsova blieb bis Herbst 1690 bei Österreich. Der Tag beruht auf Bánlaky/Röder und wurde in dieser Sitzung nicht erneut verifiziert.", "4c6ebd2c"]},
"OLAYLAR_EK3:1690-09-27:0":{"b": ["Niš wieder osmanisch", "0c4f44eb"], "d": ["Fâzıl Mustafa Pascha brach im Juli 1690 zum Feldzug auf; nach der Einnahme von Şehirköy, Pasarofça und Güvercinlik fiel das belagerte Niš am 27. September 1690 in die Hand der Osmanen (TDV semendire). Zur selben Zeit war auch Vidin zurückgewonnen worden.", "f252f3ae"]},
"OLAYLAR_EK3:1690-10-01:0":{"b": ["Österreichische Truppen in Semendria ergeben sich", "90da20c4"], "d": ["Nach der Einnahme von Niš am 27. September 1690 ergaben sich die österreichischen Truppen in Semendria nach viertägiger Belagerung (TDV semendire). Bánlaky/Röder nennt den 24. September; die Quellen widersprechen sich, TDV wurde zugrunde gelegt.", "9034a37d"]},
"OLAYLAR_EK3:1690-10-08:0":{"b": ["Belgrad zurückerobert", "ab435838"], "d": ["Großwesir Köprülüzâde Fâzıl Mustafa Pascha nahm Belgrad am 8. Oktober 1690 von Österreich zurück; die 1688 verlorene Stadt kehrte so zu den Osmanen zurück (TDV suleyman-ii).", "c93eeef6"]},
"OLAYLAR_EK3:1691-08-19:0":{"b": ["Niederlage bei Salankamen – Fâzıl Mustafa Pascha fällt als Märtyrer", "10d626f1"], "d": ["In einer der blutigsten Feldschlachten des Jahrhunderts fiel der Großwesir, in die Stirn getroffen, als Märtyrer; das Heer löste sich auf. Die Hoffnung auf Erholung erlosch mit dieser Schlacht.", "36dfe6ea"]},
"OLAYLAR_EK3:1694-09-21:0":{"b": ["Verlust der Insel Chios (Sakız)", "07c084f8"], "d": ["Die venezianische Flotte besetzte Chios; die osmanische Herrschaft in der Ägäis geriet in Gefahr. Die Insel sollte im folgenden Jahr zurückgewonnen werden.", "f5f59c77"]},
"OLAYLAR_EK3:1695-02-11:0":{"b": ["Beschluss Mustafas II., persönlich in den Feldzug zu ziehen", "61c3ba9c"], "d": ["Der neue Sultan erklärte, dem Weg seiner Vorfahren folgend an der Spitze des Heeres in den Feldzug zu ziehen; dieser Beschluss weckte Moral im Heer und eröffnete die Zeit der persönlichen Feldzüge, die zwei Jahre dauern sollte.", "2794ae0f"]},
"OLAYLAR_EK3:1695-02-22:0":{"b": ["Rückgewinnung von Chios", "6b496fca"], "d": ["Mezomorto Hüseyin Pascha, der in den Seeschlachten bei den Koyun-Inseln die venezianische Flotte besiegt hatte, nahm Chios zurück; es war ein Zeichen für ein kurzes Wiederaufleben der osmanischen Seefahrt.", "7638e074"]},
"OLAYLAR_EK3:1695-09-22:0":{"b": ["Sieg von Lugoş – Feldzug II. Him", "6527cee3"], "d": ["Auf dem ersten Feldzug, an dem der Sultan persönlich teilnahm, wurde Lipova zurückgewonnen, und bei Lugoş wurden die österreichischen Streitkräfte geschlagen; in der seit Jahren währenden Kette von Niederlagen kam es zum ersten Bruch.", "54aa0f54"]},
"OLAYLAR_EK3:1696-07-19:0":{"b": ["Verlust der Festung Azak (Asow)", "2b78b5cd"], "d": ["Peter I., der zum Schwarzen Meer vordringen wollte, nahm Azak bei seiner zweiten Belagerung; Russland setzte sich erstmals dauerhaft in einer osmanischen Festung fest und tat den ersten Schritt auf dem Weg zur Seemacht.", "b765c903"]},
"OLAYLAR_EK3:1696-08-27:0":{"b": ["Sieg von Ulaş (Olaşin)", "02ac9ca8"], "d": ["Der auf dem zweiten Feldzug des Sultans am Donauufer errungene Sieg durchkreuzte den österreichischen Plan, Temeswar zu nehmen; er änderte jedoch das Gesamtgleichgewicht des Krieges nicht.", "b6e2d27a"]},
"OLAYLAR_EK3:1697-09-11:0":{"b": ["Niederlage bei Zenta – das Schicksal des Krieges war entschieden", "475c4a7b"], "d": ["Das Heer wurde beim Überschreiten der Theiß (Tisa) von Prinz Eugen überraschend überfallen; die auf beide Ufer des Flusses verteilten Kräfte wurden in wenigen Stunden vernichtet, Tausende von Soldaten und Staatsmännern, darunter Großwesir Elmas Mehmed Pascha, kamen ums Leben. Zenta, eine der schwersten Niederlagen der osmanischen Geschichte, machte den Verhandlungstisch unausweichlich.", "ced10fdc"]},
"OLAYLAR_EK3:1698-11-13:0":{"b": ["Beginn der Friedensverhandlungen von Karlowitz", "1f395cf3"], "d": ["In den unter Vermittlung Englands und der Niederlande begonnenen Verhandlungen musste die osmanische Delegation erstmals den Grundsatz „uti possidetis“ (der Besitzstand bleibt) akzeptieren; die zweiundsiebzig Sitzungen währenden Verhandlungen gelten als Geburt der modernen osmanischen Diplomatie.", "1d41e9e8"]},
"OLAYLAR_EK4:1801-03-08:0":{"b": ["Mehmed Ali von Kavala landet in Ägypten", "514c943f"], "d": ["Im Heer der osmanischen Truppen, die zur Rückeroberung des französisch besetzten Ägypten geschickt wurden, befand sich auch ein aus Kavala zusammengestellter Freiwilligenverband. Mehmed Ali, damals in seinen Dreißigern, war der zweite Kommandeur dieses Verbandes; er betrat Ägypten nicht als Statthalter, sondern als Offizier einer Kompanie.", "b7e3bb36"]},
"OLAYLAR_EK4:1803-05-01:0":{"b": ["Albanische Soldaten stürzten den Statthalter Ägyptens", "c76a0ec2"], "d": ["Albanische Truppen, deren Sold nicht ausgezahlt wurde, erhoben sich und zwangen den Statthalter Hüsrev Pascha, die Zitadelle zu verlassen. In dem durch den Abzug der Franzosen entstandenen Vakuum traten die Mamlukenbeys, das albanische Korps und die von der Hohen Pforte ernannten Statthalter in einen Dreikampf ein; Mehmed Ali trat hervor, indem er in diesem Dreieck die Gewichte ausbalancierte. Weitere am selben Datum verlorene Siedlungen: Tâif.", "669d61a0"]},
"OLAYLAR_EK4:1805-05:0":{"b": ["Die Ulema Kairos riefen Mehmed Ali zum Statthalter aus", "a16752f2"], "d": ["Von der Steuerlast erdrückt, erhoben sich die Kairoer Kaufleute und Ulema unter der Führung des Naqib al-Ashraf Ömer Mekrem, erklärten, den Statthalter Hurşid Pascha nicht anzuerkennen, und setzten Mehmed Ali in das Amt des Statthalters ein. Dass ein Statthalter vom Volk gewählt wurde, ist in der osmanischen Geschichte ein selten anzutreffendes Ereignis.", "1572b66f"]},
"OLAYLAR_EK4:1805-07-03:0":{"b": ["Die Hohe Pforte erkannte die vollendete Tatsache an: Ferman über die Statthalterschaft Ägyptens", "b86736a3"], "d": ["Die Hohe Pforte, die in Ägypten nicht die Kraft hatte, ihren eigenen Kandidaten durchzusetzen, sandte Mehmed Ali einen Ferman über die Statthalterschaft Ägyptens mit dem Rang eines Wesirs. Auf der Karte wechselt Ägypten ab diesem Datum in die Vasallenschicht (hellerer Ton): rechtlich osmanisches Land, faktisch das Land der Dynastie von Kavala. Weitere am selben Datum in die Vasallenschicht übergegangene Siedlungen: Kairo, Alexandria, Damiette, Asyut, Assuan, İbrim, Suez, Reşîd (Rosetta).", "e769c607"]},
"OLAYLAR_EK4:1807-03-17:0":{"b": ["Die britische Fraser-Expedition landete in Alexandria", "4d6c31be"], "d": ["Als Antwort auf die Annäherung des Osmanischen Reiches an Frankreich entsandte Großbritannien ein Landungskorps nach Ägypten. Mehmed Ali war zu dieser Zeit in Oberägypten mit den Mamluken beschäftigt; er kehrte rasch zurück und organisierte die Verteidigung.", "fd5f278f"]},
"OLAYLAR_EK4:1807-04-21:0":{"b": ["Niederlage von Reşid (Rosetta) – die Briten wurden zurückgeschlagen", "3636004c"], "d": ["Die in die Stadt Reşid eingedrungene britische Kolonne erlitt in Straßenkämpfen schwere Verluste; im September räumten die Truppen Ägypten vollständig. Dieser Sieg festigte Mehmed Alis Ansehen sowohl in Ägypten als auch in Istanbul.", "68a2ba26"]},
"OLAYLAR_EK4:1811-03-01:0":{"b": ["Das Massaker in der Zitadelle: Beseitigung der Mamlukenbeys", "84030b97"], "d": ["Die zum Festzug für den Hedschas-Feldzug eingeladenen Mamlukenbeys wurden im engen Durchgang der Kairoer Zitadelle eingeschlossen und beseitigt. Damit endete der fünfhundertjährige Einfluss der Mamluken, und Mehmed Ali blieb in Ägypten ohne Rivalen.", "1ca00e33"]},
"OLAYLAR_EK4:1811-09-03:0":{"b": ["Der Hedschas-Feldzug begann – das Heer marschierte von Suez zur See und auf der Pilgerstraße zu Lande nach Yanbu", "1c05c159"], "d": ["Die seit 1803 unter saudisch-wahhabitischer Herrschaft stehenden Haramain zurückzugewinnen, war für Mahmud II. die größte Legitimitätsfrage; da die Hohe Pforte dazu nicht in der Lage war, wurde die Aufgabe dem Statthalter Ägyptens übertragen. Mehmed Ali sandte seinen sechzehnjährigen Sohn Tosun an die Spitze des Heeres.", "5e614d69"]},
"OLAYLAR_EK4:1811-10-01:0":{"b": ["Yanbu wurde übernommen – erster Küstenstützpunkt des Hedschas-Feldzugs", "179bc78d"], "d": ["Etwa zweitausend albanische Infanteristen, die mit neu gebauten Schiffen von Suez aufgebrochen waren, landeten im Oktober 1811 bei Yanbu; die Stadt ergab sich nach zwei Tagen schwachen Widerstands. Die Reiterei unter Tosuns Kommando folgte der Pilgerstraße zu Lande und erreichte Yanbu über Akaba und Wadschh erst zwei Wochen später. Yanbu wurde der erste Stützpunkt des ägyptischen Heeres im Hedschas, das gegen Medina und Mekka marschieren sollte.", "cfc2ed8a"]},
"OLAYLAR_EK4:1812-01-01:0":{"b": ["Erste Niederlage in der Schlucht von Safra-Cedîde", "99ef804d"], "d": ["Die in engen Bergpässen in einen Hinterhalt gelockte ägyptische Vorhut wurde zerstreut. Die Niederlage wurde zur taktischen Lehre des Feldzugs: Es zeigte sich, dass ein Vormarsch im Hedschas ohne die Unterstützung der Beduinenstämme unmöglich war.", "765dd19d"]},
"OLAYLAR_EK4:1812-12-03:0":{"b": ["Medina wurde zurückerobert", "6f6a5d55"], "d": ["Nach langer Belagerung ergab sich Medina. Die Wiedergewinnung der Stadt des Propheten wurde in Istanbul mit Kanonenfeuerwerk gefeiert; Mehmed Ali erhielt als Belohnung zusätzlich die Statthalterschaft von Dschidda.", "45cc4c79"]},
"OLAYLAR_EK4:1813-01-23:0":{"b": ["Mekka wurde zurückerobert – die Pilgerstraße wurde geöffnet", "3d6d66a0"], "d": ["Die in Mekka einziehenden ägyptischen Truppen ließen an der Kaaba erneut die Chutba im Namen des osmanischen Sultans verlesen. Die seit zehn Jahren unterbrochenen Pilgerkarawanen konnten wieder aufbrechen. Auf der Karte kehrt der Hedschas unter osmanische Herrschaft zurück, wird aber, da er von Kairo aus verwaltet wird, im Vasallenton dargestellt. Der andere am selben Datum in die Vasallenverwaltung übergegangene Ort: Dschidda.", "f0970e28"]},
"OLAYLAR_EK4:1813-05-02:0":{"b": ["Rückeroberung von Tâif – Abschluss des Hedschas-Feldzugs", "6315fb31"], "d": ["Nach Medina (Dezember 1812) und Mekka (Januar 1813) eroberte das ägyptische Heer unter Tosun Pascha zuletzt Tâif von den Wahhabiten zurück. Die zehn Jahre währende saudische Herrschaft endete, und alle drei heiligen Zentren des Hedschas gelangten wieder unter osmanisch-ägyptische Kontrolle.", "374bf563"]},
"OLAYLAR_EK4:1813-08-28:0":{"b": ["Mehmed Ali ging persönlich in den Hedschas", "fda0ea2d"], "d": ["Der Statthalter, der den Feldzug schleppend verlaufen sah, nahm die Verwaltung unmittelbar selbst in die Hand; durch Verhandlungen mit den Stammesführern versuchte er, die saudische Front von innen aufzulösen. Auch Ägyptens Anteil am Handel im Roten Meer wuchs durch diesen Feldzug.", "aeb051d1"]},
"OLAYLAR_EK4:1815-01-20:0":{"b": ["Schlacht von Bisel: Die saudischen Streitkräfte wurden vernichtend geschlagen", "9c9ab91f"], "d": ["Die in der Feldschlacht schwer besiegten Saudis zogen sich in die inneren Landesteile zurück. Der geschlossene Waffenstillstand hatte keinen Bestand; zwei Jahre später sollte der Feldzug ins Herz des Nadschd getragen werden.", "4a8ae0e2"]},
"OLAYLAR_EK4:1816-09-01:0":{"b": ["Ibrahim Pascha brach zum Nadschd-Feldzug auf", "d5ed80d1"], "d": ["Ibrahim Pascha, der nach dem Tod seines Bruders Tosun das Kommando übernommen hatte, begann einen zwei Jahre währenden, beschwerlichen Marsch durch die Wüste. Das Heer rückte Brunnen für Brunnen vor, schaltete die Stämme einzeln aus und stand schließlich vor der saudischen Hauptstadt.", "e84c2cef"]},
"OLAYLAR_EK4:1818-09-09:0":{"b": ["Diriyya fiel – der Erste Saudische Staat endete", "aa96206d"], "d": ["Nach sechsmonatiger Belagerung ergab sich Diriyya und wurde zerstört. Der Emir Abdullah b. Saud wurde nach Istanbul gebracht und hingerichtet. Die osmanische Fahne erreichte erstmals so tief das Innere Arabiens; die Garnison im Nadschd blieb bis 1824. Weitere am selben Datum angegliederte Orte: Diriyya (Nadschd).", "4b161cf5"]},
"OLAYLAR_EK4:1820-07-20:0":{"b": ["Der Sudan-Feldzug begann", "b1fc6905"], "d": ["Mehmed Alis Ziel war dreifach: Soldaten für sein Heer auszuheben, an das Gold von Sennar zu gelangen und die geflohenen Reste der Mamluken zu vernichten. Die Truppe unter dem Kommando seines Sohnes İsmâil Pascha zog dem Nil folgend nach Süden.", "478563e9"]},
"OLAYLAR_EK4:1821-01-04:0":{"b": ["Dongola wurde eingenommen – die Mamlukenreste wurden zerstreut", "ba6bc24b"], "d": ["Das Heer, das in Dongola an der großen Nilschleife einzog, liquidierte die letzte dorthin geflüchtete Mamlukengruppe. Auf der Karte erscheint der Sudan ab diesem Datum in der Vasallenschicht: Der Eroberer ist Kairo, und auch der Verwalter wird Kairo sein.", "bca7d521"]},
"OLAYLAR_EK4:1821-06-14:0":{"b": ["Das Sultanat Sennar (Funj) ergab sich", "3cac7dd2"], "d": ["Die dreihundertjährige Funj-Dynastie ergab sich ohne Kampf. Das im selben Jahr am Zusammenfluss der beiden Nilarme errichtete Lager wurde binnen kurzer Zeit zu Khartum, dem Verwaltungszentrum des Sudan. Weitere am selben Datum angegliederte Orte: Sennar.", "1ad105c1"]},
"OLAYLAR_EK4:1821-08-19:0":{"b": ["Kordofan wurde erobert", "06440602"], "d": ["Die nach Westen entsandte zweite Kolonne besiegte bei Bâre die Truppen von Darfur und nahm Kordofan ein. Ägyptens Herrschaft im Sudan dehnte sich damit vom Niltal bis in die westlichen Steppen aus.", "e18d449a"]},
"OLAYLAR_EK4:1822-06-28:0":{"b": ["Ägyptische Truppen landeten auf Kreta", "835aee90"], "d": ["Als der griechische Aufstand auf Kreta übergriff, forderte die Hohe Pforte, dass eine ägyptische Truppe auf die Insel entsandt werde. Mehmed Alis Einfluss auf der Insel begann mit diesem Eingreifen und mündete acht Jahre später in die Übertragung der Statthalterschaft von Kreta an ihn.", "8d651366"]},
"OLAYLAR_EK4:1822-10-24:0":{"b": ["Die Ermordung İsmâil Paschas in Şendî", "223860c9"], "d": ["Der über die schweren Steuer- und Soldatenforderungen erzürnte lokale Emir Nemir setzte das Haus, in dem İsmâil Pascha logierte, in Brand und verbrannte ihn samt Gefolge. Der Vergeltungsfeldzug verwandelte die Region in ein Blutbad; die Verwaltung des Sudan beruhte fortan auf Härte.", "722af711"]},
"OLAYLAR_EK4:1824-07-19:0":{"b": ["Mahmud II. bat Mehmed Ali um Hilfe für die Morea", "03594a42"], "d": ["Für den Aufstand in der Morea, der mit dem Janitscharenheer in drei Jahren nicht niedergeschlagen werden konnte, wandte sich der Sultan an das nach europäischer Art ausgebildete ägyptische Heer. Als Gegenleistung wurden ihm die Statthalterschaft der Morea und Kreta in Aussicht gestellt. Diese Bitte war das erste offene Eingeständnis, dass das Reich auf seine eigene Provinz angewiesen geworden war.", "1b0ee342"]},
"OLAYLAR_EK4:1825-02-24:0":{"b": ["Ibrahim Pascha landete in Modon", "9c993dba"], "d": ["Das von der ägyptischen Flotte geschützte Landungskorps setzte an der Südwestspitze der Morea den Fuß an Land. Dieses mit regulärer Infanterie (Nizam) und Feldartillerie ausgerüstete Heer gewann gegenüber den aufständischen Banden in kurzer Zeit die Oberhand.", "edf38fca"]},
"OLAYLAR_EK4:1825-06-22:0":{"b": ["Tripolitsa wurde zurückerobert – das Zentrum der Morea fiel", "8a478c11"], "d": ["Mit dem Fall von Tripolitsa, dem Verwaltungszentrum des Aufstands, kam der größte Teil der Morea wieder unter Kontrolle. Auf der Karte erscheint die Halbinsel, da sie in der Hand der ägyptischen Truppen ist, im Vasallenton.", "e7d9b818"]},
"OLAYLAR_EK4:1826-04-22:0":{"b": ["Missolonghi (Mesolongi) fiel", "07257f87"], "d": ["Nach einer einjährigen Belagerung wurde die Stadt genommen. Doch der Widerhall der Verteidigung in der europäischen Presse steigerte die Sympathie für die griechische Sache auf ihren Höhepunkt und bereitete den Boden für das Eingreifen der Großmächte.", "9bf1efc2"]},
"OLAYLAR_EK4:1827-06-05:0":{"b": ["Die Akropolis von Athen wurde übernommen", "3b19f946"], "d": ["Mit dem Fall der Akropolis war der griechische Aufstand militärisch nahezu beendet. Genau an diesem Punkt hörte die Angelegenheit auf, ein innerer Aufstand zu sein, und wurde Gegenstand der europäischen Diplomatie.", "e096fc52"]},
"OLAYLAR_EK4:1827-07-06:0":{"b": ["Londoner Vertrag: Drei Mächte erzwangen die griechische Autonomie", "7ce46fd8"], "d": ["Großbritannien, Frankreich und Russland beschlossen gemeinsames Vorgehen, um Osmanen und Griechen einen Waffenstillstand und die Bedingung der Autonomie aufzuzwingen; für den Fall der Ablehnung wurde mitgeteilt, dass ihre Flotten eingreifen würden. Die Hohe Pforte lehnte das Angebot ab.", "8382f516"]},
"OLAYLAR_EK4:1828-08-06:0":{"b": ["Konvention von Alexandria: Ägyptens Beschluss zum Abzug aus der Morea", "cc978f37"], "d": ["Mehmed Ali, der bei Navarino seine Flotte verloren hatte, einigte sich, ohne Istanbul zu konsultieren, unmittelbar mit dem britischen Admiral und willigte ein, seine Truppen aus der Morea abzuziehen. Dass ein Statthalter mit den Großmächten eigenständig einen Vertrag schloss, kündigte die kommende Krise an.", "9430ea24"]},
"OLAYLAR_EK4:1828-10-05:0":{"b": ["Ägyptische Truppen räumten die Morea", "8fb742dd"], "d": ["Die letzten Einheiten wurden eingeschifft; die Halbinsel ging faktisch verloren und wurde durch das Londoner Protokoll von 1830 zum Kern des unabhängigen Griechenland. Mehmed Ali hatte die versprochene Statthalterschaft der Morea nicht erhalten und dafür eine große Flotte und ein großes Heer verloren. Weitere am selben Datum verlorene Siedlungen: Modon, Koron.", "7bfbefe0"]},
"OLAYLAR_EK4:1830-11-01:0":{"b": ["Die Verwaltung Kretas wurde Mehmed Ali überlassen", "7f76396d"], "d": ["Als Ausgleich für den Verlust der Morea wurde Mehmed Ali die Statthalterschaft von Kreta übertragen. Die Insel wurde zehn Jahre lang von Kairo aus verwaltet; auf der Karte erscheint sie während dieser Zeit im Vasallenton. Weitere am selben Datum angegliederte Orte: Kandiye (Kreta).", "5b000d2b"]},
"OLAYLAR_EK4:1831-10-31:0":{"b": ["Ibrahim Pascha drang in Syrien ein – die erste Krise begann", "1a5cc386"], "d": ["Der Vorwand war der Statthalter von Akkon, der die aus Ägypten geflohenen Fellachen nicht auslieferte; der wahre Grund war Mehmed Alis Bedarf an Syriens Bauholz, Häfen und Menschenreserven. Das Heer überquerte den Sinai und nahm die palästinensische Küste rasch in Besitz.", "9d41b0f9"]},
"OLAYLAR_EK4:1831-11-26:0":{"b": ["Die Belagerung von Akkon begann", "b211d96d"], "d": ["Die Festung, die 1799 Napoleon aufgehalten hatte, leistete sechs Monate lang Widerstand. Die Belagerung war die erste große Bewährungsprobe der modernen Artillerie des ägyptischen Heeres.", "97d9816b"]},
"OLAYLAR_EK4:1832-05-27:0":{"b": ["Akkon fiel", "0f47917b"], "d": ["Als die die Mauern beschießenden Batterien eine Bresche schlugen, wurde die Festung genommen. Das Tor Syriens war geöffnet; die Hohe Pforte erklärte Mehmed Ali in denselben Tagen zum Rebellen und hob seine Statthalterschaft auf.", "f92b4224"]},
"OLAYLAR_EK4:1832-06-16:0":{"b": ["Damaskus ergab sich", "48da3b62"], "d": ["Die Stadt ergab sich ohne Kampf. Ibrahim Pascha versuchte, die lokale Unterstützung zu gewinnen, indem er die Steuerordnung und die den Nichtmuslimen zugestandene Gleichheit verkündete; dieselben Politiken sollten wenige Jahre später auch zum Grund von Aufständen gegen ihn werden. Weitere in denselben Tagen angegliederte Orte: Beirut, Tripoli, Sidon.", "c67bd97e"]},
"OLAYLAR_EK4:1832-07-08:0":{"b": ["Schlacht von Homs", "867810ee"], "d": ["Das zur Rettung Syriens entsandte osmanische Heer wurde im offenen Gelände vernichtend geschlagen. Es zeigte sich, dass das neue Heer, das sechs Jahre nach der Abschaffung des Janitscharenkorps aufgestellt worden war, noch nicht bereit war.", "f429ba2e"]},
"OLAYLAR_EK4:1832-07-15:0":{"b": ["Aleppo wurde eingenommen", "9c0ead76"], "d": ["Auch das Handels- und Verwaltungszentrum Nordsyriens fiel. Damit stand das ägyptische Heer am Fuß des Taurus und wandte sich den Pässen am Tor Anatoliens zu.", "b8b4a1bd"]},
"OLAYLAR_EK4:1832-07-29:0":{"b": ["Niederlage im Belen-Pass (Beylan) – die Çukurova wurde geöffnet", "4bae872b"], "d": ["Im engen Pass im Amanos-Gebirge wurde die Verteidigungslinie durchbrochen. Antiochia, Adana und Tarsus fielen an die ägyptischen Truppen (die Besetzung von Maraş fällt nach dem TDV in das Jahr 1833, ein gesonderter Eintrag); auf der Karte kehrt die Çukurova in den Vasallenton zurück. Der Weg ins Innere Anatoliens war nun ungeschützt.", "73cb1c5e"]},
"OLAYLAR_EK4:1832-09-13:0":{"b": ["Der Gülek-Pass fiel – die Küste von İçil (Mersin, Silifke) kam unter ägyptische Kontrolle", "d9049b5b"], "d": ["Der Gülek-Pass, das Tor des Taurus zur Çukurova, fiel in die Hand des ägyptischen Heeres. Ibrahim Pascha setzte für den Sandschak İçil seinen eigenen Mütesellim ein, und sämtliche Anlegestellen an der Küste kamen unter ägyptische Kontrolle. Auf der Karte erscheinen Mersin und Silifke ab diesem Tag (Untergrenze; das Datum der Einsetzung fehlt in der Quelle) als Ägypten zugehörig; da im Beschluss von Kütahya nur das Muhassıl-Amt von Adana erwähnt wird, endet diese Kontrolle mit der Räumung Anatoliens.", "fa650158"]},
"OLAYLAR_EK4:1832-09-13:1":{"b": ["Konya Ereğlisi unter ägyptischer Besetzung – Taurus-Eingang der Straße Konya–Adana", "fb908900"], "d": ["Ereğli, das an der Route des den Gülek-Pass überschreitenden ägyptischen Heeres nach Konya lag, kam 1832 unter die Besetzung Ibrahim Paschas und wurde bei der Räumung gemäß der Regelung von Kütahya 1833 wieder dem Vilayet Karaman angegliedert. Auf der Karte ist es der belegte Zwischenpunkt der Besatzungslinie zwischen Adana und Konya; für Ulukışla und Karapınar konnte auf Stadtebene kein Beleg gefunden werden.", "c5c7c153"]},
"OLAYLAR_EK4:1832-11-21:0":{"b": ["Das ägyptische Heer zog in Konya ein", "13952a2d"], "d": ["Das den Taurus überschreitende Heer erreichte Zentralanatolien. Erstmals rückten die Truppen eines osmanischen Statthalters in den Kernlanden des Reiches vor. Weitere am selben Datum angegliederte Orte: Karaman.", "569bd202"]},
"OLAYLAR_EK4:1832-12-21:0":{"b": ["Schlacht von Konya: Der Großwesir geriet in Gefangenschaft", "ec82cc9a"], "d": ["Das bei Nebel zerstreute osmanische Heer erlitt eine schwere Niederlage, und der Großwesir Reşid Mehmed Pascha wurde gefangen genommen. Das Zentralheer des Staates existierte nicht mehr; zwischen Istanbul und den ägyptischen Truppen war keine Macht mehr, die sie aufhalten konnte.", "30e73138"]},
"OLAYLAR_EK4:1833-01-01:0":{"b": ["Maraş geriet unter ägyptische Besetzung", "f558e383"], "d": ["Nach dem TDV geriet Maraş 1833 unter die Besetzung Ibrahim Paschas von Kavala und verblieb fast neunzehn Monate unter dessen Verwaltung. Da Maraş außerhalb der Provinzgrenzen der Regelung von Kütahya blieb, ist diese Verwaltung nicht rechtlich, sondern faktisch.", "3d3c898a"]},
"OLAYLAR_EK4:1833-01-01:1":{"b": ["Karahisâr-ı Sâhib (Afyon) geriet unter ägyptische Besetzung – Straße Konya–Kütahya", "ae0c2c78"], "d": ["Karahisâr-ı Sâhib, das an der Route des nach der Schlacht von Konya gegen Kütahya vorrückenden ägyptischen Heeres lag, blieb 1833 für einige Zeit in der Hand Ibrahim Paschas. Auf der Karte ist es der belegte Zwischenpunkt der Besatzungslinie zwischen Konya und Kütahya; für Akşehir, Ilgın und İshaklı konnte auf Stadtebene kein Beleg gefunden werden, sie erscheinen in osmanischer Farbe.", "bce0b466"]},
"OLAYLAR_EK4:1833-02-02:0":{"b": ["Das ägyptische Heer erreichte Kütahya", "214f8df6"], "d": ["Ibrahim Pascha hielt in Kütahya, drei Tagesmärsche von Istanbul entfernt, an. Dass er nicht weiter vorrückte, hatte keine militärischen, sondern politische Gründe: Das russische Eingreifen und die Reaktion Europas waren einkalkuliert.", "0f1c5f03"]},
"OLAYLAR_EK4:1833-02-20:0":{"b": ["Die russische Flotte vor Büyükdere", "6f836d61"], "d": ["Mahmud II., der von Großbritannien und Frankreich keine Hilfe erhielt, wandte sich an Russland, den Feind von gestern. Diese Entscheidung, die mit dem Ausspruch des Sultans ‚Der ins Meer Gefallene klammert sich auch an eine Schlange‘ in Erinnerung blieb, mündete in der Landung russischer Soldaten an den Meerengen und ließ in Europa die Alarmglocken läuten.", "3e402e00"]},
"OLAYLAR_EK4:1833-05-06:0":{"b": ["Konvention von Kütahya – Syrien und Adana an den Mann aus Kavala", "c16c5a94"], "d": ["Die Hohe Pforte überließ Mehmed Ali neben Ägypten, Kreta und dem Hedschas die Statthalterschaften von Damaskus, Aleppo, Tripoli und Sidon und Ibrahim Pascha das Muhassıl-Amt von Adana. Im Gegenzug zog sich das Heer südlich des Taurus zurück. Dies war kein Vertrag, sondern erfolgte in Form von Fermanen, die der Sultan einem Statthalter erteilte – die Frage war nicht gelöst, sondern vertagt.", "4160e4f4"]},
"OLAYLAR_EK4:1833-06-15:0":{"b": ["Der Abzug des ägyptischen Heeres aus Anatolien wurde über den Gülek-Pass abgeschlossen", "a53ac2a3"], "d": ["Nach der Regelung von Kütahya räumten die ägyptischen Truppen Anatolien; gegen Mitte Juni war das gesamte Heer durch den Gülek-Pass in die Çukurova übergetreten. Die Küste von İçil (Mersin, Silifke) kehrt wieder unter osmanische Verwaltung zurück; das Muhassıl-Amt von Adana und Syrien verbleiben bei Ägypten.", "c5e13625"]},
"OLAYLAR_EK4:1833-07-08:0":{"b": ["Vertrag von Hünkâr İskelesi", "da741d5c"], "d": ["Mit Russland wurde ein auf acht Jahre befristetes gegenseitiges Verteidigungsbündnis unterzeichnet. Nach einem Geheimartikel sollte das Osmanische Reich die Meerengen für Kriegsschiffe sperren, falls Russland angegriffen würde. Dies wurde zu einer der umstrittensten Entscheidungen der osmanischen Diplomatie und machte Großbritannien in der Ägyptenfrage aktiv.", "43dc2c96"]},
"OLAYLAR_EK4:1834-05-19:0":{"b": ["Aufstand von Palästina-Nablus gegen die ägyptische Verwaltung", "4fe43e27"], "d": ["Wehrpflicht, Waffenablieferung und neue Steuern lösten in Palästina einen breiten Aufstand aus. Der Aufstand wurde hart niedergeschlagen; die Unterstützung der ägyptischen Verwaltung bei der einheimischen Bevölkerung schwand rasch.", "2a3301a2"]},
"OLAYLAR_EK4:1834-08-01:0":{"b": ["Ende der ägyptischen Verwaltung von Maraş (ungefähr)", "bb46ca42"], "d": ["Rechnet man den Satz des TDV ‚fast neunzehn Monate‘ ab der Besetzung von 1833, so endet die ägyptische Verwaltung um den Sommer 1834. Dass Mustafa Bey aus den Küçükalioğulları 1834 dem ägyptischen Heer nicht standhalten konnte und sich in Richtung Maraş zurückzog, zeigt zudem, dass Maraş zu jener Zeit ein Zufluchtsort außerhalb der ägyptischen Kontrolle war.", "fbb6814a"]},
"OLAYLAR_EK4:1837-10-15:0":{"b": ["Aufstand im Dschabal ad-Duruz", "12e74626"], "d": ["Der im drusischen Gebiet ausgebrochene Widerstand dauerte zwei Jahre. Die in Syrien angestaute Unzufriedenheit sollte 1840, als die verbündeten Flotten an der Küste landeten, dem ägyptischen Heer den Rücken entblößen.", "75c50707"]},
"OLAYLAR_EK4:1838-05-25:0":{"b": ["Mehmed Ali gab seine Unabhängigkeitsabsicht bekannt", "48633bbd"], "d": ["Der Statthalter eröffnete den Konsuln der Großmächte, er erwäge, die Unabhängigkeit Ägyptens und Syriens zu erklären. Großbritannien lehnte dies entschieden ab: Die Entstehung eines starken, Frankreich nahestehenden Staates im Mittelmeer hätte den Weg nach Indien bedroht.", "d6181bd9"]},
"OLAYLAR_EK4:1839-04-21:0":{"b": ["Das osmanische Heer überschritt den Euphrat", "9af1ea69"], "d": ["Mahmud II. trieb sein Heer an die syrische Grenze, um das in Kütahya Verlorene zurückzugewinnen. Der als Berater im Heer weilende preußische Offizier Moltke erhob Einwände gegen die Stellungswahl und den frühen Angriff; seine Einwände wurden nicht gehört.", "85d5db1c"]},
"OLAYLAR_EK4:1839-06-24:0":{"b": ["Schlacht von Nizip – das osmanische Heer löste sich auf", "156b3cdf"], "d": ["Das schlecht aufgestellte osmanische Heer wurde innerhalb weniger Stunden vernichtend geschlagen. Der Sultan starb, bevor die Nachricht von der Niederlage Istanbul erreichte; der Staat sollte binnen weniger Tage sein Heer, seinen Herrscher und danach seine Flotte verlieren.", "fb8af82d"]},
"OLAYLAR_EK4:1839-06-28:0":{"b": ["Tod Mahmuds II.", "07eccfff"], "d": ["Der Sultan, der während seiner einunddreißigjährigen Herrschaft das Janitscharenkorps abgeschafft und die zentrale Verwaltung neu errichtet hatte, starb, ohne seinen größten Gegner bezwungen zu haben. Seine Krankheit war nicht zutreffend diagnostiziert worden. Sein Tod wurde bis zum 30. Juni geheim gehalten, bis in der Stadt militärische Vorkehrungen getroffen waren, aus Furcht, die Janitscharengesinnung könne sich regen.", "3174d901"]},
"OLAYLAR_EK4:1839-07-01:0":{"b": ["Thronbesteigung Abdülmecids und Bestattungszug Mahmuds II.", "d0f3d2cc"], "d": ["Nach dem Tod seines Vaters bestieg der sechzehnjährige Abdülmecid den Thron. Am selben Tag wurde der Leichnam Mahmuds II. zum Topkapı-Palast gebracht; die befürchteten Unruhen blieben aus, und breite Massen von Muslimen und Nichtmuslimen schlossen sich dem Trauerzug an.", "7b398ea4"]},
"OLAYLAR_EK4:1839-07-14:0":{"b": ["Übergabe der Flotte an Alexandria", "a53e6103"], "d": ["Der Kapudan Pascha Ahmed Fevzi Pascha brachte die Flotte aus dem Verdacht, der Großwesir Koca Hüsrev Pascha werde sie Russland übergeben, nach Alexandria und übergab sie Mehmed Ali. Das Osmanische Reich stand im selben Monat ohne Heer, ohne Sultan und ohne Flotte da.", "78a26255"]},
"OLAYLAR_EK4:1839-07-27:0":{"b": ["Gemeinsame Note der Großmächte", "2a3b8316"], "d": ["Die fünf Mächte übergaben der Hohen Pforte eine Note, in der sie verlangten, in der Ägyptenfrage nicht allein eine Einigung zu schließen. Eine innere Angelegenheit wurde damit offiziell zu einer ‚europäischen Frage‘; der osmanische Staat verlor faktisch die Befugnis, über seine eigene Provinz zu entscheiden.", "979e7f0a"]},
"OLAYLAR_EK4:1840-07-15:0":{"b": ["Londoner Vertrag: Vier Mächte an der Seite der Osmanen", "a517f775"], "d": ["Der unter Ausschluss Frankreichs unterzeichnete Vertrag stellte Mehmed Ali ein Ultimatum: Nehme er innerhalb von zehn Tagen an, erhalte er die erbliche Statthalterschaft Ägyptens und auf Lebenszeit Akkon; nehme er innerhalb von zwanzig Tagen an, nur Ägypten; lehne er ab, nichts. Der Statthalter lehnte ab.", "fc066f82"]},
"OLAYLAR_EK4:1840-09-10:0":{"b": ["Bombardierung Beiruts und Landung der Verbündeten", "0905ce92"], "d": ["Die britisch-österreichische Flotte beschoss Beirut; an die im Libanon-Gebirge gegen die ägyptische Verwaltung aufständische Bevölkerung wurden Waffen verteilt. Ibrahim Paschas Kontrolle über Syrien brach zwischen innerem Aufstand und äußerem Eingreifen zusammen.", "743ec7e2"]},
"OLAYLAR_EK4:1840-10-10:0":{"b": ["Beirut und die Küstenstädte gingen verloren", "09bdaf23"], "d": ["Nach den Gefechten in Richtung Baalbek zogen sich die ägyptischen Truppen von der Küste zurück. Auf der Karte verlässt die libanesische Küste den Vasallenton und kehrt zur unmittelbaren osmanischen Verwaltung zurück.", "fe5e95aa"]},
"OLAYLAR_EK4:1840-11-03:0":{"b": ["Akkon fiel in zwei Stunden", "5aec21f0"], "d": ["Beim Bombardement der verbündeten Flotte explodierte das Munitionsdepot der Festung, und Akkon ergab sich binnen weniger Stunden. Die Festung, die Ibrahim Pascha acht Jahre zuvor erst in sechs Monaten hatte nehmen können, zeigte die Überlegenheit der Schiffsartillerie.", "5cf01edf"]},
"OLAYLAR_EK4:1840-11-27:0":{"b": ["Konvention von Alexandria", "85cb47b0"], "d": ["Mehmed Ali willigte ein, auf Syrien, Adana, Kreta und den Hedschas zu verzichten, die osmanische Flotte zurückzugeben und die Oberhoheit des Sultans anzuerkennen; im Gegenzug wurde die erbliche Statthalterschaft Ägyptens gesichert.", "63d90626"]},
"OLAYLAR_EK4:1841-02-25:0":{"b": ["Das ägyptische Heer räumte Syrien und die Çukurova", "719a28dc"], "d": ["Die neunjährige Besetzung endete; Ibrahim Paschas Heer kehrte über den Sinai nach Ägypten zurück. Auf der Karte geht ein breiter Gürtel von Aleppo bis Gaza, von Adana bis Kreta wieder in die unmittelbare osmanische Verwaltung über. Weitere am selben Datum verlorene Siedlungen: Urfa, Maraş, Tarsus, Antiochia, Kandiye (Kreta), Hama, Damaskus, Jerusalem, Jaffa, Nablus.", "a678b17a"]},
"OLAYLAR_EK4:1841-05-24:0":{"b": ["Ferman: Die Statthalterschaft Ägyptens wurde der Familie von Kavala erblich überlassen", "87b89ff8"], "d": ["Der Ferman des Sultans erkannte die Statthalterschaft in der Weise an, dass sie innerhalb der Dynastie vom Vater auf den Sohn übergehen sollte; im Gegenzug wurde die Heeresstärke auf achtzehntausend herabgesetzt, die Steuer an Istanbul gebunden und das Recht zum Münzprägen und zum Vertragsschluss aufgehoben. Ägypten blieb eine Provinz, war aber nun das Land einer eigenen Dynastie. Die Verwaltung des Hedschas und der Haramain kehrte an die Hohe Pforte zurück. Weitere am selben Datum aus der Vasallenschicht in die unmittelbare Schicht zurückgekehrte Siedlungen: Mekka, Medina, Dschidda, Yanbu.", "48099454"]},
"OLAYLAR_EK4:1841-07-13:0":{"b": ["Londoner Meerengenkonvention", "0e95a1ea"], "d": ["Die an die Stelle von Hünkâr İskelesi tretende Konvention bestimmte, dass die Meerengen in Friedenszeiten für alle Kriegsschiffe gesperrt sind. Das von Russland allein erlangte Vorrecht wurde damit zu einer gemeinsamen Garantie Europas; die Meerengenfrage erhielt einen internationalen Status.", "5bbbb459"]},
"OLAYLAR_EK4:1848-09-01:0":{"b": ["Ibrahim Pascha wurde faktisch Statthalter Ägyptens", "9e14f5d9"], "d": ["An die Stelle des alternden und seiner geistigen Fähigkeiten verlustig gegangenen Mehmed Ali wurde sein Sohn Ibrahim Pascha zum Statthalter ernannt. Doch wenige Monate später, im November 1848, starb er vor seinem Vater.", "338908f8"]},
"OLAYLAR_EK4:1849-08-02:0":{"b": ["Tod des Kavalalı Mehmed Ali Pascha", "871310e0"], "d": ["Der in Kavala geborene Statthalter, der in Ägypten eine Dynastie begründete und das Reich zweimal an den Rand des Abgrunds brachte, starb im Alter von achtzig Jahren. Die von ihm gegründete Dynastie herrschte bis 1953 in Ägypten; der Staat aber, der sah, dass er die von ihm geschlagene Wunde nur durch europäisches Eingreifen schließen konnte, schritt auf dem Weg der Tanzimat voran.", "c0877894"]},
"OLAYLAR_EK5:1086-06-04:0":{"b": ["Süleyman ibn Kutalmisch bei Ain Salm besiegt und getötet; Antiochia schied aus dem Besitz der Anatolischen Seldschuken aus", "0412dfa1"], "d": ["Süleyman ibn Kutalmisch, der Antiochia 1084 den Byzantinern abgenommen hatte, fiel in der Schlacht von Ain Salm gegen den Herrscher der Syrischen Seldschuken, Tutusch; die Stadt kam unter die Kontrolle des Großseldschukensultans Malik-Schah, und Yaghi-Siyan wurde als Statthalter eingesetzt.", "67de3930"]},
"OLAYLAR_EK5:1092-11-20:0":{"b": ["Malik-Schah starb; Antiochia wurde mit Yaghi-Siyan dem Syrischen Seldschuken Tutusch unterstellt", "c61da1b4"], "d": ["Nach dem Tod des Großseldschukensultans Malik-Schah wurde der Staat unter den Erben aufgeteilt; der Statthalter von Antiochia, Yaghi-Siyan, wurde dem Herrscher Syriens, Tutusch, unterstellt.", "6c441576"]},
"OLAYLAR_EK5:1097-06-19:0":{"b": ["Nikaia (İznik) ergab sich den Kreuzfahrern; das seldschukische Zentrum zog sich nach Konya zurück, Byzanz begann, Westanatolien zurückzugewinnen", "8a4e90fa"], "d": ["Nach der Belagerung Nikaias (İznik) durch die Kreuzfahrer ergab sich die Stadt am 19. Juni 1097 den Byzantinern; der seldschukische Sultan Kılıçarslan I. verlegte sein Zentrum ins Landesinnere nach Konya, während Byzanz Orte wie Ephesos an den westanatolischen Küsten zurückgewann.", "c63f0616"]},
"OLAYLAR_EK5:1180-05-28:0":{"b": ["Kılıçarslan II. nahm Dorylaion (Eskişehir) und Kütahya den Byzantinern ab", "3ddee6c2"], "d": ["Nach Myriokephalon (1176) gingen die byzantinischen Festungen Dorylaion und Kütahya im Inneren Anatoliens in den letzten Jahren Manuels beziehungsweise nach seinem Tod 576/1180 in die Hand Kılıçarslans II. über.", "4358e7d4"]},
"OLAYLAR_EK5:1281-01-01:0":{"b": ["Tod Ertuğrul Ghazis und Übergang Osman Beys zum Beylik – das Erbe von Söğüt und Domaniç", "395fb9fa"], "d": ["Nach dem TDV starb Ertuğrul Ghazi im Jahr 680 (1281–82); der Artikel vermerkt, dass auch die Daten 1288 und 1289 angegeben werden. Osman Bey übernahm von seinem Vater keine eroberte Stadt, sondern zwei Zuteilungen, die der seldschukische Sultan Ertuğrul, den er an der vordersten Linie des Grenzgebiets angesiedelt hatte, gegeben hatte: das Winterquartier (yurtluk) in Söğüt und die Sommerweide (yaylak) in Domaniç. Das Beylik begann also nicht mit einem Eroberungserbe, sondern mit zwei Weidezuteilungen; auf der Karte werden diese beiden Orte nicht als „Eroberung“, sondern als „Erbe“ dargestellt.", "37fbc33c"]},
"OLAYLAR_EK5:1282-03-30:0":{"b": ["Sizilianische Vesper – das Haus Anjou verlor die Insel Sizilien", "547db635"], "d": ["Der Aufstand, der in Palermo zur Stunde des Abendgebets am Ostermontag gegen die Herrschaft Karls I. von Anjou ausbrach, riss die Insel Sizilien vom Haus Anjou los. Das Königreich Sizilien wurde geteilt: Die Insel wandte sich Aragon zu, das Haus Anjou behauptete sich dagegen im auf Neapel zentrierten Festlandskönigreich. Auch die Besitzungen des Hauses an Adria und Mittelmeer blieben diesem Königreich verbunden: Korfu, das seit 1267, und Durazzo, das seit den 1270er Jahren in seiner Hand war, bestanden als Teil des Königreichs Neapel fort; auch die Burgen Avlona, Kanina und Himara an der albanischen Küste blieben im auf Neapel zentrierten Königreich (der Kommandant von Avlona, John of Taxis, widerstand 1282 über das ganze Jahr den Byzantinern; Durazzo, Avlona und Kanina gingen höchstwahrscheinlich Anfang 1285 an Byzanz über). Malta fiel dagegen erst 1284 in die Hand der Aragonesen.", "7c8ea21d"]},
"OLAYLAR_EK5:1285-01-01:0":{"b": ["Überfall auf Kulacahisar – Osman Beys erste militärische Unternehmung", "79b00b14"], "d": ["TDV, Artikel Osman I.: ‚Er plünderte und verbrannte die kleine Burg Kulaca Hisarı bei İnegöl (684/1285).‘ Dies ist Osman Beys erste in den Quellen datierbare militärische Aktion. Es wurde keine dauerhafte Siedlung erobert, die Burg wurde geplündert und niedergebrannt; es handelt sich daher weniger um eine Eroberung als um einen klassischen Grenzraubzug. Sie gilt als Ausgangspunkt der militärischen Tätigkeit des Beylik.", "15ee9a09"]},
"OLAYLAR_EK5:1288-01-01:0":{"b": ["Eroberung von Karacahisar – erster Stadtgewinn und Herrschaft über Eskişehir", "178ae619"], "d": ["TDV, Artikel Osman I.: Osman Bey ‚eroberte im Jahr 687 (1288) Karacahisar und wurde Herr von Eskişehir‘. Dies ist der erste echte Stadtgewinn des Beylik, und der Überlieferung nach stieg Osman Bey mit diesem Erfolg zum Sandschakbey an der Grenze auf; es wird berichtet, dass in Karacahisar erstmals in seinem Namen die Freitagspredigt verlesen und dort der erste Kadi eingesetzt wurde. Der TDV-Artikel Eskişehir vermerkt, dass die osmanische Tradition das Jahr 1291 nennt, deren Richtigkeit aber zweifelhaft ist.", "90949e22"]},
"OLAYLAR_EK5:1291-05-18:0":{"b": ["Fall Akkons an die Mamluken – Beseitigung der Kreuzfahrer von der syrischen Küste: Sidon und Beirut", "3ca7a464"], "d": ["Akkon, lange das Zentrum des Kreuzfahrerkönigreichs Jerusalem, wurde vom Mamlukensultan al-Malik al-Aschraf Halîl erobert, und die Herrschaft der Kreuzfahrer in Palästina endete. Die aus Akkon abgezogenen Templer flüchteten nach Sidon; als das mamlukische Heer nahte, verließen sie die Seeburg und flohen nach Zypern, und die Stadt ging im selben Sommer an die Mamluken über. Auch das seit 1197 in der Hand der Kreuzfahrer befindliche Beirut wurde 1291 vom Statthalter von Damaskus, Sencer eş-Şücâî, genommen. Damit wurde die zweihundertjährige Präsenz der Kreuzfahrer von der syrisch-palästinensischen Küste getilgt.", "63b3c40c"]},
"OLAYLAR_EK5:1299-01-01:0":{"b": ["Eroberung von Bilecik und Yarhisar durch einen nächtlichen Überfall", "f461b0af"], "d": ["TDV, Artikel Bilecik: ‚Der Tekfur von Bilecik und die anderen Tekfure der Gegend bereiteten ein Attentat auf Osman Ghazi vor; als die Osmanen davon Kenntnis erhielten, eroberten sie in einem plötzlichen Überfall Yarhisar und Bilecik (1299).‘ Beide Burgen wurden in einer einzigen Unternehmung, im Überfall derselben Nacht, genommen. Dieses Datum ist der Wendepunkt, der als Gründungsjahr des Osmanischen Staates gilt. Weitere am selben Datum angegliederte Orte: İnegöl.", "ec452c9e"]},
"OLAYLAR_EK5:1302-07-27:0":{"b": ["Schlacht von Koyunhisar (Bapheus) – erster großer Sieg gegen das byzantinische Heer", "584a9512"], "d": ["TDV, Artikel Osman I.: Osman Bey kämpfte am 27. Juli 1302 bei Bapheus (Koyunhisar) gegen das byzantinische Heer und besiegte es. Dieser Sieg ist der Wendepunkt, der Osman Bey von einem regionalen Grenzbey zum Dynastiegründer erhob. Nach der Schlacht kam die Ebene von Bursa unter osmanische Kontrolle, und die Blockade von İznik begann.", "b82fb787"]},
"OLAYLAR_EK5:1303-01-01:0":{"b": ["Sieg bei Dimbos und anschließende Einnahme von Kite und Ulubat", "e168ab64"], "d": ["TDV, Artikel Osman I.: Im Jahr 702 (1303) wurde das Bündnis der Tekfure von Bursa, Kestel, Kite und Adranos am Engpass von Dimbos vernichtend geschlagen; der Feind wurde kämpfend bis in die Enge zurückgedrängt, und der Tekfur von Kestel fiel auf dem Schlachtfeld. Unmittelbar nach dem Sieg wurden die Burgen Kite und Ulubat genommen, die Landverbindung von Bursa abgeschnitten und seine Blockade verschärft. Auch der junge Orhan nahm an dieser Schlacht teil.", "4afb53bf"]},
"OLAYLAR_EK5:1304-01-01:0":{"b": ["Sakarya-Feldzug: Einnahme von Leblebicihisar, Lefke, Mekece und Geyve", "a51ba4d3"], "d": ["Der TDV-Artikel Osman I. gibt die Abfolge des Sakarya-Feldzugs von 704 (1304) an: ‚Als er nach Leblebüci Hisarı kam, unterwarf sich der Tekfur … Er gelangte nach Lefke … Er erreichte Mekece … Er ging nach Geyve und nahm die Burg, die er leer vorfand.‘ Lefke ist das Tor des Sakarya-Tals nach Bilecik. Dieser eine Feldzug brachte die längs des Tals verlaufende Burgenkette unter osmanische Kontrolle und schloss die Ostflanke des Beckens von İznik.", "ae2866c2"]},
"OLAYLAR_EK5:1304-01-01:1":{"b": ["Chios kam unter die Kontrolle der genuesischen Familie Zaccaria", "9eebe4de"], "d": ["Angesichts der Bedrohung durch die Aydınoğulları bat der byzantinische Kaiser den Genuesen Benedetto Zaccaria um Hilfe; die Insel kam unter dessen Kontrolle (nominelle byzantinische Vasallenschaft). Die Herrschaft der Zaccaria dauerte bis 1329.", "4d0e4fd8"]},
"OLAYLAR_EK5:1304-01-01:2":{"b": ["Samos kam in den Besitz der Genuesen (Zaccaria) von Chios", "0e6f51e3"], "d": ["Die genuesische Familie Zaccaria, die Chios unter ihre Kontrolle genommen hatte, fügte auch das nahezu entvölkerte Samos ihrem Besitz hinzu (TDV: 1304–1329).", "8eb44fb2"]},
"OLAYLAR_EK5:1305-01-01:0":{"b": ["Eroberung der Burgen am Engpass von Geyve: Karaçepüş, Karatigin und Absu", "76907c78"], "d": ["TDV, Artikel Orhan: Orhan ‚eroberte 705 (1305) auf dem Sakarya-Feldzug die Burgen Karaçepüş (Katoikia), Karatigin vor İznik und Absu (Hypsu: im Engpass von Geyve)‘. Diese drei Burgen sperrten den Übergang zwischen dem Sakarya-Tal und dem Becken von İznik und schnitten İznik damit vollständig von Hilfe zu Lande ab. In Karaçepüş und Absu am Engpass von Geyve wurde Gazi Abdurrahman angesiedelt; die Stadt konnte nun nur noch durch Hunger zu Fall gebracht werden.", "d330595f"]},
"OLAYLAR_EK5:1323-09-01:0":{"b": ["Feldzug gegen Adranos (Orhaneli) – Osman Beys letzter Feldzug", "4811546c"], "d": ["Der TDV-Artikel Orhan verzeichnet den Feldzug gegen die Burg Adranos im Herbst 1323 als Osman Beys letzten Feldzug. Der Tekfur von Adranos war Mitglied des vor zwanzig Jahren bei Dimbos gegen die Osmanen geschlossenen Tekfur-Bündnisses; dieser Feldzug bedeutete die Begleichung jener Rechnung. Der genaue Tag der Eroberung der Burg ist unbekannt; die Unternehmung wurde von Orhan Bey fortgeführt.", "1e8ea25a"]},
"OLAYLAR_EK5:1324-01-01:0":{"b": ["Tod Osman Ghazis und Übergang Orhan Beys zum Beylik", "021487cd"], "d": ["Osman Ghazi, der dem Beylik den Namen gab, starb nach Zeugnis der Stiftungsurkunden von Asporça Hatun und Mekece im Jahr 724 (1324). Sein Sohn Orhan, der seit 1305 an der Spitze des Heeres in den Feldzügen stand, übernahm nach dem Tod seines Vaters ohne jeden Thronstreit die Spitze des Beylik. Dass die Gründergeneration die Fahne ohne Erschütterung weitergab, zeigt, dass die Dynastie auf dem Weg vom Grenz-Beylik zum Staat ihre erste große Prüfung gelassen bestand.", "6f95e64a"]},
"OLAYLAR_EK5:1329-01-01:0":{"b": ["Chios den Zaccaria abgenommen und an Byzanz gebunden", "f6741b26"], "d": ["Kaiser Andronikos III. entfernte die Zaccaria von der Insel und band die Insel unter der Statthalterschaft Benedettos III. an Byzanz. Die Insel sollte 1346 vom Genuesen Simone Vignosi besetzt werden.", "84f19c2b"]},
"OLAYLAR_EK5:1329-01-01:1":{"b": ["Samos kehrte von den Zaccaria zu Byzanz zurück (Chios-Kette)", "08034974"], "d": ["Mit dem Untergang der Herrschaft der Zaccaria (Anbindung von Chios an Byzanz 1329) endete auch der genuesische Besitz auf Samos.", "314dce74"]},
"OLAYLAR_EK5:1329-06-01:0":{"b": ["Schlacht von Pelekanon (Maltepe) und Einnahme ganz Kocaelis", "389e7bd4"], "d": ["TDV, Artikel Orhan: Am ersten Tag der Schlacht entsandte Orhan Ghazi eine dreihundert Mann starke Truppe, um das byzantinische Heer an sich zu ziehen; am zweiten Tag weitete sich die Schlacht aus, als die Einheiten unter Pazarlu in die Ebene hinabstiegen, und als der Kaiser von einem Pfeil verwundet wurde, brach im byzantinischen Heer Panik aus. Das Ergebnis ist eindeutig: ‚Orhan nahm ganz Kocaeli ein; nach dem Sieg blieb den Leuten von İznik keine Hoffnung.‘ Die Küstenstädte von Hereke bis Üsküdar kamen unter osmanische Herrschaft, und Gebze wurde zum Zentrum der Region gemacht. Dies war das letzte byzantinische Kaiserheer, das zur Rettung Konstantinopels kam.", "73fe4332"]},
"OLAYLAR_EK5:1331-03-03:0":{"b": ["Gründung der ersten osmanischen Medrese in İznik", "c85fb625"], "d": ["Orhan Bey ernannte unmittelbar nach der Einnahme von İznik Çandarlı Kara Halil dort zum Kadi, ließ eine Basilika in eine Moschee umwandeln und neben ihr ein Imaret und eine Medrese errichten und begann so den Ausbau der Stadt. Nach dem TDV-Artikel Dâvûd-i Kayserî wurde der Bau der Medrese 1336 abgeschlossen, und Orhan Ghazi berief Dâvûd-i Kayserî mit einer täglichen Bezahlung von 30 Akçe zum Lehrer. Diese Medrese ist der erste institutionelle Schritt des osmanischen Wissenschaftslebens; das Beylik fügte der Eroberungskraft auch eine Gelehrtentradition hinzu. Die Verwandlung einer eroberten byzantinischen Hauptstadt in ein Zentrum islamischer Gelehrsamkeit war das erste greifbare Zeichen des osmanischen Anspruchs, ein gefestigter Staat zu sein.", "4f11a077"]},
"OLAYLAR_EK5:1333-08-01:0":{"b": ["Byzanz wurde tributpflichtig – Belagerung von İzmit und Vertrag", "0c1ec8d3"], "d": ["TDV, Artikel Orhan: Orhan belagerte im Sommer 733 (1333) İzmit mit einem großen Heer und Mangonels, und der Kaiser willigte in einen Vertrag ein. Im Gegenzug dafür, dass er die Belagerung aufgab, erklärte sich Byzanz bereit, Orhan jährlich 12.000 Goldstücke (Hyperpyra) zu zahlen; ‚damit geriet Byzanz in den Augen des osmanischen Emirs in den Zustand eines tributpflichtigen Landes‘. Orhan wiederum sollte ein Freund des Kaisers sein und die Byzanz untertanen Städte nicht angreifen. Dass ein Grenz-Beylik Ostrom tributpflichtig machte, war die Verkündung dessen, wie sehr sich das Kräfteverhältnis gedreht hatte.", "e2e3eeb4"]},
"OLAYLAR_EK5:1335-01-01:0":{"b": ["Samothrake ging von den Venezianern an die genuesische Familie Gattilusio über", "c499ed5f"], "d": ["Die genuesische Familie Gattilusio vertrieb die Venezianer, die die Insel seit 1204 in der Hand gehalten hatten, von der Insel.", "97a996b3"]},
"OLAYLAR_EK5:1345-01-01:0":{"b": ["Annexion des Beylik von Karesi: Balıkesir, Bergama, Biga, Edremit und Erdek", "c7cb0511"], "d": ["Der TDV-Artikel Orhan (İnalcık) datiert die Annexion auf 735 (1334–35): Nach dem Tod Demirhan Beys luden die Gazis von Karesi und Hacı İlbey Dursun Bey auf den Thron ein und baten Orhan um Hilfe. Orhan zog zunächst gegen Balıkesir; als Dursun Bey, der zu Friedensverhandlungen ging, durch einen von der Burg Bergama abgeschossenen Pfeil starb, wurde das Beylik vollständig dem osmanischen Land angegliedert. Im selben Feldzug unterwarfen sich Kirmasti und Mihaliç, Gölyazı wurde genommen, und das zuvor gegen Gnade belassene Ulubat wurde endgültig besetzt. Orhan ernannte Süleyman Pascha zum Sandschakbey von Karesi und machte Biga zum Grenzzentrum – damit wurden die seemännischen Kader für den Übergang nach Rumelien gewonnen. Anmerkung: Der TDV-Artikel Karesioğulları nennt für dasselbe Ereignis das Datum 746 (1345); die Enzyklopädie widerspricht sich also selbst. Weitere am selben Datum angegliederte Orte: Çanakkale.", "f5ed82c2"]},
"OLAYLAR_EK5:1346-06-15:0":{"b": ["Samos kam in den Besitz der Maona von Chios", "01628b2f"], "d": ["Als der Genuese Simone Vignosi Chios einnahm und die Verwaltung der Gesellschaft Maona überließ, kam auch Samos in den Besitz der Genuesen von Chios (Maona) (TDV: 1346–1475).", "3b122d12"]},
"OLAYLAR_EK5:1352-01-01:0":{"b": ["Orhan Ghazis erste Kapitulation mit den Genuesen", "e64cb196"], "d": ["Orhan Ghazi, der sich während des venezianisch-genuesischen Krieges mit den Genuesen verständigte, entsandte nach der Meerengenschlacht vom Februar 1352 tausend Bogenschützen zur Verteidigung von Pera und stellte 60.000 Goldstücke für den Truppentransport bereit; im Gegenzug gewährte er den Genuesen die erste Kapitulation. Der vollständige Text des Vertrags ist nicht überliefert. Dies ist die erste offizielle Vereinbarung der Osmanen mit einer europäischen Seemacht, und sie sollte fünfunddreißig Jahre später, 1387, erneuert werden.", "68c60677"]},
"OLAYLAR_EK5:1354-03-02:0":{"b": ["Einnahme von Gelibolu – dauerhafter Brückenkopf in Rumelien", "ba51a160"], "d": ["Die Osmanen nahmen 1354 Gelibolu, dessen Umgebung sie in den Jahren 1349–1352 als Verbündete Kantakuzenos’ kennengelernt hatten; das große Erdbeben, das die Stadtmauern zerstörte, hatte die Gelegenheit geschaffen. Der schmale Brückenkopf bei Çimpe wurde so auf der rumelischen Seite des Bosporus zu einem wirklichen Stützpunkt, und das Tor nach Thrakien wurde weit aufgestoßen. Gelibolu sollte 1366 durch den savoyischen Kreuzzug verloren gehen, durch die zweite Eroberung 1376 aber endgültig unter osmanische Herrschaft kommen. Weitere am selben Datum angegliederte Orte: Kilitbahir.", "cac0192e"]},
"OLAYLAR_EK5:1357-09-01:0":{"b": ["Tod des Eroberers Rumeliens, Süleyman Pascha", "2dc98228"], "d": ["Süleyman Pascha, der älteste Sohn Orhan Beys und Architekt der Eroberungen in Rumelien, starb im Herbst 1357 – von den in den Quellen als 758 (1357), 759 und 760 (1359) angegebenen Daten das am meisten akzeptierte –, indem er bei einer Jagd vom Pferd stürzte. Der Tod des Prinzen, der mit seinen Übergängen in den Jahren 1352–1354 die dauerhafte osmanische Präsenz in Rumelien begründet hatte, überließ die Thronfolge seinem Bruder Murad. Das Mausoleum Süleyman Paschas, der in Bolayır beigesetzt wurde, blieb als ältestes Dynastiedenkmal der Osmanen in Europa bestehen.", "1f780557"]},
"OLAYLAR_EK5:1361-01-01:0":{"b": ["Pençik-Gesetz – Legung des Fundaments des Janitscharenkorps", "e5877c2d"], "d": ["Nach den Eroberungen in Rumelien wurde auf Anraten des Gelehrten Karamanlı Kara Rüstem das Pençik-System in Kraft gesetzt, das vorsah, ein Fünftel der Kriegsgefangenen oder deren Gegenwert in Geld dem Staat vorzubehalten. Indem aus diesen Gefangenen Ausgewählte bei türkischen Familien aufgezogen und zum Militärdienst herangezogen wurden, entstand der Kern einer unmittelbar dem Sultan unterstehenden ständigen Infanterietruppe – des Janitscharenkorps. Mit dieser Regelung begann die Verwandlung eines auf Stammesreiterei beruhenden Grenz-Beylik in einen Staat mit einem Zentralheer.", "f28873dd"]},
"OLAYLAR_EK5:1363-01-01:0":{"b": ["Vorstoß nach Westthrakien: Eroberung von Gümülcine", "9ef69221"], "d": ["Die nach der Einnahme von Edirne westlich der Maritza vorrückenden Grenztruppen nahmen unter dem Kommando von Gazi Evrenos Bey Gümülcine, das Zentrum Westthrakiens, ein. Die Stadt wurde zum vorgeschobenen Hauptquartier, von dem aus Evrenos Bey seine Raubzüge nach Makedonien tragen sollte. Damit kam der bis zur Ägäisküste reichende Teil Thrakiens unter osmanische Kontrolle, und der Weg nach Thessaloniki öffnete sich.", "0206d2bb"]},
"OLAYLAR_EK5:1373-01-01:0":{"b": ["Westlich von Philippopel: Angliederung von Tatarpazarcığı und İhtiman", "1664d0e1"], "d": ["Nach der Einnahme von Philippopel (Filibe) 1372 wurden Tatarpazarcığı am oberen Ende des Maritza-Tals und İhtiman, das den nach Sofia führenden Pass hielt, der osmanischen Verwaltung angegliedert. Diese Linie, die in der Hand der nach der Schlacht an der Maritza zu Vasallen gewordenen lokalen Beys lag, wurde unter direkte Verwaltung gestellt und die Route Philippopel–Sofia damit lückenlos gemacht. Dieser Vormarsch ist die Vorbereitung auf den zwölf Jahre später folgenden Weg zur Eroberung Sofias.", "0e9acfa0"]},
"OLAYLAR_EK5:1373-05-15:0":{"b": ["Aufstand Savcı Beys – gemeinsame Erhebung eines Prinzen und des byzantinischen Thronfolgers", "75198c33"], "d": ["Savcı Bey, der Sohn Murads I., und Andronikos Palaiologos, der Sohn des byzantinischen Kaisers Johannes V., erhoben sich Anfang Mai 1373 gleichzeitig in Bursa und Konstantinopel gegen ihre Väter. Dieses die Thronfolger zweier Dynastien vereinende Bündnis wurde rasch niedergeschlagen; Savcı Bey wurde ergriffen, geblendet und hingerichtet. Das von der osmanischen Überlieferung für den Aufstand angegebene Datum 787 (1385) ist falsch; das Ereignis fällt unmittelbar in die Jahre nach dem Eintritt von Byzanz in die osmanische Vasallität und zeigt, wie sehr die beiden Höfe ineinander verflochten waren.", "9776426c"]},
"OLAYLAR_EK5:1374-01-01:0":{"b": ["Struma- und Mesta-Täler: Angliederung von Köstendil, Petritsch, Nevrokop und Drama", "8c0980c4"], "d": ["Die Täler von Struma und Mesta, die in der Hand der nach dem Sieg an der Maritza tributpflichtig gewordenen serbischen und bulgarischen lokalen Beys lagen, wurden durch den Vormarsch der Grenzbeys unter direkte osmanische Verwaltung genommen. Mit der Angliederung von Köstendil, Petritsch, Nevrokop und Drama öffnete sich die östliche Hälfte Makedoniens, und Thessaloniki und Serres gerieten in den Belagerungsring. Die Ausdehnung Rumeliens nach Südwesten auf der Karte ist das Ergebnis dieser Unternehmung.", "a50a02ad"]},
"OLAYLAR_EK5:1381-04-01:0":{"b": ["Timur nahm Herat ein: Ende der Kart-Dynastie und Übergang Chorasans an die Timuriden", "15f6019e"], "d": ["Chorasan war 1380 durch den Kampf zwischen den Sarbadaren, den Kart und den Muzaffariden zersplittert. Nachdem Timur seinen Sohn Mîrân Şah in die Region entsandt hatte, zog er selbst gegen Herat und nahm die Stadt nach einiger Belagerung vom Kart-Malik Gıyâseddin Pîr Ali entgegen. Der nach seinem Abzug ausgebrochene Aufstand wurde von Mîrân Şah blutig niedergeschlagen und beendete die seit 1255 in Herat herrschende Kart-Dynastie. Ganz Chorasan von Meschhed bis Nischapur kam zu diesem Datum unter timuridische Verwaltung.", "6ae06d43"]},
"OLAYLAR_EK5:1381-10-01:0":{"b": ["Ende des Beylik von Eretna und Gründung des Staates des Kadı Burhâneddin", "60dcaf57"], "d": ["Die Eretnaoğulları, die 1335 aus der ilchanidischen Statthalterschaft hervorgegangen waren und sechsundvierzig Jahre lang Zentralanatolien mit den Zentren Sivas und Kayseri regiert hatten, lösten sich durch Streitigkeiten im Palast auf. Kadı Burhâneddin, der im Mai 1378 Wesir geworden war, beseitigte seine Rivalen Kılıcarslan und Hacı Şadgeldi, rief im Herbst 1381 seine Sultanswürde aus, beendete das Beylik und gründete den nach ihm benannten Staat. Damit wechselte der östliche Nachbar der Osmanen den Besitzer; die Linie Sivas–Kayseri sollte danach siebzehn Jahre in der Hand Kadı Burhâneddins bleiben.", "f5b2be0c"]},
"OLAYLAR_EK5:1385-01-01:0":{"b": ["Vorstoß ins Innere Makedoniens: Eroberung von Monastir und Ohrid", "63bb7838"], "d": ["Monastir an der Via Egnatia und Ohrid am Seeufer kamen während der Raubzüge in Richtung Albanien unter osmanische Verwaltung. Beide waren Schlüsselpunkte der zur Adria führenden Straße; Ohrid war zudem das älteste orthodoxe Erzbischofszentrum des Balkans. Das TDV vermerkt, dass für das Eroberungsdatum Ohrids keine sichere Angabe vorliegt und die Daten 787 (1385) sowie 797 (1395) nach dem Tod von Marko Kraljević vorgebracht werden; hier wurde 1385 zugrunde gelegt. Monastir sollte in den folgenden Jahrhunderten eines der wichtigsten Militärzentren Rumeliens werden.", "e5418654"]},
"OLAYLAR_EK5:1385-09-18:0":{"b": ["Schlacht von Savra – Öffnung der Tore Albaniens", "dda6671b"], "d": ["Auf den Hilferuf des gegen das Haus Balša bedrängten albanischen Fürsten Karl Thopia hin schlugen die osmanischen Truppen in der Ebene von Savra das Heer Balšas II. vernichtend; Balša fiel auf dem Schlachtfeld. Diese Schlacht, die auf Einladung eines einheimischen Fürsten geführt wurde, verschaffte den Osmanen den ersten dauerhaften Einfluss in den bis zur Adriaküste reichenden albanischen Ländern. Diese Politik, die die Zwietracht der Fürsten der Region zur Gelegenheit machte, sollte im folgenden Jahrhundert die unveränderliche Methode der Balkaneroberungen sein.", "05382964"]},
"OLAYLAR_EK5:1386-01-01:0":{"b": ["Timurs „Dreijahresfeldzug“: Eroberung Aserbaidschans und Nordirans", "2a98ec51"], "d": ["Timur, der bei den Chorasan-Feldzügen die Zersplitterung Irans aus der Nähe gesehen hatte, marschierte 788 (1386) nach Westen. Im als „Dreijahresfeldzug“ bezeichneten Unternehmen von 1386–1388 ging er über Mazandaran, Luristan und Georgien nach Aserbaidschan und erreichte Karabach; Täbris, Ardabil, Urmia und Nachitschewan kamen unter timuridische Verwaltung. Die Inbesitznahme Nordirans und Aserbaidschans war, wie einst zwischen dem Ulus des Dschötschi und den Ilchanen, auch der Beginn eines langen Ringens mit der Goldenen Horde.", "aaf3b558"]},
"OLAYLAR_EK5:1386-06-01:0":{"b": ["Schlacht von Frenkyazısı und Belagerung von Konya – erster Karaman-Feldzug", "af4e5d77"], "d": ["Gegen den Karamaniden Alâeddin Ali Bey, der trotz seiner Stellung als Schwiegersohn über die osmanische Expansion in Westanatolien verärgert war, zog Murad I. persönlich zu Felde; in der Schlacht an der Frenk Yazısı genannten Stelle besiegte das geübte und erfahrene osmanische Heer die karamanidischen Truppen. Anschließend wurde die Burg von Konya belagert, doch da Alâeddin Bey begnadigt wurde, wurde das Beylik nicht vollständig beseitigt. Dieser Feldzug ist der Eröffnungsakt der langen, ein Jahrhundert währenden Auseinandersetzung zwischen den Osmanen und Karaman, die erst 1468 mit der endgültigen Annexion enden sollte.", "087a605a"]},
"OLAYLAR_EK5:1390-06-01:0":{"b": ["Gründung der Werft von Gelibolu – Geburt der osmanischen Flotte", "47546241"], "d": ["Die erste voll ausgestattete Werft des Osmanischen Staates wurde 1390 von Yıldırım Bayezid in Gelibolu an der Stelle der von Byzanz übrig gebliebenen Werft gegründet. Die Osmanen, die das maritime Erbe der westanatolischen Beyliks übernommen hatten, wurden damit erstmals zu einer Seemacht, die ihre Schiffe selbst baute. Die am Schlüsselpunkt der Dardanellen gelegene Werft diente von der Belagerung Konstantinopels bis zu den Ägäis-Feldzügen anderthalb Jahrhunderte lang als Hauptstützpunkt der osmanischen Flotte.", "f214717c"]},
"OLAYLAR_EK5:1391-01-01:0":{"b": ["Einnahme von Warna an der Schwarzmeerküste", "a84b2abf"], "d": ["Bei der Einengung der Länder des Bulgarenzarenreichs zwischen Donau und Schwarzem Meer kam Warna, der größte Hafen an der Küste, unter osmanische Verwaltung. Die Einnahme des Hafens ebnete den Vormarsch in Richtung Dobrudscha und verschaffte den Osmanen die erste große Anlegestelle an der Westküste des Schwarzen Meeres. Warna sollte dreiundfünfzig Jahre später auch Schauplatz des Sieges von 1444 sein, in dem das Kreuzfahrerheer vernichtet wurde.", "421a978f"]},
"OLAYLAR_EK5:1393-01-01:0":{"b": ["Ende der Muzaffariden-Dynastie: Niederlage Şah Mansûrs vor Schiras", "5fd14eb8"], "d": ["Şah Mansûr, der letzte starke Herrscher der seit 1318 in Yazd, Fars, Isfahan und Kerman herrschenden Muzaffariden, verbündete sich mit seinen Verwandten und zog gegen Timur. In der Schlacht bei Schiras verlor er, nachdem einer seiner Emire zur Gegenseite übergelaufen war, den Großteil seiner Truppen, wurde besiegt und getötet. Als Timur anschließend auch alle Mitglieder der Dynastie töten ließ, endete die Muzaffariden-Herrschaft, und Fars und Kerman wurden der timuridischen Verwaltung angegliedert.", "8e89c2dc"]},
"OLAYLAR_EK5:1393-06-01:0":{"b": ["Angliederung Amasyas an das osmanische Land", "fe2860cf"], "d": ["Der Emir von Amasya, das bei Yıldırım Bayezids Zentralanatolien-Unternehmung belagert wurde, übergab die Stadt den Osmanen, und Bayezid zog 1393 in die Stadt ein. Der Sultan überließ ihre Verwaltung seinem Sohn Mehmed Çelebi; als Sandschak der Prinzen wurde Amasya von da an zu einer der wichtigsten Erziehungsstätten der osmanischen Dynastie. Diese Wahl sollte im späteren Interregnum entscheidend werden, und Çelebi Mehmed sollte seinen Kampf um die Wiedervereinigung des Staates von dieser Amasya-Basis aus führen.", "389ab68d"]},
"OLAYLAR_EK5:1393-08-29:0":{"b": ["Timur nahm Bagdad ein – die Dschalairiden flohen nach Anatolien", "4d5602b3"], "d": ["Timur eroberte nach langer Belagerung Bagdad; der Herrscher der Stadt, der dschalairidische Sultan Ahmed, floh nach Westen und fand zuerst bei den Mamluken, dann am osmanischen Hof Zuflucht. Timurs Expansion nach Westen kam damit erstmals in unmittelbaren Kontakt mit der osmanischen Einflusssphäre. Das erste Glied der Feindschaft zwischen den beiden Herrschern beginnt hier.", "2fac674f"]},
"OLAYLAR_EK5:1398-01-01:0":{"b": ["Die Region Nevşehir und Ürgüp ging von den Karamanoğulları in osmanische Hand über", "06ff59e8"], "d": ["In den Feldzügen Bayezids des Blitzes gegen die Karamanoğulları ging die Region Nevşehir (Muşkara) und Ürgüp 800/1398 an die osmanische Verwaltung über; 1402, nach der Schlacht von Ankara, gab Timur die Region den Karamanoğulları zurück.", "5faa82e5"]},
"OLAYLAR_EK5:1398-07-15:0":{"b": ["Untergang des Staates des Kadı Burhâneddin", "b13391e3"], "d": ["Kadı Burhâneddin, der dem Ak-Koyunlu-Herrscher Karayülük Osman Bey in die Gefangenschaft geraten war, bot an, gegen die Übergabe von Sivas freigelassen zu werden, doch die Bevölkerung der Stadt leistete Widerstand, und der Sultan wurde vor den Mauern hingerichtet. Die Notabeln von Sivas setzten seinen Sohn Alâeddin Ali Çelebi an die Spitze, baten aber angesichts des Drucks der Ak Koyunlu Yıldırım Bayezid um Hilfe; die osmanischen Truppen unter dem Kommando von Süleyman Çelebi besiegten Karayülük und kamen in den Besitz der Stadt. Damit verschwand der Staat des Kadı Burhâneddin aus der Geschichte, und Sivas, Tokat, Niksar und Kayseri wurden dem osmanischen Land angegliedert. Weitere am selben Datum angegliederte Orte: Kırşehir, Çorum.", "2a0c7f3a"]},
"OLAYLAR_EK5:1399-11-01:0":{"b": ["Timurs Ultimatum: Die Auslieferung der Flüchtlinge wurde abgelehnt", "33790bc8"], "d": ["Auf Timurs Druck hin flüchteten der dschalairidische Sultan Ahmed und der Kara-Koyunlu-Führer Kara Yûsuf auf osmanisches Gebiet; Timur verlangte die Auslieferung dieser beiden Flüchtlinge, Yıldırım Bayezid lehnte ab. Daraufhin begannen die beiden Herrscher, Briefe mit gegenseitig schweren Beleidigungen auszutauschen. Der ideologische Boden des Krieges wurde mit diesem Briefwechsel bereitet, noch ehe sich ein einziger Soldat bewegt hatte.", "ac66be59"]},
"OLAYLAR_EK5:1400-01-01:0":{"b": ["Das Yıldırım-Darüşşifa in Bursa – erstes osmanisches Krankenhaus", "5f0dc59a"], "d": ["Yıldırım Bayezid ließ in den Jahren, in denen er in Bursa die prächtige Ulucami errichten ließ, der Stadt auch ein Darüşşifa hinzufügen; dies war das der Medizin gewidmete Glied seines umfangreichen Stiftungsprogramms aus Imaret, Medrese, Han und Brücke. Dieser Bau, das erste vom Staat gegründete Krankenhaus, diente auch als Medizinschule, die Ärzte ausbildete, und bestimmte das Modell der osmanischen Gesundheitseinrichtungen. Das nur zwei Jahre vor der Katastrophe von Ankara vollendete Werk gehört zu den letzten Gliedern von Yıldırıms Vorstellung, Bursa in eine Reichshauptstadt zu verwandeln.", "5765ebac"]},
"OLAYLAR_EK5:1400-08-01:0":{"b": ["Timur machte Sivas dem Erdboden gleich", "f4d79de6"], "d": ["Timur, der unter der Führung des Ak-Koyunlu-Fürsten Karayülük Osman Bey und des Emirs von Erzincan, Mutahharten, nach Sivas marschiert war, belagerte die Stadt achtzehn Tage und richtete, nachdem er sie unter dem Versprechen, kein Blut zu vergießen, übernommen hatte, ein großes Massaker an; die Verteidiger ließ er in Gräben werfen und lebendig zuschütten. Die bedeutenden Bauwerke der Stadt, allen voran die Mauern, wurden zerstört, Sivas brach demografisch zusammen. Dies war der erste große Schlag, den Timur zwei Jahre vor der Schlacht von Ankara dem osmanischen Land versetzte.", "8ddb3e3a"]},
"OLAYLAR_EK5:1401-02-01:0":{"b": ["Yıldırım Bayezid nahm Erzincan und Kemah zurück", "7047ca08"], "d": ["Yıldırım Bayezid nutzte Timurs Aufbruch zum Syrien-Feldzug und nahm Erzincan und Kemah aus der Hand des Timur untertanen Emirs von Erzincan, Mutahharten. Obwohl er sich in die Zerstörung von Sivas nicht eingemischt hatte, bedeutete dieser Zug eine direkte Herausforderung von Timurs Einflusssphäre in Ostanatolien. Das Verhältnis der beiden Herrscher war von da an nicht mehr zu reparieren.", "2160d645"]},
"OLAYLAR_EK5:1402-03-13:0":{"b": ["Timurs Ultimatum aus Täbris – vier Bedingungen", "3e1ac50e"], "d": ["Timur ließ durch einen aus Täbris entsandten Gesandten vier Bedingungen mitteilen: die Rückgabe von Kemah an Mutahharten, die Rückgabe der den anatolischen Beys abgenommenen Gebiete an ihre Besitzer, die Entsendung eines osmanischen Prinzen als Geisel und die Annahme von Kopfbedeckung (külah) und Gürtel als Zeichen der Untertänigkeit sowie die Auslieferung Kara Yûsufs. Bayezid nahm keine davon an; trotz des Drängens der Staatsmänner und der Vermittlung Mutahhartens scheiterten die Verhandlungen. Timur war entschlossen, die anatolische Frage endgültig zu erledigen, bevor er zum China-Feldzug aufbrach.", "bd475bc3"]},
"OLAYLAR_EK5:1402-08-17:0":{"b": ["Die Saruhaniden wurden neu gegründet – Manisa schied aus dem Osmanischen Reich aus", "ac747b05"], "d": ["Drei Wochen nach der Niederlage von Ankara übernahm Orhan Bey mit Timurs Unterstützung die Spitze des Beylik, und das Land Saruhan wurde wieder unabhängig. Die auf Manisa zentrierte Region verschwand zwölf Jahre nach der osmanischen Annexion von 1390 von der Karte. Dies gehört zu den ersten mit sicher bekanntem Datum erfolgten Anwendungen von Timurs Politik der Wiederbelebung der Beyliks.", "9fe5744d"]},
"OLAYLAR_EK5:1402-08-20:0":{"b": ["Emir Süleyman floh mit dem Staatsschatz nach Rumelien", "0a2b7363"], "d": ["Emir Süleyman nahm den Staatsschatz in Bursa, die Archive, seine Familie und seine Brüder mit sich, setzte von Gemlik per Schiff nach Güzelcehisar (Anadoluhisarı) über, gelangte von dort nach Gelibolu und rief in Edirne seine Herrschaft aus. Die Verlagerung von Staatsarchiv und Schatz nach Rumelien ist der Beginn der für eine Generation währenden Verschiebung des osmanischen Schwerpunkts auf den Balkan. Auf der Karte wird Rumelien ab diesem Datum in der eigenen Farbe Emir Süleymans gezeichnet.", "393aa053"]},
"OLAYLAR_EK5:1402-09-15:0":{"b": ["Timur stellte die anatolischen Beyliks wieder her – die türkische Einheit löste sich auf", "15187774"], "d": ["Nach dem Sieg von Ankara gab Timur die bei ihm weilenden Beys in ihre früheren Länder zurück. Den Karamanidenbeys Mehmed und Ali wurden das Land Karaman sowie Kayseri, Kırşehir, Sivrihisar und Beyşehir gegeben; Germiyanoğlu Yâkub Bey II. Kütahya und das Land Germiyan; Candaroğlu İsfendiyar Bey zusätzlich zur Linie Kastamonu–Sinop Çankırı und Kalecik. Auch die Länder Aydın, Menteşe und Teke fielen an ihre früheren Dynastien zurück. Die von Yıldırım Bayezid in zehn Jahren geschaffene türkische Einheit Anatoliens löste sich in einem einzigen Sommer auf; auf der Karte erscheinen diese Beyliks wieder in ihren eigenen Farben.", "3a86d489"]},
"OLAYLAR_EK5:1402-12-14:0":{"b": ["Timur nahm İzmir den Johannitern ab", "66dd1dd4"], "d": ["Timur, der über Kütahya, Denizli, Aydın, Ayasuluk und Tire nach Westen hinabgezogen war, belagerte und nahm die seit 1344 in christlicher Hand befindliche Küstenstadt İzmir. Nachdem Timur diese Festung, die Yıldırım Bayezid jahrelang nicht hatte nehmen können, in kurzer Zeit erobert und auch die umliegenden Burgen genommen hatte, überließ er das Land Aydın seinen früheren Besitzern und wandte sich nach Osten. Die Stadt kam danach unter die Verwaltung des Aydınoğlu Cüneyd Bey.", "b6c372a5"]},
"OLAYLAR_EK5:1402-12-20:0":{"b": ["Îsâ Çelebi nahm Bursa ein – der anatolische Anteil entstand", "955128c1"], "d": ["Îsâ Çelebi, der sich nach der Niederlage von Ankara in die Gegend von Karesi zurückgezogen hatte, nahm Bursa ein, während Timur in İzmir stand. In der von Timurs Soldaten geplünderten und niedergebrannten alten Hauptstadt rief er seine Herrschaft aus und ließ in seinem Namen Münzen prägen; im Januar 1403 wurde er in Anatolien als „Herrscher der Türken“ anerkannt. Auf der Karte erscheint dieser sich entlang der asiatischen Küste des Marmarameeres erstreckende Anteil in der eigenen Farbe Îsâ Çelebis.", "fdd5eed3"]},
"OLAYLAR_EK5:1403-03-15:0":{"b": ["Timurs Abzug aus Anatolien", "93a98839"], "d": ["Timur, der die Nachricht erhielt, dass Yıldırım Bayezid in Akşehir gestorben war, hielt sein Werk in Anatolien für erledigt und wandte sich nach Osten. Zurück blieben die ihm Treue bekundenden Beyliks und die untereinander verfeindeten osmanischen Prinzen; einige Städte wie Sivas wurden in der Hand von Emiren wie dem Timur untertanen Mezid Bey belassen. Timur kehrte nie wieder nach Anatolien zurück, doch die von ihm geschaffene zersplitterte Ordnung hielt zehn Jahre.", "646cb1bc"]},
"OLAYLAR_EK5:1404-03-01:0":{"b": ["Emir Süleyman setzte nach Anatolien über: Bursa fiel in seine Hand", "9b27aa5f"], "d": ["Als Emir Süleyman von der Niederlage Îsâ Çelebis erfuhr, setzte er mit Çandarlı Ali Pascha an der Spitze eines starken Heeres nach Anatolien über und nahm Bursa ein; die Aufzeichnungen vom März 1404 zeigen, dass auch Karadeniz Ereğlisi unter seiner Verwaltung stand. Gegen Süleyman, der in kurzer Zeit sowohl Rumelien als auch den größten Teil Anatoliens beherrschte, konnte Çelebi Mehmed nicht standhalten. Auf der Karte erscheinen beide Ufer von diesem Datum bis zur erneuten Einnahme Bursas durch Çelebi Mehmed (1410) in einer Farbe, im Anteil Emir Süleymans.", "bca67f28"]},
"OLAYLAR_EK5:1405-01-01:0":{"b": ["Schlacht in der Ebene von Yenişehir – Çelebi Mehmed zog sich nach Amasya zurück", "f1568288"], "d": ["Çelebi Mehmed, der Bursa und Ankara verloren hatte, wurde in der Ebene von Yenişehir von Emir Süleyman besiegt, verlor alle seine Gewinne in Westanatolien und zog sich auf die Basis Tokat–Amasya zurück. Nach dieser Niederlage mied er die direkte Auseinandersetzung und wandte sich der Festigung seiner Autorität im Inneren Anatoliens zu. So begann die längste stille Phase des Interregnums.", "8c8a3c8c"]},
"OLAYLAR_EK5:1406-01-01:0":{"b": ["Emir Süleyman nahm Ankara von Çelebi Mehmed", "d6a2acd6"], "d": ["Das nach Timurs Abzug aus Anatolien in der Hand Çelebi Mehmeds verbliebene Ankara wurde 1406 von Emir Süleyman belagert. Der Burgkommandant Yâkub Bey hielt eine Weile stand, übergab die Burg jedoch durch eine List des Großwesirs Çandarlı Ali Pascha an Süleyman. Daraufhin verständigte sich Çelebi Mehmed mit dem Karamaniden Mehmed Bey und ging gegen Süleyman vor.", "f2a18bf9"]},
"OLAYLAR_EK5:1408-06-01:0":{"b": ["Çelebi Mehmed nahm Sivas vom Timuriden Mezid Bey zurück", "90079b0c"], "d": ["Nach der Timur-Invasion war die Verwaltung von Sivas dem Timur untertanen Mezid Bey überlassen worden. Çelebi Mehmed in Amasya entsandte seinen Kommandanten Bayezid Pascha, um die Stadt zu nehmen, und nach heftigem Widerstand fiel Sivas zum zweiten Mal in die Hand des osmanischen Herrscherhauses. Damit erreichte Mehmeds Anteil sechs Jahre nach der Schlacht von Ankara im Osten seine alte Grenze.", "22c266b9"]},
"OLAYLAR_EK5:1409-01-01:0":{"b": ["Ende der Artukiden-Dynastie: Übergabe Mardins an die Kara Koyunlu", "15b06f33"], "d": ["Die Artukiden, die seit 1106 in Mardin herrschten und den langlebigsten Zweig der Dynastie bildeten, konnten sich dem Druck der Ak Koyunlu nicht widersetzen. Melek Ahmed, der erkannte, dass er die Stadt nicht verteidigen konnte, einigte sich mit dem Kara-Koyunlu-Herrscher Kara Yûsuf und übergab ihm Mardin. Die über drei Jahrhunderte währende Artukiden-Herrschaft endete damit; Mardin und seine Umgebung wurden bis zum Übergang an die Osmanen ein Jahrhundert später zum Schauplatz des Ringens zwischen Kara Koyunlu und Ak Koyunlu.", "52e31654"]},
"OLAYLAR_EK5:1410-02-13:0":{"b": ["Schlacht von Yanbolu – Mûsâ Çelebi zog in Edirne ein", "8f978408"], "d": ["Mûsâ Çelebi, der über die Walachei nach Rumelien übergesetzt war, schlug mit walachischer und serbischer Unterstützung bei Yanbolu die Truppen Emir Süleymans vernichtend und zog in Edirne ein. Im Interregnum war Rumelien damit erstmals aus der Hand Emir Süleymans gegangen. Doch seine Herrschaft hatte keinen Bestand; vier Monate später sollte er bei Kosmidion besiegt werden und sich ins Innere des Balkans zurückziehen.", "e80e7126"]},
"OLAYLAR_EK5:1412-10-01:0":{"b": ["Schlacht von İnceğiz – Çelebi Mehmeds erste Niederlage in Rumelien", "3c35cd43"], "d": ["Çelebi Mehmed, der mit byzantinischen Schiffen nach Rumelien übergesetzt war, trat bei İnceğiz gegen Mûsâ Çelebi an; Mûsâ besiegte Mehmed mit den ihm unterstehenden siebentausend Janitscharen, und Mehmed musste nach Anatolien zurückkehren. Diese Niederlage wandte Mehmed der Strategie zu, statt direkten Kampfes die rumelischen Grenzbeys und das serbische Despotat auf seine Seite zu ziehen. Auf dieser Diplomatie wurde der Boden für den neun Monate später folgenden Sieg von Çamurlu bereitet.", "dd443a98"]},
"OLAYLAR_EK5:1415-03-01:0":{"b": ["Belagerung von Konya und Vertrag mit den Karamaniden – Hamîd-ili, Said-ili, Beyşehir, Seydişehir und Akşehir zurückgewonnen", "0996257e"], "d": ["Gegen die Karamaniden, die im Interregnum das osmanische Land angriffen und Bursa belagerten und niederbrannten, veranstaltete Çelebi Mehmed einen großen Feldzug und belagerte im Muharram 818 Konya. Der Karamanide Mehmed Bey II. musste um Frieden bitten; als Ergebnis des Vertrags wurden Hamîd-ili (Gegend von Isparta) und Said-ili wieder dem osmanischen Land angegliedert, Beyşehir, Seydişehir und Akşehir wurden zurückgegeben; auch Sivrihisar, das Timur 1402 den Karamaniden gegeben hatte, kehrte zu den Osmanen zurück. Dieser Feldzug, mit dem die durch die Schlacht von Ankara zerfallene Einheit Anatoliens wieder zusammenzuwachsen begann, gehört zu den konkreten Begründungen dafür, dass Çelebi Mehmed als „zweiter Gründer“ gilt.", "952c9f73"]},
"OLAYLAR_EK5:1415-06-01:0":{"b": ["Die Einnahme von İzmir von Aydınoğlu Cüneyd Bey", "2377ca51"], "d": ["İzmir, das Zentrum Aydınoğlu Cüneyd Beys, der während des Interregnums ständig zwischen den Prinzen die Seiten wechselte, wurde nach zehntägiger Belagerung von Çelebi Mehmed genommen; Cüneyd wurde begnadigt und als Sandschakbey nach Nikopolis geschickt. Die Stadt, die Timur 1402 den Aydınoğulları zurückgegeben hatte, kehrte so nach dreizehn Jahren zu den Osmanen zurück. Cüneyd sollte die Stadt 1422 erneut einnehmen, die Angelegenheit wurde erst 1424–1426 von Murad II. beendet.", "41fefe61"]},
"OLAYLAR_EK5:1416-01-01:0":{"b": ["Hinrichtung Torlak Kemals – Saruhan endgültig osmanisch", "8a09dbf1"], "d": ["Torlak Kemal, der den westanatolischen Zweig der Bewegung des Scheichs Bedreddin anführte, wurde in der Gegend von Manisa besiegt und hingerichtet. Von diesem Datum an kam die Region Saruhan endgültig unter osmanische Kontrolle, und das 1402 von Timur wiederbelebte Beylik verschwand aus der Geschichte. Die letzten politischen Überreste des Interregnums in Westanatolien wurden damit beseitigt.", "43bec619"]},
"OLAYLAR_EK5:1417-01-01:0":{"b": ["Eroberung von Avlona, Berat und Kanina", "1e1949b8"], "d": ["Die Osmanen nahmen 1417 das Avlona an der Adriaküste zusammen mit der Stadt Berat im Binnenland und der Burg Kanina in Besitz. Ein Jahr später scheiterte Venedigs Versuch, die Stadt zurückzuerobern, und durch die Einrichtung einer Sandschak-Organisation wurde die osmanische Autorität dauerhaft. Die Einnahme Avlonas machte die Osmanen erstmals zum unmittelbaren Hafenbesitzer an der Adria und verschaffte ihnen gegenüber Italien ein Sprungbrett über das Meer.", "508b9927"]},
"OLAYLAR_EK5:1419-01-01:0":{"b": ["Rückgewinnung Zentralanatoliens: Kayseri und Kırşehir", "204eacb3"], "d": ["Die im Interregnum in die Hand der Karamaniden gelangten zentralanatolischen Städte kehrten bei Çelebi Mehmeds Feldzügen zur Wiederherstellung des Staates unter osmanische Verwaltung zurück. Mit der Angliederung von Kayseri und Kırşehir wurde das in der Schlacht von Ankara verlorene Becken des Kızılırmak weitgehend zurückgewonnen. Dieser Vormarsch ist die Fortsetzung der mit der Belagerung von Konya vier Jahre zuvor begonnenen Ostpolitik.", "c663fc08"]},
"OLAYLAR_EK5:1421-06-25:0":{"b": ["Tod Mehmeds I. und Thronbesteigung Murads II.", "98acac77"], "d": ["Mehmed I., der die Fetret-Zeit beendet und das osmanische Land wieder in einer Hand vereinigt hatte, starb am 25. Juni 1421 in Adrianopel, und sein Sohn Murad bestieg in Bursa den Thron. Nach der vor seinem Tod mit Byzanz getroffenen Regelung sollten die jüngeren Söhne als Geiseln zum Kaiser geschickt werden, und der Kaiser sollte den von ihm festgehaltenen Thronprätendenten Mustafa Çelebi nicht freilassen; Murad II. weigerte sich, seine Brüder zum Kaiser zu schicken.", "c8093fa8"]},
"OLAYLAR_EK5:1423-01-01:0":{"b": ["Endgültige Beseitigung der Tekeoğulları: Einnahme von Antalya", "e65565b2"], "d": ["Das nach der Schlacht von Ankara durch Timurs Wiederbelebung neu gegründete Beylik der Tekeoğulları endete, als die osmanischen Truppen unter dem Kommando von Hamza Bey Antalya belagerten; Osman Çelebi, der letzte bedeutende Mann des Beylik, wurde beseitigt. Damit wurde das Land Teke an der Mittelmeerküste nach einundzwanzigjähriger Trennung endgültig dem Osmanischen Reich angegliedert. Das Beylik herrschte als von den Hamîdoğulları abgespaltener Zweig seit 1321 in Antalya.", "6b81398d"]},
"OLAYLAR_EK5:1423-05-01:0":{"b": ["Turahan Beys Morea-Feldzug und Zerstörung der Hexamilion-Mauer", "c6c2706d"], "d": ["Als Byzanz den rivalisierenden Thronanwärter Mustafa Çelebi unterstützte, entsandte Murad II. Turahan Bey gegen die Morea. Turahan Bey riss die den Isthmus von Korinth von einem Ende zum anderen sperrende Hexamilion-Mauer nieder, drang in die Halbinsel ein und richtete große Zerstörung an. Der Friede kam unter den Bedingungen zustande, dass die Mauer nie wieder errichtet und eine jährliche Steuer gezahlt werde; das Despotat Morea wurde so militärisch schutzlos gemacht, und der Boden für die endgültige Eroberung von 1460 wurde siebenunddreißig Jahre im Voraus bereitet.", "3482eb23"]},
"OLAYLAR_EK5:1424-01-01:0":{"b": ["Die Athos-Klöster traten unter osmanischen Schutz", "562de5ea"], "d": ["In den Jahren, in denen Thessaloniki belagert wurde, wandte sich die Klosterrepublik Athos auf dem östlichen Finger der Chalkidike an Murad II., bat um Schutz und erkannte die osmanische Herrschaft an. Besitz- und Gebetsrechte der Mönche wurden garantiert; die Klöster blieben gegen Steuerzahlung in ihren inneren Angelegenheiten frei. Diese Ordnung wurde zum langlebigsten Beispiel des Schutzverhältnisses der Osmanen zu orthodoxen Institutionen und währte fünf Jahrhunderte.", "6be1a9f2"]},
"OLAYLAR_EK5:1427-01-01:0":{"b": ["Annexion des Beylik der Tâceddinoğulları: Niksar", "370ffd47"], "d": ["Auf den Druck des Beylerbey von Amasya, Yörgüç Pascha, hin übergab Tâceddinoğlu Hüsâmeddin Hasan Bey im Jahr 830 (1427) die Schlüssel seines Landes mit dem Zentrum Niksar; ihm wurde in Rumelien ein Sandschak gegeben. Damit endete das in der zweiten Hälfte des 14. Jahrhunderts gegründete Beylik, dessen Grenzen zeitweise bis Kelkit, Amasya, Samsun, Ordu und Giresun reichten. Im selben Jahr wurden auch die Gebiete der Hacıemiroğulları registriert (tahrir) und dem Sandschak Canik angegliedert; die Zeit der Beyliks im mittleren Schwarzmeerraum war beendet.", "06fa8222"]},
"OLAYLAR_EK5:1427-01-01:1":{"b": ["Überlassung Belgrads an Ungarn – Vertrag von Tata", "62481183"], "d": ["Nach dem Tod des serbischen Despoten Stefan Lazarević wurde die Festung Belgrad gemäß dem zwischen dem ungarischen König Sigismund und dem Erben Đurađ Branković geschlossenen Vertrag von Tata an Ungarn übergeben. Die Festung, die am Zusammenfluss von Donau und Save steht und bis dahin in der Hand des serbischen Despotats gewesen war, war für das Osmanische Reich das Schloss des Tores nach Mitteleuropa. Diese Übergabe machte Belgrad hundert Jahre lang zum härtesten Hindernis vor dem osmanischen Vormarsch: Die Belagerungen von 1440 und 1456 sollten scheitern, die Festung erst 1521 fallen.", "ee1ad2d8"]},
"OLAYLAR_EK5:1432-01-01:0":{"b": ["Mardin ging von der Kara-Koyunlu-Garnison an den Ak-Koyunlu-Herrscher Karayülük Osman Bey über", "d82bc97f"], "d": ["Das 1409 von Kara Yûsuf eingenommene Mardin wurde von den Kara Koyunlu durch Statthalter verwaltet; der als Wachposten belassene Emir Nâsır übergab die Stadt 835 (1432) an den Ak-Koyunlu-Herrscher Karayülük Osman Bey. Die Ak-Koyunlu-Herrschaft dauerte bis Anfang des 16. Jahrhunderts.", "407382cb"]},
"OLAYLAR_EK5:1446-05-05:0":{"b": ["Vorfall von Buçuktepe – erster Janitscharenaufstand und Rückkehr Murads II. auf den Thron", "6388dda1"], "d": ["Der in Edirne ausgebrochene Vorfall von Buçuktepe, der erste in der Geschichte bekannte Janitscharenaufstand, begann mit der Forderung nach einer Erhöhung des Soldes (ulûfe) um einen halben Akçe und endete mit der Absetzung des jungen Mehmed II. Murad II. brach am 8. Safar 850 eilig aus Manisa auf und begann seine zweite Herrschaft. Das Ereignis war das erste Zeichen dafür, dass das Kapıkulu-Korps zu einer Macht geworden war, die beim Thron ein Wort mitzureden hatte, und prägte die lebenslange Vorsicht des Eroberers gegenüber den Janitscharen.", "c03ef4f8"]},
"OLAYLAR_EK5:1449-01-01:0":{"b": ["Angliederung der Küste von Epirus: Arta und Preveza", "796f7ecf"], "d": ["Neunzehn Jahre nach der Übergabe von Ioannina 1430 kamen auch Arta und Preveza im Küstenbereich des Despotats Epirus unter osmanische Verwaltung. Damit wurde der zum Ionischen Meer geöffnete Ambrakische Golf unter Kontrolle gebracht und die Seeverbindung von Ioannina vervollständigt. Preveza ist der Schlüsselpunkt der Bucht, die neunzig Jahre später dem in die Geschichte eingehenden Sieg Barbarossas ihren Namen geben sollte.", "b5e95ae5"]},
"OLAYLAR_EK5:1451-02-18:0":{"b": ["Tod Murads II. und zweite Thronbesteigung Mehmeds II.", "8f8256ad"], "d": ["Murad II., der nach der Hochzeit seines Sohnes erkrankte, starb am 1. Muharram 855 (3. Februar 1451) in Edirne. Der neunzehnjährige Mehmed II. bestieg am 16. Muharram 855 (18. Februar 1451) zum zweiten Mal den osmanischen Thron – diesmal dauerhaft. Die Rückkehr des fünf Jahre zuvor bei Buçuktepe vom Thron gestoßenen jungen Herrschers ist der Beginn der Herrschaft, die zwei Jahre später mit der Eroberung Konstantinopels gekrönt werden und das Osmanische Beylik in ein Weltreich verwandeln sollte.", "5363b0f7"]},
"OLAYLAR_EK5:1454-07-14:0":{"b": ["Erste Belagerung von Kaffa durch osmanisch-krimische Streitkräfte", "e346d163"], "d": ["Der Krim-Khan Hacı Giray, der sich im Juni 1454 mit Sultan Mehmed dem Eroberer verständigt hatte, belagerte Kaffa mit 7000 Reitern von Land aus; auch eine osmanische Flotte von fünfzig bis sechzig Galeeren bezog vor der Küste Stellung. Das genuesische Kaffa ließ die Belagerung gegen Tributzahlung aufheben, und die endgültige Eroberung blieb einundzwanzig Jahre später, 1475, vorbehalten. Diese erste gemeinsame Unternehmung war das erste Beispiel der osmanisch-krimischen militärischen Zusammenarbeit, die bei der endgültigen Eroberung Kaffas wiederholt werden sollte.", "bf590b3e"]},
"OLAYLAR_EK5:1455-01-01:0":{"b": ["Einnahme der nördlichen Ägäisinseln: Tenedos, Imbros und Thasos", "76575895"], "d": ["Unmittelbar nach der Eroberung Konstantinopels wandte sich Sultan Mehmed der Eroberer den Inseln an der ägäischen Mündung der Dardanellen zu, um den Seeweg der neuen Hauptstadt zu sichern; Tenedos und Imbros wurden Byzanz, Thasos der Familie Gattilusio genuesischer Herkunft abgenommen. Diese Inseln, die beide Seiten der Meerenge sperrten, wurden fortan das erste Glied der Versorgungs- und Verteidigungslinie Istanbuls. Durch Eingreifen der päpstlichen und der venezianischen Flotte wechselte die Herrschaft eine Zeit lang hin und her und wurde erst 1459 endgültig.", "9a34e8f0"]},
"OLAYLAR_EK5:1455-06-01:0":{"b": ["Eroberung des Kosovo: Einnahme von Priština und Novi Pazar", "d7ed2345"], "d": ["Das gegen das Serbische Despotat vorrückende osmanische Heer nahm Priština in der Kosovo-Ebene und Novi Pazar, das Zentrum der Region Raszien, ein; im selben Feldzug wurde auch das für seine Silberbergwerke berühmte Novo Brdo genommen. Damit wurde die südliche Hälfte Serbiens unmittelbar an die osmanische Verwaltung gebunden und das Despotat in Smederevo von seinem Kernland abgeschnitten. Diese Eroberung war der entscheidende Schritt auf dem Weg zur vollständigen Annexion Serbiens vier Jahre später.", "b2c7fcce"]},
"OLAYLAR_EK5:1456-01-01:0":{"b": ["İpek (Peć) kam unter osmanische Verwaltung – eines der Zentren des Sandschaks Dukakin", "19511588"], "d": ["Unmittelbar nach dem Serbien-Feldzug Sultan Mehmeds des Eroberers von 1455 ging İpek, das Zentrum des serbischen Patriarchats, in osmanische Verwaltung über; in osmanischen Quellen gibt es zu diesem Übergang keine Aufzeichnung. Der Ort wurde mit der Zeit zu einem kleinen muslimischen Städtchen und eine der Residenzen des Sandschakbeys im Sandschak Dukakin.", "4d7160f6"]},
"OLAYLAR_EK5:1456-01-24:0":{"b": ["Eroberung von Enez und Semadirek – Vollendung der westthrakischen Küste", "106e723b"], "d": ["Enez an der Mündung der Maritza ins Meer wurde der Familie Gattilusio genuesischer Herkunft abgenommen, die es seit achtzig Jahren hielt; auch die zu ihm gehörende Insel Samothrake wurde im selben Feldzug genommen. Mit dem Fall von Enez wurde der westthrakische Küstenstreifen von Thessaloniki bis Gelibolu zu lückenlosem osmanischem Land. In der Hand der Familie Gattilusio blieb nur Lesbos; auch dieses sollte sechs Jahre später genommen werden.", "327297a0"]},
"OLAYLAR_EK5:1456-07-22:0":{"b": ["Scheitern der Belagerung von Belgrad", "3d53a604"], "d": ["Sultan Mehmed der Eroberer belagerte nach der Eroberung Konstantinopels Belgrad, das als Schloss Mitteleuropas galt; doch die von Johann Hunyadi über die Donau herangeführte Verstärkung und die vom Kreuzzugsprediger Johannes Capistranus gesammelten Freiwilligen verhinderten den Fall der Festung. Der Sultan musste trotz persönlicher Tapferkeit vor der Belagerung verwundet abziehen. Dieses Scheitern sollte die ungarische Grenze fünfundsechzig Jahre lang dem osmanischen Vormarsch verschließen; Belgrad konnte erst 1521 von Süleyman dem Gesetzgeber genommen werden.", "036836cb"]},
"OLAYLAR_EK5:1458-05-01:0":{"b": ["Eroberung der nördlichen Morea: Balyabadra (Patras)", "c08a8509"], "d": ["Die Truppen Sultan Mehmeds des Eroberers, die sich in denselben Jahren wie die Annexion Serbiens gegen das Despotat Morea wandten, nahmen Balyabadra im Nordwesten der Halbinsel ein. Dieser Hafen, der die Mündung des Golfs von Korinth hält, ist der Riegel für den Zugang zur Morea zu Lande; seine Einnahme bereitete den Boden für die endgültige Eroberung zwei Jahre später. Die Stadt war die letzte große Anlegestelle, über die die byzantinischen Despoten Verbindung zur lateinischen Welt hielten.", "4490cc14"]},
"OLAYLAR_EK5:1459-06-20:0":{"b": ["Einnahme der westlichen Schwarzmeerküste: Amasra", "f43608fc"], "d": ["Amasra, die befestigte genuesische Kolonie am Westlichen Schwarzen Meer, ergab sich unter dem gemeinsamen Druck von Flotte und Landstreitkräften Sultan Mehmeds des Eroberers ohne Widerstand. Dieser Hafen an der Küste von Bartın–Zonguldak stand als lateinische Enklave zwischen den Candaroğulları und dem osmanischen Land; mit seiner Einnahme wurde die Küste zusammenhängend. Der Fall Amasras ist der erste Schritt des großen Schwarzmeer-Feldzugs, der zwei Jahre später (1461) gegen Sinope und Trapezunt gerichtet sein sollte.", "b8b9f4f0"]},
"OLAYLAR_EK5:1462-09-17:0":{"b": ["Eroberung der Insel Lesbos", "fe17aeba"], "d": ["Das osmanische Heer unter dem Kommando Sultan Mehmeds des Eroberers nahm Lesbos im Dhu l-Hiddscha 866 nach kurzer, aber heftiger Belagerung der Familie Gattilusio genuesischer Herkunft ab und annektierte es. Der Fall der größten Insel der nördlichen Ägäis tilgte auch den letzten bedeutenden Stützpunkt der Genuesen in der Region. Die Insel sollte dank ihrer Nähe zur anatolischen Küste von da an der osmanischen Flotte als vorgeschobener Posten dienen und zugleich als Ort, an dem die Brüder Barbarossa aufwuchsen, in die Seefahrtsgeschichte eingehen.", "453088e2"]},
"OLAYLAR_EK5:1463-07-28:0":{"b": ["Beginn des sechzehnjährigen Osmanisch-Venezianischen Krieges", "563ddb68"], "d": ["Die Venezianer begannen den Krieg 1463 im Bündnis mit den Verwaltern von Karaman und Ak Koyunlu, um den osmanischen Vormarsch in der Morea und der Ägäis aufzuhalten. Diese Einkreisungsstrategie – im Osten Uzun Hasan, im Westen Venedig und dazwischen Karaman – zwang den Eroberer, gleichzeitig an mehreren Fronten zu kämpfen. Das sechzehn Jahre währende Ringen sollte von Otlukbeli bis zu den Albanien-Feldzügen alle großen Unternehmungen der Zeit umfassen und erst mit dem Vertrag von Istanbul 1479 enden.", "e70079e9"]},
"OLAYLAR_EK5:1466-01-01:0":{"b": ["Eroberung des größten Teils der Herzegowina: Trebinje und Mostar", "f54c0100"], "d": ["Das Land des Herzogs der Herzegowina, Stjepan Vukčić-Kosača, der von Bosnien getrennt eine eigene Verwaltung errichtet hatte, ging drei Jahre nach dem Untergang des Königreichs Bosnien weitgehend unter osmanische Verwaltung: Im Süden wurde Trebinje 1466 „zusammen mit fast der gesamten Region Herzegowina“ genommen. Mostar, das um die zwei kleinen Burgen der Brücke über die Neretva entstand, muss kurz vor der Eroberung des Zentrums der Herzegowina, Blagaj, in den Jahren 1466–1468 genommen worden sein; im Bosnischen Icmal-Tahrir von 1468–1469 ist es unter dem Namen „Köprülü Hisar“ verzeichnet. Mit den restlichen Burgen des Herzogtums wurde die Eroberung der Herzegowina 1483 abgeschlossen.", "a7f22be7"]},
"OLAYLAR_EK5:1466-06-01:0":{"b": ["Zweiter Albanien-Feldzug – Mehmeds des Eroberers persönlicher Marsch gegen Skanderbeg", "9cdd2bfa"], "d": ["Um den mehr als ein Vierteljahrhundert währenden Widerstand Skanderbegs zu brechen, veranstaltete Sultan Mehmed der Eroberer in den Jahren 1466–1467 große Feldzüge unter seinem persönlichen Kommando. Das osmanische Heer belagerte Akçahisar und errichtete zur Kontrolle der Region die Burg Elbasan. Der Feldzug brach dem albanischen Widerstand zwar das Rückgrat, vermochte die Burg aber nicht zu Fall zu bringen; die vollständige Unterwerfung der Region sollte bis zu zehn Jahre nach Skanderbegs Tod dauern.", "00e75aca"]},
"OLAYLAR_EK5:1467-11-10:0":{"b": ["Zusammenbruch des Staates der Kara Koyunlu: Tötung Cihan Şahs", "30bc6358"], "d": ["Der Kara-Koyunlu-Herrscher Cihan Şah, der auf dem Rückweg von einem Feldzug gegen Uzun Hasan wegen des hereinbrechenden Winters überfallen wurde, wurde auf der Flucht zwischen Bingöl und Kiğı getötet. Von diesem Schlag erholte sich der Staat nicht mehr; der letzte Herrscher Hasan Ali wurde 1469 von Uğurlu Mehmed, dem Sohn Uzun Hasans, gefangen genommen und getötet. Die fast ein Jahrhundert in Ostanatolien, Aserbaidschan und im Irak währende Herrschaft der Kara Koyunlu ging so an die Ak Koyunlu über.", "5a5288e7"]},
"OLAYLAR_EK5:1468-01-17:0":{"b": ["Tod Skanderbegs – Erlöschen des albanischen Widerstands", "9158c35f"], "d": ["Skanderbeg, der am osmanischen Hof aufgewachsen war, 1444 nach der Niederlage von Lezhë revoltierte und über ein Vierteljahrhundert in Albanien Widerstand leistete, starb in Leş, wohin er sich geflüchtet hatte. Dieser Widerstand, der die osmanischen Heere zu Zeiten Murads II. und des Eroberers wiederholt aufgehalten hatte, verlor mit seinem Tod die zentrale Führung. Mit dem Zusammenbruch der von Papsttum und Venedig genährten albanischen Front nahmen die Osmanen binnen zehn Jahren Akçahisar und Skutari und gliederten die Region endgültig ihrem Land an.", "5c7cffad"]},
"OLAYLAR_EK5:1474-01-01:0":{"b": ["Osmanische Verwaltung in Kayseri errichtet: Gedik Ahmed Pascha beendete die Karamanoğulları", "33cf35fc"], "d": ["Als Gedik Ahmed Pascha 1474 die Karamanoğulları beendete, kam Kayseri unter osmanische Verwaltung; die Stadt war im Laufe des 15. Jahrhunderts zwischen den Dulkadıroğulları, den Ramazanoğulları und den Karamanoğulları von Hand zu Hand gegangen. Unter osmanischer Verwaltung wurde Kayseri Sandschakzentrum des Beylerbeyliks Karaman.", "5d1db169"]},
"OLAYLAR_EK5:1475-01-01:0":{"b": ["Samos aufgegeben: genuesischer (Maona-)Besitz endete", "5bdc380c"], "d": ["Nach dem TDV wurde die Insel nach 1475 aufgegeben; 1479 eroberte Mehmed der Eroberer die Insel und ließ eine Festung bauen.", "4e48c423"]},
"OLAYLAR_EK5:1475-01-10:0":{"b": ["Niederlage von Racova (Vaslui) in der Moldau", "a1a74bf7"], "d": ["Der moldauische Woiwode Stefan der Große lockte die osmanischen Truppen unter dem Kommando des Beylerbey von Rumelien, Hadım Süleyman Pascha, in sumpfiges Gelände und fügte ihnen eine schwere Niederlage zu. Diese Niederlage, eine der schwersten Landniederlagen der Zeit des Eroberers, fand in Europa großen Widerhall und trug Stefan Ruhm in der Kreuzfahrerwelt ein. Der Sultan sollte im folgenden Jahr persönlich zu einem Vergeltungsfeldzug aufbrechen.", "3247c9fe"]},
"OLAYLAR_EK5:1476-07-26:0":{"b": ["Sieg bei Akdere (Valea Albă) – Moldau-Feldzug", "45a66791"], "d": ["Sultan Mehmed der Eroberer, der persönlich zu Felde zog, um die Niederlage von Racova des Vorjahres zu rächen, brachte dem osmanischen Heer zusammen mit den moldauischen Truppen bei Akdere eine große Niederlage bei und zog in Suceava, das Zentrum des Fürstentums, ein. Die Burgen konnten jedoch nicht genommen werden; wegen Versorgungsschwierigkeiten, der unter den Janitscharen ausgebrochenen Pest und ungarischer Vorbereitungen musste sich das Heer zurückziehen. Die endgültige Bindung der Moldau sollte erst in den folgenden Jahren und mit der Einnahme von Kili und Akkirman 1484 erreicht werden.", "27b9dd1c"]},
"OLAYLAR_EK5:1478-06-15:0":{"b": ["Eroberung von Akçahisar (Kruja) und Vollendung der Eroberung Albaniens", "559a79b4"], "d": ["Zehn Jahre nach dem Tod Skanderbegs wurde mit der Einnahme von Akçahisar, Drivasto, Leş und Jabyak 1478 die Eroberung Albaniens weitgehend abgeschlossen. Der Fall der Burg Kruja, die jahrelang den osmanischen Heeren widerstanden hatte und das Symbol des Skanderbeg-Widerstands war, bedeutete das Ende des venezianisch-albanischen Bündnisses in der Region. Das übrig gebliebene Skutari sollte dagegen durch den im folgenden Jahr unterzeichneten Vertrag von Istanbul den Osmanen überlassen werden.", "4f6059e8"]},
"OLAYLAR_EK5:1479-01-01:0":{"b": ["Angliederung der Halbinsel Taman", "4ef917b8"], "d": ["Nach der Einnahme von Kaffa und Kertsch 1475 eroberte die von Sultan Mehmed dem Eroberer an die kaukasische Küste entsandte Flotte zusammen mit Anapa und Kopa das genuesische Matrega (Tamatarhan) auf der Halbinsel Taman. Damit wurden beide Seiten der Meerenge unter Kontrolle gebracht und der Zugang zum Asowschen Meer vollständig kontrollierbar. Taman wurde als Tor zum Nordkaukasus dem Sandschak Kaffa angegliedert.", "74a0de9f"]},
"OLAYLAR_EK5:1479-01-01:1":{"b": ["Übergang von Samos unter osmanische Verwaltung (Mehmed der Eroberer)", "c877bc14"], "d": ["Mehmed der Eroberer eroberte Samos, ließ eine Festung bauen und ordnete die Erfassung neu; die Festung wurde 1483 von Bayezid II. aus politischen Gründen geschleift.", "2965b1d9"]},
"OLAYLAR_EK5:1480-07-28:0":{"b": ["Scheitern der Belagerung von Rhodos", "35a85c28"], "d": ["Die auf Befehl Sultan Mehmeds des Eroberers unter dem Kommando von Mesih Pascha stehende Flotte von 160 Schiffen belagerte Rhodos im Frühjahr 885 (1480), und die Insel blieb drei Monate lang blockiert. Die Johanniter unter der Führung des Großmeisters Pierre d’Aubusson leisteten trotz schwerer Verluste heftigen Widerstand; nachdem auch der letzte große Sturm am 20. Dschumada l-ula 885 abgewehrt worden war, zog die Flotte am 3. August ab. Nach diesem Scheitern wurden die Mauern der Stadt von Grund auf erneuert und zur stärksten Festung Europas gemacht; die Insel konnte erst 1522 von Süleyman dem Gesetzgeber genommen werden.", "23334bd0"]},
"OLAYLAR_EK5:1481-01-01:0":{"b": ["Nikarya (Ikaria) kam unter die Verwaltung der Johanniterritter von Rhodos", "5cbc2669"], "d": ["Nikarya zwischen Samos und Chios stand von 1481 bis 1521 unter der Verwaltung der Johanniterritter von Rhodos.", "9d387479"]},
"OLAYLAR_EK5:1481-06-22:0":{"b": ["Schlacht von Yenişehir – Niederlage Cem Sultans", "c35abee2"], "d": ["Die beiden Brüder, die nach dem Tod des Eroberers um den Thron aktiv wurden, standen sich in der Ebene von Yenişehir gegenüber, und Cem Sultan erlitt eine endgültige Niederlage. Der Prinz, der achtzehn Tage in Bursa herrschte und in seinem Namen die Chutba verlesen ließ, musste sich nach der Niederlage zunächst nach Konya, von dort auf mamlukisches Gebiet flüchten. Yenişehir löste die langwierigste dynastische Krise der osmanischen Geschichte aus: Die Cem-Frage sollte die osmanische Außenpolitik gegenüber Europa vierzehn Jahre lang lähmen.", "9d30204e"]},
"OLAYLAR_EK5:1482-01-01:0":{"b": ["Annexion der Herzegowina", "bf247891"], "d": ["Das Land des nach der Eroberung Bosniens 1463 bestehen gebliebenen Herzogtums Herzegowina ging stufenweise in osmanische Verwaltung über: Trebinje und Mostar waren 1466 genommen, der Sandschak Herzegowina 1470 gebildet worden, und die letzten Gebiete des Herzogtums an der Adriaküste wurden zusammen mit Herceg Novi Anfang 1482 erobert und dem Sandschak angegliedert. Damit wurde die hinter der Adria gelegene Bergregion vollständig osmanisch, und Bosnien und die Herzegowina wurden zu einer einzigen Verwaltungsgeografie. Der in den osmanischen Hof eingetretene Sohn des letzten Herzogs ist Hersekzâde Ahmed Pascha, der später bis zum Großwesir aufsteigen sollte.", "0522e47f"]},
"OLAYLAR_EK5:1482-01-01:1":{"b": ["Überlassung von Zakynthos (Zaklise) an Venedig gegen jährlichen Tribut", "268a691a"], "d": ["Zakynthos, eine der am Ende der Zeit Mehmeds des Eroberers der Familie Tocco abgenommenen Ionischen Inseln, wurde von dem mit der Angelegenheit des Prinzen Cem beschäftigten neuen Sultan, der im Westen Ruhe suchte, an Venedig überlassen. Die Insel wurde einer venezianischen Verwaltung übergeben, die die osmanische Oberhoheit anerkannte und einen jährlichen Tribut von fünfhundert Dukaten zahlte. So blieb die unmittelbare osmanische Verwaltung im Ionischen Meer nur noch auf Ayamavra (Leukas).", "0773761c"]},
"OLAYLAR_EK5:1482-07-29:0":{"b": ["Cem Sultans Zuflucht auf Rhodos", "2228d6da"], "d": ["Cem Sultan, dessen Versuch, Konya zu belagern, ebenfalls erfolglos blieb, floh mit etwa dreißig Männern aus Anatolien, erreichte Rhodos und wurde von den Johannitern feierlich empfangen. Doch der Gastaufenthalt wandelte sich rasch in Gefangenschaft; der Prinz wurde zunächst an Frankreich, dann an das Papsttum übergeben und wurde zu einem Trumpf in der Hand der europäischen Politik. Bayezid II. musste als Gegenleistung für die Festhaltung seines Bruders jährliche Zahlungen leisten, und die militärischen Vorstöße der Osmanen gegen den Westen wurden bis zu Cems Tod ausgesetzt.", "05ca0dd6"]},
"OLAYLAR_EK5:1485-01-01:0":{"b": ["Beginn des Osmanisch-Mamlukischen Krieges (Front der Çukurova)", "3fe3f0c7"], "d": ["Der Wettstreit um den Einfluss auf die Dulkadıroğulları und die Feindschaft, die die Zuflucht Cem Sultans auf mamlukischem Gebiet hinterlassen hatte, lösten 1485 einen sechs Jahre währenden Krieg zwischen den beiden sunnitischen Großmächten aus. In den Gefechten um Adana und Tarsus in der Çukurova konnte keine Seite der anderen überlegen werden; die osmanischen Heere erlitten mehrere schwere Schläge. Dieser Krieg ist die erste Phase des Bruchs in den osmanisch-mamlukischen Beziehungen und die Eröffnung des Prozesses, der dreißig Jahre später mit Yavuz’ Feldzügen von Mardsch Dabiq und Raydaniyya enden sollte.", "08141630"]},
"OLAYLAR_EK5:1491-05-01:0":{"b": ["Osmanisch-mamlukischer Friede – Vermittlung von Tunis", "60dd6719"], "d": ["Im 1485 begonnenen osmanisch-mamlukischen Krieg konnten die Parteien keinen entscheidenden Sieg erringen; durch Vermittlung des Herrschers von Tunis, Osman Hafsî, wurde 1491 eine Einigung erzielt. Der Vertrag stellte die Grenzen weitgehend auf den Vorkriegszustand zurück, und die Auseinandersetzung zwischen den beiden islamischen Staaten wurde um eine Generation vertagt. Das sechs Jahre währende zermürbende Ringen gehört zu den Hauptgründen für Bayezids II. vorsichtige Außenpolitik und dafür, dass er statt einer Hinwendung nach Osten innere Regelungen in den Vordergrund stellte.", "406d3b78"]},
"OLAYLAR_EK5:1492-08-01:0":{"b": ["Aufnahme der aus Spanien vertriebenen sephardischen Juden im Osmanischen Reich", "5c2b5c24"], "d": ["Nach dem Fall Granadas flüchtete ein Teil der vor der Verfolgung durch die Inquisition aus Spanien fliehenden Juden auf osmanisches Gebiet und wurde in verschiedenen Städten angesiedelt. Unter osmanischer Herrschaft gelangten diese sephardischen Gemeinden zu einer bis dahin nie gesehenen Freiheit: sich anzusiedeln, wo sie wollten, ihren Glauben zu leben, Bildungseinrichtungen zu eröffnen und neue Synagogen zu bauen. Diese Migration, die mit ihrem Wissen über Buchdruck, Medizin und Finanzen das Wirtschaftsleben Thessalonikis und Istanbuls veränderte, wurde zum in Europa am meisten besprochenen Beispiel der osmanischen Toleranzordnung.", "b5b4a53b"]},
"OLAYLAR_EK5:1495-02-25:0":{"b": ["Tod Cem Sultans – Ende der vierzehnjährigen Geiselschaft", "f6588b70"], "d": ["Cem Sultan, der vom Papsttum an König Karl VIII. von Frankreich übergeben worden war, starb, nachdem er am 27. Januar 1495 aus Rom aufgebrochen war, an einem Castel Capuana genannten Ort; die Quellen vermerken, dass er von päpstlichen Kreisen vergiftet worden sein könnte. Der Tod des Prinzen, der vierzehn Jahre lang in der Hand der europäischen Staaten als Drohkarte gegen die Osmanen gehalten worden war, machte Bayezid II. endlich die Hand frei. Tatsächlich sollte der Sultan danach Venedig den Krieg erklären und seine Flotte zu ihrem ersten großen Sieg führen.", "8f2579d5"]},
"OLAYLAR_EK5:1499-08-28:0":{"b": ["Seesieg bei Sapienza (Zonchio) – erster großer Flottenerfolg im Mittelmeer", "9754aaef"], "d": ["Bayezid II., der mit dem Ende der Cem-Frage freie Hand fand, erklärte 1499 Venedig den Krieg; die osmanische Flotte besiegte vor Sapienza (Zonchio) die venezianische Flotte und errang im Mittelmeer ihren ersten großen Seesieg. Mit diesem Sieg tat die Flotte kund, dass sie Venedig nun auch zur See entgegentreten konnte.", "5fa6989c"]},
"OLAYLAR_EK5:1500-12-24:0":{"b": ["Verlust von Kefalonia und Ithaka", "60f0f687"], "d": ["Venedig, durch die Einnahme von Modon und Koron erschüttert, ging im Bündnis mit Spanien zum Gegenangriff über und belagerte Kefalonia, das seit 1479 in osmanischer Hand war. Nach siebenundvierzigtägigem Widerstand fiel die Festung, die Insel ging zusammen mit Ithaka an Venedig über und kehrte dreihundert Jahre lang nicht unter osmanische Verwaltung zurück. Dieser Verlust schuf ein Gleichgewicht, in dem das auf der Morea Gewonnene im Ionischen Meer zurückgegeben wurde.", "a61731e0"]},
"OLAYLAR_EK5:1502-03-01:0":{"b": ["Untergang des Khanats der Goldenen Horde und Aufstieg der Krim", "0d1dc515"], "d": ["Der letzte Herrscher, Şeyh Ahmed Han (1481–1502), konnte sein Land nicht aus der Krise retten, in die es geraten war, und das Khanat der Goldenen Horde verschwand 1502 durch den Schlag des Krim-Khans Mengli Giray aus der Geschichte. Infolge der Thronstreitigkeiten und der Zersplitterung entstanden auf dem Gebiet der früheren Goldenen Horde die Khanate Krim, Kasan, Nogaier, Astrachan und Sibirien. Dieser Triumph der unter osmanischem Schutz stehenden Krim machte den osmanischen Einfluss nördlich des Schwarzen Meeres unbestreitbar, während das in der Region entstandene Vakuum im folgenden Jahrhundert von Moskau gefüllt werden sollte.", "9314f239"]},
"OLAYLAR_EK5:1502-12-14:0":{"b": ["Ende des Osmanisch-Venezianischen Krieges und Friede", "125b1526"], "d": ["Der 1499 begonnene Krieg, der Venedig durch Sapienza, Lepanto sowie den Verlust von Modon und Koron erschütterte, endete 1502 mit einem Frieden. Venedig verlor seine wichtigsten Stützpunkte in der Morea und musste im Gegenzug für die Bewahrung seiner Handelsprivilegien im östlichen Mittelmeer die osmanische Überlegenheit anerkennen. Bayezids II. als vorsichtig geltende Herrschaft hatte die Osmanen mit diesem Krieg erstmals in die Stellung einer ernstzunehmenden Seemacht im Mittelmeer erhoben.", "3d102f53"]},
"OLAYLAR_EK5:1511-07-02:0":{"b": ["Şahkulu-Aufstand – kizilbaschische Erhebung von der Gegend Teke bis Sivas", "3beadca7"], "d": ["Şahkulu Baba Tekeli, der unter dem Einfluss der safawidischen Propaganda in Anatolien 1510 seinen Aufstand offen erklärt hatte, hatte im März 1511 den Basar von Antalya überfallen und im April in der Gegend von Kütahya osmanische Truppen besiegt. Im letzten Gefecht mit dem Großwesir Hadım Ali Pascha bei Sivas erlitten beide Seiten schwere Verluste; sowohl der Großwesir als auch der Anführer des Aufstands kamen ums Leben. Diese Erhebung, die die Autorität des Staates in Anatolien erschütterte, legte das Machtvakuum der letzten Jahre Bayezids II. offen und wurde zur stärksten Begründung für den Marsch des Prinzen Selim auf den Thron.", "846180f5"]},
"OLAYLAR_EK5:1512-04-24:0":{"b": ["Rücktritt Bayezids II. und Thronbesteigung Yavuz Sultan Selims", "c4cfab69"], "d": ["Auf den Druck des Prinzen Selim hin, der im Thronkampf mit seinen Brüdern die Unterstützung der Janitscharen hinter sich gebracht hatte, trat Bayezid II. am 24. April 1512 vom Thron zurück, und Selim I. bestieg am selben Tag als neunter osmanischer Herrscher den Thron. Der greise Sultan starb auf dem Weg nach Dimetoka, seinem Geburtsort, im Dorf Abalar bei Çorlu am 25. Rabîʿ al-awwal 918 (10. Juni 1512). Die Herrschaft eines einunddreißig Jahre währenden vorsichtigen und nach innen gewandten Sultans wurde von der Yavuz-Zeit abgelöst, die die Grenzen des Reiches in acht Jahren verdoppeln sollte.", "7194b8c2"]},
"OLAYLAR_EK5:1513-01-01:0":{"b": ["Eroberung der Festung Sinj", "83271ea5"], "d": ["Osmanische Akinci-Truppen an der bosnischen Grenze nahmen die bis ins Innere Dalmatiens reichende Festung Sinj dem Königreich Ungarn ab. Dies war ein frühes Glied der dalmatinischen Grenzlinie, die sich neun Jahre später durch die Eroberung von Knin und Umgebung durch Gazi Hüsrev Bey erweitern sollte; die Festung sollte 1686 an Venedig verloren gehen.", "28c20426"]},
"OLAYLAR_EK5:1513-04-01:0":{"b": ["Schlacht von Yenişehir und Beseitigung des Prinzen Ahmed", "e2ed15dd"], "d": ["Yavuz Sultan Selim schlug seinen älteren Bruder, den Prinzen Ahmed, den stärksten Rivalen um den Thron, in der Ebene von Yenişehir bei Bursa vernichtend, nahm ihn gefangen und beseitigte ihn. Damit war der seit 1511 währende Bruderkampf beendet und die innere Spaltung Anatoliens zu Ende. Selim gewann, den Rücken gesichert, die Freiheit, sich der safawidischen Frage zuzuwenden.", "ed5f5ec0"]},
"OLAYLAR_EK5:1514-09-06:0":{"b": ["Einzug Yavuz Sultan Selims in Täbris", "dad2e227"], "d": ["Nach dem Sieg von Çaldıran zog das osmanische Heer in die safawidische Hauptstadt Täbris ein, und in der Stadt wurde die Chutba im Namen des Sultans verlesen. Selim blieb dort eine Woche und ließ einen Teil der Täbriser Künstler und Ulema nach Istanbul überführen; diese Überführung sollte die osmanische Hofkunst tief beeinflussen. Obwohl die Stadt angesichts des nahenden Winters und der Unzufriedenheit der Janitscharen verlassen wurde, war die safawidische Überlegenheit im Osten gebrochen. Auf der Karte sind die an diesem Tag an die Osmanen gefallenen Orte nicht zusammenhängend, und das ist richtig so: Täbris ist eine neuntägige Heeresbesetzung; die Ebene von Erzincan hatte sich während des Feldzugs kampflos ergeben, die Burg Kemah in ihrer Mitte leistete den Safawiden bis zum 19. Mai 1515 Widerstand; Siirt hat Halil Bey, der Malik von Hasankeyf, der in Täbris aus der Haft Schah İsmâils befreit wurde, durch seine Unterwerfung unter die Osmanen den Safawiden wieder abgenommen – das umliegende Diyarbakır blieb bis 1515, Hasankeyf bis 1517 safawidisch.", "3f65211e"]},
"OLAYLAR_EK5:1515-02-25:0":{"b": ["Muş und Bingöl (Çapakçur) gingen von den Safawiden in osmanische Verwaltung über", "b0a53b5a"], "d": ["Mit der Wegnahme Ostanatoliens von den Safawiden nach Çaldıran kam Muş 921/1515 unter osmanische Verwaltung; das benachbarte Çapakçur (Bingöl) wurde im selben Prozess dem Osmanischen Reich angeschlossen.", "9c979b3f"]},
"OLAYLAR_EK5:1515-05-19:0":{"b": ["Eroberung der Burg Kemah von den Safawiden", "73fd8671"], "d": ["Yavuz Sultan Selim, der nach der Rückkehr von Çaldıran den Winter in Amasya verbracht hatte, beauftragte Bıyıklı Mehmed Pascha mit der Eroberung der befestigten Burg Kemah, die den Übergangspunkt über den Euphrat hielt. Nach der Belagerung, an der der Sultan persönlich teilnahm, wurde die Burg dem Safawiden abgenommen und das Tor Ostanatoliens geöffnet. Diese Eroberung ist der erste konkrete Schritt, der den Sieg von Çaldıran in einen dauerhaften Gebietsgewinn verwandelte.", "9e896ebe"]},
"OLAYLAR_EK5:1515-06-13:0":{"b": ["Sieg von Turnadağ – das Beylik Dulkadir wurde den Osmanen tributpflichtig", "fd879145"], "d": ["Die osmanischen Truppen besiegten den Beys von Dulkadir, Alâüddevle Bozkurt, der sich während des Çaldıran-Feldzugs unschlüssig verhalten hatte, am Ort Ördekli zwischen Göksun und Andırın; Alâüddevle wurde in dieser Schlacht getötet. Das Beylik wurde zu diesem Datum nicht annektiert: Nach Alâüddevle wurde von Yavuz Sultan Selim Şehsuvaroğlu Ali Bey an die Spitze des Beylik der Dulkadıroğulları gesetzt, und das auf Maraş–Elbistan zentrierte Land bestand als den Osmanen tributpflichtiges Beylik fort. Der Puffer an der mamlukischen Grenze kam damit unter osmanische Kontrolle, und der Weg für den Ägypten-Feldzug zwei Jahre später war frei; die Annexion sollte dagegen nach der Tötung Ali Beys erfolgen.", "cf9c7460"]},
"OLAYLAR_EK5:1515-09-19:0":{"b": ["Eroberung von Âmid (Diyarbekir) und Gründung des Beylerbeylik Diyarbekir", "a6867d5b"], "d": ["Nachdem İdrîs-i Bitlisî die sunnitischen kurdischen Beys der Region für die Osmanen gewonnen hatte, hielten die safawidischen Truppen einer langen Belagerung nicht stand, und die Schlüssel von Âmid wurden Bıyıklı Mehmed Pascha übergeben. Die Stadt wurde zum Zentrum des neu gegründeten Beylerbeylik Diyarbekir gemacht. Damit fiel der Verwaltungskern Obermesopotamiens in osmanische Hand.", "70169bcc"]},
"OLAYLAR_EK5:1516-03-26:0":{"b": ["Eroberung von Harput – Öffnung der Straße nach Diyarbekir", "564eb269"], "d": ["Hüsrev Pascha, der Beylerbey von Karaman, der aufgebrochen war, das nach Çaldıran genommene Diyarbekir aus der safawidischen Belagerung zu befreien, nahm nach dreitägiger Belagerung die Burg Harput, deren Umgebung zuvor Çerkez Hüseyin Bey erobert hatte. Die Straße östlich des Euphrat nach Diyarbekir wurde damit gesichert.", "eb738178"]},
"OLAYLAR_EK5:1516-05-01:0":{"b": ["Schlacht von Koçhisar (Kızıltepe) – Niederlage Kara Hans", "9ea9e843"], "d": ["Das osmanische Heer unter dem Kommando von Bıyıklı Mehmed Pascha besiegte bei Koçhisar im Gelände Koruk der Steppe Dede Garkın den safawidischen Statthalter Kara Han in einer den ganzen Tag währenden Feldschlacht; der abgeschlagene Kopf Kara Hans wurde ins Lager des Sultans gesandt. Anschließend zogen die osmanischen Truppen zwar in die Stadt Mardin ein, verließen sie aber nach wenigen Tagen wieder; die von safawidischen Wachen gehaltene Burg von Mardin konnte erst ein Jahr später übernommen werden. Dieser Sieg sicherte Yavuz’ Südgrenze und ermöglichte ihm die Hinwendung zum Ägypten-Feldzug. Weitere am selben Datum angegliederte Orte: Palu, Çemişgezek, Siverek.", "6bc19ce1"]},
"OLAYLAR_EK5:1516-06-05:0":{"b": ["Aufbruch Yavuz Sultan Selims aus Istanbul zum Ägypten-Feldzug", "ac258b4b"], "d": ["Yavuz Sultan Selim brach scheinbar mit den Vorbereitungen zu einem neuen Ostfeldzug gegen die Safawiden aus Istanbul auf und wandte sich über Akşehir nach Süden. Dass der Mamlukensultan Kansu Gavri Kontakt zu Schah İsmâil aufnahm und die Ostflanke der Osmanen bedrohte, sollte das Ziel in kurzer Zeit ändern. Der Feldzug ist der Beginn der großen Unternehmung, die zwei Jahre währen und die Osmanen in ein Reich des Nahen Ostens verwandeln sollte.", "6b27f782"]},
"OLAYLAR_EK5:1516-06-20:0":{"b": ["Einnahme von Zabid: Erstes Eindringen osmanischer Seeleute ins Rote Meer", "38740e0c"], "d": ["Die aufgrund des portugiesischen Drucks im Indischen Ozean auf Bitten des Mamlukensultans Kansu Gavri ins Rote Meer entsandten Seeleute osmanischer Herkunft, Hüseyin Bey und Selman Reis, nahmen mit ihren Flotten Zabid ein. Diese noch im mamlukischen Dienst geführte Unternehmung ist die erste faktische Präsenz der osmanischen Marine auf der Linie Rotes Meer–Indien. Als Ägypten ein Jahr später an die Osmanen überging, sollte dieselbe Flotte unmittelbar Istanbul unterstellt werden.", "f715b0aa"]},
"OLAYLAR_EK5:1516-07-30:0":{"b": ["Offizielle Verkündung des Feldzugsziels: Mamluken und Aleppo", "689e310d"], "d": ["Yavuz Sultan Selim erklärte das Ziel des Feldzugs offen zum Mamlukensultan und zu Aleppo, nachdem Kansu Gavri sich mit den Safawiden verständigt und sein Heer gegen Aleppo geführt hatte. Damit wandelte sich die seit Jahren währende verdeckte Rivalität zwischen den beiden sunnitischen Staaten in offenen Krieg. Diese Verkündung löste den vierwöchigen Countdown nach Mardsch Dabiq aus.", "f2a137f3"]},
"OLAYLAR_EK5:1516-08-02:0":{"b": ["Scheitern der Belagerung von Aden: Erster Versuch im Roten Meer gegen Portugal", "8ffd46f2"], "d": ["Selman Reis und Hüseyin Bey führten eine achttägige Belagerung, um Aden, das zum Indischen Ozean geöffnete Tor des Roten Meeres, zu nehmen, mussten sich aber angesichts der starken Befestigung der Stadt zurückziehen. Dass Aden nicht genommen werden konnte, wird die gegen Portugal zu führende Südstrategie über Jahre hemmen. Dieser Versuch ist die erste Bewährungsprobe der osmanischen Ozeanpolitik.", "8b584b76"]},
"OLAYLAR_EK5:1516-08-24:0":{"b": ["Anbindung des Beylik der Ramazanoğulları an die Osmanen", "cfaa3754"], "d": ["Im Zuge der Belehnungen nach dem Sieg von Mardsch Dabiq wurde das auf Adana zentrierte Beylik der Ramazanoğulları an Mahmud Bey vergeben und unter osmanische Herrschaft genommen. Das aus der mamlukischen Oberhoheit ausgeschiedene Beylik wurde, statt aufgehoben zu werden, der Familie im Status eines „Ocaklık“ belassen; die Ramazanoğulları setzten die Verwaltung der Çukurova in der Eigenschaft osmanischer Sandschakbeys fort. Diese privilegierte Ordnung währte bis 1608, dem Jahr, in dem Pîr Mansûr das Beylik verließ. Weitere am selben Datum angegliederte Orte: Malatya, Tarsus, Mossul, Antep.", "af7c4758"]},
"OLAYLAR_EK5:1516-08-28:0":{"b": ["Aleppo, Raqqa und Deir ez-Zor kamen unter osmanische Herrschaft", "2088eb6a"], "d": ["Vier Tage nach Mardsch Dabiq zog Yavuz Sultan Selim, ohne auf Widerstand zu stoßen, in Aleppo ein, und in den Moscheen der Stadt wurde die Chutba in seinem Namen verlesen. Dass Aleppo, das als Handels- und Verwaltungshauptstadt Syriens galt, so schnell fiel, zeigt, dass die mamlukische Autorität in der Region zusammengebrochen war. Die Einnahme der Stadt öffnete mit einem Schlag den Weg nach Damaskus und von dort nach Ägypten. Weitere am selben Datum angegliederte Orte: Antiochia, Raqqa, Deir ez-Zor.", "6055ffc7"]},
"OLAYLAR_EK5:1516-08-29:0":{"b": ["Begegnung mit dem abbasidischen Kalifen al-Mutawakkil III. auf dem Gökmeydan in Aleppo", "22979f42"], "d": ["Der abbasidische Kalif von Kairo, al-Mutawakkil III., der bei Mardsch Dabiq zusammen mit dem mamlukischen Heer gefangen genommen worden war, wurde in Aleppo auf dem Gökmeydan vor den Sultan geführt, und Yavuz Sultan Selim erwies ihm große Achtung. Das Kalifat von Kairo, das seit 1261 im Schatten der Mamlukensultane ein symbolisches Amt gewesen war, ging mit dieser Begegnung faktisch unter osmanischen Schutz über. Der Kalif sollte später zusammen mit dem Sultan nach Istanbul gebracht werden.", "b1490892"]},
"OLAYLAR_EK5:1516-09-26:0":{"b": ["Tripoli und Hama kamen unter osmanische Verwaltung", "a1e19a79"], "d": ["Nach Aleppo und Hama ging auch Tripoli an der syrischen Küste ohne Widerstand in osmanische Verwaltung über. Die Stadt, einer der geschäftigsten Häfen des östlichen Mittelmeers, war das Tor von Damaskus zum Meer und das Zentrum des Seiden- und Zuckerhandels. Mit ihrer Einnahme wechselte der Küstenstreifen von Bilâd al-Scham vollständig den Besitzer.", "57168655"]},
"OLAYLAR_EK5:1516-09-27:0":{"b": ["Damaskus kam unter osmanische Herrschaft", "2b844d91"], "d": ["Yavuz Sultan Selim, dem sich nach Aleppo mit der Übergabe von Hama und Homs der Weg geöffnet hatte, erreichte am 27. September Damaskus; er zog nicht sofort in die Stadt ein, sondern schlug außerhalb am Ort Mastaba sein Zelt auf und zog am zwölften Tag seiner Ankunft in einer großen Zeremonie ein. Er blieb lange in Damaskus, errichtete die Verwaltungsordnung Syriens und ließ das Grab von Muhyiddin Ibn al-ʿArabi errichten. Damit war ganz Bilâd al-Scham aus der mamlukischen Verwaltung ausgeschieden. Weitere am selben Datum angegliederte Orte: Beirut.", "7cd1cd2b"]},
"OLAYLAR_EK5:1516-10-10:0":{"b": ["Ausrufung Tomanbays zum Mamlukensultan in Kairo", "6020d90d"], "d": ["Nach dem Tod Kansu Gavris bei Mardsch Dabiq setzten die mamlukischen Emire Tomanbay, der der letzte Sultan des Staates werden sollte, auf den Thron. Der neue Sultan tscherkessischer Herkunft übernahm einen Staat, der Syrien verloren hatte, dessen Schatzkammer leer war und dem es an Feuerwaffen mangelte. Dennoch sollte er vor Kairo eine Verteidigungslinie errichten und einen letzten Widerstand gegen den osmanischen Vormarsch organisieren.", "c55b45e9"]},
"OLAYLAR_EK5:1516-12-21:0":{"b": ["Schlacht von Gaza (Han Yûnus): Niederlage Canbirdi Gazâlîs", "9f1eb8cb"], "d": ["Yavuz Sultan Selim sandte den Großwesir Hadım Sinan Pascha mit einer viertausend Mann starken Vorhut nach Gaza. Canbirdi Gazâlî, von Tomanbay zum Statthalter von Damaskus ernannt, versuchte, die osmanische Vorhut auf der Linie Gaza–Han Yûnus aufzuhalten, erlitt aber eine schwere Niederlage und floh nach Ägypten. Mit der Auflösung der letzten mamlukischen Pufferstreitmacht in Palästina war der Weg in die Sinai-Wüste völlig geöffnet.", "042a934e"]},
"OLAYLAR_EK5:1516-12-28:0":{"b": ["Ostjordanland: Amman kam unter osmanische Verwaltung", "9db62667"], "d": ["Als die osmanischen Truppen nach der Schlacht von Gaza, zum Ägypten-Feldzug rüstend, nach Süden zogen, kam auch Amman östlich des Jordan unter osmanische Verwaltung. Die Küsten- und Binnenstädte Palästinas (Jaffa, Nablus, Sidon, Akkon, Jerusalem) hatten dagegen nach Mardsch Dabiq im Herbst 1516 bereits den Besitzer gewechselt. Diese Städte wurden vier Jahrhunderte lang als Sandschaks der Provinz Damaskus verwaltet.", "fac75355"]},
"OLAYLAR_EK5:1516-12-29:0":{"b": ["Ankunft Yavuz Sultan Selims in Jerusalem", "66d7bfad"], "d": ["In Jerusalem, das sich nach Mardsch Dabiq ohne Widerstand der osmanischen Verwaltung unterstellt hatte, traf Yavuz Sultan Selim nach der Schlacht von Gaza mit den Würdenträgern des Staates und dem Heer ein. Der Sultan besuchte den Felsendom und die Al-Aqsa-Moschee und bekräftigte den heiligen Status der Stadt. Jerusalem sollte von diesem Datum bis Dezember 1917 volle vier Jahrhunderte unter osmanischer Verwaltung bleiben.", "42cf2ec1"]},
"OLAYLAR_EK5:1517-01-02:0":{"b": ["Einzug Yavuz Sultan Selims in Gaza und Wendung zur Sinai-Wüste", "2106bfc7"], "d": ["Nach der Niederlage Canbirdi Gazâlîs bei Han Yûnus (21. Dezember 1516) war Gaza in der Hand der Vorhut. Der Sultan zog am 2. Januar 1517 in Gaza ein und traf dort Sinan Pascha an der Spitze der Vorhut, und das Heer traf die letzten Vorbereitungen für den Übergang nach Ägypten. In der wasserlosen Katya-Wüste (Sinai) von Gaza bis Sâlihiye sollten acht Tagesmärsche zurückgelegt und Wasser mit Kamelen transportiert werden. Dieser Übergang ist die riskanteste und logistisch schwierigste Phase des Feldzugs.", "5c3d7bc1"]},
"OLAYLAR_EK5:1517-01-24:0":{"b": ["Einnahme von Suez – das Tor zum Roten Meer", "05f3324e"], "d": ["Mit dem Einzug der osmanischen Truppen in Kairo nach dem Sieg von Raydaniyya kam auch Suez am Nordende des Roten Meeres unter osmanische Verwaltung. Dieser Werft- und Hafenort, von dem aus die Mamluken Flotten in den Indischen Ozean entsandt hatten, wurde zum Stützpunkt der gegen Portugal zu führenden Südpolitik. Suez ist die nördliche Mündung der Linie, an der drei Jahrhunderte später der Kanal geöffnet werden sollte.", "501facb1"]},
"OLAYLAR_EK5:1517-01-24:1":{"b": ["Erster Einzug osmanischer Truppen in Kairo", "0a3f4f4d"], "d": ["Am Tag nach dem Sieg von Raydaniyya wurde den osmanischen Heeren der Einzug in Kairo erlaubt, und am 24. Januar bezogen die Truppen Quartier in der Stadt. Dieser Einzug bedeutete jedoch noch nicht die volle Kontrolle über die Stadt; Tomanbay hatte sich nach Oberägypten zurückgezogen, der mamlukische Widerstand war noch nicht gebrochen. Die Eroberung Kairos sollte nicht an einem einzigen Tag, sondern in einem über Wochen verteilten blutigen Prozess abgeschlossen werden.", "32d9401c"]},
"OLAYLAR_EK5:1517-01-27:0":{"b": ["Tomanbays Überfall auf Kairo und die dreitägigen Straßenkämpfe", "b83b6ce6"], "d": ["Tomanbay, der sich nach Oberägypten zurückgezogen hatte, drang in der Nacht vom 27. auf den 28. Januar mit etwa siebentausend Mann überraschend in Kairo ein, begann in der Stadt Widerstand und brachte die osmanischen Truppen in eine äußerst schwierige Lage. In den drei Tage währenden heftigen Straßenkämpfen hielten die Mamluken den größten Teil der Stadt vorübergehend in ihrer Hand. Der Widerstand konnte erst durch den Einsatz der osmanischen Artillerie und von Verstärkungen gebrochen werden.", "98838d21"]},
"OLAYLAR_EK5:1517-02-08:0":{"b": ["Canbirdi Gazâlî trat in osmanische Dienste", "a94ea459"], "d": ["Der frühere mamlukische Emir Canbirdi Gazâlî, der sich nach Raydaniyya nach Sâlihiye zurückgezogen hatte, wandte sich an den Sultan und bat um Gnade. Yavuz Sultan Selim nahm ihn in seinen Dienst, da er meinte, er werde bei der Herstellung der Ordnung in Ägypten und Syrien nützlich sein. Diese Wahl ist das erste große Beispiel der osmanischen Politik, die mamlukischen Kader nicht zu beseitigen, sondern in das System einzugliedern.", "847c1e81"]},
"OLAYLAR_EK5:1517-02-15:0":{"b": ["Feierlicher Einzug Yavuz Sultan Selims in Kairo und Verlesung der Chutba", "6d98080c"], "d": ["Nach der Niederschlagung der Straßenkämpfe zog der Sultan am 15. Februar 1517 in einer sehr glanzvollen Zeremonie in Kairo ein, und in den Moscheen wurde die Chutba in seinem Namen verlesen. Die Verlesung der Chutba in Kairo im Namen des osmanischen Sultans ist die Verkündung, dass die seit 1250 währende mamlukische Herrschaft rechtlich beendet war. Dieses Datum gilt als der symbolische Abschlusspunkt der faktischen Eroberung Ägyptens.", "3f8589a3"]},
"OLAYLAR_EK5:1517-03-30:0":{"b": ["Gefangennahme des letzten Mamlukensultans Tomanbay bei Terrûce", "7058e6ad"], "d": ["Tomanbay, der sich nach dem Verlassen Kairos im Nildelta versteckt hielt, wurde von den Beduinen, die ihm Unterschlupf gewährt hatten, verraten und in der Gegend von Terrûce ergriffen. Seine Gefangennahme beseitigte das organisierte Zentrum des mamlukischen Widerstands. Der letzte Sultan sollte danach vierzehn Tage in osmanischer Hand gehalten werden.", "5fc98f13"]},
"OLAYLAR_EK5:1517-04-13:0":{"b": ["Hinrichtung Tomanbays am Bâb Zuwayla und Ende des Mamlukenstaates", "ad9820be"], "d": ["Vierzehn Tage nach seiner Gefangennahme wurde Tomanbay am berühmten Tor Kairos, dem Bâb Zuwayla, gehängt; sein Leichnam wurde später in der von seinem Onkel erbauten Medrese beigesetzt. Damit verschwand der seit 1250 über Ägypten und Syrien herrschende Mamlukenstaat offiziell aus der Geschichte. Mit dem Brechen des Widerstands wurden auch Städte in Oberägypten (Saʿīd) wie Asyut und Assuan der osmanischen Verwaltung angegliedert.", "96555946"]},
"OLAYLAR_EK5:1517-04-18:0":{"b": ["Angriff der portugiesischen Flotte auf Dschidda und die Verteidigung Selman Reis’", "52322cf5"], "d": ["Die aus etwa dreißig Galeeren und Galeonen bestehende portugiesische Flotte griff Dschidda an; Selman Reis leitete die Verteidigung der Stadt, verhinderte die Landung des Feindes und versenkte einige portugiesische Schiffe. Diese Verteidigung verhinderte, dass der Hafen Mekkas und damit die Pilgerstraße in die Hand eines christlichen Staates fielen. Dschidda sollte einige Monate später durch die Huldigung des Hedschas offiziell in die osmanische Verwaltung eingegliedert werden.", "a480f1f5"]},
"OLAYLAR_EK5:1517-05-19:0":{"b": ["Übernahme Alexandrias durch die Flotte – Vollendung der Eroberung Ägyptens", "386878fe"], "d": ["Genau vier Monate nach Raydaniyya und sechsunddreißig Tage nach der Hinrichtung Tomanbays ging Alexandria mit der Ankunft der osmanischen Flotte unter Câfer Bey im Hafen in osmanische Verwaltung über; auch Deltahäfen wie Reşîd und Damiette wurden im selben Prozess angeschlossen. Dass dieser große, zum Mittelmeer geöffnete Hafen Ägyptens erst Monate nach dem Fall Kairos und nicht zu Lande, sondern zur See übernommen wurde, zeigt deutlich, dass die Eroberung nicht in einer einzigen Schlacht, sondern Region für Region abgeschlossen wurde. Alexandria sollte von da an zum lebenswichtigen Hafen werden, der Istanbul und Kairo verband. Weitere am selben Datum angegliederte Orte: Reşîd (Rosetta).", "52187c14"]},
"OLAYLAR_EK5:1517-07-06:0":{"b": ["Kampflose Angliederung des Hedschas: Huldigung Abû Numayys, des Sohnes des Scherifen von Mekka", "c13b98c7"], "d": ["Yavuz Sultan Selim hatte zunächst erwogen, Truppen zur Besetzung Mekkas und seiner Umgebung zu entsenden, davon aber Abstand genommen, als der Emir von Mekka, Scherif Berekât, seine Gehorsamserklärung übermittelte. Berekâts zwölfjähriger Sohn Abû Numayy kam mit den Geschenken seines Vaters und den Schlüsseln Mekkas nach Kairo und wurde vom Sultan empfangen. So wurde der Hedschas nicht als automatische Folge von Raydaniyya, sondern fünfeinhalb Monate später und ohne einen einzigen Schuss, friedlich und auf dem Weg der Huldigung (bay’a), dem Osmanischen Reich angegliedert. Weitere am selben Datum angegliederte Orte: Tâif.", "636183e3"]},
"OLAYLAR_EK5:1517-07-12:0":{"b": ["Annahme des Titels Hâdimü’l-Haremeyn und Chutba in Medina", "63b32b59"], "d": ["Nach dem zweiten Empfang der mekkanischen Delegation übernahm Yavuz Sultan Selim offiziell den Schutz der Haramain und begann, den Titel „Hâdimü’l-Haremeyni’ş-şerîfeyn“ (Diener der beiden edlen Heiligtümer) zu führen. Scherif Berekât zog das ihm gesandte Ehrengewand an und ließ im Namen des Sultans die Chutba verlesen; da auch die Delegation Medinas nach Istanbul reiste, wurde Berekâts Emirat durch Berat bestätigt. Der Sultan sandte der Bevölkerung der Haramain zweihunderttausend Goldstücke und reichlich Proviant und begründete damit die jährlich zu wiederholende Surre-Tradition. Weitere am selben Datum angegliederte Orte: Yanbu, Tebük.", "3b3bfd8f"]},
"OLAYLAR_EK5:1517-08-28:0":{"b": ["Selman Reis trat in osmanische Dienste – Übernahme der Rotmeer-Politik", "771da99a"], "d": ["Selman Reis, der Dschidda gegen die Portugiesen verteidigt hatte, kam nach Kairo und trat vor Yavuz Sultan Selim; obwohl er eine Zeit lang festgehalten wurde, wurde er 1519 nach Istanbul gerufen und verpflichtete sich, gegen die portugiesische Bedrohung dreißig Galeeren und einige Galeonen vorzubereiten. Diese Begegnung ist der Beginn dessen, dass die Politik im Roten Meer und im Indischen Ozean aus dem mamlukischen Erbe übernommen und unmittelbar an Istanbul gebunden wurde. Die Osmanen waren nun nicht nur ein Mittelmeerstaat, sondern auch eine Macht mit Ozeanpolitik.", "c87580bd"]},
"OLAYLAR_EK5:1517-09-10:0":{"b": ["Abreise Yavuz Sultan Selims aus Kairo und das Beylerbeylik Hayır Beys", "8cd4fb23"], "d": ["Yavuz Sultan Selim, der etwa acht Monate in Ägypten geblieben war und die administrative, finanzielle und militärische Ordnung errichtet hatte, verließ Kairo; Hayır Bey, der frühere Statthalter von Aleppo, der bei Mardsch Dabiq den linken Flügel abgezogen und die mamlukische Niederlage beschleunigt hatte, begann als erster osmanischer Beylerbey Ägyptens von der Zitadelle aus die Verwaltung. Die Wahl eines Statthalters mamlukischer Herkunft war eine bewusste Übergangspolitik, die dafür sorgte, dass die neue Verwaltung der einheimischen Bevölkerung nicht fremd erschien. Auf dem Rückweg nahm der Sultan den letzten abbasidischen Kalifen al-Mutawakkil III. sowie die ausgewählten Künstler und Gelehrten Ägyptens mit nach Istanbul.", "c2b3bc7e"]},
"OLAYLAR_EK5:1517-09-11:0":{"b": ["Ende des abbasidischen Kalifats von Kairo – die Überlieferung der „Übertragungszeremonie“", "1d357640"], "d": ["Nach der Eroberung Ägyptens brachte Yavuz Sultan Selim den bei Mardsch Dabiq gefangen genommenen letzten Kalifen al-Mutawakkil ʿalā ’llāh III. mit nach Istanbul; das seit 1261 im Schatten der Mamlukensultane ohne Befugnisse fortbestehende abbasidische Kalifat von Kairo endete damit. Die berühmte Überlieferung dagegen, das Kalifat sei in einer offiziellen Zeremonie in der Hagia Sophia an Yavuz übertragen worden, erscheint erstmals Ende des 18. Jahrhunderts im Werk d’Ohssons und findet sich in keiner der Quellen der Yavuz-Zeit. Die TDV İslâm Ansiklopedisi hält die Überlieferung für erfunden, weil keine Originalquelle die Zeremonie belegt; sie vermerkt aber auch, dass für den Übergang des Kalifats eine solche Übertragungszeremonie nach dem Religionsrecht nicht erforderlich war.", "86efdf28"]},
"OLAYLAR_EK5:1518-01-01:0":{"b": ["Erzurum wurde der osmanischen Verwaltung angegliedert – safawidischer Einfluss in Ostanatolien gebrochen", "78d1be02"], "d": ["Obwohl der osmanische Einfluss in der Region nach dem Sieg von Çaldıran (1514) zugenommen hatte, verzögerte sich die vollständige Besetzung Erzurums bis zum Brechen des iranischen Einflusses; die Stadt wurde erst nach dem Ägypten-Feldzug 1518–19 der osmanischen Verwaltung angegliedert. Erzurum war 1502, als Schah İsmâil dem Beylik der Ak Koyunlu ein Ende setzte, unter safawidische Herrschaft geraten; diese sechzehnjährige Zeit wurde damit beendet. 1534 sollte während des Irakeyn-Feldzugs das Beylerbeylik Erzurum gegründet werden.", "e137cb2e"]},
"OLAYLAR_EK5:1519-03-01:0":{"b": ["Beginn der Dschelali-Aufstände: Aufstand des Bozoklu Şeyh Celâl", "99bd8a99"], "d": ["In der Gegend von Bozok erklärte sich ein Mann namens Şeyh Celâl zum Mahdi und erhob sich in der Umgebung von Tokat; der Aufstand wurde zwar niedergeschlagen, doch sein Name wurde ein Jahrhundert lang zum Namen aller Banditen- und Aufstandsbewegungen in Anatolien. Der Dschelalismus verband sich Ende des 16. Jahrhunderts mit der Auflösung der Timar-Ordnung und dem Bevölkerungsdruck und wuchs zum langlebigsten Problem der inneren Sicherheit des Reiches. Die Aufstände führten in Anatolien zu Massenwanderungen, die „große Flucht“ (büyük kaçgunluk) genannt werden.", "ec33f73b"]},
"OLAYLAR_EK5:1519-09-01:0":{"b": ["Anbindung Algiers an das Osmanische Reich", "b8eba4c1"], "d": ["Hayreddin Reis, der in Nordafrika dem spanischen Druck Widerstand leistete, wandte sich, um sich behaupten zu können, an Istanbul, trug Algier dem Sultan an, und die Chutba wurde im Namen Yavuz Sultan Selims verlesen. Damit wurde Algier offiziell dem osmanischen Land angegliedert, und Hayreddin wurden mit dem Titel Beylerbey Soldaten und Kanonen gesandt. Diese Anbindung legte den Grundstein der jahrhundertelang währenden osmanischen Seeherrschaft im westlichen Mittelmeer. Weitere am selben Datum angegliederte Orte: Konstantin, Şerşel (Cherchell), Medea (Titteri), Setif.", "42dac5d2"]},
"OLAYLAR_EK5:1520-09-21:0":{"b": ["Tod Yavuz Sultan Selims in Çorlu", "9fe83744"], "d": ["Selim I., der in acht Jahren das Gebiet des Staates mehr als verdoppelt hatte, brach am 18. Juli 1520 zu einem neuen Feldzug aus Istanbul auf; wegen eines großen Geschwürs auf dem Rücken kam er nicht über Çorlu hinaus. Trotz der Eingriffe der Ärzte verschlimmerte sich seine Krankheit, und nach einer zwei Monate währenden hoffnungslosen Behandlung starb er hier am 8.–9. Schawwal 926 (21.–22. September 1520). Mit Çaldıran, Mardsch Dabiq und Raydaniyya hatte er Iran aufgehalten und den Mamlukenstaat beseitigt, Kalifat und Schirmherrschaft über die Haramain an die Osmanen gebracht. Er hinterließ nur einen männlichen Nachkommen: Süleyman.", "39cccc63"]},
"OLAYLAR_EK5:1521-01-01:0":{"b": ["Übergang der Insel Nikarya (Ikaria) unter osmanische Verwaltung", "6afa972b"], "d": ["Nikarya zwischen Samos und Chios stand von 1481 bis 1521 unter der Verwaltung der Johanniterritter von Rhodos; die erste osmanische Zeit auf der Insel begann 1522 und dauerte bis 1822. In dieser Zeit war der Kaymakam für die Erhebung und Zahlung der Steuern verantwortlich; wie auf den übrigen Ägäischen Inseln bestand auch der örtliche Ältestenrat (Demogerontia) fort und geriet zeitweise mit der osmanischen Verwaltung in Konflikt.", "7c6cc486"]},
"OLAYLAR_EK5:1522-01-01:0":{"b": ["Annexion des Landes Dulkadir – Eyalet Dulkadir mit Sitz in Marasch", "595c3c30"], "d": ["Das Land Dulkadir, das nach der Niederlage am Turnadağ 1515 als dem Osmanischen Reich untergeordnetes Beylik fortbestanden hatte, wurde nach der Ermordung von Şehsuvaroğlu Ali Bey mit seinen Kindern in Artukova unmittelbar dem osmanischen Land angeschlossen und mit Marasch als Zentrum zu einem Eyalet gemacht. Die Region Bozok des Beyliks wurde als eigener Sandschak der osmanischen Verwaltung unterstellt. Damit endete die etwa zweihundertjährige Dulkadir-Zeit von Marasch, Elbistan, Göksun, Gürün, Zamantı und Darende; das Pufferbeylik an der mamlukischen Grenze verschwand vollständig.", "9b819db9"]},
"OLAYLAR_EK5:1522-05-29:0":{"b": ["Eroberung von Knin", "a46d3117"], "d": ["Durch die Streifzüge des bosnischen Sandschakbeys Gazi Hüsrev Bey in den Jahren 927–928 (1521–1522) gingen eine Reihe venezianischer Festungen, allen voran Knin, Skradin und Ostrovica, in osmanische Verwaltung über; die Grenze wurde über die zweite Gebirgskette hinaus geschoben. Diese Eroberungskette legte den Grundstein des Sandschaks Dalmatien, der fünfzehn Jahre später mit der Einnahme von Klis vollendet werden sollte.", "21f9fbd5"]},
"OLAYLAR_EK5:1523-01-05:0":{"b": ["Abzug der Ritter: Übergabe von Bodrum, Kos und der Dodekanes", "ea01666e"], "d": ["Gemäß den Kapitulationsbedingungen von Rhodos räumten die Johanniterritter nicht nur das Inselzentrum, sondern alle Stellungen, die sie zweihundert Jahre lang gehalten hatten. Die Festung Bodrum (St. Peter) an der anatolischen Küste sowie die Inseln Kos, Kalymnos und Leros gingen so ohne Kampf in osmanische Verwaltung über. Mit dieser zwei Wochen nach dem Fall von Rhodos vollzogenen Übergabe endete die lateinische Präsenz in der Südostecke der Ägäis vollständig.", "bcbe8fa8"]},
"OLAYLAR_EK5:1524-01-01:0":{"b": ["Aufstand Hain Ahmed Paschas in Ägypten", "b18bb805"], "d": ["Ahmed Pascha, der in der Erwartung des Großwesirats zum Statthalter Ägyptens entsandt worden war, verkündete in Kairo seine Unabhängigkeit, indem er sich zu „al-Malik al-Mansûr Sultan Ahmed“ erklärte. Der Aufstand wurde in kurzer Zeit niedergeschlagen und der Pascha getötet, doch das Ereignis zeigte die Brüchigkeit der zentralen Kontrolle in der reichsten Provinz des Reiches. Daraufhin reiste İbrahim Pascha nach Ägypten und ließ das berühmte Ägyptische Kanunnâme ausarbeiten, das die Verwaltung der Provinz neu ordnete.", "35eb542c"]},
"OLAYLAR_EK5:1528-01-01:0":{"b": ["Annexion Nordbosniens: Jajce und Banja Luka", "8ec86cfa"], "d": ["Als die ungarische Verteidigungslinie nach Mohács zusammenbrach, marschierte der bosnische Sandschakbey Gazi Hüsrev Bey ins Vrbas-Tal und nahm die letzten Bosnien-Festungen, die dem ungarischen Königreich verblieben waren. Mit dem Fall von Jajce und Banja Luka stieß das Eyalet Bosnien im Norden an die Save, und die kroatische Front entstand. Banja Luka wurde bald zum zweiten Zentrum des Eyalets.", "1f634005"]},
"OLAYLAR_EK5:1529-09-08:0":{"b": ["Einnahme Ofens und Übergabe an Zápolya", "fba4f89b"], "d": ["Auf dem Weg zum Wien-Feldzug belagerte das osmanische Heer das in die Hand Ferdinands gefallene Ofen, nahm es zurück und übergab die Stadt dem unter osmanischem Schutz stehenden ungarischen König János Szapolyai. Damit wurde in der habsburgisch-osmanischen Rivalität um Ungarn das Modell eines vasallischen Pufferkönigreichs errichtet. Diese Ordnung sollte bis 1541 währen; nach Zápolyas Tod sollte Ofen unmittelbar zu einer osmanischen Provinz gemacht werden.", "6777eb1d"]},
"OLAYLAR_EK5:1532-04-25:0":{"b": ["Süleyman der Gesetzgeber brach zum Deutschen Feldzug auf – Herausforderung Karls V.", "7c3d7055"], "d": ["Nach dem ergebnislosen Ausgang der Belagerung Wiens und Ferdinands erneuter Belagerung Ofens brach der Sultan diesmal aus Istanbul auf, um den Kaiser Karl V. unmittelbar in eine Feldschlacht zu ziehen. Das Heer sollte im August durch den Widerstand der kleinen Burg Güns aufgehalten werden, und da der Kaiser nicht zur Schlacht antrat, sollte sich der Feldzug auf Streifzüge beschränken. Der Feldzug bereitete den Boden für den ersten Frieden mit den Habsburgern im folgenden Jahr.", "c3e6e378"]},
"OLAYLAR_EK5:1532-08-05:0":{"b": ["Deutscher Feldzug und Belagerung von Güns (Kőszeg)", "8aec937a"], "d": ["Süleyman der Gesetzgeber marschierte mit seinem Heer auf Österreich, um Karl V. zu einer Feldschlacht zu zwingen; die kleine Burg Güns widerstand fünfundzwanzig Tage und verzögerte den Vormarsch des Heeres. Da der Kaiser nicht zur Schlacht antrat, trafen die Akıncı die Umgebung Wiens, und mit fortschreitender Jahreszeit kehrte man um. Der Feldzug brachte keinen Gebietsgewinn, setzte die Habsburger aber an den Verhandlungstisch und bereitete den Boden für den Frieden des folgenden Jahres.", "792fc40e"]},
"OLAYLAR_EK5:1533-01-01:0":{"b": ["Vertrag von Istanbul – erster Friede mit den Habsburgern", "b085767a"], "d": ["Der Sultan, der den Gesandten Ferdinands, Cornelius, empfing, willigte in einen Waffenstillstand ein, und der erste offizielle Friedenstext zwischen den Osmanen und Österreich entstand. Mit dem Vertrag erklärte sich Ferdinand bereit, für die von ihm gehaltenen ungarischen Gebiete eine jährliche Steuer zu zahlen; der Erzherzog von Österreich wurde im Protokoll dem Großwesir gleichgestellt. Dieser ungleiche Status war der offene Ausdruck des Überlegenheitsanspruchs der osmanischen Diplomatie im 16. Jahrhundert.", "e51c434d"]},
"OLAYLAR_EK5:1534-06-01:0":{"b": ["Einnahme von Kars und Öffnung der Nordostgrenze", "742e3101"], "d": ["Als die Vorhut des Irakeyn-Feldzugs von Erzurum nach Osten zog, wurde die Festung Kars, die sich in der Hand des georgischen Atabegtums befand und seit Timur in Trümmern lag, ohne Widerstand übernommen. Da die Stadt den Pass zwischen dem Araxes-Bogen und Çıldır hielt, galt sie als Schlüssel zum nördlichen Tor, das sich nach Iran öffnet. Dieser Gewinn wurde das erste Glied des dreißig Jahre später zu gründenden Beylerbeyliks Kars und der kaukasischen Linie.", "b3a27cc8"]},
"OLAYLAR_EK5:1534-07-13:0":{"b": ["Erster Einzug in Täbris – Eröffnung des Irakeyn-Feldzugs", "cf7ed4e3"], "d": ["İbrahim Pascha, der als Serdar-ı ekrem vorausmarschierte, zog ohne Widerstand in die safawidische Hauptstadt Täbris ein, nachdem Schah Tahmasb der Feldschlacht ausgewichen und ins Landesinnere zurückgewichen war. Süleyman der Gesetzgeber erreichte die Stadt im September; wegen des einbrechenden Winters und der allzu langen Nachschublinie wandte sich das Heer jedoch in Richtung Bagdad, und Täbris konnte lange nicht gehalten werden. Die Stadt, die nach Çaldıran zum zweiten Mal eingenommen wurde, wurde zu dem Ort, an dem das Osmanische Reich lernte, dass im Osten das Erobern leicht, das Halten aber schwer ist.", "a303a9e4"]},
"OLAYLAR_EK5:1534-09-22:0":{"b": ["Barbarossas Eroberung von Tunis", "d8754216"], "d": ["Der Kapudan Pascha Barbarossa Hayreddin Pascha wandte sich, nachdem er mit seiner Flotte die Küsten Italiens getroffen hatte, nach Tunis, vertrieb den Hafsiden-Herrscher Mevlây Hasan und zog in die Stadt ein. Die Einnahme von Tunis kehrte mit ihrer Lage, die die Straße von Sizilien kontrollierte, das Kräfteverhältnis im westlichen Mittelmeer mit einem Schlag zugunsten der Osmanen. Diese Herrschaft sollte jedoch nicht lange währen; Karl V. sollte im folgenden Jahr mit einer großen Flotte antworten.", "b0aeb30e"]},
"OLAYLAR_EK5:1535-07-21:0":{"b": ["Verlust von Tunis an Karl V.", "a691f0f8"], "d": ["Karl V. nahm in einem großen, von der genuesischen und der päpstlichen Flotte unterstützten Feldzug, nachdem er Halkulvâd zu Fall gebracht hatte, Tunis ein und setzte Mevlây Hasan unter spanischem Schutz wieder auf den Thron. Durch die Einrichtung einer spanischen Garnison in der Stadt wurde der Vormarsch der Osmanen im Mittelmeerzentrum vorübergehend aufgehalten. Die endgültige Eroberung von Tunis sollte erst vierzig Jahre später, 1574, möglich sein.", "cbb995cd"]},
"OLAYLAR_EK5:1536-01-01:0":{"b": ["Gazi Hüsrev Beys Operation entlang der Save: Bosna Brod und Jasenovac", "3740ec83"], "d": ["Nach der Einnahme von Jajce und Banja Luka 1528 blieben die Festungen entlang der Save noch eine Zeitlang in der kroatisch-slawonischen Grenze, die der Habsburger Krone unterstand. Gazi Hüsrev Bey, der 1536 zum dritten Mal Sandschakbey von Bosnien wurde, nahm im selben Jahr Pojega und Umgebung und schloss auch die Festungen Brod und Jasenovac am Ufer der Save der osmanischen Verwaltung an. Damit stieß die Nordgrenze Bosniens an die Save; die Region wurde zwei Jahre später mit der Einnahme von Dubica vollendet.", "415f0592"]},
"OLAYLAR_EK5:1536-03-15:0":{"b": ["Hinrichtung des Makbul İbrahim Pascha", "348aa7b8"], "d": ["İbrahim Pascha, der dreizehn Jahre Großwesir war, der engste Freund des Gesetzgebers und der faktische zweite Mann des Staates, wurde im Palast, wohin er zum Fastenbrechen gerufen worden war, ohne jede Begründung erdrosselt und hingerichtet. Seine Haltung im Irakeyn-Feldzug, sein Gebrauch des Titels „Serasker Sultan“ und die Gleichgewichte im Palast gelten als für seinen Tod ausschlaggebend. Die Hinrichtung ist ein Wendepunkt, der zeigt, dass die Großwesire in der osmanischen Zentralverwaltung keine absolute Sicherheit besaßen.", "a780f3de"]},
"OLAYLAR_EK5:1537-03-12:0":{"b": ["Eroberung der Burg Klis und Gründung des Sandschaks Dalmatien", "6ffd4ebf"], "d": ["Murad Bey, ein zum Islam übergetretener Kroate und Kâhya des Gazi Hüsrev Bey, nahm Venedig die strategische Burg Klis unmittelbar nördlich von Split ab. Unmittelbar nach der Eroberung wurde Klis zum Zentrum eines neuen, seine Umgebung umfassenden Sandschaks und Kazas gemacht; die Grenzen dieses Sandschaks zeichneten weitgehend den Rahmen des osmanischen Kroatien vor. Diese Eroberung, die fünfzehn Jahre nach Knin erfolgte, vollendete das Verwaltungsgerüst des dalmatinischen Binnenlandes.", "8338f8aa"]},
"OLAYLAR_EK5:1537-08-25:0":{"b": ["Belagerung von Korfu und Krieg mit Venedig", "11af95bd"], "d": ["Nach dem Apulien-Feldzug landete das osmanische Heer auf Korfu und belagerte die starke venezianische Festung der Insel. Wegen der Steilheit der Burg, schwerer Verluste und der Jahreszeit wurde die Blockade am 6. September aufgehoben und der Rückzug angetreten. Obwohl die Belagerung ergebnislos blieb, mündete der mit Venedig eröffnete Krieg in die Angliederung zahlreicher Inseln in Ägäis und Adria an die Osmanen und im folgenden Jahr in den Sieg von Preveza.", "f023c2b9"]},
"OLAYLAR_EK5:1537-10-01:0":{"b": ["Barbarossas Ägäis-Feldzug: Einnahme der von Venedig unmittelbar verwalteten Inseln", "1b32ed96"], "d": ["Die von der Belagerung Korfus zurückkehrende Flotte nutzte die Tatsache, dass Venedig der Krieg erklärt war, und übernahm in der Ägäis nacheinander die nicht dem Herzogtum, sondern unmittelbar Venedig unterstehenden Inseln. Ägina wurde nach heftigem Widerstand erobert, Astypalaia, das der Familie Querini gehörte, sowie Karpathos und Kasos ergaben sich, und auch Patmos, das unter klösterlicher Verwaltung stand, nahm den osmanischen Schutz an. Das Herzogtum Naxos dagegen wurde unter Tributpflicht an seinem Platz belassen; seine Annexion musste bis 1566 warten.", "632f4747"]},
"OLAYLAR_EK5:1538-08-01:0":{"b": ["Barbarossas Nordägäis-Feldzug: Einnahme von Skyros und den Nördlichen Sporaden", "20ab688e"], "d": ["Auf dem Weg nach Preveza übernahm die Flotte nacheinander die Nordägäischen Inseln, die sich nach der Eroberung Istanbuls zu Venedig geflüchtet hatten. Skyros nördlich von Euböa sowie Skiathos, Skopelos und Alonissos, die die Mündung des Golfs von Saloniki halten, kamen so unter osmanische Verwaltung. Diese Inseln schlossen die letzte nordägäische Lücke, die trotz der Einnahme Euböas 1470 noch achtundsechzig Jahre in venezianischer Hand geblieben war.", "2a9ea08f"]},
"OLAYLAR_EK5:1538-08-03:0":{"b": ["Eroberung Adens und Annexion der jemenitischen Küste", "e7d46d8f"], "d": ["Die von Suez aufgebrochene Flotte des Indienfeldzugs wandte sich zunächst der jemenitischen Küste zu, da man nicht in den Ozean hinausfahren konnte, ohne das Rote Meer gesichert zu haben. Hadım Süleyman Pascha lief am 3. August 1538 in den Hafen von Aden ein; der den Portugiesen zuneigende tahiridische Herrscher Âmir ibn Dâvud wurde vor das Tor des Kapitäns gebracht und hingerichtet, und in der Stadt wurde eine Wache von 500 Mann zurückgelassen. Während desselben Feldzugs wurden auch Mokka sowie die die Meerenge beherrschenden Inseln Kamaran und Farasan übernommen, und der Grundstein des Beylerbeyliks Jemen wurde gelegt. Damit besaß das Osmanische Reich zum ersten Mal die gesamte Nordküste von Bab al-Mandab; Sanaa und das Landesinnere mussten noch neun Jahre warten.", "495e1991"]},
"OLAYLAR_EK5:1538-09-01:0":{"b": ["Moldau-Feldzug und Annexion der Region Bucak (Bender)", "90a88a56"], "d": ["Im Feldzug gegen den Woiwoden der Moldau, Petru Rareş, der seine Verpflichtungen gegenüber den Osmanen nicht erfüllte, wurde Suceava erobert, und die Stadt Yaş wurde vom Krim-Khan Sâhib Giray geplündert. Der Sultan setzte Stefan Çekirge als Woiwoden ein und gliederte Bender zusammen mit der Region Bucak (Süd-Bessarabien) unmittelbar dem osmanischen Land an. Diese Annexion wurde zu einem der Glieder, die das nordwestliche Ufer des Schwarzen Meeres zu einem osmanischen Binnenmeer machten. Die Moldau war ohnehin ein den Osmanen tributpflichtiges Woiwodat; dieser Feldzug nahm das Land keinem fremden Staat ab, sondern nahm lediglich die innere Verwaltung von Bender und Bucak dem Woiwoden und band sie unmittelbar an den Sultan; der Rest des Woiwodats behielt seinen tributpflichtigen Status. Dieselbe Struktur sollte sich 1484 in Kili und Akkirman und 1713 in Hotin wiederholen: Grenzburgen direkt, Binnenland tributpflichtig.", "96376de1"]},
"OLAYLAR_EK5:1540-11-01:0":{"b": ["Übernahme von Anabolu (Nauplia) durch Vertrag", "104d0937"], "d": ["Der nach Preveza drei Jahre währende Krieg mit Venedig endete damit, dass die Republik einwilligte, ihre letzten beiden Festungen in der Morea abzutreten. Anabolu und Benefşe, die durch Belagerung nicht genommen werden konnten, wurden neben einer Kriegsentschädigung von dreihunderttausend Dukaten am Verhandlungstisch dem Osmanischen Reich übergeben. Die Halbinsel Morea wurde so zu einer Einheit, ohne dass ein einziger venezianischer Fußabdruck blieb.", "4a26ee03"]},
"OLAYLAR_EK5:1543-01-01:0":{"b": ["Übergang Szegeds unter osmanische Verwaltung und Bildung des Livâs Szeged", "019aa000"], "d": ["Nach der vollständigen Errichtung der osmanischen Verwaltung in Buda 1541 erkannten die Notabeln Szegeds die Herrschaft Ferdinands I. an und bereiteten sich auf bewaffnete Verteidigung vor. Der Beylerbey von Buda, Küçük Bâlî Pascha, ließ Anfang 1543 die Stadtverwalter zu sich rufen und wegen Verrats hinrichten, dann entsandte er eine Truppe, um die Stadt einzunehmen. Währenddessen wurde das Livâ Szeged gebildet und Derviş Bey, der Sohn Bâlî Paschas, zum ersten Sandschakbey ernannt; das Livâ erstreckte sich anfangs zwischen Donau und Theiß.", "8293a839"]},
"OLAYLAR_EK5:1543-07-21:0":{"b": ["Eroberung von Valpo, Şikloş und Peçuy", "2ca030a3"], "d": ["Das erste Ziel des zwei Jahre nach der Annexion Budas unternommenen Ungarn-Feldzugs war es, die Südflanke der neuen Provinz zwischen Drau und Donau zu sichern. Nachdem die Festungen Valpo und Şikloş genommen waren, ergab sich Peçuy, das Zentrum der Baranya. Die Stadt sollte zum bevölkerungsreichsten und am stärksten ausgebauten Zentrum des osmanischen Ungarn werden, und der Geschichtsschreiber İbrahim Peçuylu sollte seinen Namen von hier erhalten.", "aacf43d3"]},
"OLAYLAR_EK5:1543-08-10:0":{"b": ["Eroberung von Gran und Stuhlweißenburg", "efca9e05"], "d": ["Im Ungarn-Feldzug, den der Gesetzgeber persönlich unternahm, kam nach einer zweieinhalbwöchigen Belagerung Gran, das religiöse Zentrum des Königreichs Ungarn und Erzbischofsstadt, unter osmanische Verwaltung. Anschließend wurde auch Stuhlweißenburg, die Krönungsstadt der ungarischen Könige, genommen und der Verteidigungsgürtel der Provinz Ofen vollendet. Gran sollte bis 1595 als Schlüsselburg der Donaulinie in osmanischer Hand bleiben.", "93577806"]},
"OLAYLAR_EK5:1544-09-01:0":{"b": ["Nördlicher und westlicher Verteidigungsgürtel Budas: Vaç, Hatvan und Şimontorna", "733ee5ce"], "d": ["Nach der Einnahme von Estergon und Istolni Belgrad setzte sich der Beylerbey von Buda ohne Feldzug des Sultans in Bewegung, um den Festungsring um die Hauptstadt zu vollenden. Vaç am Donauknie, Hatvan, das Tor der Alföld, und Şimontorna an der Sió-Linie wurden nacheinander übernommen. Die Gewinne dieses stillen Jahres machten Buda aus einer Grenzstadt zu einem Provinzzentrum, das hundertvierzig Jahre bestehen sollte.", "0ca98fa3"]},
"OLAYLAR_EK5:1545-12-26:0":{"b": ["Annexion Basras und Zugang zum Persischen Golf", "02f87c11"], "d": ["Râşid ibn Megāmis, der Herrscher von Basra, hatte während der Eroberung Bagdads (1534) Süleyman dem Gesetzgeber seinen Gehorsam erklärt und 1538 die Schlüssel der Stadt gesandt. Als der Nachfolger Scheich Yahyâ gegen die Osmanen Front machte, marschierte der Beylerbey von Bagdad, Ayas Pascha, auf dem Landweg, der Sandschakbey von Mossul mit 120 Schiffen auf dem Euphrat; Ayas Pascha zog am 26. Dezember 1545 in Basra ein, und die Stadt wurde Sitz eines Beylerbeyliks. Dieser Hafen an der Mündung des Schatt al-Arab war das Tor, durch das sich das Osmanische Reich zum Golf öffnete, den Portugal von Hormus aus kontrollierte; durch den Vertrag von Amasya 1555 erkannte auch Iran diesen Zustand an.", "8905782c"]},
"OLAYLAR_EK5:1547-01-01:0":{"b": ["Eroberung von Sanaa und des jemenitischen Binnenlandes", "d31ded85"], "d": ["Nach Taizz wurde auch Sanaa genommen, und das ganze Land wurde dem Beylerbeylik angeschlossen. Wegen der schroffen Geographie und des konfessionellen Unterschieds war diese Herrschaft jedoch nie bequem; der Jemen wurde für das Osmanische Reich zu einer Front, die ständig Soldaten verschlang.", "66968d6d"]},
"OLAYLAR_EK5:1547-02-01:0":{"b": ["Eroberung von Taizz", "d4509df9"], "d": ["Im Jemen, wo man sich neun Jahre zuvor mit dem Küstenstreifen begnügt hatte, stiegen die Kräfte Özdemir Paschas, da die zaiditischen Imame im gebirgigen Landesinneren immer stärker wurden, ins Hochland auf und nahmen Taizz ein.", "46b811eb"]},
"OLAYLAR_EK5:1547-06-18:0":{"b": ["Vertrag von Istanbul – fünfjähriger Friede mit den Habsburgern", "41f81773"], "d": ["Zwischen den Osmanen und den Habsburgern wurde ein auf fünf Jahre befristeter Friede unterzeichnet; Ferdinand willigte ein, für die von ihm gehaltenen ungarischen Gebiete jährlich 30.000 Dukaten zu zahlen. Der Vertrag besiegelte den faktischen Zustand der Dreiteilung Ungarns auch rechtlich. Die damit erreichte Sicherung der Westfront gab dem Gesetzgeber die Möglichkeit, neue Feldzüge gegen Iran zu veranstalten.", "36cfadaa"]},
"OLAYLAR_EK5:1548-07-27:0":{"b": ["Zweiter Iran-Feldzug und erneute Einnahme von Täbris", "e82365df"], "d": ["Bei dem auf Anstiftung von Elkas Mirza, dem Bruder, der gegen Schah Tahmasb rebelliert hatte und nach Istanbul geflohen war, unternommenen Feldzug zog das Heer zum zweiten Mal in Täbris ein. Da die Safawiden sich wieder nicht auf eine Feldschlacht einließen, sondern unter Verbrennung des Landes zurückwichen, konnte man in der Stadt nur wenige Wochen bleiben. Der Feldzug machte endgültig klar, dass Täbris nicht zu halten war, und lenkte die osmanische Strategie darauf, eine dauerhafte Grenzlinie zu errichten, das heißt Van zu befestigen.", "bb2a7ceb"]},
"OLAYLAR_EK5:1548-08-24:0":{"b": ["Eroberung von Van und Festlegung der Ostgrenze", "fc8f930b"], "d": ["Die auf dem Rückweg von Täbris belagerte Festung Van war mit ihrer auf dem Felsen am Ostufer des Sees aufragenden Lage der unbestrittene Schlüssel der Region und ergab sich nach kurzer Belagerung. Die Stadt wurde sofort zum Sitz eines Beylerbeyliks gemacht; die Sandschaks Erciş, Adilcevaz und Hakkâri wurden ihr unterstellt. Anders als Täbris wurde Van gehalten und blieb vierhundert Jahre lang die vorgeschobenste dauerhafte Stellung des Osmanischen Reiches im Osten.", "3ca861b4"]},
"OLAYLAR_EK5:1550-01-01:0":{"b": ["Annexion von al-Hasa und al-Qatif – die arabische Küste des Golfs", "f6701e60"], "d": ["Nach der Einnahme Basras wurde Katîf, das an der Westküste des Golfs zum vorgeschobenen Stützpunkt Portugals geworden war, genommen, und zusammen mit den Oasen von Lahsa im Landesinneren wurde ein neues Beylerbeylik gegründet. Von hier aus gingen die Operationen gegen Bahrain und Hormus aus. Das Osmanische Reich hatte damit zugleich an der Roten-Meer- und an der Persischen-Golf-Küste der Arabischen Halbinsel ein Wort mitzureden.", "240c0b43"]},
"OLAYLAR_EK5:1550-01-01:1":{"b": ["Verlust Schahrisurs – der Herr von Erdelân, Sührâb, neigte den Safawiden zu", "5600efc9"], "d": ["Das Gebiet Schahrisur, das während des Irakeyn-Feldzugs (1535) die osmanische Verwaltung anerkannt hatte, stand unter der Herrschaft des Emirs von Erdelân, Bige Bey, der in der Festung Zalm saß. Nach Bige Beys Tod 1550 nahm sein Bruder Sührâb die Festung Zalm ein, riss die Herrschaft über das Beylik an sich, wandte sich den Safawiden zu und löste sich vom Gehorsam gegenüber dem Osmanischen Reich; das Gebiet Schahrisur schied damit aus dem osmanischen Einfluss aus. Die Region wurde erst während des Nachitschewan-Feldzugs 1554 durch Belagerung und Einnahme der Festung Zalm zurückgewonnen.", "62ddad8a"]},
"OLAYLAR_EK5:1551-01-01:0":{"b": ["Einnahme von Ardahan und des Çıldır-Beckens", "14c9eb76"], "d": ["Der Beylerbey von Erzurum wandte sich während des andauernden Krieges mit den Safawiden den Ländereien der georgischen Atabegs im Kura-Bogen zu und stellte Ardahan sowie die Umgebung von Çıldır unter osmanische Verwaltung. Die Linie Kars–Ardahan wurde damit zu einer Einheit, und die nach Georgien führenden Hochebenen im Nordosten kamen unter Kontrolle. Die endgültige Verwaltungsordnung der Region sollte siebenundzwanzig Jahre später durch das Eyalet Çıldır vollendet werden.", "2f8d92cc"]},
"OLAYLAR_EK5:1551-09-07:0":{"b": ["Sokullu Mehmed Pascha überschreitet die Donau – Beginn des Siebenbürgen-Krieges", "38fde931"], "d": ["Aufgrund der Wirren, die der Mönch Martinuzzi, der Vormund des siebenbürgischen Königs Johann Sigismund, verursachte, und weil Siebenbürgen die Banater Festungen Ferdinand überließ, hielt man einen neuen Feldzug für nötig; der Oberbefehl wurde dem Beylerbey von Rumelien, Sokullu Mehmed Pascha, übertragen. Das Heer überschritt trotz Martinuzzis Hinhaltebemühungen die Donau und nahm Becse, Beçkerek, Çanad und Lippa; die Belagerung von Temeswar wurde jedoch am 16. November wegen der Kälte aufgehoben. Damit war in Ungarn ein neuer osmanisch-habsburgischer Krieg eröffnet.", "85071c5e"]},
"OLAYLAR_EK5:1551-11-06:0":{"b": ["Die Stadt Lipova (Lippa) fällt in die Hand des österreichischen Heeres Castaldos – die Festung ergab sich am 5. Dezember", "a0e1ff0d"], "d": ["Das von Sokullu Mehmed Pascha im Oktober 1551 eingenommene Lipova wurde am 4. November von der Armee General Castaldos belagert; zwei Tage später fiel die Stadt in die Hand der Österreicher. Ulama Pascha verteidigte die Festung mit einer Besatzung von 5.000 Mann noch neun Tage lang und zog am 5. Dezember 1551 aufgrund einer Vereinbarung ab. Bis zum Fall Temeswars 1552 blieb Lipova in habsburgischer Hand.", "22c85b1c"]},
"OLAYLAR_EK5:1552-07-27:0":{"b": ["Besetzung der südbanater Palanken durch von Temeswar entsandte Truppen – Versec, Haram, Keve", "edca0921"], "d": ["Nachdem sich Temeswar dem osmanischen Heer ergeben hatte, wandten sich aus dem Belagerungsheer ausgesonderte Einheiten den kleinen Palanken des Banat zu; nach der Darstellung Bánlakys wurden die Palanken Versec, Facset, Mehádia, Csákóvár, Haramvár und Keve von diesen Truppen besetzt. Damit fiel auch Haram am Donauufer in osmanische Hand.", "a5906d21"]},
"OLAYLAR_EK5:1552-09-04:0":{"b": ["Eroberung von Szolnok und Scheitern der Belagerung von Erlau", "a7156e8f"], "d": ["Die beiden nach der Einnahme von Temeswar vereinigten osmanischen Heere nahmen Szolnok an der Theiß fast ohne Kampf, da die Söldnerwachen die Festung verließen. Die anschließend belagerte Festung Erlau (Eğri) konnte dagegen angesichts des achtunddreißigtägigen Widerstands der zweitausend Mann starken Garnison unter dem Kommando von István Dobó nicht genommen werden, und das Heer zog ab, als der Winter einbrach. Dass im selben Feldzug eine Festung leicht fiel, während die andere standhielt, war das erste offene Zeichen dafür, dass die Grenze in Ungarn nicht mehr von selbst zugunsten des Osmanischen Reiches vorrückte.", "354ed31f"]},
"OLAYLAR_EK5:1553-02-01:0":{"b": ["Osmanisch-französisches Bündnis – die französische Flotte unter osmanischem Befehl", "a8e01b22"], "d": ["Mit dem Vertrag vom 1. Februar 1553 wurde die Flotte Frankreichs dem Befehl der osmanischen Flotte unterstellt; gemeinsame Operationen im westlichen Mittelmeer gegen Spanien wurden vorgesehen. Nach dem Vertrag brach Turgut Reis am 15. Juni 1553 mit fünfundvierzig Galeeren zu einem Feldzug zur Unterstützung Frankreichs auf. Dies war der erste offizielle Bündnisvertrag, der den wirtschaftlichen Boden der Kapitulationen von 1536 zu einer militärischen Zusammenarbeit weiterführte.", "bfa2fc2d"]},
"OLAYLAR_EK5:1553-10-05:0":{"b": ["Hinrichtung des Prinzen Mustafa in Konya Ereğlisi", "dec36858"], "d": ["Der Prinz Mustafa, der zum Heer, das für den Feldzug nach Nachitschewan zusammengezogen worden war, ins Zelt seines Vaters trat, begegnete im Augenblick, da er vor den Sultan treten sollte, den Henkern und wurde erdrosselt. Die Ermordung des im Heer sehr beliebten Thronanwärters erregte unter den Janitscharen tiefen Zorn, und Rüstem Pascha wurde aus dem Großwesirat entlassen. Das Ereignis ging als eine der umstrittensten Brüche der osmanischen Prinzenpolitik in Literatur und Volksgedächtnis ein.", "ce2742ae"]},
"OLAYLAR_EK5:1555-01-01:0":{"b": ["Verlagerung der Grenze bei Ibrim und Nubien nach Süden", "c57d5d77"], "d": ["Die Südgrenze des Beylerbeyliks Ägypten wurde über den zweiten Katarakt hinaus verschoben, indem die auf einem Felsvorsprung am Nil aufragende Festung Ibrim durch Özdemir Bey befestigt und Unternubien vollständig dem osmanischen Ägypten angeschlossen wurde. (Die osmanische Verwaltungsorganisation in Ibrim war nach der Eroberung Ägyptens eingerichtet worden; auf der Karte wird Ibrim ab 1517 als osmanisch gezeigt. Dieses Jahr ist ungefähr, die Quelle nennt kein Jahr.) Die Festung war ebenso ein Damm gegen die Überfälle aus Nubien wie ein Kontrollpunkt des Gold- und Sklavenweges nach Sennar. Die dort angesiedelte bosnische Wachtruppe wurde so dauerhaft, dass ihre Nachkommen dreihundert Jahre später noch in der Festung waren. Die Quellen geben für den Zeitpunkt des Übergangs Ibrims unter osmanische Verwaltung zwei verschiedene Darstellungen: Der TDV-Artikel Sudan bindet den Anschluss Unternubiens an das osmanische Ägypten an die Operation Özdemir Paschas Mitte des 16. Jahrhunderts, während der Artikel Nûbe schreibt, die Region bis zum Tal von Halfa und die Verwaltungsorganisation in Ibrim seien unmittelbar nach der Eroberung von 1517 eingerichtet worden. Der Sandschak Ibrim wurde am 26. Juli 1573 dem Eyalet Habesch angeschlossen.", "cd2c7ae9"]},
"OLAYLAR_EK5:1555-09-27:0":{"b": ["Einnahme von Bidschaya (Bougie) von den Spaniern", "49691cda"], "d": ["Bidschaya, das seit dreiundvierzig Jahren in spanischer Hand war und die Küste zwischen Algier und Konstantine in zwei Teile teilte, ergab sich nach Belagerung zu Land und zu Wasser. Mit dem Fall der Festung wurde die Küste des Algerischen Odschaks bis Oran ununterbrochen. In Spanien rief dieser Verlust solche Empörung hervor, dass der Kommandant Alonso de Peralta, der die Festung übergeben hatte, in seiner Heimat hingerichtet wurde.", "a030d882"]},
"OLAYLAR_EK5:1559-01-01:0":{"b": ["Anschluss von Zeila an das Eyalet Habesch", "7bbf369a"], "d": ["Der Hafen Zeila an der afrikanischen Küste des Golfs von Aden, am Südende des Eyalets Habesch, wurde der osmanischen Verwaltung unterstellt. Diese Stadt, das Tor des Sultanats Adal zum Meer, war der letzte Versorgungspunkt für Schiffe, die über Bab al-Mandab hinausfuhren. Mit dem Anschluss Zeilas erreichte die Grenze des Osmanischen Reiches in Afrika ihren südlichsten Punkt.", "fe4597b7"]},
"OLAYLAR_EK5:1559-05-30:0":{"b": ["Schlacht der Prinzen bei Konya", "1c8de387"], "d": ["Der in den Thronkampf eingetretene Prinz Bayezid kam mit seinen etwa 30.000 Mann vor Konya und unterlag in einem zwei Tage währenden Gefecht seinem Bruder, dem Prinzen Selim. Der besiegte Bayezid flüchtete über Amasya nach Iran zu Schah Tahmasp. Die Schlacht machte die Thronfolgekrise in den letzten Jahren des Gesetzgebers zu einem außenpolitischen Problem.", "d466cfc5"]},
"OLAYLAR_EK5:1560-05-14:0":{"b": ["Seesieg von Djerba", "c7b905c1"], "d": ["Die osmanische Flotte unter dem Kommando von Piyâle Pascha zerstreute die zur Wiedereroberung von Tripolis versammelte spanisch-genuesisch-maltesische Bundesflotte vor Djerba mit dem Manöver der Zweiteilung. Die Verbündeten verloren den größten Teil ihrer Flotten, und auch die Burg auf der Insel fiel in kurzer Zeit. Djerba gilt nach Preveza als der zweite große Seesieg, der die Überlegenheit der Osmanen im Mittelmeer festigte.", "e987b794"]},
"OLAYLAR_EK5:1562-07-23:0":{"b": ["Hinrichtung des Prinzen Bayezid in Kazvin", "a759de14"], "d": ["Der nach Iran geflüchtete Prinz Bayezid wurde nach langen Verhandlungen von Schah Tahmasp einer osmanischen Delegation übergeben und zusammen mit seinen vier Söhnen erdrosselt. Als Gegenleistung für die Auslieferung erlangten die Safawiden bedeutende materielle Zugeständnisse und eine Grenzgarantie. Mit dieser Hinrichtung fiel das letzte Hindernis für die Thronbesteigung Selims II., und die Friedensordnung des Friedens von Amasya blieb gewahrt.", "cf625eb3"]},
"OLAYLAR_EK5:1566-04-14:0":{"b": ["Einnahme von Chios von den Genuesen", "a4559b96"], "d": ["Chios, das zweihundert Jahre lang als Handelskolonie der genuesischen Familie Giustiniani verwaltet worden war und dem Osmanischen Reich Tribut zahlte, wurde von Piyale Pascha mit der Begründung, es habe den Tribut vernachlässigt und feindlichen Schiffen Hafen gewährt, ohne einen einzigen Schuss übernommen. Mit Chios und Psara wurde auch die letzte genuesische Präsenz an der Ostküste der Ägäis beseitigt. Unter Wahrung der Mastixproduktion und der Privilegien der Chioten wurde die Insel dem Eyalet Cezâyir-i Bahr-i Sefîd angeschlossen.", "a5ec4417"]},
"OLAYLAR_EK5:1566-04-15:0":{"b": ["Annexion des Herzogtums Naxos – aller Kykladen", "68f0ec0b"], "d": ["Das lateinische Herzogtum Naxos, das seit 1207 bestand und seit 1537 dem Osmanischen Reich Tribut zahlte, wurde mit der Begründung aufgehoben, es seien Beschwerden eingegangen, weil der letzte Herzog Giacomo Crispo seine Untertanen unterdrückte. Naxos, Paros, Değirmenlik, Andros, Syros, Mykonos, Ios, Amorgos und alle Kykladen in ihrer Umgebung wurden mit einem einzigen Beschluss unmittelbar unter osmanische Verwaltung genommen. Süleyman der Gesetzgeber übertrug die Verwaltung der Inseln eine Zeitlang an Yasef Nasi; die dreieinhalb Jahrhunderte währende lateinische Herrschaft endete damit mitten in der Ägäis.", "d4d7a143"]},
"OLAYLAR_EK5:1567-04-01:0":{"b": ["Aufstand im Jemen und Jemen-Feldzug des Koca Sinan Pascha", "c8218d8e"], "d": ["Der zaiditische Imam al-Mutahhar erhob sich mit der Begründung zwangsweise erhobener Steuern und riss die osmanische Verwaltung aus dem größten Teil des Jemen heraus. Der aus Istanbul entsandte Koca Sinan Pascha stellte mit seiner Unternehmung der Jahre 1568–1570, indem er Kawkabān nach langer Belagerung nahm, die osmanische Herrschaft in der Region wieder her. Der Feldzug war lebenswichtig, um die Kontrolle über das Südtor des Roten Meeres und die Handelsstraße des Indischen Ozeans zu bewahren.", "d4771f85"]},
"OLAYLAR_EK5:1567-10-01:0":{"b": ["Verteidigungsbündnis mit dem Sultanat Aceh und Hilfe im Indischen Ozean", "8e835f24"], "d": ["Die Gesandten von Aceh, die angesichts portugiesischer Angriffe Süleyman den Gesetzgeber um Hilfe gebeten hatten, trugen nach dem Tod des Sultans in Szigetvár Selim II. ihre Treue an, und mit ihm wurde ein Verteidigungsvertrag unterzeichnet. Der Sultan befahl, aus Alexandria Kanonen, Gewehre, Munition und Meister zu senden; siebzehn Kriegsschiffe wurden zur Entsendung in indische Gewässer vorbereitet. Das Anwachsen des Jemen-Aufstands verhinderte das Auslaufen der Flotte, doch die nach Aceh gelangten osmanischen Artilleristen und Meister hinterließen in der Region bleibende Spuren.", "65c41562"]},
"OLAYLAR_EK5:1570-07-02:0":{"b": ["Landung auf Zypern: Einnahme von Limassol", "9074ccc9"], "d": ["Das auf der Insel gelandete osmanische Heer nahm Limassol ohne nennenswerten Widerstand und wandte sich am folgenden Tag Larnaka zu. Weil die einheimische Bevölkerung mit der venezianischen Verwaltung unzufrieden war und den osmanischen Truppen half, stieß man auch in Larnaka auf keinen ernsthaften Widerstand; der Landeplatz Tuzla wurde zur Anlande- und Ausrüstungsbasis gemacht. Venedig hatte seine Verteidigung in Nikosia und Famagusta konzentriert; der Statthalter von Paphos erklärte erst nach dem Fall Nikosias dem Serdar seinen Gehorsam.", "6bbd2fee"]},
"OLAYLAR_EK5:1570-09-09:0":{"b": ["Eroberung von Nikosia", "413d866b"], "d": ["Nach der am 25. Juli 1570 begonnenen und fünfundvierzig Tage währenden Belagerung ergab sich Nikosia, die unter venezianischer Verwaltung stehende Hauptstadt Zyperns, dem osmanischen Heer. Der Fall des Zentrums der Insel drängte den venezianischen Widerstand auf die Festung Famagusta zusammen. Die Eroberung erregte im Westen großes Aufsehen und beschleunigte den Prozess, der zur Gründung der Flotte der Heiligen Liga unter Führung des Papstes führte.", "1ef832d4"]},
"OLAYLAR_EK5:1570-09-17:0":{"b": ["Übergabe von Kyrenia – die Nordküste Zyperns", "39fdeea5"], "d": ["Der Fall Nikosias am 9. September unter Schwertschlägen brach den Widerstand im Norden Zyperns. Die Festung Kyrenia hinter dem Beşparmak-Gebirge ergab sich, als sie das Schicksal der Hauptstadt erfuhr, acht Tage später unter Bedingungen, und ihre Garnison wurde unter Erlaubnis zum Abzug von der Insel entlassen. Auf der Insel blieb die venezianische Fahne nur noch in Famagusta; auch diese sollte noch elf Monate standhalten.", "ecf762c9"]},
"OLAYLAR_EK5:1572-06-01:0":{"b": ["Wiederaufbau der Flotte nach Lepanto", "db51fe44"], "d": ["Das Erste, was Kılıç Ali Pascha, der nach der Niederlage von Lepanto zum Kapudan Pascha ernannt wurde, tat, war der Wiederaufbau der schwer geschädigten Flotte; die Werften arbeiteten im Winter 1571–1572 ununterbrochen. Im Juni 1572 stach eine neue Flotte aus etwa 250 Galeeren und 300 Galeeren freiwilliger Reis ins Mittelmeer. Diese rasche Erholung zeigte, dass Lepanto die osmanische Seemacht nicht dauerhaft hatte brechen können.", "324f2d99"]},
"OLAYLAR_EK5:1573-03-07:0":{"b": ["Vertrag von Istanbul mit Venedig – Anerkennung Zyperns", "4d08ef50"], "d": ["Venedig, das nach der Auflösung der Heiligen Liga allein geblieben war, schloss mit den Osmanen einen separaten Frieden, erkannte offiziell an, dass Zypern den Osmanen gehörte, und willigte ein, Kriegsentschädigung zu zahlen. Der Vertrag zeigte deutlich, dass der Sieg von Lepanto der christlichen Welt keinen politischen Gewinn gebracht hatte. Venedig sollte es danach siebzig Jahre lang vermeiden, unmittelbar in einen Krieg mit den Osmanen einzutreten.", "de6151ba"]},
"OLAYLAR_EK5:1574-12-13:0":{"b": ["Tod Selims II.", "c289f5ee"], "d": ["Selim II. konnte, nachdem er gestürzt war, etwa zwei Monate nicht mehr zum Diwan erscheinen und starb. Sein Tod wurde zwölf Tage lang im Palast geheim gehalten, bis sein ältester Sohn Murad aus Manisa nach Istanbul gekommen war. Über den Todestag gehen die Quellen auseinander: Selânikî nennt den 15. Dezember; Gerlach, Mehmed b. Mehmed und Cenâbî nennen den 13. Dezember.", "e9e279ab"]},
"OLAYLAR_EK5:1574-12-22:0":{"b": ["Verkündung des Todes Selims II. und Thronbesteigung Murads III.", "84334d70"], "d": ["Der Tod Selims II. und die Thronbesteigung Murads III., der aus Manisa herbeigeholt worden war, wurden am 22. Dezember 1574 offiziell verkündet. Der neue Sultan sollte einundzwanzig Jahre auf dem Thron bleiben, und seine Herrschaft sollte im Osten für die langen Iran-Kriege, im Westen für den Vorabend des Langen Krieges und im Inneren für die Münzverschlechterung des Akçe in Erinnerung bleiben. Bis zum Tod Sokollu Mehmed Paschas 1579 blieb die alte Ordnung in der Staatsführung bestehen.", "3e1ec091"]},
"OLAYLAR_EK5:1578-08-04:0":{"b": ["Schlacht von Wadi al-Makhazin (Ksar el-Kebir) – der von den Osmanen unterstützte Abd al-Malik vernichtete das portugiesische Heer", "21280dac"], "d": ["Abd al-Malik, der mit osmanischer Unterstützung den marokkanischen Thron bestiegen hatte, vernichtete das große Heer des portugiesischen Königs Sebastian bei Wadi al-Makhazin; da in der Schlacht drei Herrscher zugleich starben, wird sie in westlichen Quellen „Schlacht der drei Könige“ genannt. Portugals militärische Macht brach zusammen, und das Land fiel kurz darauf in die Hand Spaniens. Auch Abd al-Malik starb in der Schlacht; sein an seine Stelle tretender Bruder Ahmed al-Mansûr meldete den Sieg durch eine Delegation nach Istanbul. Das Verhältnis zwischen den beiden Staaten blieb nicht auf der Ebene von Tribut oder Untertänigkeit, sondern des Austauschs von Gesandten und Geschenken und wurde kurz darauf wegen der Geschenkfrage gespannt.", "0ddf3962"]},
"OLAYLAR_EK5:1578-10-05:0":{"b": ["Treuebekundung der Bevölkerung von Derbent an Lala Mustafa Pascha – Demirkapı unter osmanischer Verwaltung", "9c55aeff"], "d": ["Während des Schirwan-Feldzugs begab sich eine siebenköpfige Abordnung der Bevölkerung von Derbent zum Serdar Lala Mustafa Pascha, der sich in Ereş aufhielt, und bekundete ihre Treue. Derbent (Demirkapı), das den schmalen Pass zwischen der Kaukasusmauer und dem Kaspischen Meer sperrt, spielte als zwingender Durchgang der Landwege aus dem Norden eine Schlüsselrolle für das Halten Schirwans. Die osmanische Herrschaft hielt sich hier bis 1607.", "9776382c"]},
"OLAYLAR_EK5:1578-11-01:0":{"b": ["Eroberung von Schirwan: Einnahme von Schamachi", "9afae4c1"], "d": ["Nach dem Sieg von Çıldır drang das zum Kaukasus aufgebrochene Heer in Schirwan ein, die reichste Provinz der Safawiden an der Kaspischen Küste, und nahm die Zentralstadt Schamachi. Özdemiroğlu Osman Pascha wurde hier zum Beylerbey ernannt, und der Nordarm der Seidenstraße wurde unter osmanische Kontrolle gebracht. Schirwan sollte zur am häufigsten den Besitzer wechselnden und teuersten Front des zwölf Jahre währenden Ostkrieges werden.", "9955f6f2"]},
"OLAYLAR_EK5:1583-08-01:0":{"b": ["Einnahme von Baku – Zugang zur Kaspischen Küste", "eb5adab8"], "d": ["Als letztes Glied der Schirwan-Operation wurde der Hafen Baku an der Westküste des Kaspischen Meeres genommen. Die Erdölquellen um die Stadt waren schon damals eine bekannte Einnahmequelle, und der Hafen war der Ausfuhrpunkt der über das Kaspische Meer kommenden iranischen Seide. Das Osmanische Reich wurde damit zum ersten und einzigen Mal in seiner Geschichte Küstenanrainer des Kaspischen Meeres.", "ffafa858"]},
"OLAYLAR_EK5:1583-09-13:0":{"b": ["Eroberung von Eriwan (Revan) und Bau der Festung", "7f623b7b"], "d": ["Ferhad Pascha, der in Kars den Befehl erhalten hatte, nach Eriwan zu gehen und dort eine Festung zu bauen, marschierte auf Eriwan, und die Stadt wurde Anfang Ramadan 991 (Mitte September 1583) unter osmanische Kontrolle genommen. In Eriwan, das das Nordtor des Araxes-Tals hält, wurde eine neue, große Festung gebaut; die Stadt wurde zum Sitz eines Beylerbeyliks gemacht. Eriwan, das mitten auf der Heerstraße zwischen Kars und Täbris stand, war das logistische Rückgrat der Ostfront. Die Festung wurde so stark gebaut, dass sie in den folgenden zweihundert Jahren das unveränderliche Ziel der osmanisch-iranischen Kriege wurde.", "f6b3bd6e"]},
"OLAYLAR_EK5:1588-09-01:0":{"b": ["Annexion von Karabach und Gandscha", "29abaead"], "d": ["Als letzten Gewinn des zehnjährigen Ostkrieges marschierte Ferhad Pascha 1588 auf Gandscha und zog am 1. September in die Stadt ein; die Region Karabach zwischen Kura und Araxes und ihr Zentrum Gandscha wurden unter osmanische Verwaltung genommen. So vereinigten sich Schirwan, Eriwan und Karabach zu einer ununterbrochenen osmanischen Linie im Kaukasus. Der 1590 unterzeichnete Vertrag von Ferhad Pascha sollte diese Grenze bestätigen, doch der Gewinn konnte nur zwanzig Jahre gehalten werden.", "67f1d89d"]},
"OLAYLAR_EK5:1592-06-19:0":{"b": ["Eroberung von Bihać", "651a7275"], "d": ["Der Beylerbey von Bosnien, Telli Hasan Pascha, nahm im November 1591 Ripač, die Vorburg von Bihać, und eroberte 1592 auch die Stadt und die Burg selbst; nach zehntägiger Belagerung ergab sich der Kommandant Lamberg. Diese Eroberung schob die bosnische Grenze entlang der Una vor und war der letzte große osmanische Gewinn am Vorabend des Langen Krieges, der ein Jahr später mit dem Tod Telli Hasan Paschas vor Kulpa ausbrechen sollte.", "b6814991"]},
"OLAYLAR_EK5:1593-07-01:0":{"b": ["Beginn des osmanisch-österreichischen „Langen Krieges“", "bd22c392"], "d": ["Nachdem der Beylerbey von Bosnien, Telli Hasan Pascha, vor Kulpa (Sisak) vernichtend geschlagen worden und als Märtyrer gefallen war, erklärte das Osmanische Reich Österreich den Krieg, und der dreizehn Jahre währende Lange Krieg begann. Dieser Krieg, in dem die Infanterie mit Feuerwaffen entscheidend war, beschleunigte im osmanischen Heerwesen den Einsatz von Sekban und Gewehrsoldaten und vertiefte den Niedergang der Timar-Reiter (Sipahi). Der Krieg sollte 1606 mit dem Vertrag von Zsitvatorok enden.", "f309a27f"]},
"OLAYLAR_EK5:1593-07-19:0":{"b": ["Koca Sinan Pascha brach zum Österreich-Feldzug auf – erster Feldzug des Langen Krieges", "d4a2f46d"], "d": ["Nachdem der Beylerbey von Bosnien, Hasan Pascha, vor Siska (Sisak) vernichtend geschlagen worden und als Märtyrer gefallen war, überredete der Großwesir Koca Sinan Pascha mit glänzenden Worten und Versprechungen den Sultan zum Krieg und brach mit 12.000 Janitscharen und anderen Einheiten auf. Damit wurde der erste Feldzug des dreizehn Jahre währenden osmanisch-österreichischen Krieges eröffnet.", "0f217276"]},
"OLAYLAR_EK5:1594-09-27:0":{"b": ["Eroberung von Yanıkkale (Raab)", "14b75207"], "d": ["Der Großwesir Koca Sinan Pascha übernahm nach mehr als einem Monat währender Belagerung Yanıkkale, das als Schloss der Straße nach Wien galt. Der Fall der Festung löste in Europa große Panik aus und wurde der glänzendste Gewinn der Osmanen im Langen Krieg. Doch die Festung sollte nur vier Jahre gehalten werden können.", "a634af40"]},
"OLAYLAR_EK5:1595-01-17:0":{"b": ["Tod Murads III.", "1b62e886"], "d": ["Nach einer einundzwanzigjährigen Herrschaft starb Murad III. in den Tagen, in denen das walachische Heer Brăila niederbrannte und bis Silistre vordrang, und wurde auf dem Friedhof der Hagia Sophia beigesetzt. Sein aus Manisa gerufener Sohn Mehmed III. erreichte zehn Tage später Istanbul und bestieg den Thron (27. Januar 1595).", "1deabc61"]},
"OLAYLAR_EK5:1595-09-02:0":{"b": ["Verlust von Gran an Österreich", "f420d333"], "d": ["Die Verteidiger von Gran, die bei der von Karl von Mansfeld geführten Belagerung nicht genug Hilfe erhielten, übergaben die Festung dem Erzherzog Matthias. Mit dem Ende der zweiundfünfzigjährigen osmanischen Herrschaft riss die Verteidigungskette der Donaulinie, und Ofen geriet in unmittelbare Bedrohung. Die Festung konnte erst zehn Jahre später, 1605, zurückgewonnen werden.", "7617d6f2"]},
"OLAYLAR_EK5:1596-10-12:0":{"b": ["Eroberung der Burg Eğri", "3e511629"], "d": ["Nach dreiwöchigem Ringen fiel die starke Burg Eğri (Erlau), die die Osmanen zuvor nie hatten nehmen können, durch die Übergabe der Besatzung. Diese Eroberung, bei der der Sultan persönlich anwesend war, behob die durch den Verlust von Gran entstandene Demoralisierung bis zu einem gewissen Grad, und die Provinz Eğri wurde gegründet. Zusammen mit dem zwei Wochen später errungenen Sieg von Haçova wurde 1596 das erfolgreichste osmanische Jahr des Langen Krieges.", "5dc53fa9"]},
"OLAYLAR_EK5:1598-03-29:0":{"b": ["Verlust von Yanıkkale (Raab)", "b4ccc679"], "d": ["Die Truppen unter dem Kommando von Miklós Pálffy und Adolf von Schwarzenberg sprengten in einem Überfall die Burgtore und eroberten Yanıkkale zurück. Der Verlust der Festung, die Koca Sinan Pascha vier Jahre zuvor mit großer Mühe erlangt hatte, ließ die vorgeschobene Linie der Osmanen in Ungarn zusammenbrechen. Obwohl im selben Jahr die Ofen belagernden feindlichen Truppen zurückgeschlagen wurden, wandelte sich das Gleichgewicht des Krieges allmählich in einen Zermürbungskrieg.", "80bf88e0"]},
"OLAYLAR_EK5:1599-01-01:0":{"b": ["Aufstand des Karayazıcı Abdülhalim", "30493b0d"], "d": ["Karayazıcı Abdülhalim, der die im Langen Krieg aus dem Heer geflohenen Sekban und Levend sammelte, nahm in Zentralanatolien ein weites Gebiet unter seine Kontrolle, eroberte die Burg Urfa (November 1599), rief mit dem Titel „Halim Şah“ seine Herrschaft aus und sandte Fermane, die seine eigene Tugra trugen. Karayazıcı, der als erster Anführer der großen Dschelali-Welle gilt, starb 1602, und die Bewegung wurde von seinem Bruder Deli Hasan fortgeführt. Der Aufstand ist der Beginn der Zeit der „großen Flucht“ (büyük kaçgunluk), in der die anatolischen Bauern in Massen ihr Land verließen.", "ceda9161"]},
"OLAYLAR_EK5:1601-09-10:0":{"b": ["Die Verteidigung von Kanizsa durch Tiryaki Hasan Pascha", "d56a5e6a"], "d": ["Erzherzog Ferdinand und seine Verbündeten, die das ein Jahr zuvor eroberte Kanizsa zurückgewinnen wollten, belagerten die Festung mehr als zwei Monate; Tiryaki Hasan Pascha leistete mit seinen 9000 Mann Widerstand. Obwohl er keine Hilfe von außen erhielt, schlug er die allgemeinen Angriffe zurück und zwang den Feind durch Ausfälle, unter schweren Verlusten abzuziehen. Die Verteidigung wurde in der osmanischen Geschichtsschreibung zum Epos, und die „Belagerung von Kanizsa“ wurde an sich zu einer literarischen Gattung.", "edc6d7b6"]},
"OLAYLAR_EK5:1603-12-20:0":{"b": ["Tod Mehmeds III. und Thronbesteigung Ahmeds I.", "da735fde"], "d": ["Nach dem Tod Mehmeds III. am 20. Dezember bestieg sein vierzehnjähriger Sohn Ahmed I. den Thron. Dass er der erste Sultan war, der im Kindesalter und ohne einen Sandschak innegehabt zu haben, den Thron bestieg, zeigt, dass die Sitte, die Prinzen in der Provinz zu erziehen, faktisch zu Ende war. In der Herrschaft Ahmeds I. sollte der Brudermord aufgegeben und zum Prinzip der „ekberiyet“ (Thronfolge des ältesten männlichen Mitglieds) übergegangen werden.", "a5f7151a"]},
"OLAYLAR_EK5:1605-10-03:0":{"b": ["Rückeroberung von Gran", "7330f273"], "d": ["Der Großwesir Lala Mehmed Pascha belagerte das zehn Jahre zuvor verlorene Gran und gliederte es erneut der osmanischen Verwaltung an. Im selben Feldzug wurden auch Pest und Vác zurückgewonnen, und die Osmanen hatten ihre Linie in Ungarn wieder gefestigt. Dieser Erfolg sorgte dafür, dass man im folgenden Jahr in Zsitvatorok verhältnismäßig stark am Tisch saß; Gran sollte bis 1683 in osmanischer Hand bleiben.", "242d3547"]},
"OLAYLAR_EK5:1607-10-24:0":{"b": ["Sieg auf der Oruç-Ebene und Niederschlagung des Canbolatoğlu-Aufstands", "30f93532"], "d": ["Canbolatoğlu Ali Pascha, der in Aleppo ein unabhängiges Beylik gegründet hatte und ein Bündnis mit der Toskana suchte, wurde vom Großwesir Kuyucu Murad Pascha auf der Oruç-Ebene schwer geschlagen. Mit der Wiedererrichtung der zentralen Autorität in Syrien wurde der gefährlichste Zweig der Dschelali-Welle gebrochen. Die zwei Jahre währende gnadenlose Säuberung Kuyucu Murad Paschas sicherte in Anatolien, wenn auch nur vorübergehend, die Ordnung.", "6e620c57"]},
"OLAYLAR_EK5:1608-08-09:0":{"b": ["Sieg von Alaçayır und Niederschlagung des Kalenderoğlu-Aufstands", "55db0485"], "d": ["Der dschelalische Anführer Kalenderoğlu, der die Gegenden von Manisa und Bursa zur Tributzahlung zwang, wurde von Kuyucu Murad Pascha bei Alaçayır vernichtend geschlagen und musste nach Iran fliehen. Mit diesem Sieg wurde das letzte der großen Dschelali-Heere in Anatolien zerschlagen. Obwohl Kuyucu Murad Paschas harte Säuberung, bei der er die von ihm getöteten Aufständischen angeblich in von ihm gegrabene Brunnen füllen ließ, kurzfristig Ordnung brachte, konnte sie den Bevölkerungs- und Produktionsverlust Anatoliens nicht ausgleichen.", "dc332b4b"]},
"OLAYLAR_EK5:1612-07-06:0":{"b": ["Erste Ahdname für die Niederlande", "5d9d117e"], "d": ["Cornelis Haga, der Gesandte der Republik der Vereinigten Niederlande, erreichte von Ahmed I. eine Ahdname im gleichen Umfang wie die für Frankreich und England. Die Niederlande erlangten damit das Recht, in Istanbul eine Gesandtschaft, in osmanischen Häfen Konsulate zu eröffnen und unter eigener Flagge Handel zu treiben. Diese Ahdname symbolisiert den Eintritt der nördlichen Seemächte, die im Mittelmeerhandel den Platz Venedigs einnahmen, in den osmanischen Markt.", "7991027b"]},
"OLAYLAR_EK5:1617-11-22:0":{"b": ["Tod Ahmeds I. und Thronbesteigung Mustafas I. – das Prinzip der ekberiyet", "9901c09e"], "d": ["Nach einer einundfünfzig Tage währenden Magenkrankheit starb der achtundzwanzigjährige Ahmed I., und anstelle seines Sohnes wurde sein Bruder Mustafa I. auf den Thron gesetzt. Damit wurde das von Vater auf Sohn übergehende Erbfolgeprinzip aufgegeben und faktisch zum System der „ekberiyet“ übergegangen, in dem das älteste männliche Mitglied der Dynastie den Thron besteigt. Diese erste, sechsundneunzig Tage währende Herrschaft ist zugleich der Beginn der Zeit, in der die Prinzen im „Kafes“ aufwuchsen.", "1f866a67"]},
"OLAYLAR_EK5:1618-02-26:0":{"b": ["Absetzung Mustafas I. und Thronbesteigung des jungen Osman (Osmans II.)", "e0f552f2"], "d": ["Mustafa I. wurde nach sechsundneunzig Tagen mit der Begründung, seine geistige Gesundheit sei nicht in Ordnung, vom Thron gestoßen, und der vierzehnjährige Sohn Ahmeds I., Osman II., wurde Sultan. Nach einer auf Hasanbeyzâde beruhenden Überlieferung war bei dieser Absetzung der Kızlar Ağası Mustafa Ağa einflussreich. Der junge Osman gilt mit seinem Plan, das Janitscharenkorps abzuschaffen und ein neues Heer aufzustellen, als der erste radikale Name der osmanischen Reformdebatten. Dieser Plan sollte ihm vier Jahre später das Leben kosten.", "4d655aca"]},
"OLAYLAR_EK5:1618-09-26:0":{"b": ["Vertrag von Serav – Erneuerung des Friedens mit Iran", "e778aca8"], "d": ["Der nach der Niederlage von Pul-i Schikaste mit Iran erzielte Vertrag von Serav bestätigte weitgehend die Bedingungen des Vertrags von Nasuh Pascha von 1612; die Menge der jährlich von den Safawiden zu sendenden Seide wurde von zweihundert Lasten auf hundert Lasten herabgesetzt. Damit ging die zweite Phase der seit 1603 währenden Ostkriege zu Ende. Der Friede sollte nicht langlebig sein; mit dem Verlust Bagdads 1623 sollte der Krieg wieder aufflammen.", "f14d72aa"]},
"OLAYLAR_EK5:1621-10-09:0":{"b": ["Hotin-Feldzug und Vertrag von Hotin", "bc4c823c"], "d": ["Das von Chodkiewicz vor Hotin errichtete befestigte Lager konnte vom großen Heer unter dem persönlichen Kommando Osmans II. nicht überwunden werden, und nach monatelangen Angriffen wurde kein Ergebnis erzielt. Mit dem am 9. Oktober unterzeichneten Vertrag wurde der Dnister als Grenze anerkannt, und die Polen verpflichteten sich, die Kosakenüberfälle zu verhindern. Der Feldzug, der trotz seiner Darstellung als Sieg keine Ergebnisse brachte, verstärkte das Misstrauen des jungen Sultans gegenüber den Janitscharen und seine Absicht, das Korps zu säubern.", "7d812c58"]},
"OLAYLAR_EK5:1623-09-10:0":{"b": ["Zweite Absetzung Mustafas I. und Thronbesteigung Murads IV.", "1b3a9e74"], "d": ["Mustafa I., der nach der Ermordung Osmans II. zum zweiten Mal auf den Thron gesetzt worden war, wurde nach einem Jahr und drei Monaten erneut abgesetzt, und der elfjährige Murad IV. wurde zum Sultan ausgerufen. Die ersten neun Jahre wurde der Staat faktisch von seiner Mutter Kösem Sultan und den Palastgrößen regiert. Murad IV. sollte ab 1632 die Regierung persönlich übernehmen und eine Zeit harter Zentralisierung einleiten.", "6dea0fec"]},
"OLAYLAR_EK5:1623-11-28:0":{"b": ["Verlust Bagdads an die Safawiden", "db81be0c"], "d": ["Nach den Verhandlungen, die der in Bagdad aufständische Bekir Subaşı mit den Safawiden geführt hatte, übergab sein Sohn Derviş Mehmed, der die Innenburg verteidigte, die Stadt den Truppen Schah Abbas’. Dass eine der Symbolstädte des Kalifatserbes und der größte Teil des Irak verloren gingen, erregte in Istanbul große Empörung. Bagdad zurückzugewinnen sollte fünfzehn Jahre lang das einzige Ziel der osmanischen Ostpolitik sein.", "ef09360d"]},
"OLAYLAR_EK5:1628-09-22:0":{"b": ["Niederschlagung des Aufstands des Abaza Mehmed Pascha mit Zentrum Erzurum", "e6da2729"], "d": ["Der Beylerbey von Erzurum, Abaza Mehmed Pascha, der sich mit dem Anspruch, die Ermordung Osmans II. zu rächen, gegen die Janitscharen erhoben hatte, hielt Ostanatolien jahrelang unter seiner Kontrolle und leistete dem Zentrum Widerstand. Er musste sich der Belagerung Erzurums durch den Großwesir Hüsrev Pascha ergeben, wurde begnadigt und nach Bosnien versetzt. Das Ende des Aufstands war die Voraussetzung dafür, dass Murad IV. einen Feldzug gegen Iran unternehmen konnte.", "68311e29"]},
"OLAYLAR_EK5:1634-01-08:0":{"b": ["Erste Hinrichtung eines Scheich ül-Islam: Ahîzâde Hüseyin Efendi", "a60a58c5"], "d": ["Der Scheich ül-Islam Ahîzâde Hüseyin Efendi wurde unter Hinweis darauf, dass er in der militärischen Unruhe vermittelt und dem Sultan eine schriftliche Warnung zum Rechtsverfahren gesandt hatte, bei Büyükçekmece hingerichtet. Dass er der erste hingerichtete osmanische Scheich ül-Islam war, brach die tief verwurzelte Tradition, dass die schwerste Strafe für Angehörige der Ilmiye die Verbannung war. Das Ereignis gilt als Symbol der sich verhärtenden Autorität Murads IV. und der Störung des Gleichgewichts zwischen Staat und Ulema.", "2822f303"]},
"OLAYLAR_EK5:1635-08-08:0":{"b": ["Murads IV. Eroberung von Eriwan", "b65a9b73"], "d": ["Murad IV., der am 28. März 1635 aus Istanbul aufgebrochen war, belagerte Eriwan am 28.–29. Juli und übernahm die Festung am 8. August; anschließend zog er in das geräumte Täbris ein und ließ die Stadt zerstören. Der Sultan ließ zum Gedenken an den Sieg im Topkapı-Palast den Eriwan-Pavillon (Revan Köşkü) errichten. Dieser Feldzug war nach einer dreißigjährigen Pause die erste große Ostunternehmung, bei der der Sultan persönlich das Heer befehligte.", "2da4da04"]},
"OLAYLAR_EK5:1636-04-01:0":{"b": ["Verlust von Eriwan an die Safawiden", "fbb8dd25"], "d": ["Nach dem Abzug des osmanischen Heeres belagerten die Truppen Schah Safis Eriwan und eroberten es binnen acht Monaten zurück. Dass die Festung so schnell verloren ging, zeigte, wie schwierig dauerhafte Herrschaft im Kaukasus logistisch war. Eriwan sollte auch durch den Vertrag von Qasr-e Schirin 1639 in Iran belassen werden, und die Osmanen sollten auf ihren Anspruch auf Aserbaidschan verzichten.", "f90cb004"]},
"OLAYLAR_EK5:1638-12-24:0":{"b": ["Rückeroberung Bagdads", "4d2f27f3"], "d": ["Murad IV., der am 8. Mai 1638 aus Istanbul aufgebrochen war, nahm nach vierzig Tage währender heftiger Belagerung das seit fünfzehn Jahren in safawidischer Hand befindliche Bagdad zurück; bei der Belagerung fiel der Wesir Tayyar Mehmed Pascha als Märtyrer. Mit der Eroberung der Stadt wurde die osmanische Verwaltung im Irak wiederhergestellt, und der Sultan nahm den Titel „Eroberer Bagdads“ an. Die Eroberung wurde durch den Vertrag von Qasr-e Schirin im folgenden Jahr dauerhaft und legte den Grundstein der heutigen türkisch-iranischen Grenze.", "bb99d1fb"]},
"OLAYLAR_EK5:1640-02-09:0":{"b": ["Tod Murads IV. und Thronbesteigung Sultan İbrahims", "e2ca1ca0"], "d": ["Nach dem Tod des achtundzwanzigjährigen Murad IV. bestieg sein Bruder İbrahim, das einzige überlebende männliche Mitglied der Dynastie, den Thron. In der Herrschaft des neuen Sultans, der jahrelang im Kafes gelebt hatte, erschütterten Palastausgaben und Machtkämpfe im Palast die Ordnung des Staates. Acht Jahre später sollte durch seine Absetzung und Ermordung der zweite Sultansmord der osmanischen Geschichte erfolgen.", "4c336200"]},
"OLAYLAR_EK5:1642-02-26:0":{"b": ["Rückeroberung der Burg Asow von den Kosaken", "e5fcf160"], "d": ["Die 1637 von den Donkosaken eingenommene Burg Asow wurde angesichts der gemeinsamen Unternehmung von Sultanzâde Mehmed Pascha und dem Krim-Khan Mehmed IV. Giray geräumt; die Kosaken zogen ab, nachdem sie die Burg in Brand gesetzt hatten. Die Rückgewinnung des Nordtors des Schwarzen Meeres beendete die gefährliche Zeit, in der die Kosakenüberfälle bis an den Bosporus reichten. Die Burg sollte 1696 diesmal an den russischen Zaren Peter I. verloren gehen.", "39448f1f"]},
"OLAYLAR_EK5:1645-08-22:0":{"b": ["Beginn des Kreta-Feldzugs und Eroberung von Hanya", "a1b0c77f"], "d": ["Unter dem Vorwand, dass maltesische Korsaren ein osmanisches Pilgerschiff beschossen und auf Kreta Zuflucht gesucht hätten, wurde Venedig der Krieg erklärt, und die Flotte unter dem Kommando von Yûsuf Pascha landete Truppen auf der Insel. Nach vierundfünfzigtägiger Belagerung wurde die Burg Hanya genommen und auf Kreta der erste dauerhafte osmanische Stützpunkt errichtet. Damit begann der am längsten währende Krieg der osmanischen Geschichte; die Insel sollte erst vierundzwanzig Jahre später, 1669, vollständig erobert werden.", "2809708a"]},
"OLAYLAR_EK5:1646-11-13:0":{"b": ["Eroberung von Rethymno – Teilung Kretas", "8f2c4353"], "d": ["Ein Jahr nach der Einnahme von Chania fiel auch die Festung Rethymno im mittleren Teil der Insel, und die Westhälfte Kretas kam vollständig unter osmanische Verwaltung. In Venedigs Hand blieben nur die Hauptstadt Kandia und das Ostende; die Insel lebte dreiundzwanzig Jahre lang zweigeteilt. Die Einnahme Rethymnos war der Schritt, der die Belagerung Kandias einleitete – die längste Belagerung der Geschichte begann hier.", "88ec9840"]},
"OLAYLAR_EK5:1648-03-31:0":{"b": ["Verlust von Klis an Venedig", "5473c22c"], "d": ["Der Gegenangriff des venezianischen Kommandanten Leonardo Foscolo an der dalmatinischen Front des Kreta-Krieges (Kandiye-Krieges) umfasste auch Klis, das seit 1537 Sandschakzentrum war; die Burg ging an Venedig über. Dass sich die Osmanen mit aller Kraft auf Kreta konzentrierten, machte die Rückgewinnung dieses Verlusts an der dalmatinischen Grenze unmöglich – Klis sollte nie wieder unter osmanische Verwaltung zurückkehren; das Sandschakzentrum wurde nach Livno verlegt.", "d0ec59d4"]},
"OLAYLAR_EK5:1648-05-01:0":{"b": ["Beginn der Belagerung von Kandiye", "13016b10"], "d": ["Nach der Einnahme von Hanya und Resmo nahm das osmanische Heer Kandiye, Venedigs letzten großen Stützpunkt auf der Insel, unter Belagerung. Diese einundzwanzig Jahre währende Blockade ging als eine der längsten Belagerungen der Weltkriegsgeschichte in die Aufzeichnungen ein. Die Versuche der venezianischen Flotte, während der Belagerung die Dardanellen zu sperren, sollten den Krieg ins Herz der Ägäis tragen.", "8a35e8f9"]},
"OLAYLAR_EK5:1651-09-02:0":{"b": ["Ermordung der Großen Valide Kösem Sultan", "9d763f79"], "d": ["Die etwa zweiundsechzigjährige Kösem Sultan wurde von Başlala Uzun Süleyman Ağa und seinen Männern, die auf Befehl Turhan Sultans, der Mutter Mehmeds IV., handelten, in einem Zimmer im Harem gefunden und getötet. Der Tod dieser mächtigen Dynastiefrau, die unter drei Sultanen die Staatspolitik gelenkt hatte, gilt als faktisches Ende der als „Frauenherrschaft“ bezeichneten Zeit. Die frei gewordene Autorität öffnete fünf Jahre später den Weg dazu, dass Köprülü Mehmed Pascha mit außerordentlichen Vollmachten Großwesir wurde.", "d1ff09cb"]},
"OLAYLAR_EK5:1656-07-13:0":{"b": ["Niederlage in den Dardanellen und Verlust von Tenedos und Lemnos", "e01a1f7e"], "d": ["Der große Seesieg des venezianischen Admirals Mocenigo im Juni 1656 vor den Dardanellen vernichtete die osmanische Flotte nahezu vollständig; anschließend wurden Tenedos, Lemnos und Samothrake besetzt. Als die Meerenge unter venezianische Blockade geriet, schnellten in Istanbul die Lebensmittelpreise in die Höhe, und die Furcht vor einem Angriff auf die Hauptstadt breitete sich aus. Diese Katastrophe war der unmittelbare Grund dafür, dass Köprülü Mehmed Pascha im September 1656 unter Bedingungen und mit außerordentlichen Vollmachten zum Großwesir ernannt wurde.", "31f7a914"]},
"OLAYLAR_EK5:1657-08-25:0":{"b": ["Sieg in den Dardanellen und Rückeroberung von Tenedos", "603da863"], "d": ["Die von Köprülü Mehmed Pascha mobilisierte Flotte schlug am 19. Juli 1657 vor der Meerenge die venezianische Flotte; anschließend nahmen die Truppen unter dem Kommando von Kurd Pascha am 25. August Tenedos zurück, und am 30. August räumten die Venezianer die Insel vollständig. Im November wurde auch Lemnos befreit, die Dardanellen-Blockade gebrochen und der Versorgungsweg Istanbuls wieder geöffnet. Köprülü setzte persönlich auf die Insel über und ließ die Befestigungen instand setzen; dieser Erfolg ist der erste große militärische Gewinn der Köprülü-Zeit.", "af4d7bfd"]},
"OLAYLAR_EK5:1657-11-15:0":{"b": ["Rückeroberung Limnos von Venedig", "a4c3c69b"], "d": ["Limnos, das Venedig im Juli 1656 genommen hatte, kehrte im November 1657 zum Osmanischen Reich zurück.", "1d61fe33"]},
"OLAYLAR_EK5:1658-08-27:0":{"b": ["Eroberung von Yanova (Ineu) und Siebenbürgen-Feldzug", "d1089616"], "d": ["Köprülü Mehmed Pascha, der zur Bestrafung des Fürsten von Siebenbürgen Georg II. Rákóczi ausgezogen war, der ohne Erlaubnis einen Polen-Feldzug unternommen und damit den osmanischen Schutz missachtet hatte, nahm auf dem Marsch über Belgrad die strategische Burg Yanova. In Siebenbürgen wurde ein neuer Fürst eingesetzt und das Vasallenverhältnis unsanft in Erinnerung gerufen. Dieser Feldzug war das erste Glied des Versuchs der Osmanen, ihre Autorität in Mitteleuropa wiederherzustellen. Siebenbürgen war ohnehin ein den Osmanen tributpflichtiges Fürstentum; mit der Einnahme von Yanova wurde nicht von einem fremden Staat erobert, sondern diese Burg des tributpflichtigen Siebenbürgen aus der Verwaltung des Fürstentums herausgelöst und unmittelbar dem osmanischen Sandschak angegliedert; der Rest des Fürstentums blieb im tributpflichtigen Status.", "4e24d834"]},
"OLAYLAR_EK5:1659-02-16:0":{"b": ["Niederschlagung des Aufstands des Abaza Hasan Pascha", "4ba74321"], "d": ["Abaza Hasan Pascha, der gegen die harten Säuberungen Köprülü Mehmed Paschas die anatolischen Beylerbeys und Sekban-Agas hinter sich brachte, begann einen großen Aufstand und forderte die Absetzung des Großwesirs. Der Aufstand wurde in Aleppo niedergeschlagen und die Rädelsführer beseitigt; dies war der letzte kollektive Widerstand der Provinzpaschas gegen das Zentrum. Köprülüs Autorität wurde damit unbestritten, und das Großwesirat erhob sich wieder in die Stellung des wirklichen Exekutivzentrums des Staates.", "900e66b5"]},
"OLAYLAR_EK5:1660-08-27:0":{"b": ["Eroberung von Varad (Oradea)", "0e6ad300"], "d": ["Im Rahmen des Feldzugs gegen den Fürsten von Siebenbürgen Georg II. Rákóczi, der den Osmanen den Krieg erklärt hatte, wurden die Burg und die Stadt Varad genommen. Mit dem Fall einer der Schlüsselburgen Siebenbürgens wurde in der Region eine neue osmanische Provinz (Provinz Varad) gegründet. Die Eroberung versetzte die Habsburger in Alarm und wurde zu einem der unmittelbaren Gründe des drei Jahre später beginnenden osmanisch-österreichischen Krieges. Weitere am selben Datum angegliederte Orte: Varat. Auch hier wurde das Land keinem fremden Staat abgenommen: Siebenbürgen war bereits ein tributpflichtiges osmanisches Fürstentum; dass Varad zur Provinz wurde, löste lediglich die Verwaltung dieser Stadt aus dem tributpflichtigen Fürstentum und band sie unmittelbar an den Sultan, genau wie zwei Jahre zuvor in Yanova.", "991162de"]},
"OLAYLAR_EK5:1664-08-01:0":{"b": ["Schlacht von St. Gotthard", "61ebc1f2"], "d": ["Die osmanischen Truppen, die die Raab überschritten hatten, wurden von dem unter dem Kommando Montecuccolis stehenden verbündeten europäischen Heer aufgehalten und erlitten schwere Verluste. Die Schlacht gilt in der Militärgeschichte als Wendepunkt, weil sie erstmals offen die Überlegenheit des disziplinierten Gewehrfeuers der Feuerwaffen-Infanterie gegenüber dem osmanischen Reiterangriff zeigte. Trotz der Niederlage gelang es den Osmanen, im neun Tage später unterzeichneten Vertrag von Vasvar vorteilhafte Bedingungen zu erlangen.", "4ab743fc"]},
"OLAYLAR_EK5:1664-08-09:0":{"b": ["Vertrag von Vasvar", "089c978c"], "d": ["Der trotz der Niederlage von St. Gotthard unterzeichnete Vertrag bestimmte, dass Neuhäusel (Uyvar) und Varad bei den Osmanen blieben, Siebenbürgen unter osmanischem Schutz neutral belassen wurde und Österreich ein „Geschenk“ von 200.000 Kuruş zahlte. Dieser auf zwanzig Jahre befristete Friede gehört zu den seltenen Beispielen, in denen die den Krieg verlierende Seite am Tisch gewann. Die Unzufriedenheit, die der Vertrag in der habsburgischen Öffentlichkeit hervorrief, sollte die Bewegung der Mittelungarn und indirekt den Wien-Feldzug von 1683 nähren.", "61ca5d47"]},
"OLAYLAR_EK5:1671-01-01:0":{"b": ["Beginn der Dey-Herrschaft in Algier", "e99faa51"], "d": ["Das Korps von Algier und die Taife der Reis (Korsarenkapitäne) setzten den letzten Aga ab und wählten Hacı Mehmed auf Lebenszeit zum Dey. Von da an wurde Algier nicht mehr von einem aus Istanbul ernannten Beylerbey, sondern von dem aus dem Korps selbst gewählten Dey regiert; die osmanische Bindung beschränkte sich auf die Verlesung des Sultansnamens in der Chutba sowie auf Fahne und Feldzugspflicht. Algier wandelte sich so von einer Provinz zu einem Odschak – denselben Wandel erlebten Tunis 1705 mit den Husainiden und Tripolis 1711 mit den Karamanlı.", "b8decd95"]},
"OLAYLAR_EK5:1672-06-04:0":{"b": ["Beginn des Polen-Feldzugs – Mehmed IV. und Fâzıl Ahmed Pascha an der Spitze des Heeres", "75e15a39"], "d": ["Als die Angriffe Polens auf den unter osmanischen Schutz getretenen ukrainischen Hetman Petro Doroschenko anhielten, verlangte Istanbul vom polnischen König, von den Angriffen abzulassen; da keine zustimmende Antwort kam, wurde der Feldzug gegen Polen beschlossen. Der Großwesir Fâzıl Ahmed Pascha brach am 4. Juni 1672 mit dem Heer, bei dem auch der Sultan war, nach Polen auf. Der Feldzug sollte mit der Eroberung von Kamaniçe und dem Vertrag von Bucaş enden.", "7340721a"]},
"OLAYLAR_EK5:1672-08-27:0":{"b": ["Eroberung von Kamaniçe und Gründung der Provinz Podolien", "c3f4f6d0"], "d": ["Nach neuntägiger Belagerung wurde Kamaniçe, das als stärkste Festung Polens im Osten galt, übernommen; Mehmed IV. verrichtete am 2. September in der aus der Kathedrale umgewandelten Moschee das erste Freitagsgebet. Mit der Festung als Zentrum wurde die Provinz Podolien gegründet, und die osmanische Fahne erreichte auf dem Gebiet der heutigen Ukraine ihren nördlichsten Punkt. Kamaniçe sollte bis zum Vertrag von Karlowitz 1699 die nordwestliche Spitze des Reiches bleiben.", "d89c513a"]},
"OLAYLAR_EK5:1674-08-03:0":{"b": ["Kara Mustafa Pascha übernahm Uman von Polen", "0d3543a0"], "d": ["Kara Mustafa Pascha, der gegen Polen entsandt worden war, übernahm Uman, eine der in polnischer Hand befindlichen Burgen; die Stadt blieb bis Karlowitz unter osmanischer Verwaltung.", "bdb8e553"]},
"OLAYLAR_EK5:1678-08-21:0":{"b": ["Eroberung der Burg Çehrin", "a17cedd0"], "d": ["Nach dem Unternehmen des Vorjahres, bei dem Melek İbrahim Pascha kein Ergebnis erzielt hatte, belagerte der Großwesir Merzifonlu Kara Mustafa Pascha die befestigte Burg Çehrin unter persönlichem Kommando (19./21. Juli) und nahm sie am 21. August ein. Der Fall der Burg, des Symbols der osmanisch-russischen Rivalität um das Kosaken-Hetmanat in der Ukraine, zwang Russland zum Frieden. Dieser Erfolg war eine der Quellen des Selbstvertrauens Merzifonlus, das sich auf Wien richten sollte.", "aee53ec4"]},
"OLAYLAR_EK5:1681-02-13:0":{"b": ["Vertrag von Bahçesaray – erster offizieller Friede mit Russland", "df82bc0b"], "d": ["Nach Verhandlungen, die nach den Çehrin-Feldzügen durch Vermittlung des Krim-Khans geführt wurden, wurde zwischen dem Osmanischen Reich und Russland unter Anerkennung des Dnepr (Özü) als Grenze ein zwanzigjähriger Friede unterzeichnet. Da dies der erste umfassende Vertrag zwischen den beiden Staaten war, gilt er als Ausgangsdokument der osmanisch-russischen Beziehungen. Dank des Friedens wurde die Ostfront gesichert, und das Heer konnte nach Mitteleuropa gelenkt werden.", "56f57388"]},
"OLAYLAR_EK5:1682-09-16:0":{"b": ["Verleihung des Berats über das Königtum Mittelungarns an Imre Thököly", "3cd8d51d"], "d": ["Der gegen den habsburgischen Druck aufständische protestantische ungarische Adlige Imre Thököly galt ab April 1682 als „gewählter König von Mittelungarn“, und am 16. September überreichte ihm der Beylerbey von Ofen, İbrahim Pascha, die Fürstenzeichen. Damit wurde unter osmanischem Schutz ein neuer ungarischer Vasallenstaat errichtet. Dieses Eingreifen machte den Krieg mit Österreich unvermeidlich und setzte die Kette in Gang, die zur Zweiten Belagerung Wiens im folgenden Jahr führte.", "6f7f5236"]},
"OLAYLAR_EK5:1684-08-06:0":{"b": ["Verlust von Ayamavra (Lefkada) an Venedig", "e6905fee"], "d": ["Die Flotte Venedigs, das der Heiligen Liga beigetreten war, beschoss die Stadt und besetzte dann die Insel Ayamavra im Ionischen Meer. Als im selben Jahr auch Preveza fiel, wurde die osmanische Kontrolle an der Mündung der Adria gebrochen. Diese Verluste waren die Anfangsschritte der Unternehmung, mit der Morosini binnen drei Jahren die gesamte Morea in seine Hand bringen sollte.", "8fe34c55"]},
"OLAYLAR_EK5:1685-08-11:0":{"b": ["Verlust von Koron an Venedig", "2ed762bc"], "d": ["Die venezianischen Truppen unter Morosini nahmen die Burg Koron an der Südwestspitze der Morea-Halbinsel ein; die Stadt sollte danach dreißig Jahre unter venezianischer Verwaltung bleiben. Der Fall Korons war der erste große Gewinn der venezianischen Unternehmung zur Eroberung der Morea. Die Burg konnte erst 1715 vom osmanischen Heer unter dem Kommando von Silâhdar Ali Pascha zurückgewonnen werden.", "506cf83e"]},
"OLAYLAR_EK5:1688-04-08:0":{"b": ["Rückeroberung Athens – Abzug Venedigs", "03393b46"], "d": ["Morosini, der im September 1687 die Akropolis beschossen und den Parthenon in die Luft gesprengt hatte, erkannte nach dem Überwintern in Athen, dass er sich in der Stadt nicht halten konnte. Wegen der Pestepidemie, der Nachschubschwierigkeiten und der Erholung der osmanischen Kräfte räumte die venezianische Garnison die Stadt und zog sich auf die Morea zurück. Athen kehrte so ohne Kampf wieder unter osmanische Verwaltung zurück, doch die Zerstörung des Parthenon war nicht wiedergutzumachen.", "79c8586a"]},
"OLAYLAR_EK5:1688-06-22:0":{"b": ["Lipova (Lippa) ergab sich Caraffa – fiel an Österreich", "7f0a8d38"], "d": ["Nach der dreitägigen Belagerung durch Antonio Caraffa ergab sich Lipova zwischen dem 12. und 22. Juni 1688 und fiel an Österreich. Die Osmanen nahmen die Stadt später zurück, Österreich eroberte sie 1691 erneut; im Feldzug von 1695 stellte das Osmanische Reich die Kontrolle wieder her.", "9ddd4e2f"]},
"OLAYLAR_EK5:1688-10-20:0":{"b": ["Abwehr der venezianischen Belagerung von Eğriboz", "aae7e6a0"], "d": ["Morosini, der sich nach der Eroberung der Morea der Ägäis zuwandte, versuchte in einer mehr als drei Monate währenden Belagerung Eğriboz zu nehmen; angesichts der im Winter 1687–1688 verstärkten Befestigungen und des Widerstands der Garnison musste er sich unter schweren Verlusten zurückziehen. Dieses Scheitern hielt Venedigs Vormarsch in der Ägäis auf und erschütterte Morosinis militärisches Ansehen. Eğriboz sollte auch in Karlowitz in osmanischer Hand bleiben.", "ea8430a3"]},
"OLAYLAR_EK5:1690-04-23:0":{"b": ["Verlust der Burg Kanizsa an Österreich", "553b45f3"], "d": ["Kanizsa, seit Januar 1690 in der engen Blockade eines 60.000 Mann starken habsburgischen Heeres, leistete monatelang ohne Hilfe Widerstand und ging durch die von seinem letzten Befehlshaber Mustafa Pascha unterzeichnete Übergabevereinbarung verloren. Damit endete in der Burg, die durch die epische Verteidigung Tiryaki Hasan Paschas in Erinnerung geblieben war, die neunzigjährige osmanische Herrschaft. Der Verlust Kanizsas war der Zusammenbruch der letzten großen Stütze der Osmanen im Westen Ungarns.", "dc630d57"]},
"OLAYLAR_EK5:1691-06-22:0":{"b": ["Tod Süleymans II.", "d2478080"], "d": ["Süleyman II., der nach etwa vierzig Jahren im Kafes 1687 auf den Thron gesetzt worden war, starb kränklich, während er die Vorbereitungen des Heeres verfolgte, am Freitag, dem 22. Juni 1691, gegen Mittag in Edirne; seine Regierungszeit hatte drei Jahre, acht Monate und zwei Tage gedauert. Der Großwesir hatte die notwendige Anweisung, im Falle des Todes des Sultans seinen Bruder Ahmed auf den Thron zu setzen, im Voraus gegeben. Das Totengebet wurde am selben Tag im Alay-Pavillon gesprochen; sein Leichnam wurde nach Istanbul gebracht und im Mausoleum Süleymans des Gesetzgebers an dessen rechter Seite beigesetzt.", "3cf4fcb1"]},
"OLAYLAR_EK5:1691-06-23:0":{"b": ["Thronbesteigung Ahmeds II.", "52947b14"], "d": ["Nach dem Tod Süleymans II. bestieg dessen neunundvierzigjähriger Bruder Ahmed II. in Edirne den Thron. Seine Herrschaft fiel in die schwersten Jahre der Kriege der Heiligen Liga; zwei Monate nach seiner Thronbesteigung fiel bei Slankamen der Großwesir Fâzıl Mustafa Pascha als Märtyrer. Dagegen wurde das in seiner Zeit eingeführte Malikâne-System zu einer der wichtigsten Regelungen, die die langfristige Struktur der osmanischen Finanzen veränderten.", "d3441b14"]},
"OLAYLAR_EK5:1693-01-06:0":{"b": ["Tod Mehmeds IV. in Edirne", "17388b7e"], "d": ["Der 1687 abgesetzte Avcı Mehmed wurde während des Ungarn-Feldzugs Süleymans II. 1689 nach Edirne gebracht und wurde auch Zeuge der Regierungszeit seines anderen Bruders Ahmed II. Er starb in dieser von ihm so sehr geliebten Stadt. Sein Leichnam wurde nach Istanbul gebracht und im Mausoleum seiner Mutter Turhan Sultan neben der Yenicami beigesetzt.", "fd0f3d8c"]},
"OLAYLAR_EK5:1695-02-06:0":{"b": ["Tod Ahmeds II. in Edirne", "c6306c08"], "d": ["Ahmed II., dessen vierjährige Regierungszeit im Krieg verging, starb im Alter von zweiundfünfzig Jahren in Edirne an istiskā (Wassersucht). Sein Leichnam wurde nach Istanbul gebracht und im Mausoleum Süleymans des Gesetzgebers beigesetzt. An seine Stelle trat sein Neffe Mustafa II.", "a61e819c"]},
"OLAYLAR_EK5:1696-01-01:0":{"b": ["Einnahme Basras durch die Iraner", "a9cdf3a3"], "d": ["Während das Osmanische Reich in den Kriegen der Heiligen Liga im Westen beschäftigt war, wurde Basra nach der Pestepidemie von 1690 zunächst vom Muntafiq-Scheich Mâni und dann von Ferecullah, dem Khan von Huweiza, geplündert. Die Iraner nutzten dieses Durcheinander, nahmen 1696 die Stadt ein und ließen in Basra eine Wache zurück.", "2db76d27"]},
"OLAYLAR_EK5:1700-07-14:0":{"b": ["Vertrag von Istanbul – Überlassung Asows an Russland", "79db4724"], "d": ["In Karlowitz hatte mit Russland nur ein zweijähriger Waffenstillstand geschlossen werden können; der dauerhafte Friede wurde in Istanbul nach anderthalb Jahre währenden harten Verhandlungen unterzeichnet. Das Osmanische Reich trat die 1696 verlorene Burg Asow und die umliegenden Gebiete offiziell an Russland ab und verzichtete auf die jährliche Steuer des Krim-Khans von Moskau. Dafür erlangte Russland das Recht, in Istanbul einen ständigen Gesandten zu halten; damit wurde die russische Präsenz an der Nordküste des Schwarzen Meeres rechtlich besiegelt.", "a3a5a803"]},
"OLAYLAR_EK5:1701-01-01:0":{"b": ["Rückeroberung von Kürne und Basra durch Daltaban Mustafa Pascha", "7adb777d"], "d": ["Daltaban Mustafa Pascha, der nach dem Frieden von Karlowitz zum Statthalter von Bagdad und zum Seraskier von Basra ernannt worden war, marschierte mit den Kräften von Aleppo, Rakka, Sivas und Karaman sowie einer von Birecik herabfahrenden Flussflotte nach Süden. Die Stammesscheichs der Umgebung unterwarfen sich einer nach dem anderen, der iranische Befehlshaber von Basra, Dâvud Khan, verließ die Stadt, und Kürne und Basra kamen wieder unter osmanische Verwaltung.", "60abbe06"]},
"OLAYLAR_EK5:1703-12-29:0":{"b": ["Tod Mustafas II.", "626c394d"], "d": ["Mustafa II., der durch den Edirne-Vorfall den Thron seinem Bruder Ahmed III. überlassen hatte, starb etwa fünf Monate nach seiner Absetzung in dem von ihm so sehr geliebten Edirne. Zu seiner Krankheit kam noch der Kummer über die jüngsten Entwicklungen hinzu. Einige westliche Quellen schreiben, dass im Volk die Überzeugung weit verbreitet war, er sei vergiftet worden.", "8ce146e8"]},
"OLAYLAR_EK5:1704-01-01:0":{"b": ["Beginn der Kölemen- (Mamluken-)Herrschaft in Bagdad", "abe52618"], "d": ["Mit der Ernennung des Hasan Pascha georgischer Herkunft zum Statthalter von Bagdad begann im Irak die Zeit, in der anstelle von vom Zentrum ernannten Statthaltern eine aus ihren eigenen Sklaven herangezogene Verwalterschicht herrschte. Mit der Statthalterschaft Süleyman Paschas 1749 festigte sich das System, und die Hohe Pforte musste nicht mehr die Person ernennen, die sie wollte, sondern einen der Kölemen, die den Einfluss in der Hand hielten. Obwohl sich diese halbautonome Struktur bei der Verteidigung der iranischen Grenze bewährte, schwächte sie die Kontrolle der zentralen Autorität über den Irak anderthalb Jahrhunderte lang.", "7cf655d4"]},
"OLAYLAR_EK5:1705-07-12:0":{"b": ["Gründung der Husainiden-Dynastie in Tunis", "cb1a98f9"], "d": ["Im Machtvakuum, das durch die Invasion von Tunis durch algerische Truppen entstanden war, ergriff der Sipahi-Aga türkischer Herkunft Hüseyin b. Ali das Beylik und erlangte Legitimität, indem er dem osmanischen Sultan seine Treue erklärte. Die von ihm gegründete Dynastie regierte Tunis in den Jahren 1705–1735 und 1756–1957; an die Stelle der Odschak-Verwaltung trat eine von Vater auf Sohn übergehende Beylik-Ordnung. Damit entstand das erste Beispiel von an das Zentrum gebundenen, faktisch aber autonomen dynastischen Strukturen in den Odschaks des Westens (Garp).", "941c7858"]},
"OLAYLAR_EK5:1708-04-04:0":{"b": ["Einnahme von Oran und Mers el-Kébir von den Spaniern", "b67ce06a"], "d": ["Die Truppen des Beylerbey des Odschaks von Algier nahmen nach langer Belagerung Oran, das seit zwei Jahrhunderten in der Hand der spanischen Garnison war, und den Hafen Mers el-Kébir ein. Es war der größte Erfolg der unter osmanischem Schutz stehenden Odschaks des Westens gegen Spanien im westlichen Mittelmeer und sicherte die Westflanke Algiers. Die Stadt sollte 1732 erneut spanisch besetzt werden, aber 1792 endgültig zurückgewonnen werden.", "33d9da74"]},
"OLAYLAR_EK5:1711-07-21:0":{"b": ["Vertrag vom Prut – Rückgewinnung von Asow und Taganrog", "bac5d2a1"], "d": ["Der nach der Kapitulation des am Prut eingeschlossenen russischen Heeres unterzeichnete siebenartikelige Vertrag bestimmte die Rückgabe der Burg Asow samt Gelände und Munition an die Osmanen. Die Festungen Taganrog, Kamenka und Yenikale sollten geschleift werden, und die Parteien sollten in diesen Gebieten keine neuen Burgen bauen. Die von Peter I. in sechzehn Jahren in Woronesch und Asow aufgebaute Flotten- und Stützpunktordnung brach zusammen; Russlands Zugang zum Schwarzen Meer verzögerte sich um etwa fünfzig Jahre.", "657d45ff"]},
"OLAYLAR_EK5:1711-07-29:0":{"b": ["Gründung der Karamanli-Dynastie in Tripolis (Tripolitanien)", "e1105d4a"], "d": ["In Tripolitanien, das von den Streitigkeiten der Odschak-Agas erschöpft war, ergriff der Reiteroffizier Ahmed Karamanlı die Herrschaft und machte seine Stellung durch das aus Istanbul erhaltene Beylerbey-Berat offiziell. Durch Ahmed Pascha, seinen Sohn Mehmed Pascha und seinen Enkel Yûsuf Pascha entstand eine Dynastie, die von 1711 bis 1835 währte; es entstand eine halbunabhängige Struktur, die eine eigene Flotte aufbaute und mit europäischen Staaten unmittelbar Verträge unterzeichnete. Diese Zeit sollte erst 1835 enden, als die Provinz unmittelbar an das Zentrum gebunden wurde.", "b1c3dd0a"]},
"OLAYLAR_EK5:1713-06-24:0":{"b": ["Vertrag von Edirne mit Russland", "14901a70"], "d": ["Nachdem die am Prut gegebenen Versprechen nicht erfüllt worden waren, war zweimal erneut der Krieg erklärt worden; schließlich wurde, als die Russen die Verpflichtungen annahmen, in Edirne ein dauerhafter Friede unterzeichnet. Der Vertrag bestätigte die Prut-Bedingungen; Russland werde sich nicht in die polnischen Angelegenheiten einmischen, sich aus dem Kosakengebiet zurückziehen und die Rückkehr des schwedischen Königs Karl XII. („Demirbaş Şarl“) in sein Land nicht behindern. Der damit erreichte Abschluss der Nordfront ermöglichte es dem Osmanischen Reich, sein Gesicht der Front von Morea und Venedig zuzuwenden. Weitere am selben Datum angegliederte Orte: Hotin.", "34010e06"]},
"OLAYLAR_EK5:1714-12-08:0":{"b": ["Kriegserklärung an Venedig – Vorbereitung des Morea-Feldzugs", "d970b122"], "d": ["Unter Hinweis darauf, dass Venedig die montenegrinischen Aufständischen unterstützte, osmanische Handelsschiffe beschlagnahmte und die in Karlowitz erlangte Morea mit schweren Steuern erdrückte, wurde im Diwan der Kriegsbeschluss gefasst. Der vom Großwesir Silâhdar Damad Ali Pascha vorbereitete Feldzug sollte im folgenden Jahr in weniger als hundert Tagen zur Rückgewinnung der gesamten Morea-Halbinsel führen. Doch dieser Erfolg sollte Österreich in Bewegung setzen und 1716 die Tür zu einem weit schwereren Krieg öffnen.", "ef2edb5f"]},
"OLAYLAR_EK5:1715-06-05:0":{"b": ["İstendil (Tinos): Übergabe der letzten Insel Venedigs in der Ägäis", "4abec891"], "d": ["Die zum Morea-Feldzug ausgelaufene Flotte ging unterwegs vor İstendil vor Anker, der einzigen Insel, die Venedig in der Ägäis noch in der Hand hatte. Die Insel, die dank ihrer lateinischen Bevölkerung noch hundertfünfzig Jahre die venezianische Flagge getragen hatte, obwohl das Herzogtum Naxos 1566 gefallen war, ergab sich nach kurzer Belagerung ohne Blutvergießen. Damit wurde Venedigs letzter Fußabdruck in der Ägäis getilgt, und das Meer wurde vollständig zu einem osmanischen Binnenmeer.", "7b191aca"]},
"OLAYLAR_EK5:1715-07-20:0":{"b": ["Eroberung von Anabolu – die Schlüsselfestung der Morea", "62a5808a"], "d": ["Anabolu, die Hauptstadt Venedigs auf der Morea und seine stärkste Befestigung, fiel, als die Bastion Palamidi nach neuntägigem Bombardement genommen wurde. Die so schnelle Einnahme der Festung brach den Widerstand auf dem Rest der Halbinsel. Die Rückgewinnung der in Karlowitz verlorenen Morea war faktisch hier vollendet.", "9b883577"]},
"OLAYLAR_EK5:1715-08-01:0":{"b": ["Übergabe von Modon", "43faa909"], "d": ["Nach dem Fall von Anabolu wurde die Festung Modon an der Südwestspitze der Morea vom Heer zu Land und von der Flotte zu Wasser belagert und ergab sich rasch. Dieser Hafen, den Venedig zweihundert Jahre lang in seinen Ostmittelmeer-Feldzügen nutzte, war der unumgängliche Anlaufpunkt, an dem die Schiffe Wasser und Proviant aufnahmen. Sein Verlust beendete die Bewegungsfreiheit der venezianischen Flotte in der Ägäis.", "0d2c6d1a"]},
"OLAYLAR_EK5:1715-08-16:0":{"b": ["Übergabe von Koron – Abschluss des Morea-Feldzugs", "e4b9c8a4"], "d": ["Mit der Übergabe der Festung Koron, die die Mündung des Golfs von Messenien hält, endete die venezianische Herrschaft auf der Halbinsel Morea vollständig. Die in Karlowitz verlorene Halbinsel war nur drei Monate nach Eröffnung des Feldzugs vollständig zurückgewonnen. In der Fortsetzung desselben Feldzugs wurde im September 1715 auch die Insel Ayamavra (Leukas) im Ionischen Meer Venedig abgenommen. Diese Geschwindigkeit zwang Venedig, Österreich in den Krieg hineinzuziehen, und öffnete drei Jahre später den Weg nach Passarowitz.", "d3173b05"]},
"OLAYLAR_EK5:1715-09-07:0":{"b": ["Einnahme der Insel Çuha (Kythira)", "494de6c6"], "d": ["Die Insel Çuha an der Südspitze der Morea wurde nach der Vollendung der Halbinsel von der Flotte übernommen. Die Insel, die den Übergang zwischen Ionischem Meer und Ägäis überwachte, war der vorgeschobene Posten, mit dem Venedig diese Gewässer kontrollierte. Sie blieb jedoch nicht die einzige gehaltene osmanische Insel: Drei Jahre später wurde sie in Passarowitz an Venedig zurückgegeben.", "42162c0d"]},
"OLAYLAR_EK5:1716-04-13:0":{"b": ["Österreich und Venedig schlossen ein Bündnis – Tor zum Osmanisch-Österreichischen Krieg von 1716–1718", "99511ca2"], "d": ["Nachdem die Osmanen die Morea von Venedig zurückgenommen hatten, schloss Österreich unter Berufung darauf, dass der Vertrag von Karlowitz verletzt worden sei, mit Venedig einen Bündnisvertrag; Prinz Eugen verlangte in einem Brief an den Großwesir die Rückgabe der Venedig abgenommenen Gebiete. Bei der Beratung im Lager von Davudpaşa wurde auf den Druck des Großwesirs Ali Pascha hin Österreich der Krieg erklärt, und dazu wurde vom Scheich ül-Islam ein Fetwa eingeholt.", "4a2089d7"]},
"OLAYLAR_EK5:1716-04-24:0":{"b": ["Großwesir Ali Pascha brach zum Österreich-Feldzug auf", "2fbdce42"], "d": ["Nach der Kriegserklärung an Österreich brach der Serdar-ı Ekrem Ali Pascha mit einem Heer von mehr als 100.000 Mann zum Österreich-Feldzug auf; die Flotte wandte sich im selben Sommer Korfu zu. Das Heer sollte von Belgrad auf Peterwardein marschieren, und in der Niederlage Anfang August sollte der Großwesir als Märtyrer fallen.", "02a5590b"]},
"OLAYLAR_EK5:1716-08-05:0":{"b": ["Niederlage von Peterwardein (Varadin) – Märtyrertod Damad Ali Paschas", "265c1d81"], "d": ["Das osmanische Heer, das von Belgrad aus die Donau überschritt, stieß vor Peterwardein auf die österreichischen Truppen unter dem Kommando des Prinzen Eugen; zwar zwang der Janitscharenangriff beim ersten Ansturm die feindlichen Schützengräben, doch mit dem Zusammenbruch des Reiterflügels lösten sich die Reihen auf. Der Großwesir Silâhdar Damad Ali Pascha fiel, an der Stirn getroffen, als Märtyrer, Lager und Artillerietross fielen vollständig in die Hand des Feindes. Diese Niederlage, die die osmanischen Chroniken als „Jahr von Varadin“ erwähnen, war das erste Glied der Kette, die zum Verlust Temeswars und im folgenden Jahr Belgrads führte.", "ad21a2c3"]},
"OLAYLAR_EK5:1716-08-20:0":{"b": ["Scheitern der Belagerung von Korfu", "b2aa7011"], "d": ["Der Seraskier der Morea, Kara Mustafa Pascha, von Land, und der Kapudan Pascha Canım Hoca Mehmed Pascha mit der Flotte von See drangen auf Korfu ein; die Insel war Venedigs Schlüsselstützpunkt in der Adria. Doch die äußerst starken Befestigungen der Burg, die von der venezianischen Flotte gebrachten Verstärkungen und die Nachrichten von der Niederlage an der Donaufront führten zur Aufhebung der Belagerung. Dass Korfu nicht genommen werden konnte, löschte die durch die Wiedereroberung der Morea gestiegene Stimmung aus und verlagerte den Schwerpunkt des Krieges nach Ungarn.", "4589579c"]},
"OLAYLAR_EK5:1716-10-13:0":{"b": ["Verlust von Temeswar (Timișoara) an Österreich", "27fe1365"], "d": ["Nach der Niederlage von Peterwardein marschierte Prinz Eugen unmittelbar auf Temeswar, und die Burg wurde nach einer mehr als vierzig Tage währenden Belagerung durch Vertrag übergeben. Die Stadt, die 1552 zur Zeit des Gesetzgebers erobert worden war und 164 Jahre lang als Beylerbeylik-Zentrum der Ostpfeiler der Verteidigung Ungarns gegolten hatte, ging damit verloren. Mit dem Fall Temeswars fiel die gesamte Region Banat an Österreich, und die osmanische Grenze wurde südlich der Donau zurückgedrängt.", "3f3368fd"]},
"OLAYLAR_EK5:1716-11-16:0":{"b": ["Übergabe der Burg Haram (Neu-Palanka) an Österreich – das Donauufer des Banat ging verloren", "38ee4c6d"], "d": ["Der österreichische Kavalleriegeneral Mercy, der nach dem Fall Temeswars mit der Einnahme des restlichen Banat beauftragt war, marschierte am 14. November auf Haram (Neu-Palanka) am Donauufer; als er am 16. November bei der Burg ankam, ergab sich die 200 Mann starke osmanische Garnison unter Hissen der weißen Fahne mit der Bedingung freien Abzugs. Damit ging auch die Donaulinie des seit 1552 in osmanischer Hand befindlichen Südbanat an Österreich über.", "8026e3e4"]},
"OLAYLAR_EK5:1718-07-21:0":{"b": ["Vertrag von Passarowitz – Morea gewonnen, Belgrad und Banat verloren", "d46aa216"], "d": ["Von Venedig war die Morea zurückgewonnen worden, doch das in den Krieg eingetretene Österreich gewann mit seinen Siegen bei Petrovaradin und Belgrad die Oberhand am Verhandlungstisch. Der unter Vermittlung Englands und der Niederlande unterzeichnete Vertrag ließ die Morea beim Osmanischen Reich, dafür wurden Nordserbien samt Belgrad, das Banat und die Kleine Walachei Österreich überlassen; nach der Formulierung des TDV „ist Nordbosnien vollständig Österreich überlassen worden“ – Festungen wie Bosna Dubiça und Bosna Brod an der Save gehen auf der Karte ab diesem Tag an Österreich über (die genaue Grenze zogen Kommissare einzeln, das TDV nennt diese Festungen nicht namentlich); Venedig dagegen behielt seine Stellungen an der Ionischen Küste wie Preveza und Çuha. Durch den am selben Tag unterzeichneten Handels-Ahidname wurde der Zoll auf österreichische Waren von fünf auf drei Prozent gesenkt. Während der Vertrag den Rückzug des Osmanischen Reiches in Mitteleuropa besiegelte, legte der von ihm eröffnete siebenundzwanzigjährige Frieden den Boden der Tulpenzeit (1718–1730): Unter der Verwaltung des Nevşehirli Damad İbrahim Pascha sind die erste osmanische Druckerei (1727, İbrahim Müteferrika), Übersetzungskommissionen, Beobachtungen zur Pockenimpfung und ein neues Palast- und Kulturleben Erzeugnisse dieser Friedensjahre.", "3a9f1433"]},
"OLAYLAR_EK5:1723-06-15:0":{"b": ["Ostfeldzug: Einnahme von Tiflis und Beginn des Iran-Krieges", "78343dc2"], "d": ["Als der Safawidenstaat durch die afghanische Invasion zusammenbrach und Russland an die Küsten des Kaspischen Meeres herabstieg, entsandte das Osmanische Reich ein Heer nach Osten, damit das Vakuum nicht vollständig dem russischen Einfluss überlassen bleibe. Mit der Einnahme von Tiflis wurde Georgien der osmanischen Verwaltung angegliedert; anschließend setzte sich der Vormarsch in Richtung Gence, Eriwan und Nachitschewan fort. Dieser Feldzug, der hinter dem friedlichen Anschein der Tulpenzeit geführt wurde, wurde der Beginn eines langen Ostabenteuers, das dreizehn Jahre währen und schließlich mit der Rückgabe aller gewonnenen Orte enden sollte.", "5c412d91"]},
"OLAYLAR_EK5:1723-08-01:0":{"b": ["Iran-Feldzug von 1723: Einmarsch in Schirwan und Georgien", "c81189fc"], "d": ["Nach dem Zusammenbruch des Safawidenstaates durch die afghanische Invasion wurde mit der Begründung, ein Herabsteigen Russlands an die Kaspische Küste verhindern zu müssen, ein Feldzug nach Osten eröffnet. Das Heer von Erzurum zog über Georgien nach Tiflis, der Schirwan-Arm nach Schamachi, und sie nahmen die vor hundertdreißig Jahren verlorenen Gebiete zurück. Dieser Feldzug war der letzte große Vormarsch des Osmanischen Reiches im Kaukasus.", "9f84acd9"]},
"OLAYLAR_EK5:1723-10-01:0":{"b": ["Einnahme von Kermanschah – das Tor des Zagros", "ad14799f"], "d": ["Das Heer von Bagdad überwand die Pässe des Zagros und nahm Kermanschah ein, das als Westtor Irans galt. Die Stadt lag an der Karawanen- und Heerstraße von Bagdad nach Isfahan, und ihre Einnahme sicherte die Ostsicherheit der Provinz Irak. Dieser Vormarsch eröffnete im zerfallenen Safawidenland den Teilungswettlauf zwischen dem Osmanischen Reich und Russland.", "65dba49c"]},
"OLAYLAR_EK5:1724-06-24:0":{"b": ["Teilungsvertrag von Istanbul – Aufteilung Irans mit Russland", "fce8eec2"], "d": ["Um zu verhindern, dass die Osmanen und Russland über das zusammenbrechende Safawidenland aneinandergerieten, wurde durch Vermittlung des französischen Gesandten ein Teilungsvertrag unterzeichnet. Die West- und Südküste des Kaspischen Meeres wurden Russland, Georgien, Schirwan, Aserbaidschan und die Städte Westirans dem Osmanischen Reich überlassen. Diese Aufteilung, die auf dem Papier wie ein großer Gewinn aussah, sollte durch den Aufstieg Nadir Schahs kurz darauf faktisch ungültig werden.", "36a04f61"]},
"OLAYLAR_EK5:1724-08-11:0":{"b": ["Einnahme von Nachitschewan", "bdf14d0a"], "d": ["Die entlang des Araxes vorrückenden osmanischen Kräfte nahmen Nachitschewan und Ordubad; auch Julfa wurde dem Livâ Nachitschewan angeschlossen. Die Stadt wurde als Nordwesttor Irans dem neu gegründeten Eyalet Eriwan unterstellt. So erreichte die osmanische Grenze wieder die östlichste Linie aus der Zeit Süleymans des Gesetzgebers.", "9e602879"]},
"OLAYLAR_EK5:1724-08-31:0":{"b": ["Eroberung von Hamadan", "e1339a97"], "d": ["Das von Kermanschah nach Osten marschierende Heer nahm nach langer Belagerung Hamadan an der Westschwelle des iranischen Hochlandes. Die Stadt war die letzte große Station der Straße nach Isfahan, des östlichsten Punktes, den osmanische Heere seit dem Irakeyn-Feldzug erreichen konnten. Die im selben Jahr mit Russland unterzeichnete Konvention von Istanbul brachte die Teilung des zerfallenden Iran zwischen dem Osmanischen Reich und Russland zu Papier.", "81552031"]},
"OLAYLAR_EK5:1724-10-03:0":{"b": ["Erneute Eroberung von Eriwan", "88acabef"], "d": ["Nach einer neunzig Tage währenden zähen Belagerung kam Eriwan, die Schlüsselfestung des Araxes-Tals, wieder unter osmanische Verwaltung. Die 1583 erbaute und 1604 verlorene Festung wurde diesmal mit einer stärkeren Garnison befestigt. Die Länge der Belagerung zeigte, dass das osmanische Heer nicht mehr leicht vorankam. Auch die Nahiyes Karpi (Üçkilise), Şerür, Makû und Şüregel wurden dem Eyalet Eriwan angeschlossen.", "a989b1eb"]},
"OLAYLAR_EK5:1725-07-28:0":{"b": ["Die Einnahme von Täbris – Eroberung Aserbaidschans", "e502a4f7"], "d": ["Täbris, das nach dem gescheiterten Versuch des Vorjahres erneut belagert wurde, ergab sich nach einem zähen Straßenkampf dem osmanischen Heer. Auch Merend, Merâga und Sovukbulak (Mahabad), die zur Provinz Täbris gehörten, kamen unter osmanische Verwaltung. Im selben Jahr wurden außerdem Lori, Gandscha, Ardabil und Hürremâbâd genommen, sodass die dem Osmanischen Reich im Vertrag von Istanbul zugefallenen Gebiete tatsächlich besetzt waren. Diese im Osten erreichte Ausdehnung war die weiteste Grenze seit der Zeit des Vertrags von Ferhad Pascha; ihre Behauptung belastete jedoch Heer und Staatskasse schwer.", "e0953563"]},
"OLAYLAR_EK5:1725-09-04:0":{"b": ["Eroberung von Gandscha – Ende des Kaukasus-Feldzugs", "875bca7a"], "d": ["Gandscha, das letzte Ziel der Kaukasus-Operation, wurde als Zentrum Karabachs zwischen Kura und Araxes übernommen. Mit der Vollendung der Linie Schirwan, Eriwan, Nachitschewan und Gandscha erreichte das Osmanische Reich im Kaukasus die Ausdehnung von 1590. Dieser Gewinn war jedoch kurzlebig: Der Aufstieg Nâdir Schahs sollte die gesamte Region innerhalb von zehn Jahren zurückgewinnen.", "265db7e0"]},
"OLAYLAR_EK5:1727-10-04:0":{"b": ["Vertrag von Hamadan – Anschluss Westirans an das Osmanische Reich", "94a29dc3"], "d": ["Der mit dem afghanischen Herrscher Aschraf Schah geschlossene Vertrag beendete den vier Jahre währenden Krieg und erkannte die vom Osmanischen Reich besetzten westiranischen Gebiete rechtlich an. Aschraf Schah erkannte im Gegenzug das Kalifat des osmanischen Sultans an und verpflichtete sich, in Iran die Chutba im Namen des Sultans verlesen zu lassen. Dieser diplomatische Erfolg war nur von kurzer Dauer; die Gegenoffensive, die Nâdir Schah 1730 begann, sollte die Gewinne des Vertrags innerhalb weniger Jahre zunichtemachen.", "fd0174b9"]},
"OLAYLAR_EK5:1731-01-01:0":{"b": ["Hekimoğlu Ali Pascha nahm Rûmiye ein", "eac7f64d"], "d": ["Im Iran-Feldzug nahm Hekimoğlu Ali Pascha zuerst Urmia (Rûmiye), dann das dem Osmanischen Reich geräumte Täbris am 15. November 1731. Der TDV nennt den Tag der Einnahme Urmias nicht; bekannt ist nur das Jahr und dass sie vor Täbris lag.", "f99d74f9"]},
"OLAYLAR_EK5:1732-01-08:0":{"b": ["Vertrag von Ahmed Pascha – Rückgabe des größten Teils Westirans", "590d839f"], "d": ["Nach Nâdir Schahs Sieg bei Melâyir und den aufeinanderfolgenden iranischen Offensiven unterzeichnete der Statthalter von Bagdad, Ahmed Pascha, ohne Rücksprache mit dem Zentrum einen Friedenstext. Dem Vertrag zufolge wurde der Aras als Grenze anerkannt; die westiranischen Städte wie Hamadan, Kermanschah, Erdelan, Ardabil und Täbris wurden an Iran zurückgegeben, Gandscha und Tiflis verblieben beim Osmanischen Reich. Dieser in Istanbul mit Empörung aufgenommene Text wurde auch von Nâdir Schah als unzureichend empfunden, und noch vor Ablauf des Jahres 1732 flammte der Krieg erneut auf.", "b7cf810a"]},
"OLAYLAR_EK5:1732-07-01:0":{"b": ["Erneuter Verlust Orans an Spanien", "20485027"], "d": ["Die von König Philipp V. von Spanien entsandte große Landungsflotte erschien unter dem Befehl des Grafen von Montemar vor Oran, schlug die Kräfte des Algerischen Odschaks und nahm die Stadt zurück. Der vor vierundzwanzig Jahren eroberte Hafen sollte sechzig Jahre lang wieder in der Hand einer spanischen Garnison bleiben. Dieser Verlust, der die Grenzen der Macht der westlichen Odschaks im westlichen Mittelmeer aufzeigte, konnte erst 1792 durch die endgültige Eroberung Orans wettgemacht werden.", "b255a8da"]},
"OLAYLAR_EK5:1733-05-01:0":{"b": ["Reform des Humbaracı-Korps nach europäischem Muster und Gründung der Humbarahâne", "d980cf2a"], "d": ["Der in osmanische Dienste getretene Humbaracı Ahmed Pascha französischer Herkunft machte mit der Unterstützung des Großwesirs Hekimoğlu Ali Pascha das Humbaracı-Korps zu einer besoldeten, nach europäischer Art geordneten Truppe. Dreihundert aus Bosnien rekrutierte Soldaten erhielten eine regelmäßige, auf Rechnen und Geometrie beruhende Ausbildung; neue Verordnungen für Organisation, Ausrüstung und Ruhestand wurden ausgearbeitet, und mit zeitgemäßer Technik wurden einhundert Mörser und fünfzigtausend Granaten hergestellt. Die Humbarahâne, in der Geometrie unterrichtet wurde, gilt als der erste Kern der modernen militärischen Ingenieurausbildung im Osmanischen Reich.", "181b7161"]},
"OLAYLAR_EK5:1736-06-24:0":{"b": ["Tod Ahmeds III.", "455f7fba"], "d": ["Ahmed III., der 1730 durch den Aufstand des Patrona Halil abgesetzt worden war, verbrachte die letzten sechs Jahre seines Lebens in dem für abgesetzte Sultane bestimmten Trakt des Topkapı-Palastes und starb im Alter von dreiundsechzig Jahren. Er wurde am Bahçekapı im Mausoleum seiner Großmutter Turhan Sultan neben der Yenicami beigesetzt.", "00cc8767"]},
"OLAYLAR_EK5:1736-09-01:0":{"b": ["Vertrag von Istanbul – Abtretung des Südkaukasus an Iran", "8c205aab"], "d": ["Der vier Jahre dauernde zweite Iran-Krieg endete mit einem Vertrag, der nach der Niederlage am Arpaçay und dem Verlust von Gandscha und Tiflis unterzeichnet wurde. Das Osmanische Reich zog sich aus allen seit 1723 eroberten Gebieten des Südkaukasus und Westirans zurück; die Grenze kehrte zur Linie von Kasr-ı Şîrin von 1639 zurück. Von den dreizehn Jahren der Ostfeldzüge blieben eine schwere finanzielle Last und eine geleerte Staatskasse; dafür war der Abschluss der Ostfront für den neuen Krieg gegen Russland ein lebenswichtiger Gewinn.", "bcb0cbe8"]},
"OLAYLAR_EK5:1737-07-11:0":{"b": ["Fall der Festung Özi (Otschakow) an die Russen", "f93e61f3"], "d": ["Das russische Heer unter Feldmarschall Münnich belagerte die Festung Özi an der Dnjepr-Mündung; als das Munitionsdepot explodierte, brach die Verteidigung zusammen, und die Festung fiel unter großen Verlusten. Der Verlust Özis, das als Schlüssel zur nordwestlichen Schwarzmeerküste galt, öffnete den Russen den Weg zur Krim und löste in Istanbul große Panik aus. Im folgenden Jahr sollte die Festung wegen Seuchen und Nachschubschwierigkeiten von den Russen geräumt werden und wieder an die Osmanen fallen.", "479e0090"]},
"OLAYLAR_EK5:1737-08-04:0":{"b": ["Sieg von Banja Luka – Rettung Bosniens", "f603865a"], "d": ["Als österreichische Truppen in Bosnien einfielen und Banja Luka belagerten, eilte der Statthalter von Bosnien, Hekimoğlu Ali Pascha, mit den aus der einheimischen Bevölkerung aufgebotenen Kräften zu Hilfe und brachte dem zahlenmäßig überlegenen Feind eine schwere Niederlage bei. Dieser Sieg ließ den österreichischen Plan, Bosnien zu besetzen, schon beim ersten Zug scheitern, und der Norden der Provinz wurde vollständig zurückgewonnen. Banja Luka wurde zu einem der Wendepunkte, die die Moral des seit 1683 gegenüber Österreich ständig zurückweichenden osmanischen Heeres hoben.", "81c1850e"]},
"OLAYLAR_EK5:1739-07-22:0":{"b": ["Sieg von Hisarcık (Grocka) – Öffnung des Weges nach Belgrad", "2101cdff"], "d": ["Das zum Schutz Belgrads vorrückende österreichische Heer wurde in einem Engpass am Donauufer in einen Hinterhalt gelockt und erlitt in einer den ganzen Tag währenden Schlacht schwere Verluste. Während sich die Truppen des Feldmarschalls Wallis ungeordnet nach Belgrad zurückzogen, rückte das osmanische Heer bis vor die Festung vor und begann die Belagerung. Hisarcık war der entscheidendste Sieg in offener Feldschlacht gegen Österreich seit Karlowitz und führte unmittelbar zur Rückgewinnung Belgrads.", "5811893a"]},
"OLAYLAR_EK5:1739-10-03:0":{"b": ["Vertrag von Nisch – Frieden mit Russland, Neutralisierung Asows und Ende der Krim-Überfälle", "674f974e"], "d": ["Russland, das allein geblieben war, nachdem Österreich in Belgrad den Frieden angenommen hatte, musste den Krieg unter Vermittlung des französischen Gesandten Villeneuve beenden. Die Befestigungen der Festung Asow wurden geschleift, und das Gebiet wurde zwischen beiden Staaten zu neutralem Land erklärt; Russland akzeptierte die Bedingung, im Schwarzen Meer weder Kriegs- noch Handelsschiffe zu halten. So wurde Russlands Ziel, zum Meer vorzustoßen, um eine Generation verschoben, und das Osmanische Reich verließ im 18. Jahrhundert zum letzten Mal als Gewinner den Verhandlungstisch.", "7ca0d614"]},
"OLAYLAR_EK5:1739-12-12:0":{"b": ["Özi kehrt aus russischer Besetzung zurück: Übergabe nach der Schleifung der Festung gemäß dem Frieden von 1739", "7ecc2bef"], "d": ["Die Russen hatten Özi am 11. Juli 1737 eingenommen. Gemäß dem 1739 mit Russland geschlossenen Frieden wurde die Festung nach der Schleifung ihrer Befestigungen wieder den Osmanen übergeben; das Osmanische Reich behielt Özi bis 1788, vor dem Vertrag von Jassy, in seiner Hand.", "39ee6708"]},
"OLAYLAR_EK5:1743-10-23:0":{"b": ["Verteidigung Mossuls – Abwehr Nâdir Schahs", "c03ffbc1"], "d": ["Nâdir Schah, der Kirkuk und Erbil genommen hatte und vor Mossul erschien, beschoss die Stadt vierzig Tage lang mit Kanonen und führte nacheinander Generalangriffe durch. Die Verteidigung unter Statthalter Hüseyin Pascha al-Dschalîlî, der auch die Stadtbevölkerung bewaffnete, zwang das iranische Heer, die Belagerung unter schweren Verlusten aufzuheben. Das Standhalten Mossuls verhinderte den Verlust des gesamten Irak und festigte den Einfluss der Familie al-Dschalîlî in der Stadt für ein Jahrhundert.", "b9f67e29"]},
"OLAYLAR_EK5:1744-01-01:0":{"b": ["Bündnis von Diriyya – Gründung des ersten saudischen Emirats in Nadschd", "188751bf"], "d": ["Der Emir Muhammad ibn Saud, der den aus Uyaina vertriebenen Gelehrten Muhammad ibn Abd al-Wahhab in Diriyya unter seinen Schutz nahm, schloss mit ihm ein Bündnis, das die politische Autorität in den Dienst des religiösen Rufs stellte. Diese Abmachung eröffnete für die Familie Saud eine neue Geschichte und vereinte die zersplitterten Oasenemirate Nadschds um eine einzige Bewegung. Diese Macht, die sich innerhalb eines halben Jahrhunderts bis Kerbela, Mekka und Medina ausdehnen sollte, zwang das Osmanische Reich dazu, seine Herrschaft im Hedschas zu verteidigen.", "6843c874"]},
"OLAYLAR_EK5:1746-09-04:0":{"b": ["Vertrag von Kerden – Ende der osmanisch-iranischen Kriege", "1d3a919e"], "d": ["Mit dem nach dem vier Jahre währenden letzten Krieg geschlossenen Vertrag wurde die Grenze von Kasr-ı Şîrin von 1639 unverändert erneuert; keine der beiden Seiten erzielte einen Gebietsgewinn. Nâdir Schahs hartnäckige Forderung, das Dschafaritentum als fünfte Rechtsschule anzuerkennen, blieb unerfüllt; dafür wurde beschlossen, den iranischen Pilgern die freie Pilgerfahrt zu gestatten und Gesandte gegenseitig auszutauschen. Die mehr als zwei Jahrhunderte währenden osmanisch-iranischen Kriege waren damit faktisch beendet; diese Grenze ist bis heute weitgehend erhalten geblieben.", "2a089331"]},
"OLAYLAR_EK5:1754-12-13:0":{"b": ["Tod Mahmuds I. und Thronbesteigung Osmans III.", "30203700"], "d": ["Mahmud I., der in seiner vierundzwanzigjährigen Regierungszeit die im Vertrag von Belgrad verlorenen Gebiete zurückgewonnen und die Reform des Humbaracı-Korps unterstützt hatte, starb bei der Rückkehr vom Freitagsgebetszug. Ihm folgte sein Bruder Osman III., der bis zum Alter von achtundfünfzig Jahren im Kafes gelebt hatte. Eine kurze und unruhige Regierungszeit begann; unter Osman III., der innerhalb von drei Jahren sechs Großwesire wechselte, herrschte in den Staatsgeschäften deutliche Stagnation.", "8bdf7c4e"]},
"OLAYLAR_EK5:1757-10-30:0":{"b": ["Tod Osmans III. und Thronbesteigung Mustafas III.", "3ac10f85"], "d": ["Nach dem Tod Osmans III. am Ende einer dreijährigen Regierungszeit bestieg Mustafa III. den Thron, der Reformideen aufgeschlossen war und sich eingehend um die Staatsgeschäfte kümmerte. Der neue Sultan versuchte, gestützt auf die Erfahrung des Großwesirs Koca Râgıb Pascha, die Finanzen zu ordnen und das Heer zu erneuern; die Schnellfeuer-Artilleristen des Baron de Tott wurden in dieser Zeit aufgestellt. Der 1768 begonnene Krieg gegen Russland sollte jedoch alle Errungenschaften der siebzehnjährigen Regierungszeit überschatten.", "2d13aff2"]},
"OLAYLAR_EK5:1768-10-08:0":{"b": ["Kriegserklärung an Russland – Zwischenfall von Balta und Beginn des Krieges von 1768–1774", "9c6aabe0"], "d": ["Nachdem russische und kosakische Truppen, die die Konföderation von Bar in Polen verfolgten, die Ortschaft Balta an der osmanischen Grenze überfielen und niederbrannten, fasste der Diwan den Kriegsbeschluss, und der russische Gesandte wurde in Yedikule eingekerkert. Der Krieg, in den man ohne ernsthafte militärische Vorbereitung eintrat und der sechs Monate zuvor angekündigt worden war, verlief von Anfang an schlecht. Dieses sechs Jahre dauernde Ringen sollte mit dem Überfall von Çeşme, der Niederlage bei Kartal und der Besetzung der Krim zu einer der schwersten Niederlagenserien der osmanischen Geschichte werden.", "18bfa4d5"]},
"OLAYLAR_EK5:1769-09-20:0":{"b": ["Verlust der Festung Chotin an die Russen", "66d43ea4"], "d": ["Nachdem zwei Versuche des russischen Heeres unter Fürst Golizyn abgewehrt worden waren, zog sich das Heer nach der Niederlage des Großwesirs zwischen Kamenez und Chotin zurück, und die Besatzung räumte die Festung. Der widerstandslose Verlust der stärksten osmanischen Befestigung nördlich der Donau öffnete den Russen die Tore der Walachei und der Moldau. Die beiden Fürstentümer wurden im selben Jahr besetzt; Chotin konnte erst 1774 durch den Vertrag von Küçük Kaynarca zurückgewonnen werden.", "1d0b219f"]},
"OLAYLAR_EK5:1770-08-01:0":{"b": ["Niederlage in der Ebene von Kartal (Kagul)", "6f408eaf"], "d": ["Drei Wochen nach der Verbrennung der Flotte bei Çeşme wurde das osmanische Hauptheer an der Donau in der Ebene von Kartal von den zahlenmäßig weit kleineren, aber disziplinierten Truppen des Feldmarschalls Rumjanzew zerschlagen. Lager, Tross und Hunderte von Kanonen fielen dem Feind in die Hände; die fliehenden Truppen erlitten beim Überqueren der Donau große Verluste. Die Vernichtung sowohl der Flotte als auch des Landheeres im selben Sommer führte zum Fall von Kili, Akkerman, Ismail und Bender nacheinander und zur Besetzung der Krim.", "0fd97052"]},
"OLAYLAR_EK5:1771-07-01:0":{"b": ["Russische Besetzung der Halbinsel Krim", "217837b0"], "d": ["Die russischen Heere, die ein Jahr zuvor den Budschak genommen hatten, überwanden unter dem Befehl des Fürsten Dolgorukow Or Kapı und überrannten die gesamte Halbinsel Krim. Der Khan wurde abgesetzt und der russlandfreundliche Sâhib Giray an die Spitze gestellt; damit war der erste Schritt zur Loslösung des Khanats vom Osmanischen Reich getan. Der Verlust der Krim, die seit drei Jahrhunderten der nördliche Schild des Osmanischen Reiches gewesen war, war der Beginn des Prozesses, der 1774 zur Unabhängigkeit und 1783 zur direkten Annexion führte.", "952270d8"]},
"OLAYLAR_EK5:1774-01-21:0":{"b": ["Tod Mustafas III. und Thronbesteigung Abdülhamids I.", "42cba8e2"], "d": ["An die Stelle Mustafas III., der im kritischsten Augenblick des Krieges gegen Russland starb, trat sein Bruder Abdülhamid I., der dreiundvierzig Jahre im Kafes des Palastes verbracht hatte, und bestieg im Alter von neunundvierzig Jahren den Thron. Der neue Sultan, der eine der schwierigsten Zeiten des Staates übernahm, musste sich den schweren Bedingungen des im selben Jahr zu unterzeichnenden Vertrags von Küçük Kaynarca stellen. Seine fünfzehnjährige Regierungszeit sollte vom Verlust der Krim und einem neuen Krieg gegen Russland geprägt sein und 1789 mit einem Schlaganfall enden, den er beim Lesen der Nachricht vom Fall Özis erlitt.", "05963836"]},
"OLAYLAR_EK5:1774-06-25:0":{"b": ["Niederlage von Kozludscha – die Niederlage, die nach Küçük Kaynarca führte", "8e0542f9"], "d": ["Die bei Schumen versammelten osmanischen Kräfte wurden bei Kozludscha von den vereinten Kolonnen Suworows und Kamenskis geschlagen, und der größte Teil des Heeres löste sich auf. Mit dieser Niederlage blieb auf dem Balkan keine Streitmacht mehr, die Widerstand hätte leisten können; die russischen Vorhuten belagerten Schumen, und das Hauptquartier des Großwesirs geriet in Gefahr. Dass man weniger als einen Monat später in Küçük Kaynarca an den Verhandlungstisch trat und außerordentlich schwere Bedingungen annahm, ist unmittelbar die Folge dieser Niederlage.", "6721d6e3"]},
"OLAYLAR_EK5:1775-05-07:0":{"b": ["Abtretung der Bukowina (Nordmoldau) an Österreich", "190f9caa"], "d": ["Österreich nutzte die durch Küçük Kaynarca entstandene Schwäche, forderte die Bukowina, die die Verbindung zwischen der Moldau und Siebenbürgen herstellt, und erlangte dieses Land ohne Krieg durch Drohung und Bestechung. Der Verlust dieser fruchtbaren und strategischen Region südwestlich von Chotin teilte das Woiwodentum Moldau faktisch in zwei Teile. Diese Abtretung, bei der kein einziger Schuss fiel, galt als eines der deutlichsten Zeichen dafür, dass das Osmanische Reich seine Abschreckungskraft verloren hatte.", "dc1e97dd"]},
"OLAYLAR_EK5:1776-04-16:0":{"b": ["Besetzung Basras durch Iran", "0161e709"], "d": ["Sâdık Khan, der Bruder des Zand-Herrschers Karim Khan, nahm nach einjähriger Belagerung Basra ein, und das Osmanische Reich verlor seinen wichtigsten Hafen am Persischen Golf. Die Besetzung erschütterte unmittelbar den indischen Handelsweg, die Einkünfte aus Datteln und Perlen sowie die Südverteidigung des Irak. Die Stadt konnte erst 1779 während der Thronstreitigkeiten, die in Iran nach dem Tod Karim Khans ausbrachen, zurückgewonnen werden.", "838306ba"]},
"OLAYLAR_EK5:1779-03-10:0":{"b": ["Tenkihname von Aynalıkavak – vorläufige Einigung über die Krim", "9b3b0468"], "d": ["Die beiden Staaten, die wegen der Frage, wer an die Spitze des Krim-Khanats treten sollte, am Rande eines Krieges standen, unterzeichneten unter Vermittlung Frankreichs im Palast von Aynalıkavak einen Erläuterungstext. Russland erklärte sich bereit, seine Truppen von der Krim abzuziehen, das Osmanische Reich, die Khanschaft des russlandfreundlichen Şâhin Giray anzuerkennen; das religiöse Kalifatsrecht des Sultans über die Krim wurde bestätigt. Dieses zerbrechliche Gleichgewicht, das vier Jahre währen sollte, brach 1783 mit der direkten Annexion der Halbinsel durch Russland vollständig zusammen.", "8a428802"]},
"OLAYLAR_EK5:1781-01-01:0":{"b": ["Bau der Festung Anapa – kaukasische Verteidigungslinie", "be92a80f"], "d": ["Als die Krim durch Küçük Kaynarca verloren ging, wurde, um den osmanischen Einfluss im Kaukasus zu wahren, am Mündungsgebiet des Kuban mit dem Bau einer neuen Festung begonnen. Anapa, auf Resten einer genuesischen Kolonie errichtet, wurde mit seinem Basar, seinen Bädern und mehr als zweihundertfünfzig Läden bald zu einer Stadt, die die Verbindung zu den tscherkessischen Stämmen herstellte. Die Festung blieb achtundvierzig Jahre lang der vorgeschobenste Posten des Osmanischen Reiches gegen Russlands Herabsteigen in den Kaukasus.", "334a40cb"]},
"OLAYLAR_EK5:1785-04-27:0":{"b": ["Absetzung und Hinrichtung des Großwesirs Halil Hamîd Pascha", "c44001ca"], "d": ["Der reformerische Großwesir Halil Hamîd Pascha, dem Abdülhamid I. bei verschiedenen Gelegenheiten seine Zufriedenheit mit dessen Diensten gezeigt hatte, wurde gegen Morgen des 31. März 1785 plötzlich abgesetzt und nach Gallipoli verbannt, und sein gesamtes Vermögen wurde konfisziert. Zunächst wurden ihm das Eyalet Habesch, der Sandschak Dschidda und das Scheichtum der Haram von Mekka gegeben; als er den April 1785 mit Reisevorbereitungen auf Bozcaada verbrachte, wurde er auch von diesem Statthalteramt abgesetzt und mit dem ergangenen Hinrichtungsferman von Karakethüdâzâde Ali, einem Mann des Gazi Hasan Pascha von Algier, getötet. Sein abgeschlagener Kopf wurde nach Istanbul geschickt und am Ortakapı ausgestellt. Nach dem TDV wurde dieser jähe Sturz zwar mit dem Vorwurf eines Komplotts zur Absetzung des Sultans und zur Einsetzung des Prinzen Selim gedeutet, doch dürften die eigentlichen Gründe die Empörung über sein Schweigen zur Annexion der Krim, die Feindschaft der von seinen Reformen verletzten Kreise und die Opposition Gazi Hasan Paschas gewesen sein.", "6f73b0a5"]},
"OLAYLAR_EK5:1787-08-16:0":{"b": ["Kriegserklärung an Russland – der Osmanisch-Russische Krieg von 1787–1792 beginnt", "3bfb870c"], "d": ["Nach der prunkvollen Krimreise Katharinas II. und ihrer Schutzübernahme über Georgien fasste der Diwan den Kriegsbeschluss, um die Annexion rückgängig zu machen, und der russische Gesandte wurde erneut in Yedikule eingesperrt. Doch das Heer war nicht bereit, die Staatskasse war leer, und die Suche nach Verbündeten blieb ergebnislos. Der fünf Jahre währende Krieg sollte mit dem Fall Özis unter einem Massaker, dem Verlust Ismails und den schweren Bedingungen des Vertrags von Jassy enden.", "80a26d8f"]}
});
